"""SPINA (PostgreSQL TEST Edition)

This test build connects to PostgreSQL instead of SQLite.

V33 stability/performance pass:
  - fixes client Excel import, ADV lookup, notes warning, and recursive logging
  - speeds account login and avoids duplicate PostgreSQL file uploads
  - removes an unused INSERT round trip and adds connection timeout
V11 fix: adds Backup History, Verify Backup, and Restore Test Database tools.
V10 fix: adds an in-app PostgreSQL Backup button.
V9 fix: PostgreSQL database storage for JSON, generated PDFs, and client pictures.
  - PostgreSQL DB: spina_db on localhost:5432
  - App user: spina_user
  - JSON settings/notes/routes are mirrored to PostgreSQL.
  - Generated PDFs are copied into PostgreSQL stored_files.
  - Client pictures are saved into PostgreSQL client_pictures.
  - Local files are still kept as a safety mirror during this test phase.

Keep your original SQLite app and loans.db as backup.

"""

import os, sqlite3


# Early fallback used only during module setup, before the full logger exists.
def _spina_early_log(context, exc=None):
    try:
        print(f"[SPINA][EARLY] {context}: {exc}")
    except Exception:
        pass


# =============================================================================
# POSTGRESQL TEST MODE (generated by ChatGPT)
# =============================================================================
# This copy is intentionally a TEST build. It connects to PostgreSQL instead of
# SQLite, while keeping many SQLite-style SQL statements working through a small
# compatibility layer.
#
# Required:
#   pip install "psycopg[binary]"
# PostgreSQL:
#   host=localhost port=5432 dbname=spina_db user=spina_user password=
#
# You may override credentials with environment variables:
#   SPINA_PG_HOST, SPINA_PG_PORT, SPINA_PG_DB, SPINA_PG_USER, SPINA_PG_PASSWORD
# =============================================================================
SPINA_POSTGRESQL_TEST_MODE = True

import decimal as _spina_decimal

_SPINA_PG_CONFIG = {
    "host": os.environ.get("SPINA_PG_HOST", "localhost"),
    "port": int(os.environ.get("SPINA_PG_PORT", "5432")),
    "dbname": os.environ.get("SPINA_PG_DB", "spina_db"),
    "user": os.environ.get("SPINA_PG_USER", "spina_user"),
    "password": os.environ.get("SPINA_PG_PASSWORD", ""),
    # Fail quickly when PostgreSQL is unavailable instead of freezing startup.
    "connect_timeout": int(os.environ.get("SPINA_PG_CONNECT_TIMEOUT", "5")),
    "application_name": os.environ.get("SPINA_PG_APP_NAME", "SPINA Desktop"),
}
# =============================================================================
# POSTGRESQL FILE STORAGE MODE (V9)
# =============================================================================
# Stores JSON, generated PDFs, and client pictures in PostgreSQL while keeping a
# local mirror during this TEST phase. The local mirror keeps older code paths and
# emergency recovery safe; PostgreSQL is the new primary storage target.
# =============================================================================
SPINA_PG_STORE_FILES = True

_SPINA_PG_STORAGE_SCHEMA_SQL = """
CREATE TABLE IF NOT EXISTS app_json_store (
    key TEXT PRIMARY KEY,
    category TEXT NOT NULL DEFAULT 'json',
    value JSONB NOT NULL,
    source_path TEXT,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS app_settings_store (
    key TEXT PRIMARY KEY,
    value JSONB NOT NULL,
    source_path TEXT,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE IF NOT EXISTS stored_files (
    id BIGSERIAL PRIMARY KEY,
    file_type TEXT NOT NULL,
    client_uid TEXT,
    person_uid TEXT,
    loan_type TEXT,
    collector TEXT,
    report_date DATE,
    date_from DATE,
    date_to DATE,
    original_filename TEXT NOT NULL,
    relative_path TEXT,
    mime_type TEXT,
    file_ext TEXT,
    file_size BIGINT,
    sha256 TEXT NOT NULL,
    file_bytes BYTEA NOT NULL,
    imported_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (sha256, relative_path)
);
CREATE INDEX IF NOT EXISTS idx_stored_files_type ON stored_files(file_type);
CREATE INDEX IF NOT EXISTS idx_stored_files_client_uid ON stored_files(client_uid);
CREATE INDEX IF NOT EXISTS idx_stored_files_person_uid ON stored_files(person_uid);
CREATE INDEX IF NOT EXISTS idx_stored_files_report_date ON stored_files(report_date);
CREATE INDEX IF NOT EXISTS idx_stored_files_filename ON stored_files(original_filename);

CREATE TABLE IF NOT EXISTS client_pictures (
    id BIGSERIAL PRIMARY KEY,
    client_uid TEXT,
    person_uid TEXT,
    loan_type TEXT,
    original_filename TEXT NOT NULL,
    relative_path TEXT,
    mime_type TEXT,
    file_ext TEXT,
    file_size BIGINT,
    sha256 TEXT NOT NULL,
    image_bytes BYTEA NOT NULL,
    imported_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    UNIQUE (sha256, relative_path)
);
CREATE INDEX IF NOT EXISTS idx_client_pictures_client_uid ON client_pictures(client_uid);
CREATE INDEX IF NOT EXISTS idx_client_pictures_person_uid ON client_pictures(person_uid);
"""

_SPINA_PG_STORAGE_READY = False

# Avoid reading, hashing, and uploading an unchanged PDF/image more than once in
# the same app session. This especially removes the duplicate upload caused by
# ReportLab Canvas.save() followed immediately by _open_path().
_SPINA_PG_FILE_STORE_CACHE = {}


def _spina_pg_storage_enabled():
    try:
        return bool(SPINA_POSTGRESQL_TEST_MODE and SPINA_PG_STORE_FILES)
    except Exception:
        return False


def _spina_pg_storage_conn():
    import psycopg
    return psycopg.connect(**_SPINA_PG_CONFIG)


def _spina_pg_storage_log(context, exc=None):
    try:
        # _log_suppressed_once is defined later in the file; use it if available.
        if '_log_suppressed_once' in globals():
            _log_suppressed_once('pg_storage_' + str(context), 'pg storage: ' + str(context), exc)
        else:
            print('[SPINA][PG_STORAGE]', context, exc)
    except Exception:
        pass


def _spina_pg_ensure_storage_schema():
    global _SPINA_PG_STORAGE_READY
    if _SPINA_PG_STORAGE_READY:
        return True
    if not _spina_pg_storage_enabled():
        return False
    try:
        with _spina_pg_storage_conn() as conn:
            with conn.cursor() as cur:
                cur.execute(_SPINA_PG_STORAGE_SCHEMA_SQL)
            conn.commit()
        _SPINA_PG_STORAGE_READY = True
        return True
    except Exception as e:
        _spina_pg_storage_log('ensure_schema', e)
        return False


def _spina_pg_app_dir():
    try:
        return os.path.abspath(globals().get('APP_DIR') or os.path.dirname(os.path.abspath(__file__)))
    except Exception:
        return os.getcwd()


def _spina_pg_relpath(path):
    try:
        p = os.path.abspath(str(path or ''))
        root = _spina_pg_app_dir()
        if p.lower().startswith(root.lower() + os.sep.lower()) or p.lower() == root.lower():
            return os.path.relpath(p, root).replace('\\', '/')
        return p.replace('\\', '/')
    except Exception:
        return str(path or '')


def _spina_pg_json_table_for_path(path):
    try:
        name = os.path.basename(str(path or '')).lower().strip()
    except Exception:
        name = ''
    if name in {'spina_settings.json', 'settings.json', 'access_prefs.json', 'ledger_prefs.json'}:
        return 'app_settings_store'
    return 'app_json_store'


def _spina_pg_read_json(path):
    if not _spina_pg_ensure_storage_schema():
        return None
    try:
        key = _spina_pg_relpath(path)
        table = _spina_pg_json_table_for_path(path)
        with _spina_pg_storage_conn() as conn:
            with conn.cursor() as cur:
                if table == 'app_settings_store':
                    cur.execute('SELECT value FROM app_settings_store WHERE key=%s', (key,))
                elif table == 'app_json_store':
                    cur.execute('SELECT value FROM app_json_store WHERE key=%s', (key,))
                else:
                    raise ValueError(f'Unexpected PostgreSQL JSON storage table: {table!r}')
                row = cur.fetchone()
        if not row:
            return None
        obj = row[0]
        return obj
    except Exception as e:
        _spina_pg_storage_log('read_json', e)
        return None


def _spina_pg_write_json(path, data):
    if not _spina_pg_ensure_storage_schema():
        return False
    try:
        from psycopg.types.json import Jsonb
        key = _spina_pg_relpath(path)
        table = _spina_pg_json_table_for_path(path)
        source_path = key
        with _spina_pg_storage_conn() as conn:
            with conn.cursor() as cur:
                if table == 'app_settings_store':
                    cur.execute(
                        """INSERT INTO app_settings_store (key, value, source_path, updated_at)
                           VALUES (%s, %s, %s, NOW())
                           ON CONFLICT (key) DO UPDATE SET
                               value=EXCLUDED.value,
                               source_path=EXCLUDED.source_path,
                               updated_at=NOW()""",
                        (key, Jsonb(data), source_path)
                    )
                else:
                    cur.execute(
                        """INSERT INTO app_json_store (key, category, value, source_path, updated_at)
                           VALUES (%s, %s, %s, %s, NOW())
                           ON CONFLICT (key) DO UPDATE SET
                               category=EXCLUDED.category,
                               value=EXCLUDED.value,
                               source_path=EXCLUDED.source_path,
                               updated_at=NOW()""",
                        (key, 'json', Jsonb(data), source_path)
                    )
            conn.commit()
        return True
    except Exception as e:
        _spina_pg_storage_log('write_json', e)
        return False


def _spina_pg_sha256(data: bytes) -> str:
    import hashlib
    return hashlib.sha256(data).hexdigest()


def _spina_pg_guess_file_type(path):
    try:
        rp = _spina_pg_relpath(path).lower()
        name = os.path.basename(str(path or '')).lower()
        ext = os.path.splitext(name)[1].lower()
        if ext == '.pdf':
            if 'closed_collector_routes' in rp or 'closed collector routes' in rp:
                return 'closed_collector_route_pdf'
            if 'collectorroute' in name or 'collector route' in name:
                return 'collector_route_pdf'
            if 'audit' in rp or 'audit' in name:
                return 'audit_pdf'
            if 'renew' in rp or 'renew' in name:
                return 'renewal_pdf'
            return 'client_report_pdf'
        if ext in ('.png', '.jpg', '.jpeg', '.webp', '.bmp', '.gif'):
            if name.startswith('logo'):
                return 'logo_image'
            return 'client_picture_or_image'
        return 'other'
    except Exception:
        return 'other'


def _spina_pg_guess_report_date(path):
    try:
        import re
        from datetime import date as _date
        name = os.path.basename(str(path or ''))
        m = re.search(r'(20\d{2})[-_](\d{2})[-_](\d{2})', name)
        if not m:
            return None
        return _date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except Exception:
        return None


def _spina_pg_guess_collector(path):
    try:
        import re
        name = os.path.basename(str(path or ''))
        m = re.search(r'CollectorRoute[_\s-]+(.+?)[_\s-]+20\d{2}[-_]\d{2}[-_]\d{2}', name, re.I)
        if not m:
            return None
        return m.group(1).replace('_', ' ').strip() or None
    except Exception:
        return None


def _spina_pg_store_file_to_db(path, file_type=None, client_uid=None, person_uid=None, loan_type=None, collector=None, report_date=None):
    if not _spina_pg_ensure_storage_schema():
        return None
    try:
        p = os.path.abspath(str(path or ''))
        if not p or not os.path.exists(p) or os.path.isdir(p):
            return None
        ext = os.path.splitext(p)[1].lower()
        if ext not in ('.pdf', '.png', '.jpg', '.jpeg', '.webp', '.bmp', '.gif'):
            return None
        try:
            _st = os.stat(p)
            _cache_sig = (int(getattr(_st, 'st_mtime_ns', int(_st.st_mtime * 1_000_000_000))), int(_st.st_size))
        except Exception:
            _cache_sig = None
        try:
            _cached = _SPINA_PG_FILE_STORE_CACHE.get(p)
            if _cache_sig is not None and _cached and _cached[:2] == _cache_sig:
                return _cached[2]
        except Exception:
            pass

        with open(p, 'rb') as f:
            data = f.read()
        if not data:
            return None
        import mimetypes
        digest = _spina_pg_sha256(data)
        rel = _spina_pg_relpath(p)
        mime, _enc = mimetypes.guess_type(p)
        ft = file_type or _spina_pg_guess_file_type(p)
        rd = report_date or _spina_pg_guess_report_date(p)
        col = collector or _spina_pg_guess_collector(p)
        with _spina_pg_storage_conn() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """INSERT INTO stored_files (
                           file_type, client_uid, person_uid, loan_type, collector, report_date,
                           original_filename, relative_path, mime_type, file_ext, file_size,
                           sha256, file_bytes, imported_at
                       ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, NOW())
                       ON CONFLICT (sha256, relative_path) DO UPDATE SET
                           file_type=EXCLUDED.file_type,
                           client_uid=COALESCE(EXCLUDED.client_uid, stored_files.client_uid),
                           person_uid=COALESCE(EXCLUDED.person_uid, stored_files.person_uid),
                           loan_type=COALESCE(EXCLUDED.loan_type, stored_files.loan_type),
                           collector=COALESCE(EXCLUDED.collector, stored_files.collector),
                           report_date=COALESCE(EXCLUDED.report_date, stored_files.report_date),
                           original_filename=EXCLUDED.original_filename,
                           mime_type=EXCLUDED.mime_type,
                           file_ext=EXCLUDED.file_ext,
                           file_size=EXCLUDED.file_size,
                           file_bytes=EXCLUDED.file_bytes,
                           imported_at=NOW()
                       RETURNING id""",
                    (ft, client_uid, person_uid, loan_type, col, rd, os.path.basename(p), rel, mime, ext, len(data), digest, data)
                )
                row = cur.fetchone()
            conn.commit()
        _stored_id = row[0] if row else None
        try:
            if _stored_id is not None and _cache_sig is not None:
                _SPINA_PG_FILE_STORE_CACHE[p] = (_cache_sig[0], _cache_sig[1], _stored_id)
        except Exception:
            pass
        return _stored_id
    except Exception as e:
        _spina_pg_storage_log('store_file', e)
        return None


def _spina_pg_store_client_picture_to_db(src_path, client_uid='', person_uid='', loan_type=''):
    if not _spina_pg_ensure_storage_schema():
        return ''
    try:
        p = os.path.abspath(str(src_path or ''))
        if not p or not os.path.exists(p) or os.path.isdir(p):
            return ''
        ext = os.path.splitext(p)[1].lower()
        if ext not in ('.png', '.jpg', '.jpeg', '.webp', '.bmp', '.gif'):
            ext = '.png'
        with open(p, 'rb') as f:
            data = f.read()
        if not data:
            return ''
        import mimetypes
        digest = _spina_pg_sha256(data)
        rel = _spina_pg_relpath(p)
        mime, _enc = mimetypes.guess_type(p)
        uid = str(client_uid or '').strip()
        with _spina_pg_storage_conn() as conn:
            with conn.cursor() as cur:
                cur.execute(
                    """INSERT INTO client_pictures (
                           client_uid, person_uid, loan_type, original_filename, relative_path,
                           mime_type, file_ext, file_size, sha256, image_bytes, imported_at, updated_at
                       ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, NOW(), NOW())
                       ON CONFLICT (sha256, relative_path) DO UPDATE SET
                           client_uid=COALESCE(EXCLUDED.client_uid, client_pictures.client_uid),
                           person_uid=COALESCE(EXCLUDED.person_uid, client_pictures.person_uid),
                           loan_type=COALESCE(EXCLUDED.loan_type, client_pictures.loan_type),
                           original_filename=EXCLUDED.original_filename,
                           mime_type=EXCLUDED.mime_type,
                           file_ext=EXCLUDED.file_ext,
                           file_size=EXCLUDED.file_size,
                           image_bytes=EXCLUDED.image_bytes,
                           updated_at=NOW()
                       RETURNING id""",
                    (uid or None, str(person_uid or '').strip() or None, str(loan_type or '').strip() or None,
                     os.path.basename(p), rel, mime, ext, len(data), digest, data)
                )
                row = cur.fetchone()
                pic_id = row[0] if row else None
                # Also keep the picture in the generic file store for one-table file browsing.
                cur.execute(
                    """INSERT INTO stored_files (
                           file_type, client_uid, person_uid, loan_type, original_filename, relative_path,
                           mime_type, file_ext, file_size, sha256, file_bytes, imported_at
                       ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, NOW())
                       ON CONFLICT (sha256, relative_path) DO NOTHING""",
                    ('client_picture', uid or None, str(person_uid or '').strip() or None, str(loan_type or '').strip() or None,
                     os.path.basename(p), rel, mime, ext, len(data), digest, data)
                )
            conn.commit()
        return f'dbpic:{pic_id}' if pic_id else ''
    except Exception as e:
        _spina_pg_storage_log('store_client_picture', e)
        return ''


def _spina_pg_restore_client_picture_to_cache(token):
    try:
        s = str(token or '').strip()
        if not s.lower().startswith('dbpic:'):
            return ''
        pic_id = int(s.split(':', 1)[1])
    except Exception:
        return ''
    if not _spina_pg_ensure_storage_schema():
        return ''
    try:
        with _spina_pg_storage_conn() as conn:
            with conn.cursor() as cur:
                cur.execute('SELECT original_filename, file_ext, image_bytes FROM client_pictures WHERE id=%s', (pic_id,))
                row = cur.fetchone()
        if not row:
            return ''
        original_filename, file_ext, image_bytes = row
        ext = str(file_ext or os.path.splitext(str(original_filename or ''))[1] or '.png')
        cache_dir = os.path.join(_spina_pg_app_dir(), 'data', 'pg_cache', 'client_pictures')
        try:
            os.makedirs(cache_dir, exist_ok=True)
        except Exception:
            pass
        out_path = os.path.join(cache_dir, f'{pic_id}{ext}')
        try:
            if os.path.exists(out_path) and os.path.getsize(out_path) == len(image_bytes):
                return out_path
        except Exception:
            pass
        with open(out_path, 'wb') as f:
            f.write(bytes(image_bytes))
        return out_path
    except Exception as e:
        _spina_pg_storage_log('restore_client_picture', e)
        return ''


def _spina_pg_delete_client_picture_token(token):
    try:
        s = str(token or '').strip()
        if not s.lower().startswith('dbpic:'):
            return False
        pic_id = int(s.split(':', 1)[1])
    except Exception:
        return False
    if not _spina_pg_ensure_storage_schema():
        return False
    try:
        with _spina_pg_storage_conn() as conn:
            with conn.cursor() as cur:
                cur.execute('DELETE FROM client_pictures WHERE id=%s', (pic_id,))
            conn.commit()
        return True
    except Exception as e:
        _spina_pg_storage_log('delete_client_picture', e)
        return False


def _spina_pg_patch_reportlab_canvas_save(canvas_module):
    try:
        if not _spina_pg_storage_enabled():
            return
        Canvas = getattr(canvas_module, 'Canvas', None)
        if Canvas is None or getattr(Canvas, '_spina_pg_save_patched', False):
            return
        _orig_save = Canvas.save
        def _pg_save_and_store(self, *args, **kwargs):
            res = _orig_save(self, *args, **kwargs)
            try:
                fn = getattr(self, '_filename', None) or getattr(getattr(self, '_doc', None), 'filename', None)
                if isinstance(fn, (str, bytes, os.PathLike)):
                    _spina_pg_store_file_to_db(fn)
            except Exception as e:
                _spina_pg_storage_log('canvas_save_store', e)
            return res
        Canvas.save = _pg_save_and_store
        Canvas._spina_pg_save_patched = True
    except Exception as e:
        _spina_pg_storage_log('patch_canvas_save', e)

