def _spina_pg_normalize_value(v):
    """Convert PostgreSQL-returned values into SQLite-like values."""
    try:
        if isinstance(v, _spina_decimal.Decimal):
            return float(v)
    except Exception:
        pass
    return v


class _PgCompatRow(dict):
    """SQLite Row-like object: supports row['name'], row[0], dict(row), row.get()."""
    __slots__ = ("_columns", "_values")

    def __init__(self, columns, values):
        vals = [_spina_pg_normalize_value(x) for x in (values or [])]
        super().__init__(zip(columns, vals))
        self._columns = list(columns or [])
        self._values = list(vals)

    def __getitem__(self, key):
        if isinstance(key, int):
            return self._values[key]
        return dict.__getitem__(self, key)

    def __iter__(self):
        return iter(self._values)

    def keys(self):
        return list(self._columns)


def _spina_pg_replace_qmarks(sql: str) -> str:
    """Replace SQLite ? parameters with psycopg %s outside quoted strings."""
    out = []
    in_single = False
    in_double = False
    i = 0
    while i < len(sql):
        ch = sql[i]
        if ch == "'" and not in_double:
            out.append(ch)
            # SQL escaped single quote: ''
            if in_single and i + 1 < len(sql) and sql[i + 1] == "'":
                i += 1
                out.append(sql[i])
            else:
                in_single = not in_single
        elif ch == '"' and not in_single:
            out.append(ch)
            in_double = not in_double
        elif ch == "?" and not in_single and not in_double:
            out.append("%s")
        else:
            out.append(ch)
        i += 1
    return "".join(out)


def _spina_pg_escape_literal_percents(sql: str) -> str:
    """Escape literal percent signs for psycopg while preserving %s/%b/%t placeholders.

    Old SQLite queries commonly contain LIKE '%ADV%' or LIKE '%[RC:%'.
    Psycopg uses %s-style placeholders, so a literal % in the SQL text must be
    doubled as %%. Without this, ADV/reason queries can fail silently inside the
    app's broad try/except blocks.
    """
    try:
        s = str(sql or "")
    except Exception:
        return sql
    out = []
    i = 0
    while i < len(s):
        ch = s[i]
        if ch == "%":
            nxt = s[i + 1] if i + 1 < len(s) else ""
            # Keep psycopg placeholders and existing escaped percent signs.
            if nxt in ("s", "b", "t", "%"):
                out.append("%")
            else:
                out.append("%%")
        else:
            out.append(ch)
        i += 1
    return "".join(out)


def _spina_pg_sql(sql):
    """Translate common SQLite SQL into PostgreSQL-compatible SQL."""
    if sql is None:
        return sql
    s = str(sql)
    raw = s.strip()
    low = raw.lower()

    # SQLite PRAGMAs: ignore/no-op in PostgreSQL, except table_info handled separately.
    if low.startswith("pragma ") and not low.startswith("pragma table_info"):
        return None

    # Transaction wrapper in old SQLite code.
    if low in ("begin immediate", "begin exclusive"):
        return "BEGIN"

    # PostgreSQL does not have SQLite's built-in NOCASE collation.
    # Remove it here so client/data-bank queries do not silently return blank screens.
    s = re.sub(r"\s+COLLATE\s+NOCASE\b", "", s, flags=re.IGNORECASE)

    # SQLite LIKE is usually case-insensitive for normal text; PostgreSQL LIKE is case-sensitive.
    # Use ILIKE so Clients tab search works when typing lowercase/uppercase differently.
    s = re.sub(r"\bLIKE\b", "ILIKE", s, flags=re.IGNORECASE)

    # Common SQLite functions / DDL syntax.
    s = re.sub(r"\bIFNULL\s*\(", "COALESCE(", s, flags=re.IGNORECASE)
    s = re.sub(r"datetime\s*\(\s*'now'\s*\)", "CURRENT_TIMESTAMP::text", s, flags=re.IGNORECASE)
    s = re.sub(r"date\s*\(\s*'now'\s*\)", "CURRENT_DATE::text", s, flags=re.IGNORECASE)
    s = re.sub(r"\bINTEGER\s+PRIMARY\s+KEY\s+AUTOINCREMENT\b", "BIGSERIAL PRIMARY KEY", s, flags=re.IGNORECASE)
    s = re.sub(r"\bREAL\b", "DOUBLE PRECISION", s, flags=re.IGNORECASE)

    # SQLite date arithmetic used by payment-start filters.
    s = re.sub(
        r"date\s*\(\s*([A-Za-z_][A-Za-z0-9_\.]*?)\s*,\s*'\+'\s*\|\|\s*COALESCE\s*\(\s*([A-Za-z_][A-Za-z0-9_\.]*?)\s*,\s*0\s*\)\s*\|\|\s*'\s*day'\s*\)",
        r"((CAST(\1 AS date) + (COALESCE(\2,0)::int * INTERVAL '1 day'))::date::text)",
        s,
        flags=re.IGNORECASE,
    )

    # date(x) / datetime(x) comparisons/order-bys. Keep date(...) with 2 args handled above.
    s = re.sub(r"\bdate\s*\(\s*\?\s*\)", "CAST(? AS date)", s, flags=re.IGNORECASE)
    s = re.sub(r"\bdate\s*\(\s*%s\s*\)", "CAST(%s AS date)", s, flags=re.IGNORECASE)
    s = re.sub(r"\bdate\s*\(\s*([A-Za-z_][A-Za-z0-9_\.]*)\s*\)", r"CAST(\1 AS date)", s, flags=re.IGNORECASE)
    s = re.sub(r"\bdatetime\s*\(\s*([A-Za-z_][A-Za-z0-9_\.]*)\s*\)", r"CAST(\1 AS timestamp)", s, flags=re.IGNORECASE)

    # SQLite INSERT OR IGNORE -> PostgreSQL INSERT ... ON CONFLICT DO NOTHING.
    if re.search(r"\bINSERT\s+OR\s+IGNORE\s+INTO\b", s, flags=re.IGNORECASE):
        s = re.sub(r"\bINSERT\s+OR\s+IGNORE\s+INTO\b", "INSERT INTO", s, flags=re.IGNORECASE)
        if "on conflict" not in s.lower():
            s = s.rstrip().rstrip(";") + " ON CONFLICT DO NOTHING"

    # SQLite INSERT OR REPLACE is not safely equivalent in PostgreSQL. Make it explicit.
    if re.search(r"\bINSERT\s+OR\s+REPLACE\s+INTO\b", s, flags=re.IGNORECASE):
        raise RuntimeError("PostgreSQL test mode cannot safely translate INSERT OR REPLACE automatically.")

    # SQLite placeholders -> psycopg placeholders.
    # Then escape literal percent signs so LIKE '%ADV%' works with psycopg params.
    s = _spina_pg_escape_literal_percents(_spina_pg_replace_qmarks(s))
    return s


def _spina_pg_table_name_from_pragma(sql: str):
    m = re.search(r"PRAGMA\s+table_info\s*\(\s*['\"]?([A-Za-z_][A-Za-z0-9_]*)['\"]?\s*\)", str(sql), flags=re.IGNORECASE)
    return m.group(1) if m else None


class _PgCompatCursor:
    def __init__(self, conn, cur=None):
        self._conn = conn
        self._cur = cur or conn._pg.cursor()
        self._rows = None
        self._idx = 0
        self.lastrowid = None
        self.rowcount = -1

    @property
    def connection(self):
        return self._conn

    def _set_rows(self, columns, rows):
        self._rows = [_PgCompatRow(columns, r) for r in (rows or [])]
        self._idx = 0
        self.rowcount = len(self._rows)

    def execute(self, sql, params=None):
        sql_text = str(sql or "")
        low = sql_text.strip().lower()
        params = tuple(params or ())

        # PRAGMA table_info(table) -> SQLite-compatible column metadata rows.
        tname = _spina_pg_table_name_from_pragma(sql_text)
        if tname:
            q = """
                SELECT ordinal_position - 1 AS cid,
                       column_name AS name,
                       data_type AS type,
                       CASE WHEN is_nullable = 'NO' THEN 1 ELSE 0 END AS notnull,
                       column_default AS dflt_value,
                       CASE WHEN column_name IN (
                            SELECT kcu.column_name
                            FROM information_schema.table_constraints tc
                            JOIN information_schema.key_column_usage kcu
                              ON tc.constraint_name = kcu.constraint_name
                             AND tc.table_schema = kcu.table_schema
                            WHERE tc.constraint_type = 'PRIMARY KEY'
                              AND tc.table_schema = 'public'
                              AND tc.table_name = %s
                       ) THEN 1 ELSE 0 END AS pk
                FROM information_schema.columns
                WHERE table_schema='public' AND table_name=%s
                ORDER BY ordinal_position
            """
            self._cur.execute(q, (tname, tname))
            self._set_rows(["cid", "name", "type", "notnull", "dflt_value", "pk"], self._cur.fetchall())
            return self

        # sqlite_master table-exists / table-sql queries used by old migration code.
        if "sqlite_master" in low:
            if "select sql" in low:
                # Return a harmless CREATE SQL string so legacy inspection won't trigger SQLite rebuilds.
                name = params[0] if params else ""
                self._set_rows(["sql"], [(f"CREATE TABLE {name} (...) -- PostgreSQL",)])
                return self
            if "select name" in low:
                name = params[0] if params else None
                self._cur.execute(
                    "SELECT table_name FROM information_schema.tables WHERE table_schema='public' AND table_name=%s",
                    (name,)
                )
                rows = [(r[0],) for r in self._cur.fetchall()]
                self._set_rows(["name"], rows)
                return self

        translated = _spina_pg_sql(sql_text)
        if translated is None:
            self._set_rows([], [])
            return self

        try:
            self._cur.execute(translated, params)
            self.rowcount = self._cur.rowcount
            self._rows = None
            self._idx = 0
            # The application never reads cursor.lastrowid. Avoid SELECT lastval()
            # after every INSERT, which previously doubled INSERT round trips.
            self.lastrowid = None
            return self
        except Exception as e:
            try:
                self._conn._pg.rollback()
            except Exception:
                pass
            _spina_pg_raise_sqlite_like(e)

    def executemany(self, sql, seq_of_params):
        translated = _spina_pg_sql(str(sql or ""))
        if translated is None:
            self.rowcount = 0
            return self
        try:
            self._cur.executemany(translated, list(seq_of_params or []))
            self.rowcount = self._cur.rowcount
            return self
        except Exception as e:
            try:
                self._conn._pg.rollback()
            except Exception:
                pass
            _spina_pg_raise_sqlite_like(e)

    def fetchone(self):
        if self._rows is not None:
            if self._idx >= len(self._rows):
                return None
            r = self._rows[self._idx]
            self._idx += 1
            return r
        r = self._cur.fetchone()
        if r is None:
            return None
        cols = [d.name for d in (self._cur.description or [])]
        return _PgCompatRow(cols, r)

    def fetchall(self):
        if self._rows is not None:
            out = self._rows[self._idx:]
            self._idx = len(self._rows)
            return out
        rows = self._cur.fetchall() if self._cur.description else []
        cols = [d.name for d in (self._cur.description or [])]
        return [_PgCompatRow(cols, r) for r in rows]

    def fetchmany(self, size=None):
        if self._rows is not None:
            n = size or 1
            out = self._rows[self._idx:self._idx+n]
            self._idx += len(out)
            return out
        rows = self._cur.fetchmany(size) if self._cur.description else []
        cols = [d.name for d in (self._cur.description or [])]
        return [_PgCompatRow(cols, r) for r in rows]

    def close(self):
        try:
            return self._cur.close()
        except Exception:
            return None

    def __iter__(self):
        return iter(self.fetchall())

    def __getattr__(self, name):
        return getattr(self._cur, name)


class _PgCompatConnection:
    def __init__(self):
        try:
            import psycopg
        except Exception as e:
            raise RuntimeError('Missing PostgreSQL driver. Run: python -m pip install "psycopg[binary]"') from e
        self._psycopg = psycopg
        self._pg = psycopg.connect(**_SPINA_PG_CONFIG)
        self.row_factory = None  # accepts old sqlite-style assignment; not used

    @property
    def in_transaction(self):
        # Avoid the old SQLite wrapper repeatedly issuing BEGIN IMMEDIATE.
        return True

    def cursor(self, *args, **kwargs):
        return _PgCompatCursor(self)

    def execute(self, sql, params=None):
        cur = self.cursor()
        return cur.execute(sql, params)

    def executemany(self, sql, seq_of_params):
        cur = self.cursor()
        return cur.executemany(sql, seq_of_params)

    def commit(self):
        return self._pg.commit()

    def rollback(self):
        return self._pg.rollback()

    def close(self):
        return self._pg.close()

    def backup(self, *args, **kwargs):
        # SQLite-only backup API. Not applicable in PostgreSQL test mode.
        return None


def _spina_pg_raise_sqlite_like(e):
    """Raise sqlite3-style exceptions so existing catch blocks still work."""
    msg = str(e)
    try:
        import psycopg
        if isinstance(e, psycopg.errors.UniqueViolation):
            raise sqlite3.IntegrityError(msg)
        if isinstance(e, psycopg.OperationalError):
            raise sqlite3.OperationalError(msg)
        if isinstance(e, psycopg.Error):
            raise sqlite3.DatabaseError(msg)
    except sqlite3.Error:
        raise
    except Exception:
        pass
    raise e


def _spina_pg_connect_db(path=None):
    return _PgCompatConnection()

