def connect_db(path=None):
    """Central DB connector.

    PostgreSQL TEST MODE: ignores the old SQLite file path and connects to
    spina_db using psycopg through a SQLite-compatibility wrapper.
    """
    if globals().get("SPINA_POSTGRESQL_TEST_MODE", False):
        return _spina_pg_connect_db(path)

    db_path = path or DB_FILE
    conn = sqlite3.connect(db_path, check_same_thread=False, timeout=30)
    try:
        conn.row_factory = sqlite3.Row
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0003', 'suppressed exception excpass_0003', __spina_exc)
        pass

    # Best-effort pragmas; safe if unsupported.
    try:
        conn.execute("PRAGMA foreign_keys = ON")
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0004', 'suppressed exception excpass_0004', __spina_exc)
        pass
    try:
        conn.execute("PRAGMA busy_timeout = 30000")
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0005', 'suppressed exception excpass_0005', __spina_exc)
        pass
    try:
        conn.execute("PRAGMA journal_mode = WAL")
        conn.execute("PRAGMA synchronous = NORMAL")
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0006', 'suppressed exception excpass_0006', __spina_exc)
        pass
    return conn

def run_write(op, retries: int = 8, base_delay: float = 0.08, max_delay: float = 1.20):
    """Retry wrapper for SQLite write operations."""
    import time, random, sqlite3 as _sqlite3
    last = None
    for i in range(max(1, retries)):
        try:
            return op()
        except _sqlite3.OperationalError as e:
            msg = str(e).lower()
            if ("database is locked" in msg) or ("database is busy" in msg):
                last = e
                delay = min(max_delay, base_delay * (2 ** i))
                delay = delay + (random.random() * base_delay)
                time.sleep(delay)
                continue
            raise
    if last:
        raise last
    return op()

def _is_write_sql(sql: str) -> bool:
    try:
        if not sql:
            return False
        s = str(sql).lstrip().upper()
        if not s:
            return False
        first = s.split(None, 1)[0]
        return first in {"INSERT","UPDATE","DELETE","REPLACE","CREATE","DROP","ALTER","VACUUM","REINDEX","ANALYZE"}
    except Exception:
        return False

# --- BEGIN: SQLite helper (safe IN-clause chunking) ---
def _sqlite_fetchall_in_chunks(cur, sql_template: str, items, chunk: int = 900, tail_params=()):
    """Fetch all rows for SQL that contains 'IN ({ph})' placeholder.

    - Splits `items` into batches to avoid SQLite 'too many SQL variables'.
    - `sql_template` must include '{ph}' placeholder for question marks.
    - `tail_params` are appended after the batch params (e.g. BETWEEN ? AND ? values).
    """
    try:
        items_list = list(items or [])
    except Exception:
        items_list = []
    if not items_list:
        return []
    try:
        tail = tuple(tail_params or ())
    except Exception:
        tail = ()
    out = []
    for i in range(0, len(items_list), max(1, int(chunk))):
        batch = items_list[i:i + max(1, int(chunk))]
        if not batch:
            continue
        ph = ",".join(["?"] * len(batch))
        sql = str(sql_template).format(ph=ph)
        cur.execute(sql, tuple(batch) + tail)
        out.extend(cur.fetchall() or [])
    return out
# --- END: SQLite helper ---

# --- Payment mode helpers ---
_SPINA_PAYMENT_MODE_OPTIONS = ('Cash', 'GCASH', 'ATM', 'Others')

def _spina__split_payment_mode(value):
    try:
        raw = str(value or '').strip()
    except Exception:
        raw = ''
    if not raw:
        return 'Cash', ''
    key = raw.lower().replace('-', '').replace('_', '').replace(' ', '')
    if key == 'cash':
        return 'Cash', ''
    if key == 'gcash':
        return 'GCASH', ''
    if key == 'atm':
        return 'ATM', ''
    if key in ('other', 'others', 'othermode', 'otherpaymentmode'):
        return 'Others', ''
    return 'Others', raw

def _spina__merge_payment_mode(mode_value, other_value=''):
    base, custom_from_mode = _spina__split_payment_mode(mode_value)
    try:
        custom = str(other_value or '').strip()
    except Exception:
        custom = ''
    if base != 'Others':
        return base
    custom = custom or custom_from_mode
    return custom if custom else 'Others'
# --- END: Payment mode helpers ---

