# --- Cross-platform opener for files/folders ---
import subprocess as _subp
import os
import sys

def _open_path(_p: str) -> bool:
    """Safely open a generated file/folder.

    v29 fix:
    Python 3.14 on Windows can crash hard with os.startfile() in some Tk/PDF
    workflows. Use subprocess instead so PDF generation does not close the app.
    """
    try:
        # V9: any PDF/image opened by the app is also mirrored into PostgreSQL.
        try:
            _spina_pg_store_file_to_db(_p)
        except Exception:
            pass

        _p = os.path.abspath(str(_p or ""))
        if not _p:
            return False

        if sys.platform.startswith("win"):
            try:
                flags = 0
                try:
                    flags = getattr(_subp, "CREATE_NO_WINDOW", 0)
                except Exception:
                    flags = 0

                # explorer.exe opens files with the user's default app and folders in Explorer.
                _subp.Popen(["explorer.exe", _p], close_fds=True, creationflags=flags)
                return True
            except Exception:
                try:
                    folder = _p if os.path.isdir(_p) else os.path.dirname(_p)
                    _subp.Popen(["explorer.exe", folder], close_fds=True)
                    return True
                except Exception:
                    return False

        elif sys.platform == "darwin":
            _subp.Popen(["open", _p])
            return True
        else:
            _subp.Popen(["xdg-open", _p])
            return True
    except Exception:
        return False
# --- end opener ---

