import logging as _logging

def _init_logger():
    try:
        log_dir = DATA_DIR
        os.makedirs(log_dir, exist_ok=True)
        log_file = os.path.join(log_dir, "spina_app.log")
        # Avoid duplicate handlers if reloaded
        if not _logging.getLogger().handlers:
            _logging.basicConfig(
                filename=log_file,
                level=_logging.INFO,
                format="%(asctime)s [%(levelname)s] %(message)s"
            )
        return log_file
    except Exception:
        return None

_LOG_FILE = _init_logger()

def _log_exc(context: str, exc: Exception | None = None):
    """Log exceptions to data/spina_app.log (best-effort)."""
    try:
        if exc is None:
            _logging.exception(context)
        else:
            _logging.error(
                "%s: %s",
                context,
                exc,
                exc_info=(type(exc), exc, exc.__traceback__),
            )
    except Exception:
        try:
            print(f"[SPINA][ERROR] {context}: {exc}", file=sys.stderr)
        except Exception:
            return


# --- BEGIN: log suppressed exceptions (log-once) ---
try:
    _SUPPRESS_LOG_ONCE_KEYS
except NameError:
    _SUPPRESS_LOG_ONCE_KEYS = set()

def _log_suppressed_once(key: str, context: str, exc: Exception | None = None):
    """Log a suppressed exception only once per key (to avoid log spam)."""
    try:
        k = str(key or context or "suppressed")
        if k in _SUPPRESS_LOG_ONCE_KEYS:
            return
        _SUPPRESS_LOG_ONCE_KEYS.add(k)
    except Exception:
        # Never call this function recursively from its own failure path.
        k = str(context or "suppressed")
    try:
        _log_exc(context, exc)
    except Exception:
        try:
            print(f"[SPINA][SUPPRESSED] {context}: {exc}", file=sys.stderr)
        except Exception:
            return
# --- END: log suppressed exceptions (log-once) ---

def _alert_user(title: str, message: str, kind: str = "error"):
    """Best-effort UI alert. Safe even if Tk root isn't created yet."""
    try:
        from tkinter import messagebox as _mb
        if kind == "warning":
            _mb.showwarning(title, message)
        elif kind == "info":
            _mb.showinfo(title, message)
        else:
            _mb.showerror(title, message)
    except Exception:
        try:
            print(f"[SPINA][{kind.upper()}] {title}: {message}", file=sys.stderr)
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0010', 'suppressed exception excpass_0010', __spina_exc)
            pass

# --- BEGIN: UI ignored-exception logger (log once) ---
try:
    _UI_IGNORED_ONCE = set()
except Exception:
    _UI_IGNORED_ONCE = set()

def _log_ignored(context: str, exc: Exception, key: str | None = None):
    """Log an otherwise-ignored exception once per key (to avoid log spam)."""
    try:
        k = (key or context or "ignored")
        if k in _UI_IGNORED_ONCE:
            return
        _UI_IGNORED_ONCE.add(k)
        _log_exc(context, exc)
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0011', 'suppressed exception excpass_0011', __spina_exc)
        pass
# --- END: UI ignored-exception logger ---

