def _pick_writable_dir(candidates, fallback=None):
    """Return first directory we can create + write into (best-effort)."""
    for d in candidates or []:
        try:
            if not d:
                continue
            os.makedirs(d, exist_ok=True)
            # Write-test (avoid silent failures on readonly app bundles)
            tf = os.path.join(d, ".__spina_write_test__")
            with open(tf, "w", encoding="utf-8") as f:
                f.write("ok")
            try:
                os.remove(tf)
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0015', 'suppressed exception excpass_0015', __spina_exc)
                pass
            return d
        except Exception:
            continue
    return fallback or (candidates[0] if candidates else None)

