import re as _re_advpatch
try:
    from datetime import datetime as _dt_advpatch, date as _date_advpatch, timedelta as _td_advpatch
except Exception:
    # Fallback aliases
    from datetime import datetime, date, timedelta
    _dt_advpatch = datetime
    _date_advpatch = date
    _td_advpatch = timedelta

# Recognize [ADV:YYYY-MM-DD..YYYY-MM-DD]
_ADV_TAG_RE = _re_advpatch.compile(r"\[\s*ADV\s*:\s*(\d{4}-\d{2}-\d{2})\s*\.\.\s*(\d{4}-\d{2}-\d{2})\s*\]", _re_advpatch.IGNORECASE)

# Recognize plain text: "ADV 2025-10-01 to 2025-10-14" or "Advance 2025-10-01 - 2025-10-14"
_ADV_PLAIN_RE = _re_advpatch.compile(
    r"\badv(ance)?\b[^0-9]*(\d{4}-\d{2}-\d{2})\s*(?:to|-|–|—|\.\.)\s*(\d{4}-\d{2}-\d{2})",
    _re_advpatch.IGNORECASE,
)
# --- END: Early ADV helpers ---

