from spina_app.utilities.text import _oslp__norm_area_name

def _oslp__load_prefs_json(p):
    try:
        from pathlib import Path as _Path
        P = _Path(p)
        if P.exists():
            import json as _json
            return _json.loads(P.read_text(encoding="utf-8"))
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0028', 'suppressed exception excpass_0028', __spina_exc)
        pass
    return {}

def resolve_area_order_from_prefs(all_areas, prefs_path=None):
    """
    NO-UI resolver:
      - Reads order from data/ledger_prefs.json["areas_order"]
      - Case/whitespace-insensitive matching
      - Appends new areas (not in prefs) alphabetically
    Returns arranged list.
    """
    if not prefs_path:
        try:
            prefs_path = data_path("ledger_prefs.json")
        except Exception:
            prefs_path = os.path.join(APP_DIR, "data", "ledger_prefs.json")

    # Unique areas (first occurrence wins)
    uniq = []
    seen = set()
    for a in all_areas or []:
        if a and str(a).strip() and a not in seen:
            uniq.append(a)
            seen.add(a)

    # Map normalized -> original
    norm2orig = {}
    for a in uniq:
        k = _oslp__norm_area_name(a)
        if k and k not in norm2orig:
            norm2orig[k] = a

    prefs = _oslp__load_prefs_json(prefs_path)
    saved = prefs.get("areas_order", [])
    if not isinstance(saved, list):
        saved = []

    arranged = []
    used = set()
    # Follow saved order strictly where names match (normalized)
    for name in saved:
        k = _oslp__norm_area_name(name)
        if k in norm2orig and k not in used:
            arranged.append(norm2orig[k])
            used.add(k)

    # Append any new areas not in prefs, alphabetically
    for a in sorted(uniq, key=lambda s: s.lower()):
        k = _oslp__norm_area_name(a)
        if k not in used:
            arranged.append(a)
            used.add(k)
    return arranged
# === END: NO-UI area order resolver ===

# === BEGIN: Main/Sub Area helper ===
def split_area_main_sub(area: str):
    """Split a single Area string into (main_area, sub_area).

    Backwards compatible:
      - If no separator is found, main_area = original, sub_area = ""
      - Supports separators like: 'Main - Sub', 'Main / Sub', 'Main | Sub', 'Main: Sub'
    """
    try:
        a = str(area or "").strip()
    except Exception:
        a = ""
    if not a:
        return ("", "")

    # Prefer separators with spaces first (less chance of false split)
    seps = [" | ", " / ", " - ", " > ", " : ", " — ", " – "]
    for sep in seps:
        if sep in a:
            left, right = a.split(sep, 1)
            left = (left or "").strip()
            right = (right or "").strip()
            if left and right:
                return (left, right)

    # Fallback single-char separators (use only if it looks like two parts)
    for sep in ["|", "/", ">", ":"]:
        if sep in a:
            left, right = a.split(sep, 1)
            left = (left or "").strip()
            right = (right or "").strip()
            if left and right:
                return (left, right)

    return (a, "")


def join_area_main_sub(main_area: str, sub_area: str = "") -> str:
    """Join main/sub into a single Area string using a consistent separator.

    - If sub_area is blank -> returns main_area
    - Else -> 'Main - Sub'
    """
    try:
        ma = str(main_area or "").strip()
    except Exception:
        ma = ""
    try:
        su = str(sub_area or "").strip()
    except Exception:
        su = ""
    if not ma:
        return su
    if not su:
        return ma
    return f"{ma} - {su}"

# === END: Main/Sub Area helper ===


# === BEGIN: ADV helpers (idempotent) ===
try:
    import re as _re_adv
    from datetime import datetime as _dt_adv, date as _date_adv, timedelta as _timedelta_adv
    _ADV_PAT1 = _re_adv.compile(r"\[\s*adv\s*:\s*(\d{4}-\d{2}-\d{2})\s*\.\.\s*(\d{4}-\d{2}-\d{2})\s*\]", _re_adv.I)
    _ADV_PAT2 = _re_adv.compile(r"\badv\s+(\d{4}-\d{2}-\d{2})\s*(?:to|-|–|—|\.\.)\s*(\d{4}-\d{2}-\d{2})\b", _re_adv.I)
    def _parse_any_adv_range(_s):
        if not _s:
            return None
        _s = str(_s).strip()
        _m = _ADV_PAT1.search(_s) or _ADV_PAT2.search(_s)
        if not _m:
            return None
        try:
            _a = _dt_adv.strptime(_m.group(1), "%Y-%m-%d").date()
            _b = _dt_adv.strptime(_m.group(2), "%Y-%m-%d").date()
            if _b < _a: _a, _b = _b, _a
            return (_a, _b)
        except Exception:
            return None
    def _expand_range_inclusive(_a, _b):
        _d = _a
        while _d <= _b:
            yield _d
            _d = _d + _timedelta_adv(days=1)
    def _is_adv_text(_s):
        return bool(_parse_any_adv_range(_s or ""))
except Exception as __spina_exc:
    _log_suppressed_once('excpass_0029', 'suppressed exception excpass_0029', __spina_exc)
    pass
# === END: ADV helpers ===

