# PDF Unicode-safe font registration
PDF_BASE_FONT = "Helvetica"
PDF_BOLD_FONT = "Helvetica-Bold"

def _find_ttf(paths):
    for p in paths:
        if p and os.path.exists(p):
            return p
    return None

def _register_unicode_fonts():
    """Try to register a Unicode TTF so ReportLab can encode non-ASCII safely.
    Falls back to built-ins if none found.
    """
    if not HAVE_REPORTLAB:
        return (PDF_BASE_FONT, PDF_BOLD_FONT)
    try:
        from reportlab.pdfbase import pdfmetrics
        from reportlab.pdfbase.ttfonts import TTFont
        # Candidate fonts (common on Windows/Linux/macOS or bundled near app)
        candidates_regular = [
            # Bundled near the app (recommended for portable builds)
            os.path.join(os.getcwd(), "DejaVuSans.ttf"),
            os.path.join(os.getcwd(), "fonts", "DejaVuSans.ttf"),

            # Windows
            "C:/Windows/Fonts/arial.ttf",
            "C:/Windows/Fonts/ARIAL.TTF",

            # Linux (common locations)
            "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
            "/usr/share/fonts/truetype/dejavu/DejaVuSansCondensed.ttf",
            "/usr/share/fonts/truetype/noto/NotoSans-Regular.ttf",
            "/usr/share/fonts/truetype/freefont/FreeSans.ttf",

            # macOS (common locations)
            "/Library/Fonts/Arial.ttf",
            "/Library/Fonts/Arial Unicode.ttf",
            "/System/Library/Fonts/Supplemental/Arial.ttf",
            "/System/Library/Fonts/Supplemental/Arial Unicode.ttf",
            "/System/Library/Fonts/Supplemental/AppleGothic.ttf",
            "/Library/Fonts/DejaVuSans.ttf",
            "/Library/Fonts/NotoSans-Regular.ttf",
        ]
        candidates_bold = [
            # Bundled near the app (recommended for portable builds)
            os.path.join(os.getcwd(), "DejaVuSans-Bold.ttf"),
            os.path.join(os.getcwd(), "fonts", "DejaVuSans-Bold.ttf"),

            # Windows
            "C:/Windows/Fonts/arialbd.ttf",
            "C:/Windows/Fonts/ARIALBD.TTF",

            # Linux (common locations)
            "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
            "/usr/share/fonts/truetype/dejavu/DejaVuSansCondensed-Bold.ttf",
            "/usr/share/fonts/truetype/noto/NotoSans-Bold.ttf",
            "/usr/share/fonts/truetype/freefont/FreeSansBold.ttf",

            # macOS (common locations)
            "/Library/Fonts/Arial Bold.ttf",
            "/System/Library/Fonts/Supplemental/Arial Bold.ttf",
            "/Library/Fonts/DejaVuSans-Bold.ttf",
            "/Library/Fonts/NotoSans-Bold.ttf",
        ]
        reg = _find_ttf(candidates_regular)
        bold = _find_ttf(candidates_bold)
        if reg:
            pdfmetrics.registerFont(TTFont("AppUnicode", reg))
            base = "AppUnicode"
        else:
            base = PDF_BASE_FONT
        if bold:
            pdfmetrics.registerFont(TTFont("AppUnicode-Bold", bold))
            bold_name = "AppUnicode-Bold"
        else:
            # Fake bold by using built-in bold if available
            bold_name = PDF_BOLD_FONT if base == PDF_BASE_FONT else base
        return (base, bold_name)
    except Exception:
        return (PDF_BASE_FONT, PDF_BOLD_FONT)


# --- BEGIN: Rob



def _candidate_note_keys(name: str) -> list[str]:
    raw = (name or "").strip()
    cands = [raw]
    try:
        san = "".join(ch for ch in raw if ch.isalnum())
        up  = raw.upper()
        up_san = "".join(ch for ch in up if ch.isalnum())
        for v in (san, up, up_san):
            if v and v not in cands:
                cands.append(v)
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0030', 'suppressed exception excpass_0030', __spina_exc)
        pass
    return [c for c in cands if c]


# --- BEGIN: Notes key resolver (use candidate keys: raw, stripped, upper, upper-stripped) ---
def _resolve_note_key(notes_dict: dict, name: str) -> str:
    """Return an existing key in notes_dict matching 'name' using _candidate_note_keys.
    If none found, default to the original name.
    """
    try:
        for k in _candidate_note_keys(name):
            if k in notes_dict:
                return k
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0031', 'suppressed exception excpass_0031', __spina_exc)
        pass
    return name
# --- END: Notes key resolver ---
# --- Notes: scope helpers (shared vs loan-type specific) ---
def _normalize_loan_type_value(loan_type: str | None) -> str:
    try:
        v = (loan_type or "").strip()
    except Exception:
        v = ""
    if v.lower().replace(" ", "") in ("7x7","7×7"):
        return "7x7"
    return "Regular"

def _note_scoped_prefix(loan_type: str | None) -> str:
    return _normalize_loan_type_value(loan_type) + "::"

def _note_id_key(kind: str, uid: str | None) -> str | None:
    """Stable notes keys that do NOT depend on client name.

    kind:
      - 'CID' : client_uid (per record)
      - 'PID' : person_uid (shared across Regular/7x7 when linked)

    Uses '|' separators to avoid colliding with legacy '<loan_type>::<name>' keys.
    """
    try:
        u = (uid or "").strip()
    except Exception:
        u = ""
    if not u:
        return None
    return f"{kind}|{u}"

def _note_type_key(person_uid: str | None, loan_type: str | None) -> str | None:
    """Type-scoped key stable across name changes.

    If person_uid exists (linked), store type notes under:
      PT|<person_uid>|<loan_type_norm>

    This lets us retrieve the other loan type's notes without needing that row's client_uid.
    """
    try:
        pid = (person_uid or "").strip()
    except Exception:
        pid = ""
    if not pid:
        return None
    lt = _normalize_loan_type_value(loan_type)
    return f"PT|{pid}|{lt}"

# --- BEGIN: Notes key resolver (stable IDs first; legacy fallback) ---
def _resolve_note_key_scoped(
    notes_dict: dict,
    name: str,
    loan_type: str | None = None,
    scope: str = "shared",
    client_uid: str | None = None,
    person_uid: str | None = None,
) -> str:
    """Resolve a notes_dict key for a client.

    Preferred (stable) keys:
      - shared scope: PID|<person_uid> (or CID|<client_uid> fallback)
      - type scope:   PT|<person_uid>|<loan_type> (or CID|<client_uid> fallback)

    Legacy fallback keys remain supported:
      - shared: name
      - type:   '<loan_type>::<name>'

    Uses candidate keys for case/spacing-insensitivity.
    """
    scope_norm = (scope or "shared").lower().strip()

    key_pid = _note_id_key("PID", person_uid)
    key_cid = _note_id_key("CID", client_uid)
    key_pt  = _note_type_key(person_uid, loan_type)

    if scope_norm in ("shared", "both", "default", "legacy"):
        key_id = key_pid or key_cid
        try:
            if key_id and key_id in notes_dict:
                return key_id
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0032', 'suppressed exception excpass_0032', __spina_exc)
            pass
        # legacy name match
        try:
            for k in _candidate_note_keys(name):
                if k in notes_dict:
                    return k
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0033', 'suppressed exception excpass_0033', __spina_exc)
            pass
        return key_id or (name or "")

    # type scope
    try:
        if key_pt and key_pt in notes_dict:
            return key_pt
        if key_cid and key_cid in notes_dict:
            return key_cid
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0034', 'suppressed exception excpass_0034', __spina_exc)
        pass

    prefix = _note_scoped_prefix(loan_type)
    try:
        for k in _candidate_note_keys(name):
            kk = prefix + k
            if kk in notes_dict:
                return kk
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0035', 'suppressed exception excpass_0035', __spina_exc)
        pass

    return key_pt or key_cid or (prefix + (name or ""))
# --- END: Notes key resolver ---


def _split_scoped_key(key: str) -> tuple[str | None, str]:
    """Return (loan_type_or_none, name) for keys that may be scoped like '7x7::Juan'"""
    try:
        if "::" in (key or ""):
            lt, nm = key.split("::", 1)
            lt = _normalize_loan_type_value(lt)
            return (lt, nm)
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0036', 'suppressed exception excpass_0036', __spina_exc)
        pass
    return (None, key or "")
# --- END Notes: scope helpers ---


# --- Persistent Client Notes (per client, per date) ---
CLIENT_NOTES_PATH = os.path.join(DATA_DIR, "client_notes.json")


# Notes cache (avoid reading/writing JSON on every access)
try:
    _NOTES_LOCK = threading.RLock()
    _NOTES_CACHE = None           # type: ignore
    _NOTES_CACHE_MTIME = None     # type: ignore
except Exception:
    _NOTES_LOCK = None
    _NOTES_CACHE = None
    _NOTES_CACHE_MTIME = None
def _ensure_notes_dir():
    try:
        os.makedirs(os.path.dirname(CLIENT_NOTES_PATH), exist_ok=True)
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0037', 'suppressed exception excpass_0037', __spina_exc)
        pass

def _load_client_notes():
    """
    Load client notes safely (cached).

    - Primary: <APP_DIR>/data/client_notes.json
    - Fallback (legacy): <CWD>/data/client_notes.json
    - Shallow-merge (primary wins on conflicts)
    - Cached in-memory to avoid frequent disk reads.
    - Logs problems to data/spina_app.log and shows a one-time warning if unreadable/corrupt/too large.
    """
    # Ensure globals exist (only once)
    try:
        if "_NOTES_MAX_BYTES" not in globals():
            globals()["_NOTES_MAX_BYTES"] = 5 * 1024 * 1024  # 5MB
        if "_NOTES_ALERTED" not in globals():
            globals()["_NOTES_ALERTED"] = False
    except Exception as e:
        try:
            _log_exc("notes.init_globals", e)
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0038', 'suppressed exception excpass_0038', __spina_exc)
            pass

    global _NOTES_ALERTED, _NOTES_CACHE, _NOTES_CACHE_MTIME

    primary = CLIENT_NOTES_PATH
    fallback = os.path.join(os.getcwd(), "data", "client_notes.json")

    def _warn_once(msg: str):
        global _NOTES_ALERTED
        try:
            if not _NOTES_ALERTED:
                _NOTES_ALERTED = True
                _alert_user("Notes file problem", msg, kind="warning")
        except Exception as e:
            try:
                _log_exc("notes.warn_once", e)
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0039', 'suppressed exception excpass_0039', __spina_exc)
                pass

    def _safe_load_one(p: str, label: str) -> dict:
        if not p:
            return {}
        try:
            if not os.path.exists(p):
                return {}
        except Exception as e:
            _log_exc(f"notes.exists({label})", e)
            return {}

        # Size guard (prevent huge JSON from freezing app)
        try:
            max_bytes = int(globals().get("_NOTES_MAX_BYTES", 5 * 1024 * 1024))
            sz = os.path.getsize(p)
            if sz > max_bytes:
                _log_exc(f"notes.too_large({label})", Exception(f"{sz} bytes > {max_bytes} bytes"))
                _warn_once(
                    "Notes file is too large to load safely.\n\n"
                    f"{p}\n\n"
                    f"Size: {sz} bytes\nLimit: {max_bytes} bytes\n\n"
                    "The app will continue without loading notes. Please archive/trim this file."
                )
                return {}
        except Exception as e:
            _log_exc(f"notes.size_check({label})", e)

        try:
            import json as _json2
            with open(p, "r", encoding="utf-8") as f:
                obj = _json2.load(f)
            if isinstance(obj, dict):
                return obj
            _log_exc(f"notes.not_dict({label})", Exception(f"type={type(obj)}"))
            _warn_once(
                "Notes file format looks invalid (expected JSON object).\n\n"
                f"{p}\n\n"
                "The app will continue without loading notes."
            )
            return {}
        except Exception as e:
            # Quarantine corrupt file to avoid repeated failures
            _log_exc(f"notes.load({label})", e)
            try:
                ts = datetime.now().strftime("%Y%m%d_%H%M%S")
                qp = p + f".corrupt_{ts}"
                os.replace(p, qp)
                _warn_once(
                    "Notes file appears unreadable/corrupt and was quarantined.\n\n"
                    f"Original:\n{p}\n\nQuarantined as:\n{qp}\n\n"
                    "The app will continue without loading notes."
                )
            except Exception as e2:
                _log_exc(f"notes.quarantine({label})", e2)
                _warn_once(
                    "Notes file appears unreadable/corrupt.\n\n"
                    f"{p}\n\n"
                    "The app will continue without loading notes. (Could not quarantine the file.)"
                )
            return {}

    # Cached load: if file mtime hasn't changed, return cached dict
    try:
        lock = globals().get("_NOTES_LOCK")
        if lock:
            with lock:
                try:
                    mtime = os.path.getmtime(primary) if os.path.exists(primary) else None
                except Exception:
                    mtime = None
                if isinstance(_NOTES_CACHE, dict) and (_NOTES_CACHE_MTIME == mtime):
                    return _NOTES_CACHE
        else:
            # no lock available
            try:
                mtime = os.path.getmtime(primary) if os.path.exists(primary) else None
            except Exception:
                mtime = None
            if isinstance(_NOTES_CACHE, dict) and (_NOTES_CACHE_MTIME == mtime):
                return _NOTES_CACHE
    except Exception as e:
        _log_exc("notes.cache_check", e)

    notes = {}
    # Load primary + fallback (merge)
    try:
        d_primary = _safe_load_one(primary, "primary")
        d_fallback = _safe_load_one(fallback, "fallback")
        # Merge: fallback first, then primary overwrites
        try:
            if isinstance(d_fallback, dict):
                notes.update(d_fallback)
            if isinstance(d_primary, dict):
                notes.update(d_primary)
        except Exception as e:
            _log_exc("notes.load.merge.update", e)
    except Exception as e:
        _log_exc("notes.load.merge", e)
        notes = {}

    # Update cache
    try:
        lock = globals().get("_NOTES_LOCK")
        if lock:
            with lock:
                _NOTES_CACHE = notes
                try:
                    _NOTES_CACHE_MTIME = os.path.getmtime(primary) if os.path.exists(primary) else None
                except Exception:
                    _NOTES_CACHE_MTIME = None
        else:
            _NOTES_CACHE = notes
            try:
                _NOTES_CACHE_MTIME = os.path.getmtime(primary) if os.path.exists(primary) else None
            except Exception:
                _NOTES_CACHE_MTIME = None
    except Exception as e:
        _log_exc("notes.cache_update", e)
        _NOTES_CACHE = notes
    return notes
def _save_client_notes(notes: dict) -> bool:
    """
    Save client notes atomically and refresh in-memory cache.
    """
    _ensure_notes_dir()
    try:
        import json as _json2
        tmp = CLIENT_NOTES_PATH + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            _json2.dump(notes, f, ensure_ascii=False, indent=2)
        os.replace(tmp, CLIENT_NOTES_PATH)

        # Refresh cache + mtime
        try:
            lock = globals().get("_NOTES_LOCK")
            if lock:
                with lock:
                    globals()["_NOTES_CACHE"] = notes
                    try:
                        globals()["_NOTES_CACHE_MTIME"] = os.path.getmtime(CLIENT_NOTES_PATH) if os.path.exists(CLIENT_NOTES_PATH) else None
                    except Exception:
                        globals()["_NOTES_CACHE_MTIME"] = None
            else:
                globals()["_NOTES_CACHE"] = notes
                try:
                    globals()["_NOTES_CACHE_MTIME"] = os.path.getmtime(CLIENT_NOTES_PATH) if os.path.exists(CLIENT_NOTES_PATH) else None
                except Exception:
                    globals()["_NOTES_CACHE_MTIME"] = None
        except Exception as e:
            _log_exc("notes.cache_refresh_after_save", e)
        return True
    except Exception as e:
        _log_exc('save_client_notes', e)
        return False
def get_client_note(
    name: str,
    note_date: str | None = None,
    loan_type: str | None = None,
    scope: str = "shared",
    client_uid: str | None = None,
    person_uid: str | None = None,
) -> str:
    """Fetch a note for a client.

    scope:
      - 'shared' (default): shared notes (prefer person_uid/client_uid; legacy name fallback)
      - 'type': loan-type specific notes (prefer person_uid+loan_type or client_uid; legacy fallback)
      - 'effective': prefer type-specific if present, otherwise shared
    """
    try:
        notes = _load_client_notes()

        # Effective: prefer type-scoped note if present, else fall back to shared.
        if (scope or "shared").lower() in ("effective", "auto"):
            try:
                k_type = _resolve_note_key_scoped(
                    notes, name, loan_type, scope="type",
                    client_uid=client_uid, person_uid=person_uid
                )
                ent = notes.get(k_type)
                if isinstance(ent, dict):
                    v = (ent.get(note_date or "__default__") or "").strip()
                    if v:
                        return v
                elif ent is not None:
                    v = str(ent).strip()
                    if v:
                        return v
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0040', 'suppressed exception excpass_0040', __spina_exc)
                pass
            scope = "shared"

        key = _resolve_note_key_scoped(
            notes, name, loan_type, scope=scope,
            client_uid=client_uid, person_uid=person_uid
        )
        entry = notes.get(key)
        if entry is None:
            return ""
        if isinstance(entry, dict):
            return (entry.get(note_date or "__default__") or "").strip()
        return str(entry).strip()
    except Exception:
        return ""


def set_client_note(
    name: str,
    note: str,
    note_date: str | None = None,
    loan_type: str | None = None,
    scope: str = "shared",
    client_uid: str | None = None,
    person_uid: str | None = None,
) -> None:
    """Persist note for client.

    scope:
      - 'shared' (default): shared notes (prefer person_uid/client_uid; legacy name fallback)
      - 'type': loan-type specific notes (prefer person_uid+loan_type or client_uid; legacy fallback)
    """
    notes = _load_client_notes()
    key = _resolve_note_key_scoped(
        notes, name, loan_type, scope=scope,
        client_uid=client_uid, person_uid=person_uid
    )
    entry = notes.get(key)

    dkey = (note_date or "__default__")
    new_val = (str(note).strip() if (note and str(note).strip()) else "")

    # Normalize to dict storage
    if not isinstance(entry, dict):
        entry = ({"__default__": str(entry).strip()} if entry else {})

    old_val = ""
    try:
        old_val = (entry.get(dkey) or "").strip()
    except Exception:
        old_val = ""

    changed = False
    if new_val:
        if old_val != new_val:
            entry[dkey] = new_val
            changed = True
    else:
        # delete
        if dkey in entry:
            entry.pop(dkey, None)
            changed = True

    # No-op: avoid redundant full-file writes
    if not changed:
        return

    if entry:
        notes[key] = entry
    else:
        notes.pop(key, None)

    # Critical: do not silently fail on disk write
    ok = _save_client_notes(notes)
    if not ok:
        raise IOError("Failed to save client notes (data/client_notes.json).")


def get_client_notes_in_range(
    name: str,
    s: str,
    e: str,
    loan_type: str | None = None,
    include_shared: bool = True,
    include_type: bool = True,
    include_other_type: bool = False,
    client_uid: str | None = None,
    person_uid: str | None = None,
) -> list[tuple[str, str]]:
    """Return list of (date, text) notes for 'name' between s and e inclusive.

    - Includes default (undated) note(s) as ("", text) first when present.
    - When include_type=True, includes loan-type specific notes for the current mode.
    - If include_other_type=True, also includes the other loan type (prefixed).
    - Key matching is stable-id first (person_uid/client_uid) with legacy name fallback.
    """
    try:
        from datetime import datetime
        sdt = datetime.strptime(s, "%Y-%m-%d").date()
        edt = datetime.strptime(e, "%Y-%m-%d").date()
        notes = _load_client_notes()
        out: list[tuple[str, str]] = []

        def _add_entry(entry, prefix: str = ""):
            if not isinstance(entry, dict):
                return
            _def = (entry.get("__default__") or "").strip()
            if _def:
                out.append(("", (prefix + _def).strip()))
            for d, txt in entry.items():
                if d == "__default__":
                    continue
                try:
                    dd = datetime.strptime(d, "%Y-%m-%d").date()
                except Exception:
                    continue
                if sdt <= dd <= edt and txt and str(txt).strip():
                    out.append((d, (prefix + str(txt).strip()).strip()))

        if include_shared:
            key_s = _resolve_note_key_scoped(
                notes, name, loan_type, scope="shared",
                client_uid=client_uid, person_uid=person_uid
            )
            _add_entry(notes.get(key_s), prefix="")

        if include_type:
            lt = _normalize_loan_type_value(loan_type)
            key_t = _resolve_note_key_scoped(
                notes, name, loan_type, scope="type",
                client_uid=client_uid, person_uid=person_uid
            )
            _add_entry(notes.get(key_t), prefix=f"[{lt}] ")

            if include_other_type:
                other = ("7x7" if lt != "7x7" else "Regular")
                key_o = _resolve_note_key_scoped(
                    notes, name, other, scope="type",
                    client_uid=client_uid, person_uid=person_uid
                )
                _add_entry(notes.get(key_o), prefix=f"[{other}] ")

        # de-duplicate while preserving meaning
        seen = set()
        uniq: list[tuple[str, str]] = []
        for d, t in out:
            k = (d, t)
            if k in seen:
                continue
            seen.add(k)
            uniq.append((d, t))
        return uniq
    except Exception:
        return []



# --- BEGIN: Notes legacy-name migration (for client rename safety) ---
from spina_app.utilities.notes import _append_unique_text

from spina_app.utilities.notes import _as_note_dict

from spina_app.utilities.notes import _merge_note_dict

def _migrate_legacy_notes_by_name(
    old_name: str,
    loan_type: str | None = None,
    client_uid: str | None = None,
    person_uid: str | None = None,
) -> bool:
    """Migrate legacy name-based notes (old_name and '<loan_type>::old_name') into stable-id keys.

    Use this when a client's name changes to avoid orphaning notes that were stored under the old name.
    Returns True if any changes were saved.
    """
    try:
        old_name = (old_name or "").strip()
        if not old_name:
            return False

        # Stable targets
        key_shared = _note_id_key("PID", person_uid) or _note_id_key("CID", client_uid)
        key_type = _note_type_key(person_uid, loan_type) or _note_id_key("CID", client_uid)

        if not key_shared and not key_type:
            return False

        notes = _load_client_notes()
        changed = False

        # --- shared legacy keys: old name variants ---
        try:
            legacy_shared = []
            for k in _candidate_note_keys(old_name):
                if k in notes:
                    legacy_shared.append(k)

            if legacy_shared and key_shared:
                # merge into stable shared key (even if it already exists)
                merged = _merge_note_dict(notes.get(key_shared), {})
                for lk in legacy_shared:
                    merged = _merge_note_dict(merged, notes.get(lk))
                if merged:
                    notes[key_shared] = merged
                    changed = True
                for lk in legacy_shared:
                    notes.pop(lk, None)
                    changed = True
        except Exception as e:
            _log_exc("notes:migrate_legacy_shared_by_name", e)

        # --- type legacy keys: '<loan_type>::old name variants' ---
        try:
            prefix = _note_scoped_prefix(loan_type)
            legacy_type = []
            for k in _candidate_note_keys(old_name):
                kk = prefix + k
                if kk in notes:
                    legacy_type.append(kk)

            if legacy_type and key_type:
                merged = _merge_note_dict(notes.get(key_type), {})
                for lk in legacy_type:
                    merged = _merge_note_dict(merged, notes.get(lk))
                if merged:
                    notes[key_type] = merged
                    changed = True
                for lk in legacy_type:
                    notes.pop(lk, None)
                    changed = True
        except Exception as e:
            _log_exc("notes:migrate_legacy_type_by_name", e)

        if changed:
            ok = _save_client_notes(notes)
            return bool(ok)
        return False
    except Exception as e:
        _log_exc("notes:migrate_legacy_by_name", e)
        return False
# --- END: Notes legacy-name migration ---

# --- BEGIN: Note Editor Dialog (improved UI + autosave) ---
class NoteEditorDialog(tk.Toplevel):
    '''Improved per-client notes editor.

    Features:
      - Dated and undated notes
      - Scope: Shared (both Regular/7x7) or This loan type
      - Left panel: list of existing notes (with search)
      - Autosave (debounced) + unsaved indicator
      - Safe switching between notes (prompts if needed)
    Notes storage is handled by get_client_note()/set_client_note() -> data/client_notes.json
    '''

    def __init__(self, master, client_name: str, default_date: str = "", loan_type: str | None = None, client_uid: str | None = None, person_uid: str | None = None):
        super().__init__(master)
        self.client_name = (client_name or "").strip()
        self.loan_type = loan_type
        self.client_uid = (client_uid or "").strip() or None
        self.person_uid = (person_uid or "").strip() or None

        # Best-effort: migrate any legacy name-based notes to stable-id keys
        try:
            self._migrate_legacy_notes_if_needed()
        except Exception as _e:
            try:
                _log_exc("notes:migrate_legacy", _e)
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0041', 'suppressed exception excpass_0041', __spina_exc)
                pass

        self._dirty = False
        self._autosave_job = None
        self._switching = False
        self._last_saved_sig = ""
        self._active_item = None  # (date, scope)

        self.title(self._title_text())
        self.minsize(760, 440)
        self.transient(master)
        try:
            self.grab_set()
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0042', 'suppressed exception excpass_0042', __spina_exc)
            pass

        # Vars
        self.date_var = tk.StringVar(value=(default_date or "").strip())
        self.scope_var = tk.StringVar(value=("type" if loan_type else "shared"))
        self.search_var = tk.StringVar(value="")
        self.autosave_var = tk.BooleanVar(value=True)
        self.status_var = tk.StringVar(value="")

        # Choose scope based on existing note for the default date
        self._auto_choose_scope()

        self._build_ui()
        self._refresh_list()
        self._load_note(set_active=True)

        self.bind("<Escape>", lambda e: self._close())
        self.protocol("WM_DELETE_WINDOW", self._close)

        # Shortcuts
        self.bind("<Control-s>", lambda e: self._save_note(user_action=True))
        self.bind("<Control-S>", lambda e: self._save_note(user_action=True))
        self.bind("<Control-Return>", lambda e: self._save_and_close())
        self.bind("<Control-Enter>", lambda e: self._save_and_close())  # some keyboards
        self.bind("<Control-f>", lambda e: self._focus_search())
        self.bind("<Control-F>", lambda e: self._focus_search())

        # Center on parent (best-effort)
        try:
            self.update_idletasks()
            x = master.winfo_rootx() + (master.winfo_width() // 2 - self.winfo_width() // 2)
            y = master.winfo_rooty() + (master.winfo_height() // 2 - self.winfo_height() // 2)
            self.geometry(f"+{x}+{y}")
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0043', 'suppressed exception excpass_0043', __spina_exc)
            pass

    # ---------- helpers ----------
    def _migrate_legacy_notes_if_needed(self):
        """Move legacy name-based keys into stable-id keys for this client (best-effort).

        This prevents collisions if names repeat, and keeps notes attached even if a name changes.
        Runs only when we have a stable id (person_uid or client_uid).
        """
        # Determine stable targets
        key_shared = _note_id_key("PID", self.person_uid) or _note_id_key("CID", self.client_uid)
        key_type = _note_type_key(self.person_uid, self.loan_type) or _note_id_key("CID", self.client_uid)

        if not key_shared and not key_type:
            return

        notes = _load_client_notes()
        changed = False

        # Shared legacy keys: name variants
        try:
            legacy_shared = []
            for k in _candidate_note_keys(self.client_name):
                if k in notes:
                    legacy_shared.append(k)
            if key_shared and key_shared not in notes and legacy_shared:
                # merge legacy entries into stable key
                merged = {}
                for lk in legacy_shared:
                    ent = notes.get(lk)
                    if isinstance(ent, dict):
                        merged.update(ent)
                    elif ent:
                        merged.setdefault("__default__", str(ent).strip())
                if merged:
                    notes[key_shared] = merged
                    changed = True
                for lk in legacy_shared:
                    notes.pop(lk, None)
                    changed = True
        except Exception as e:
            _log_exc("notes:migrate_legacy_shared", e)

        # Type legacy keys: '<loan_type>::<name>' variants
        try:
            prefix = _note_scoped_prefix(self.loan_type)
            legacy_type = []
            for k in _candidate_note_keys(self.client_name):
                kk = prefix + k
                if kk in notes:
                    legacy_type.append(kk)
            if key_type and key_type not in notes and legacy_type:
                merged = {}
                for lk in legacy_type:
                    ent = notes.get(lk)
                    if isinstance(ent, dict):
                        merged.update(ent)
                    elif ent:
                        merged.setdefault("__default__", str(ent).strip())
                if merged:
                    notes[key_type] = merged
                    changed = True
                for lk in legacy_type:
                    notes.pop(lk, None)
                    changed = True
        except Exception as e:
            _log_exc("notes:migrate_legacy_type", e)

        if changed:
            try:
                _save_client_notes(notes)
            except Exception as e:
                _log_exc("notes:migrate_legacy_save", e)

    def _title_text(self):
        star = " *" if getattr(self, "_dirty", False) else ""
        return f"Notes - {self.client_name}{star}"

    def _set_dirty(self, val: bool):
        self._dirty = bool(val)
        try:
            self.title(self._title_text())
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0044', 'suppressed exception excpass_0044', __spina_exc)
            pass

    def _note_date_value(self):
        nd = (self.date_var.get() or "").strip()
        return nd if nd else None

    def _sig_for_text(self, t: str) -> str:
        try:
            import hashlib
            return hashlib.sha1((t or "").encode("utf-8")).hexdigest()
        except Exception:
            return str(len(t or ""))

    def _validate_date_or_warn(self) -> bool:
        nd = (self.date_var.get() or "").strip()
        if not nd:
            return True  # undated allowed
        try:
            datetime.strptime(nd[:10], "%Y-%m-%d")
            return True
        except Exception:
            try:
                messagebox.showerror("Invalid Date", "Use YYYY-MM-DD (example: 2026-02-06) or leave blank for default note.")
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0045', 'suppressed exception excpass_0045', __spina_exc)
                pass
            return False

    def _auto_choose_scope(self):
        # Simplified notes scope: use THIS LOAN TYPE when loan_type is known.
        try:
            if self.loan_type:
                self.scope_var.set("type")
            else:
                self.scope_var.set("shared")
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0046', 'suppressed exception excpass_0046', __spina_exc)
            pass

    def _scope_label(self, scope: str) -> str:
        scope = (scope or ("type" if self.loan_type else "shared")).lower().strip()
        if scope == "type":
            lt = _normalize_loan_type_value(self.loan_type)
            return f"[{lt}]"
        return "[Note]"

    def _format_list_item(self, scope: str, d: str, text: str) -> str:
        date_part = (d if d else "(default)")
        snippet = (text or "").replace("\n", " ").strip()
        if len(snippet) > 50:
            snippet = snippet[:50].rstrip() + "…"
        return f"{self._scope_label(scope)} {date_part} — {snippet}"

    def _focus_search(self):
        try:
            self.search_entry.focus_set()
            self.search_entry.select_range(0, "end")
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0047', 'suppressed exception excpass_0047', __spina_exc)
            pass

    # ---------- UI ----------
    def _build_ui(self):
        outer = ttk.Frame(self, padding=10)
        outer.pack(fill="both", expand=True)

        hdr = ttk.Frame(outer)
        hdr.pack(fill="x")

        ttk.Label(hdr, text="Client:", width=8).pack(side="left")
        ttk.Label(hdr, text=self.client_name, font=("TkDefaultFont", 10, "bold")).pack(side="left")

        lt_txt = _normalize_loan_type_value(self.loan_type) if self.loan_type else "—"
        ttk.Label(hdr, text="   Loan Type:", padding=(12, 0, 0, 0)).pack(side="left")
        ttk.Label(hdr, text=lt_txt).pack(side="left")

        main = tk.PanedWindow(outer, orient="horizontal", sashrelief="raised")
        main.pack(fill="both", expand=True, pady=(10, 0))

        # Left panel
        left = ttk.Frame(main, padding=(0, 0, 10, 0))
        main.add(left, minsize=240)

        srow = ttk.Frame(left)
        srow.pack(fill="x", pady=(0, 6))
        ttk.Label(srow, text="Search:").pack(side="left")
        self.search_entry = ttk.Entry(srow, textvariable=self.search_var)
        self.search_entry.pack(side="left", fill="x", expand=True, padx=(6, 0))
        self.search_entry.bind("<KeyRelease>", lambda e: self._refresh_list())

        self.listbox = tk.Listbox(left, activestyle="dotbox", height=14)
        lsb = ttk.Scrollbar(left, orient="vertical", command=self.listbox.yview)
        self.listbox.configure(yscrollcommand=lsb.set)
        self.listbox.pack(side="left", fill="both", expand=True)
        lsb.pack(side="right", fill="y")
        self.listbox.bind("<<ListboxSelect>>", lambda e: self._on_list_select())

        lbtn = ttk.Frame(left)
        lbtn.pack(fill="x", pady=(6, 0))
        ttk.Button(lbtn, text="Refresh", command=self._refresh_list).pack(side="left")
        ttk.Button(lbtn, text="Today", command=self._jump_today).pack(side="left", padx=(6, 0))
        ttk.Button(lbtn, text="Default", command=self._jump_default).pack(side="left", padx=(6, 0))

        # Right panel
        right = ttk.Frame(main)
        main.add(right)

        ctrl = ttk.Frame(right)
        ctrl.pack(fill="x", pady=(0, 6))

        ttk.Label(ctrl, text="Note Date:").pack(side="left")
        self.date_entry = ttk.Entry(ctrl, textvariable=self.date_var, width=12)
        self.date_entry.pack(side="left", padx=(6, 4))
        ttk.Button(ctrl, text="📅", width=3, command=self._pick_date).pack(side="left")
        ttk.Button(ctrl, text="Load", command=lambda: self._load_note(set_active=True)).pack(side="left", padx=(6, 0))

        scope = ttk.Frame(right)
        scope.pack(fill="x", pady=(2, 6))
        if self.loan_type:
            self.scope_var.set("type")
            ttk.Label(scope, text=f"Scope: {_normalize_loan_type_value(self.loan_type)}").pack(side="left")
        else:
            self.scope_var.set("shared")
            ttk.Label(scope, text="Scope: Default").pack(side="left")

        txt_frame = ttk.Frame(right)
        txt_frame.pack(fill="both", expand=True)

        self.txt = tk.Text(txt_frame, wrap="word", height=10, undo=True, maxundo=2000, autoseparators=True)
        ysb = ttk.Scrollbar(txt_frame, orient="vertical", command=self.txt.yview)
        self.txt.configure(yscrollcommand=ysb.set)
        self.txt.pack(side="left", fill="both", expand=True)
        ysb.pack(side="right", fill="y")

        self.txt.bind("<<Modified>>", self._on_text_modified)

        status_row = ttk.Frame(right)
        status_row.pack(fill="x", pady=(6, 0))
        ttk.Checkbutton(status_row, text="Auto-save", variable=self.autosave_var).pack(side="left")
        ttk.Label(status_row, textvariable=self.status_var).pack(side="left", padx=(10, 0))

        footer = ttk.Frame(right)
        footer.pack(fill="x", pady=(8, 0))
        ttk.Button(footer, text="Open Notes File", command=self._open_notes_file).pack(side="left")
        ttk.Button(footer, text="Clear", command=self._clear_text).pack(side="left", padx=(6, 0))
        ttk.Button(footer, text="Save", command=lambda: self._save_note(user_action=True)).pack(side="right")
        ttk.Button(footer, text="Delete", command=self._delete_note).pack(side="right", padx=(0, 6))
        ttk.Button(footer, text="Close", command=self._close).pack(side="right", padx=(0, 6))

    # ---------- list handling ----------
    def _collect_items(self):
        items = []

        def add_scope(scope: str):
            try:
                notes = _load_client_notes()
                key = _resolve_note_key_scoped(
                    notes, self.client_name, self.loan_type, scope=scope,
                    client_uid=self.client_uid, person_uid=self.person_uid
                )
                entry = notes.get(key)
                if not isinstance(entry, dict):
                    entry = ({"__default__": str(entry).strip()} if entry else {})
                if not isinstance(entry, dict):
                    return
                _def = (entry.get("__default__") or "").strip()
                if _def:
                    items.append({"scope": scope, "date": "", "text": _def})
                dated = []
                for d, t in entry.items():
                    if d == "__default__":
                        continue
                    if not (t and str(t).strip()):
                        continue
                    dated.append((str(d), str(t).strip()))
                dated.sort(key=lambda it: it[0], reverse=True)
                for d, t in dated:
                    items.append({"scope": scope, "date": d, "text": t})
            except Exception:
                return

        if self.loan_type:
            add_scope("type")
        else:
            add_scope("shared")

        q = (self.search_var.get() or "").strip().lower()
        if q:
            items = [it for it in items if q in (it["date"] or "").lower() or q in (it["text"] or "").lower()]

        for it in items:
            it["display"] = self._format_list_item(it["scope"], it["date"], it["text"])

        return items

    def _refresh_list(self):
        try:
            self._items = self._collect_items()
        except Exception:
            self._items = []
        try:
            self.listbox.delete(0, "end")
            for it in self._items:
                self.listbox.insert("end", it.get("display", ""))
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0049', 'suppressed exception excpass_0049', __spina_exc)
            pass

        try:
            if self._active_item and self._items:
                ad, ascope = self._active_item
                for i, it in enumerate(self._items):
                    if it.get("date") == ad and it.get("scope") == ascope:
                        self.listbox.selection_clear(0, "end")
                        self.listbox.selection_set(i)
                        self.listbox.see(i)
                        break
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0050', 'suppressed exception excpass_0050', __spina_exc)
            pass

    def _on_list_select(self):
        if getattr(self, "_switching", False):
            return
        try:
            sel = self.listbox.curselection()
            if not sel:
                return
            idx = int(sel[0])
            if idx < 0 or idx >= len(getattr(self, "_items", [])):
                return
            it = self._items[idx]
            tgt_date = it.get("date", "")
            tgt_scope = it.get("scope", "shared")
        except Exception:
            return

        if not self._confirm_before_switch():
            self._refresh_list()
            return

        try:
            self._switching = True
            self.date_var.set(tgt_date)
            self.scope_var.set(tgt_scope)
            self._load_note(set_active=True)
        finally:
            self._switching = False

    # ---------- actions ----------
    def _pick_date(self):
        if not self._confirm_before_switch():
            return
        try:
            pick_date(self, self.date_var, initial=self.date_var.get(), title="Select Note Date")
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0051', 'suppressed exception excpass_0051', __spina_exc)
            pass
        self._load_note(set_active=True)

    def _jump_today(self):
        if not self._confirm_before_switch():
            return
        try:
            self.date_var.set(datetime.now().strftime("%Y-%m-%d"))
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0052', 'suppressed exception excpass_0052', __spina_exc)
            pass
        if self.loan_type:
            self.scope_var.set("type")
        self._load_note(set_active=True)

    def _jump_default(self):
        if not self._confirm_before_switch():
            return
        self.date_var.set("")
        if self.loan_type:
            self.scope_var.set("type")
        self._load_note(set_active=True)

    def _clear_text(self):
        if not self._confirm_before_switch(clear_only=True):
            return
        try:
            self.txt.delete("1.0", "end")
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0053', 'suppressed exception excpass_0053', __spina_exc)
            pass
        self._set_dirty(True)
        self._schedule_autosave()

    def _open_notes_file(self):
        try:
            _open_path(CLIENT_NOTES_PATH)
        except Exception:
            try:
                messagebox.showinfo("Notes File", CLIENT_NOTES_PATH)
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0054', 'suppressed exception excpass_0054', __spina_exc)
                pass

    # ---------- load/save ----------
    def _load_note(self, set_active: bool = False):
        if not self._validate_date_or_warn():
            return
        nd = self._note_date_value()
        scope = ("type" if self.loan_type else (self.scope_var.get() or "shared").strip().lower())
        if scope not in ("shared", "type"):
            scope = ("type" if self.loan_type else "shared")

        try:
            note = get_client_note(self.client_name, nd, loan_type=self.loan_type, scope=scope, client_uid=self.client_uid, person_uid=self.person_uid) or ""
        except Exception:
            note = ""

        try:
            self.txt.delete("1.0", "end")
            self.txt.insert("1.0", note)
            self.txt.edit_modified(False)
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0055', 'suppressed exception excpass_0055', __spina_exc)
            pass

        self._last_saved_sig = self._sig_for_text(note)
        self._set_dirty(False)

        if set_active:
            self._active_item = (nd or "", scope)
            self._refresh_list()

        try:
            self.status_var.set("Loaded.")
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0056', 'suppressed exception excpass_0056', __spina_exc)
            pass

    def _save_note(self, user_action: bool = False, silent: bool = False):
        if not self._validate_date_or_warn():
            return False
        nd = self._note_date_value()
        scope = ("type" if self.loan_type else (self.scope_var.get() or "shared").strip().lower())
        if scope not in ("shared", "type"):
            scope = ("type" if self.loan_type else "shared")

        try:
            note = self.txt.get("1.0", "end").strip()
        except Exception:
            note = ""

        sig = self._sig_for_text(note)
        if sig == self._last_saved_sig and not self._dirty:
            if user_action and not silent:
                try:
                    self.status_var.set("Nothing to save.")
                except Exception as __spina_exc:
                    _log_suppressed_once('excpass_0057', 'suppressed exception excpass_0057', __spina_exc)
                    pass
            return True

        try:
            set_client_note(self.client_name, note, nd, loan_type=self.loan_type, scope=scope, client_uid=self.client_uid, person_uid=self.person_uid)
            self._last_saved_sig = sig
            self._set_dirty(False)
            self._active_item = (nd or "", scope)
            self._refresh_list()
            try:
                self.status_var.set(f"Saved {datetime.now().strftime('%H:%M:%S')}")
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0058', 'suppressed exception excpass_0058', __spina_exc)
                pass
            return True
        except Exception as e:
            if not silent:
                try:
                    messagebox.showerror("Error", f"Failed to save note: {e}")
                except Exception as __spina_exc:
                    _log_suppressed_once('excpass_0059', 'suppressed exception excpass_0059', __spina_exc)
                    pass
            return False

    def _delete_note(self):
        if not self._validate_date_or_warn():
            return
        nd = self._note_date_value()
        scope = ("type" if self.loan_type else (self.scope_var.get() or "shared").strip().lower())
        if scope not in ("shared", "type"):
            scope = ("type" if self.loan_type else "shared")

        label = (nd if nd else "default")
        try:
            if not messagebox.askyesno("Delete Note", f"Delete {self._scope_label(scope)} {label} note?\n\nThis cannot be undone."):
                return
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0060', 'suppressed exception excpass_0060', __spina_exc)
            pass

        try:
            set_client_note(self.client_name, "", nd, loan_type=self.loan_type, scope=scope, client_uid=self.client_uid, person_uid=self.person_uid)
        except Exception as e:
            _log_exc('notes:delete_note', e)
            messagebox.showerror('Delete Note', f'Failed to delete note.\n\n{e}\n\nSee log: data/spina_app.log')
            return
        try:
            self.txt.delete("1.0", "end")
            self.txt.edit_modified(False)
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0061', 'suppressed exception excpass_0061', __spina_exc)
            pass

        self._last_saved_sig = self._sig_for_text("")
        self._set_dirty(False)
        self._active_item = (nd or "", scope)
        self._refresh_list()
        try:
            self.status_var.set("Deleted.")
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0062', 'suppressed exception excpass_0062', __spina_exc)
            pass

    # ---------- dirty / autosave / switching ----------
    def _on_text_modified(self, event=None):
        try:
            if self.txt.edit_modified():
                self.txt.edit_modified(False)
                self._set_dirty(True)
                self._schedule_autosave()
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0063', 'suppressed exception excpass_0063', __spina_exc)
            pass

    def _schedule_autosave(self):
        if not bool(self.autosave_var.get()):
            return
        try:
            if self._autosave_job:
                self.after_cancel(self._autosave_job)
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0064', 'suppressed exception excpass_0064', __spina_exc)
            pass
        try:
            self._autosave_job = self.after(1200, lambda: self._save_note(user_action=False, silent=True))
        except Exception:
            self._autosave_job = None

    def _confirm_before_switch(self, clear_only: bool = False) -> bool:
        if not self._dirty:
            return True

        if bool(self.autosave_var.get()):
            ok = self._save_note(user_action=False, silent=True)
            return bool(ok)

        try:
            resp = messagebox.askyesnocancel("Unsaved changes", "You have unsaved changes.\n\nYes = Save\nNo = Discard\nCancel = Keep editing")
        except Exception:
            resp = None

        if resp is None:
            return False
        if resp is True:
            return bool(self._save_note(user_action=True, silent=False))
        self._set_dirty(False)
        return True

    def _save_and_close(self):
        if self._save_note(user_action=True, silent=False):
            self._close()

    def _close(self):
        if not self._confirm_before_switch():
            return
        try:
            self.grab_release()
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0065', 'suppressed exception excpass_0065', __spina_exc)
            pass
        self.destroy()
