def parse_advance_ranges(desc: str):
    """Parse one or more ADV date ranges from a transaction description.

    Supported tags (whitespace/case-tolerant):
      - [ADV:YYYY-MM-DD..YYYY-MM-DD]                 (single range)
      - [ADV:YYYY-MM-DD,YYYY-MM-DD,YYYY-MM-DD]       (explicit days)
      - [ADV:range;range;...] where range is either:
          * YYYY-MM-DD..YYYY-MM-DD
          * YYYY-MM-DD (single day)
          * comma-separated day list

    Returns: list[(start, end)] with YYYY-MM-DD strings (sorted, normalized).
    """
    import re as _re
    if not desc:
        return []

    txt = str(desc)

    # Find all [ADV: ... ] tags (some imports may append multiple tags).
    tags = list(_re.finditer(r"\[\s*ADV\s*:\s*([^\]]+)\]", txt, flags=_re.IGNORECASE))
    if not tags:
        # No bracket tags found; fall back to plain-text ADV ranges like:
        #   'ADV 2026-02-01 to 2026-02-03' or 'Advance 2026-02-01 - 2026-02-03'
        try:
            _plain_re = globals().get('_ADV_PLAIN_RE')
            if _plain_re is None:
                _plain_re = _re.compile(r"\badv(ance)?\b[^0-9]*(\d{4}-\d{2}-\d{2})\s*(?:to|-|–|—|\.\.)\s*(\d{4}-\d{2}-\d{2})", _re.IGNORECASE)
            ms = list(_plain_re.finditer(txt))
            if not ms:
                return []
            out = []
            for m in ms:
                a = (m.group(2) or '').strip()
                b = (m.group(3) or '').strip()
                if a and b:
                    out.append((a, b) if a <= b else (b, a))
            out = sorted(set(out), key=lambda x: (x[0], x[1]))
            return out
        except Exception:
            return []

    def _is_date(s: str) -> bool:
        return bool(_re.fullmatch(r"\d{4}-\d{2}-\d{2}", (s or "").strip()))

    # Collect explicit days, then compress to ranges.
    days = set()
    ranges = []

    for mt in tags:
        inner = (mt.group(1) or "").strip()
        if not inner:
            continue

        # Split into segments (for multi-range). If no separators, treat as one segment.
        segs = [x.strip() for x in _re.split(r"[;|]", inner) if x.strip()]
        for seg in segs:
            # range (inclusive)
            if ".." in seg:
                a, b = [x.strip() for x in seg.split("..", 1)]
                if _is_date(a) and _is_date(b):
                    ranges.append((a, b) if a <= b else (b, a))
                continue

            # otherwise, treat as day or day-list
            parts = [p.strip() for p in seg.split(",") if p.strip()]
            for p in parts:
                if _is_date(p):
                    days.add(p)

    if days:
        sd = sorted(days)
        # compress contiguous days into ranges
        from datetime import datetime as _dt, timedelta as _td
        cur_s = sd[0]
        cur_e = sd[0]
        for d in sd[1:]:
            try:
                prev = _dt.strptime(cur_e, "%Y-%m-%d")
                nxt = _dt.strptime(d, "%Y-%m-%d")
                if prev + _td(days=1) == nxt:
                    cur_e = d
                else:
                    ranges.append((cur_s, cur_e))
                    cur_s = d
                    cur_e = d
            except Exception:
                # if parsing fails, just break ranges conservatively
                ranges.append((cur_s, cur_e))
                cur_s = d
                cur_e = d
        ranges.append((cur_s, cur_e))

    # Normalize and sort
    norm = []
    for a, b in ranges:
        if _is_date(a) and _is_date(b):
            norm.append((a, b) if a <= b else (b, a))
    norm.sort(key=lambda x: (x[0], x[1]))
    # De-duplicate (some descriptions may contain repeated tags)
    uniq = []
    seen = set()
    for it in norm:
        if it in seen:
            continue
        seen.add(it)
        uniq.append(it)
    return uniq

def parse_advance_range(desc: str):
    """Backward-compatible helper: return first (start,end) ADV range if present."""
    rs = parse_advance_ranges(desc)
    return rs[0] if rs else (None, None)



# --- BEGIN: SQLite thread-safety wrappers (serialize access across threads) ---
# Tkinter runs on the main thread, but long operations may use background threads.
# SQLite connections are not safely concurrent without external serialization.
# These lightweight wrappers ensure *all* cursor/execute/commit calls are guarded by a single re-entrant lock.
class _LockedCursor:
    def __init__(self, cur, lock):
        self._cur = cur
        self._lock = lock

    def execute(self, *args, **kwargs):
        sql = args[0] if args else ""
        if _is_write_sql(sql):
            def _op():
                with self._lock:
                    try:
                        conn = getattr(self._cur, "connection", None)
                        if conn is not None and not getattr(conn, "in_transaction", False):
                            try:
                                conn.execute("BEGIN IMMEDIATE")
                            except Exception as __spina_exc:
                                _log_suppressed_once('excpass_0066', 'suppressed exception excpass_0066', __spina_exc)
                                pass
                    except Exception as __spina_exc:
                        _log_suppressed_once('excpass_0067', 'suppressed exception excpass_0067', __spina_exc)
                        pass
                    return self._cur.execute(*args, **kwargs)
            run_write(_op)
            return self
        else:
            with self._lock:
                self._cur.execute(*args, **kwargs)
            return self

    def executemany(self, *args, **kwargs):
        sql = args[0] if args else ""
        if _is_write_sql(sql):
            def _op():
                with self._lock:
                    try:
                        conn = getattr(self._cur, "connection", None)
                        if conn is not None and not getattr(conn, "in_transaction", False):
                            try:
                                conn.execute("BEGIN IMMEDIATE")
                            except Exception as __spina_exc:
                                _log_suppressed_once('excpass_0068', 'suppressed exception excpass_0068', __spina_exc)
                                pass
                    except Exception as __spina_exc:
                        _log_suppressed_once('excpass_0069', 'suppressed exception excpass_0069', __spina_exc)
                        pass
                    return self._cur.executemany(*args, **kwargs)
            run_write(_op)
            return self
        else:
            with self._lock:
                self._cur.executemany(*args, **kwargs)
            return self

    def fetchone(self, *args, **kwargs):
        with self._lock:
            return self._cur.fetchone(*args, **kwargs)

    def fetchall(self, *args, **kwargs):
        with self._lock:
            return self._cur.fetchall(*args, **kwargs)

    def fetchmany(self, *args, **kwargs):
        with self._lock:
            return self._cur.fetchmany(*args, **kwargs)

    def close(self):
        with self._lock:
            try:
                return self._cur.close()
            except Exception:
                return None

    def __iter__(self):
        # Materialize rows under the lock to avoid interleaving reads across threads.
        return iter(self.fetchall())

    def __getattr__(self, name):
        return getattr(self._cur, name)


class _LockedConnection:
    def __init__(self, conn, lock):
        self._conn = conn
        self._lock = lock

    def cursor(self, *args, **kwargs):
        with self._lock:
            cur = self._conn.cursor(*args, **kwargs)
        return _LockedCursor(cur, self._lock)

    def execute(self, *args, **kwargs):
        sql = args[0] if args else ""
        if _is_write_sql(sql):
            def _op():
                with self._lock:
                    try:
                        if not getattr(self._conn, "in_transaction", False):
                            try:
                                self._conn.execute("BEGIN IMMEDIATE")
                            except Exception as __spina_exc:
                                _log_suppressed_once('excpass_0070', 'suppressed exception excpass_0070', __spina_exc)
                                pass
                    except Exception as __spina_exc:
                        _log_suppressed_once('excpass_0071', 'suppressed exception excpass_0071', __spina_exc)
                        pass
                    cur = self._conn.execute(*args, **kwargs)
                    return cur
            cur = run_write(_op)
            return _LockedCursor(cur, self._lock)
        else:
            with self._lock:
                cur = self._conn.execute(*args, **kwargs)
            return _LockedCursor(cur, self._lock)

    def executemany(self, *args, **kwargs):
        sql = args[0] if args else ""
        if _is_write_sql(sql):
            def _op():
                with self._lock:
                    try:
                        if not getattr(self._conn, "in_transaction", False):
                            try:
                                self._conn.execute("BEGIN IMMEDIATE")
                            except Exception as __spina_exc:
                                _log_suppressed_once('excpass_0072', 'suppressed exception excpass_0072', __spina_exc)
                                pass
                    except Exception as __spina_exc:
                        _log_suppressed_once('excpass_0073', 'suppressed exception excpass_0073', __spina_exc)
                        pass
                    cur = self._conn.executemany(*args, **kwargs)
                    return cur
            cur = run_write(_op)
            return _LockedCursor(cur, self._lock)
        else:
            with self._lock:
                cur = self._conn.executemany(*args, **kwargs)
            return _LockedCursor(cur, self._lock)

    def commit(self):
        def _op():
            with self._lock:
                return self._conn.commit()
        return run_write(_op)

    def rollback(self):
        with self._lock:
            return self._conn.rollback()

    def close(self):
        with self._lock:
            try:
                return self._conn.close()
            except Exception:
                return None

    def __getattr__(self, name):
        return getattr(self._conn, name)


# --- END: SQLite thread-safety wrappers ---


class LoanDB:
    def __init__(self, path=DB_FILE):
        import os, sqlite3

        self.path = path

        self._last_error = ''
        init_needed = not os.path.exists(self.path)

        # open / create DB
        self._db_lock = threading.RLock()
        self._raw_conn = connect_db(self.path)
        self._raw_conn.row_factory = sqlite3.Row
        # Best-effort pragmas for robustness; safe if unsupported.
        try:
            self._raw_conn.execute("PRAGMA foreign_keys = ON")
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0074', 'suppressed exception excpass_0074', __spina_exc)
            pass
        try:
            # journal_mode/synchronous are handled by connect_db()
            pass
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0075', 'suppressed exception excpass_0075', __spina_exc)
            pass
        self.conn = _LockedConnection(self._raw_conn, self._db_lock)

        # ensure schema
        self._create_tables()

        # (optional) seed demo data on first run
        # if init_needed:
        #     self._insert_demo_data()
    
    def _set_last_error(self, msg):
        try:
            self._last_error = str(msg or '')
        except Exception:
            self._last_error = ''

    def get_last_error(self):
        try:
            return getattr(self, '_last_error', '') or ''
        except Exception:
            return ''

    def _norm_lt(self, lt):
        lt = (str(lt or '').strip() or '')
        if lt.lower().replace(' ', '') in ('7x7', '7×7'):
            return '7x7'
        return 'Regular'

    def set_default_loan_type(self, lt):
        """Set the default loan_type context used when caller does not pass loan_type."""
        try:
            self.default_loan_type = self._norm_lt(lt)
        except Exception:
            self.default_loan_type = 'Regular'

    def _effective_lt(self, loan_type):
        if loan_type is None:
            return getattr(self, 'default_loan_type', 'Regular')
        return self._norm_lt(loan_type)

