            _ensure_column("renewals", "released_cash", "ALTER TABLE renewals ADD COLUMN released_cash REAL DEFAULT 0")
            _ensure_column("renewals", "principal_after", "ALTER TABLE renewals ADD COLUMN principal_after REAL DEFAULT 0")
            _ensure_column("renewals", "interest_rate", "ALTER TABLE renewals ADD COLUMN interest_rate REAL DEFAULT 0")
