    def _active_client_name_exists(self, name: str, loan_type=None, exclude_client_uid: str | None = None) -> bool:
        """True if an active client already uses this exact visible name in the same loan type."""
        try:
            nm = " ".join(str(name or "").strip().split())
        except Exception:
            nm = str(name or "").strip()
        if not nm:
            return False
        try:
            lt = self._effective_lt(loan_type)
        except Exception:
            _lt_raw = str(loan_type or '').strip().lower().replace(' ', '')
            lt = '7x7' if _lt_raw in ('7x7', '7×7') else 'Regular'
        try:
            cur = self.conn.cursor()
            sql = (
                "SELECT 1 FROM clients "
                "WHERE UPPER(TRIM(name)) = UPPER(TRIM(?)) "
                "AND IFNULL(NULLIF(TRIM(loan_type),''),'Regular') = IFNULL(NULLIF(TRIM(?),''),'Regular') "
                "AND IFNULL(is_archived,0)=0"
            )
            params = [nm, lt]
            ex = str(exclude_client_uid or "").strip()
            if ex:
                sql += " AND IFNULL(client_uid,'') <> ?"
                params.append(ex)
            sql += " LIMIT 1"
            return bool(cur.execute(sql, tuple(params)).fetchone())
        except Exception:
            return False

    def add_client(self, name, principal=0.0, date_released=None, area=None, interest_rate=None, new_until=None, loan_type=None, pay_start_offset_days=1, contact_number='', payment_term='Daily', payment_amount=0.0, payment_mode='Cash', due_weekday='', semi_due_day1=None, semi_due_day2=None, monthly_due_day=None, flex_due_rule=''):
        cur = self.conn.cursor()
        now = date.today().strftime("%Y-%m-%d")
        try:
            p = float(principal or 0)
        except Exception:
            p = 0.0
        try:
            rate = float(interest_rate) if interest_rate is not None else 0.20
            # treat 20 as 20% if user enters whole percent
            if rate > 1.0:
                rate = rate / 100.0
        except Exception:
            rate = 0.20

        # Normalize loan_type
        lt = (str(loan_type or '').strip() or '')
        if not lt:
            lt = '7x7' if '7X7' in (name or '').upper() else 'Regular'
        elif lt.lower().replace(' ', '') in ('7x7','7×7'):
            lt = '7x7'
        else:
            lt = 'Regular'

        # Prevent duplicate active client names only within the same loan type.
        try:
            _name_exact = " ".join(str(name or "").strip().split())
        except Exception:
            _name_exact = str(name or "").strip()
        if _name_exact and self._active_client_name_exists(_name_exact, loan_type=lt):
            return False

        # 7x7 is treated as no-interest
        if lt == '7x7':
            rate = 0.0
        intr = round(p * rate, 2)
        total = round(p + intr, 2)

        dr = date_released or now
        try:
            datetime.strptime(dr, "%Y-%m-%d")
        except Exception:
            dr = now
        due_days = 49 if lt == '7x7' else 120
        due = (datetime.strptime(dr, "%Y-%m-%d") + timedelta(days=due_days)).strftime("%Y-%m-%d")

        # Normalize new_until (optional)
        if new_until:
            try:
                datetime.strptime(str(new_until), "%Y-%m-%d")
            except Exception:
                new_until = None

        # Payment start offset: 0 = same day as release, 1 = next day after release
        try:
            psod = int(pay_start_offset_days or 0)
            psod = 1 if psod >= 1 else 0
        except Exception:
            psod = 0

        # Contact number (optional)
        try:
            cn = str(contact_number or '').strip()
        except Exception:
            cn = ''

        # Payment term & payment amount (optional)
        def _norm_term(v):
            try:
                s = str(v or '').strip()
            except Exception:
                s = ''
            if not s:
                return 'Daily'
            s2 = s.lower().replace('-', '').replace('_', '').replace(' ', '')
            if s2.startswith('d'):
                return 'Daily'
            if 'week' in s2 or s2.startswith('w'):
                return 'Weekly'
            if 'semi' in s2 or 'bi' in s2 or 'quin' in s2:
                return 'Semi'
            if 'month' in s2 or s2.startswith('m'):
                return 'Monthly'
            # allow exact title-case values
            t = s.strip().title()
            return t if t in ('Daily','Weekly','Semi','Monthly') else 'Daily'

        pt = _norm_term(payment_term)
        try:
            pa = float(str(payment_amount).replace(',', '.').strip()) if payment_amount not in (None, '') else 0.0
        except Exception:
            pa = 0.0

        # Payment mode (optional)
        pm = _spina__merge_payment_mode(payment_mode)

        # Due schedule fields
        def _norm_weekday(v):
            try:
                s = str(v or '').strip()
            except Exception:
                s = ''
            if not s:
                return ''
            key = s[:3].strip().lower()
            mp = {
                'mon': 'Mon', 'tue': 'Tue', 'wed': 'Wed', 'thu': 'Thu',
                'fri': 'Fri', 'sat': 'Sat', 'sun': 'Sun'
            }
            return mp.get(key, '')

        def _norm_dom(v):
            try:
                if v in (None, ''):
                    return None
                n = int(str(v).strip())
                return n if 1 <= n <= 31 else None
            except Exception:
                return None

        dwd = _norm_weekday(due_weekday)
        sd1 = _norm_dom(semi_due_day1)
        sd2 = _norm_dom(semi_due_day2)
        mdd = _norm_dom(monthly_due_day)
        try:
            fdr = str(flex_due_rule or '').strip()
        except Exception:
            fdr = ''

        # Stable uid for history
        try:
            import uuid
            uid = uuid.uuid4().hex
        except Exception:
            uid = str(datetime.now().timestamp()).replace('.', '')

        try:
            # Ensure area exists in master list (best-effort)
            try:
                _a = (area or '').strip()
                if _a:
                    self.ensure_area_exists(_a)
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0121', 'suppressed exception excpass_0121', __spina_exc)
                pass

            cur.execute(
                "INSERT INTO clients (client_uid, person_uid, link_opt_out, name, contact_number, principal, interest_rate, interest_amount, total_to_pay, date_released, due_date, created_at, area, new_until, pay_start_offset_days, loan_type, payment_term, payment_amount, payment_mode, due_weekday, semi_due_day1, semi_due_day2, monthly_due_day, flex_due_rule) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                (uid, '', 0, name.strip(), cn, p, rate, intr, total, dr, due, now, (area or ''), new_until, psod, lt, pt, pa, pm, dwd, sd1, sd2, mdd, fdr)
            )
            self.conn.commit()
            try:
                from spina_app.area_hierarchy_ops import sync_client_area_uid_from_path
                sync_client_area_uid_from_path(self.conn, uid)
            except Exception as __spina_exc:
                _log_suppressed_once(
                    'area_uid_sync_add',
                    'suppressed client Area UID sync after add',
                    __spina_exc,
                )
                pass

            # Ensure renew defaults (safe if columns not present)
            try:
                cur.execute("UPDATE clients SET last_released_cash = COALESCE(last_released_cash, principal), renew_count = COALESCE(renew_count, 0) WHERE client_uid=?", (uid,))
                self.conn.commit()
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0122', 'suppressed exception excpass_0122', __spina_exc)
                pass

            # Log history
            try:
                new_row = self.get_client_by_uid(uid) or self.get_client_info(name.strip(), loan_type=lt) or {}
                self._log_client_history(uid, 'ADD', old_row=None, new_row=new_row, source='clients:add')
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0123', 'suppressed exception excpass_0123', __spina_exc)
                pass

            return True
        except sqlite3.IntegrityError:
            return False



    def update_client(self, old_name, new_name=None, principal=None, date_released=None, area=None, interest_rate=None, new_until=None, loan_type=None, pay_start_offset_days=None, contact_number=None, payment_term=None, payment_amount=None, payment_mode=None, due_weekday=None, semi_due_day1=None, semi_due_day2=None, monthly_due_day=None, flex_due_rule=None):
        """Update a client (append-only history is written to client_history)."""
        cur = self.conn.cursor()
        lt = self._effective_lt(loan_type)

        old_row = self.get_client_info(old_name, loan_type=lt) or {}
        if not old_row:
            return False
        uid = (old_row.get("client_uid") or "").strip()

        # Resolve new values (keep existing if None)
        name_new = (new_name or old_name or "").strip()
        if not name_new:
            name_new = (old_row.get("name") or old_name or "").strip()

        # Prevent duplicate active client names only within the same loan type.
        try:
            _name_exact = " ".join(str(name_new or "").strip().split())
        except Exception:
            _name_exact = str(name_new or "").strip()
        if _name_exact and self._active_client_name_exists(_name_exact, loan_type=lt, exclude_client_uid=uid):
            return False

        # Principal / interest
        try:
            p = float(principal) if principal is not None else float(old_row.get("principal") or 0.0)
        except Exception:
            p = 0.0
        try:
            r = float(interest_rate) if interest_rate is not None else float(old_row.get("interest_rate") or 0.20)
            if r > 1.0:
                r = r / 100.0
        except Exception:
            r = 0.20

        # 7x7 is treated as no-interest
        if lt == '7x7':
            r = 0.0

        intr = round(p * r, 2)
        total = round(p + intr, 2)

        # Dates
        dr = (date_released or old_row.get("date_released") or date.today().strftime("%Y-%m-%d"))
        try:
            datetime.strptime(dr, "%Y-%m-%d")
        except Exception:
            dr = old_row.get("date_released") or date.today().strftime("%Y-%m-%d")

        due_days = 49 if lt == '7x7' else 120
        due = (datetime.strptime(dr, "%Y-%m-%d") + timedelta(days=due_days)).strftime("%Y-%m-%d")

        # Area
        if area is None:
            area_val = old_row.get("area") or ""
        else:
            area_val = area
            try:
                _a = (area_val or '').strip()
                if _a:
                    self.ensure_area_exists(_a)
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0124', 'suppressed exception excpass_0124', __spina_exc)
                pass

        # Contact number
        if contact_number is None:
            cn = old_row.get("contact_number") or ""
        else:
            try:
                cn = str(contact_number).strip()
            except Exception:
                cn = ""

        # Payment term & payment amount
        def _norm_term(v):
            try:
                s = str(v or '').strip()
            except Exception:
                s = ''
            if not s:
                return 'Daily'
            s2 = s.lower().replace('-', '').replace('_', '').replace(' ', '')
            if s2.startswith('d'):
                return 'Daily'
            if 'week' in s2 or s2.startswith('w'):
                return 'Weekly'
            if 'semi' in s2 or 'bi' in s2 or 'quin' in s2:
                return 'Semi'
            if 'month' in s2 or s2.startswith('m'):
                return 'Monthly'
            t = s.strip().title()
            return t if t in ('Daily','Weekly','Semi','Monthly') else 'Daily'

        if payment_term is None:
            pt = _norm_term(old_row.get("payment_term") or "Daily")
        else:
            pt = _norm_term(payment_term)

        if payment_amount is None:
            try:
                pa = float(old_row.get("payment_amount") or 0.0)
            except Exception:
                pa = 0.0
        else:
            try:
                pa = float(str(payment_amount).replace(',', '.').strip()) if payment_amount not in (None, '') else 0.0
            except Exception:
                pa = 0.0

        if payment_mode is None:
            pm = _spina__merge_payment_mode(old_row.get("payment_mode"))
        else:
            pm = _spina__merge_payment_mode(payment_mode)

        def _norm_weekday(v):
            try:
                s = str(v or '').strip()
            except Exception:
                s = ''
            if not s:
                return ''
            key = s[:3].strip().lower()
            mp = {
                'mon': 'Mon', 'tue': 'Tue', 'wed': 'Wed', 'thu': 'Thu',
                'fri': 'Fri', 'sat': 'Sat', 'sun': 'Sun'
            }
            return mp.get(key, '')

        def _norm_dom(v):
            try:
                if v in (None, ''):
                    return None
                n = int(str(v).strip())
                return n if 1 <= n <= 31 else None
            except Exception:
                return None

        if due_weekday is None:
            dwd = _norm_weekday(old_row.get("due_weekday") or "")
        else:
            dwd = _norm_weekday(due_weekday)
        if semi_due_day1 is None:
            sd1 = _norm_dom(old_row.get("semi_due_day1"))
        else:
            sd1 = _norm_dom(semi_due_day1)
        if semi_due_day2 is None:
            sd2 = _norm_dom(old_row.get("semi_due_day2"))
        else:
            sd2 = _norm_dom(semi_due_day2)
        if monthly_due_day is None:
            mdd = _norm_dom(old_row.get("monthly_due_day"))
        else:
            mdd = _norm_dom(monthly_due_day)

        if flex_due_rule is None:
            try:
                fdr = str(old_row.get("flex_due_rule") or "").strip()
            except Exception:
                fdr = ""
        else:
            try:
                fdr = str(flex_due_rule or "").strip()
            except Exception:
                fdr = ""

        # new_until (optional; allow blank to clear)
        if new_until is None:
            nu = old_row.get("new_until") or ""
        else:
            nu = str(new_until).strip()
            if nu:
                try:
                    datetime.strptime(nu[:10], "%Y-%m-%d")
                except Exception:
                    nu = ""

        # pay_start_offset_days
        if pay_start_offset_days is None:
            psod = old_row.get("pay_start_offset_days")
            try:
                psod = int(psod or 0)
            except Exception:
                psod = 0
            psod = 1 if psod >= 1 else 0
        else:
            try:
                psod = int(pay_start_offset_days or 0)
            except Exception:
                psod = 0
            psod = 1 if psod >= 1 else 0

        # Perform update (use uid if available; fallback to name+loan_type)
        try:
            if uid:
                cur.execute(
                    """UPDATE clients
                           SET name=?,
                               contact_number=?,
                               principal=?,
                               interest_rate=?,
                               interest_amount=?,
                               total_to_pay=?,
                               date_released=?,
                               due_date=?,
                               area=?,
                               new_until=?,
                               pay_start_offset_days=?,
                               payment_term=?,
                               payment_amount=?,
                               payment_mode=?,
                               due_weekday=?,
                               semi_due_day1=?,
                               semi_due_day2=?,
                               monthly_due_day=?,
                               flex_due_rule=?
                         WHERE client_uid=?""",
                    (name_new, cn, p, r, intr, total, dr, due, (area_val or ''), nu, psod, pt, pa, pm, dwd, sd1, sd2, mdd, fdr, uid)
                )
            else:
                cur.execute(
                    """UPDATE clients
                           SET name=?,
                               contact_number=?,
                               principal=?,
                               interest_rate=?,
                               interest_amount=?,
                               total_to_pay=?,
                               date_released=?,
                               due_date=?,
                               area=?,
                               new_until=?,
                               pay_start_offset_days=?,
                               payment_term=?,
                               payment_amount=?,
                               payment_mode=?,
                               due_weekday=?,
                               semi_due_day1=?,
                               semi_due_day2=?,
                               monthly_due_day=?,
                               flex_due_rule=?
                         WHERE name=? AND loan_type=?""",
                    (name_new, cn, p, r, intr, total, dr, due, (area_val or ''), nu, psod, pt, pa, pm, dwd, sd1, sd2, mdd, fdr, old_name, lt)
                )

            # If name changed, keep transactions in sync
            try:
                if name_new and name_new != old_name:
                    fixed = 0
                    if uid:
                        try:
                            fixed = int(self._sync_transactions_for_client_uid(uid, loan_type=lt, force_name=name_new) or 0)
                        except Exception:
                            fixed = 0
                    if not fixed:
                        cur.execute("UPDATE transactions SET name=? WHERE name=? AND loan_type=?", (name_new, old_name, lt))
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0125', 'suppressed exception excpass_0125', __spina_exc)
                pass
            # If name changed, migrate any legacy name-based notes to stable-id keys (prevents orphaned notes)
            try:
                if name_new and name_new != old_name:
                    _migrate_legacy_notes_by_name(
                        old_name=old_name,
                        loan_type=lt,
                        client_uid=uid or (old_row.get("client_uid") if isinstance(old_row, dict) else None),
                        person_uid=(old_row.get("person_uid") if isinstance(old_row, dict) else None),
                    )
            except Exception as e:
                _log_exc("notes:migrate_on_rename", e)


            self.conn.commit()
            try:
                from spina_app.area_hierarchy_ops import sync_client_area_uid_from_path
                _area_sync_uid = uid or (
                    old_row.get("client_uid") if isinstance(old_row, dict) else ""
                )
                if _area_sync_uid:
                    sync_client_area_uid_from_path(self.conn, _area_sync_uid)
            except Exception as __spina_exc:
                _log_suppressed_once(
                    'area_uid_sync_update',
                    'suppressed client Area UID sync after update',
                    __spina_exc,
                )
                pass

            # Log history
            try:
                new_row = self.get_client_by_uid(uid) if uid else self.get_client_info(name_new, loan_type=lt)
                self._log_client_history(uid or (new_row or {}).get("client_uid", ""), 'UPDATE', old_row=old_row, new_row=new_row or {}, source='clients:update')
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0126', 'suppressed exception excpass_0126', __spina_exc)
                pass

            return True
        except Exception:
            return False




    def renew_client(self, name, released_cash, renew_date=None, new_principal=None, loan_type=None, interest_rate=None, note='', pay_start_offset_days=None):
        """Renew a client (reloan). Updates the client row to a new cycle and records an event.

        - released_cash: cash actually released to the client for this renew (for display in reports).
        - new_principal: the new loan principal. If None/blank, defaults to released_cash.
        """
        cur = self.conn.cursor()
        lt = self._effective_lt(loan_type)

        info = self.get_client_info(name, loan_type=lt) or {}
        # Start-of-payment offset for NEW cycle (0=same-day, 1=next-day)
        # Respect the caller's explicit renew choice. If none was provided, preserve the
        # client's current saved offset instead of silently forcing next-day.
        if pay_start_offset_days is None:
            try:
                psod = int((info or {}).get('pay_start_offset_days') or 0)
            except Exception:
                psod = 0
        else:
            try:
                psod = int(pay_start_offset_days or 0)
            except Exception:
                psod = 0
        psod = 1 if psod >= 1 else 0

        if not info:
            return False

        uid = (info.get('client_uid') or '').strip()
        if not uid:
            # best-effort: fall back to name+type (older DB) but renewals history needs uid
            try:
                uid = self.get_client_uid(name, loan_type=lt) or ''
                uid = (uid or '').strip()
            except Exception:
                uid = ''

        # Parse date
        if not renew_date:
            renew_date = date.today().strftime("%Y-%m-%d")
        try:
            datetime.strptime(str(renew_date)[:10], "%Y-%m-%d")
            rd = str(renew_date)[:10]
        except Exception:
            rd = date.today().strftime("%Y-%m-%d")

        # Cash / principal
        try:
            rc = float(released_cash or 0)
        except Exception:
            rc = 0.0
        if new_principal is None or str(new_principal).strip() == '':
            new_principal = rc
        try:
            p = float(new_principal or 0)
        except Exception:
            p = 0.0

        # Interest rate
        try:
            r = float(interest_rate) if interest_rate is not None else float(info.get('interest_rate') or 0.20)
            if r > 1.0:
                r = r / 100.0
        except Exception:
            r = 0.20

        if lt == '7x7':
            r = 0.0

        intr = round(p * r, 2)
        total = round(p + intr, 2)

        due_days = 49 if lt == '7x7' else 120
        try:
            due = (datetime.strptime(rd, "%Y-%m-%d") + timedelta(days=due_days)).strftime("%Y-%m-%d")
        except Exception:
            due = rd

        # Old row for history
        old_row = dict(info)

        def _ensure_renewals_table():
            try:
                cur.execute("""
                    CREATE TABLE IF NOT EXISTS renewals (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        client_uid TEXT,
                        loan_type TEXT DEFAULT 'Regular',
                        renew_date TEXT NOT NULL,
                        released_cash REAL DEFAULT 0,
                        principal_after REAL DEFAULT 0,
                        interest_rate REAL DEFAULT 0,
                        note TEXT,
                        created_at TEXT
                    )
                """)
                # Legacy DB safety: make sure an older renewals table has the columns used below.
                try:
                    cols = [r[1] for r in cur.execute("PRAGMA table_info(renewals)").fetchall()]
                except Exception:
                    cols = []
                try:
                    if 'loan_type' not in cols:
                        cur.execute("ALTER TABLE renewals ADD COLUMN loan_type TEXT DEFAULT 'Regular'")
                except Exception as __spina_exc:
                    _log_suppressed_once('excpass_0127a', 'suppressed exception excpass_0127a', __spina_exc)
                    pass
                try:
                    if 'released_cash' not in cols:
                        cur.execute("ALTER TABLE renewals ADD COLUMN released_cash REAL DEFAULT 0")
                except Exception as __spina_exc:
                    _log_suppressed_once('excpass_0127b', 'suppressed exception excpass_0127b', __spina_exc)
                    pass
                try:
                    if 'principal_after' not in cols:
                        cur.execute("ALTER TABLE renewals ADD COLUMN principal_after REAL DEFAULT 0")
                except Exception as __spina_exc:
                    _log_suppressed_once('excpass_0127c', 'suppressed exception excpass_0127c', __spina_exc)
                    pass
                try:
                    if 'interest_rate' not in cols:
                        cur.execute("ALTER TABLE renewals ADD COLUMN interest_rate REAL DEFAULT 0")
                except Exception as __spina_exc:
                    _log_suppressed_once('excpass_0127d', 'suppressed exception excpass_0127d', __spina_exc)
                    pass
                try:
                    if 'note' not in cols:
                        cur.execute("ALTER TABLE renewals ADD COLUMN note TEXT")
                except Exception as __spina_exc:
                    _log_suppressed_once('excpass_0127e', 'suppressed exception excpass_0127e', __spina_exc)
                    pass
                try:
                    if 'created_at' not in cols:
                        cur.execute("ALTER TABLE renewals ADD COLUMN created_at TEXT")
                except Exception as __spina_exc:
                    _log_suppressed_once('excpass_0127f', 'suppressed exception excpass_0127f', __spina_exc)
                    pass
                cur.execute("CREATE INDEX IF NOT EXISTS idx_renewals_uid_date ON renewals(client_uid, loan_type, renew_date)")
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0127', 'suppressed exception excpass_0127', __spina_exc)
                pass

        _ensure_renewals_table()

        # Write changes atomically
        def _do():
            # Update client row to new cycle
            cur.execute(
                """UPDATE clients
                      SET principal=?,
                          interest_rate=?,
                          interest_amount=?,
                          total_to_pay=?,
                          date_released=?,
                          due_date=?,
                          new_until=NULL,
                          last_released_cash=?,
                          renew_count=COALESCE(renew_count,0)+1
                    WHERE name=? AND loan_type=?""",
                (p, r, intr, total, rd, due, rc, name, lt)
            )

            # Save the renew start-of-payment offset and the exact start date for the new cycle.
            # This avoids wrong-start carryover after renew and keeps reports aligned with the renew choice.
            try:
                cur.execute("UPDATE clients SET pay_start_offset_days=? WHERE name=? AND loan_type=?", (psod, name, lt))
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0128', 'suppressed exception excpass_0128', __spina_exc)
                pass
            try:
                pstart = (datetime.strptime(rd, "%Y-%m-%d") + timedelta(days=psod)).strftime("%Y-%m-%d")
                cur.execute("UPDATE clients SET payment_start_date=? WHERE name=? AND loan_type=?", (pstart, name, lt))
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0128_start', 'suppressed exception excpass_0128_start', __spina_exc)
                pass

            # Record renew event (if uid available)
            if uid:
                cur.execute(
                    """INSERT INTO renewals (client_uid, loan_type, renew_date, released_cash, principal_after, interest_rate, note, created_at)
                        VALUES (?,?,?,?,?,?,?, datetime('now'))""",
                    (uid, lt, rd, rc, p, r, (note or '').strip())
                )

        try:
            run_write(_do)
            try:
                self.conn.commit()
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0129_commit', 'suppressed exception excpass_0129_commit', __spina_exc)
                raise
        except Exception as e:
            try:
                self._last_renew_error = str(e)
            except Exception:
                pass
            try:
                _log_exc('renew_client', e)
            except Exception:
                pass
            # fallback without retry wrapper
            try:
                try:
                    self.conn.rollback()
                except Exception:
                    pass
                _do()
                self.conn.commit()
            except Exception as e2:
                try:
                    self._last_renew_error = str(e2)
                except Exception:
                    pass
                try:
                    _log_exc('renew_client:fallback', e2)
                except Exception:
                    pass
                return False

        # Log client history
        try:
            new_row = self.get_client_info(name, loan_type=lt) or {}
            self._log_client_history(new_row.get('client_uid') or uid, 'RENEW', old_row=old_row, new_row=new_row, source='clients:renew', note=(note or '').strip())
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0130', 'suppressed exception excpass_0130', __spina_exc)
            pass

        return True

    def get_renewal_stats(self, client_uid, loan_type=None):
        """Return (renew_count, last_released_cash, last_release_date).

        - renew_count counts renew events (not including the original loan release).
        - last_released_cash is the last recorded released cash; if none, returns None.
        """
        lt = self._effective_lt(loan_type)
        uid = (client_uid or '').strip()
        if not uid:
            return (0, None, None)

        cur = self.conn.cursor()

        # Prefer renewals table
        try:
            r = cur.execute(
                "SELECT COUNT(*) AS cnt FROM renewals WHERE client_uid=? AND IFNULL(NULLIF(TRIM(loan_type),''),'Regular') = IFNULL(NULLIF(TRIM(?),''),'Regular')",
                (uid, lt)
            ).fetchone()
            cnt = int(r[0] if r else 0)

            last = cur.execute(
                "SELECT renew_date, released_cash FROM renewals WHERE client_uid=? AND IFNULL(NULLIF(TRIM(loan_type),''),'Regular') = IFNULL(NULLIF(TRIM(?),''),'Regular') ORDER BY date(renew_date) DESC, id DESC LIMIT 1",
                (uid, lt)
            ).fetchone()
            if last:
                try:
                    last_date = last[0]
                except Exception:
                    last_date = None
                try:
                    last_cash = float(last[1] or 0)
                except Exception:
                    last_cash = None
            else:
                last_date = None
                last_cash = None
            return (cnt, last_cash, last_date)
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0131', 'suppressed exception excpass_0131', __spina_exc)
            pass

        # Fallback to clients columns (if present)
        try:
            row = cur.execute("SELECT renew_count, last_released_cash, date_released FROM clients WHERE client_uid=? LIMIT 1", (uid,)).fetchone()
            if row:
                try:
                    cnt = int(row[0] or 0)
                except Exception:
                    cnt = 0
                try:
                    last_cash = float(row[1]) if row[1] is not None else None
                except Exception:
                    last_cash = None
                try:
                    last_date = row[2]
                except Exception:
                    last_date = None
                return (cnt, last_cash, last_date)
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0132', 'suppressed exception excpass_0132', __spina_exc)
            pass

        return (0, None, None)


    def delete_client(self, name, loan_type=None):
        """Delete a client and related transactions for the given loan_type (history is written)."""
        cur = self.conn.cursor()
        lt = self._effective_lt(loan_type)
        old_row = self.get_client_info(name, loan_type=lt) or {}
        uid = (old_row.get("client_uid") or "").strip()

        # Count transactions (note only)
        tx_count = 0
        try:
            row = cur.execute("SELECT COUNT(*) AS c FROM transactions WHERE name=? AND loan_type=?", (name, lt)).fetchone()
            tx_count = int(row["c"] if isinstance(row, sqlite3.Row) else row[0])
        except Exception:
            tx_count = 0

        cur.execute("DELETE FROM transactions WHERE name = ? AND loan_type = ?", (name, lt))
        cur.execute("DELETE FROM clients WHERE name = ? AND loan_type = ?", (name, lt))
        self.conn.commit()

        try:
            self._log_client_history(uid, 'DELETE', old_row=old_row, new_row=None, source='clients:delete', note=f"deleted_transactions={tx_count}")
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0133', 'suppressed exception excpass_0133', __spina_exc)
            pass
    def _ensure_archive_columns(self, cur=None):
        """Best-effort: ensure archive columns exist for older DBs."""
        c = cur or self.conn.cursor()
        try:
            c.execute("ALTER TABLE clients ADD COLUMN is_archived INTEGER DEFAULT 0")
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0134', 'suppressed exception excpass_0134', __spina_exc)
            pass
        try:
            c.execute("ALTER TABLE clients ADD COLUMN archived_at TEXT")
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0135', 'suppressed exception excpass_0135', __spina_exc)
            pass
        try:
            c.execute("CREATE INDEX IF NOT EXISTS idx_clients_is_archived ON clients(is_archived)")
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0136', 'suppressed exception excpass_0136', __spina_exc)
            pass

    def archive_client(self, name, loan_type=None):
        """Soft-delete: hide the client (keeps transactions/history)."""
        cur = self.conn.cursor()
        lt = self._effective_lt(loan_type)
        self._ensure_archive_columns(cur)
        old_row = self.get_client_info(name, loan_type=lt) or {}
        if not old_row:
            raise ValueError("Client not found.")
        uid = (old_row.get("client_uid") or "").strip()

        cur.execute(
            "UPDATE clients SET is_archived=1, archived_at=datetime('now') WHERE name=? AND loan_type=?",
            (name, lt),
        )
        self.conn.commit()

        try:
            new_row = self.get_client_info(name, loan_type=lt) or {}
            self._log_client_history(uid, "ARCHIVE", old_row=old_row, new_row=new_row, source="clients:archive")
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0137', 'suppressed exception excpass_0137', __spina_exc)
            pass
        return True

    def restore_client(self, name, loan_type=None):
        """Restore a previously archived client by (name, loan_type)."""
        cur = self.conn.cursor()
        lt = self._effective_lt(loan_type)
        self._ensure_archive_columns(cur)
        old_row = self.get_client_info(name, loan_type=lt) or {}
        if not old_row:
            raise ValueError("Client not found.")
        uid = (old_row.get("client_uid") or "").strip()

        cur.execute(
            "UPDATE clients SET is_archived=0, archived_at=NULL WHERE name=? AND loan_type=?",
            (name, lt),
        )
        self.conn.commit()

        try:
            new_row = self.get_client_info(name, loan_type=lt) or {}
            self._log_client_history(uid, "RESTORE", old_row=old_row, new_row=new_row, source="clients:restore")
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0138', 'suppressed exception excpass_0138', __spina_exc)
            pass
        return True

    def restore_client_by_uid(self, client_uid):
        """Restore a previously archived client by client_uid."""
        if not client_uid:
            raise ValueError("Missing client UID.")
        cur = self.conn.cursor()
        self._ensure_archive_columns(cur)
        r = None
        try:
            r = cur.execute("SELECT name, loan_type FROM clients WHERE client_uid=?", (client_uid,)).fetchone()
        except Exception:
            r = None
        if not r:
            raise ValueError("Client not found.")
        try:
            name = r["name"] if isinstance(r, sqlite3.Row) else r[0]
            lt = r["loan_type"] if isinstance(r, sqlite3.Row) else r[1]
        except Exception:
            name, lt = r[0], r[1]
        return self.restore_client(name, loan_type=lt)

    def get_archived_clients(self, search=None, loan_type=None):
        """List archived clients for restore UI."""
        cur = self.conn.cursor()
        lt = (loan_type or "").strip()
        if lt:
            lt = self._norm_lt(lt)

        self._ensure_archive_columns(cur)

        term = (search or "").strip()
        like = f"%{term}%"
        q = "SELECT name, loan_type, area, client_uid, archived_at FROM clients WHERE COALESCE(is_archived,0)=1"
        params = []
        if lt:
            q += " AND loan_type=?"
            params.append(lt)
        if term:
            q += " AND name LIKE ?"
            params.append(like)
        q += " ORDER BY archived_at DESC, name COLLATE NOCASE"
        try:
            rows = cur.execute(q, params).fetchall()
            out = []
            for r in rows:
                if isinstance(r, sqlite3.Row):
                    out.append(dict(r))
                else:
                    out.append({"name": r[0], "loan_type": r[1], "area": r[2], "client_uid": r[3], "archived_at": r[4]})
            return out
        except Exception:
            return []




    
    def get_all_clients(self, search=None, loan_type=None, search_by='all', include_archived=False):
        """Return client names (optionally filtered by loan_type) with optional search.

        search_by:
          - 'all' / 'both' : match across common client fields (default)
          - 'client'       : match in client name only
          - 'area'         : match in area only
          - 'principal'    : match in principal (as text)
          - 'released'     : match in date_released
          - 'due_date'     : match in due_date
          - 'start_date'   : match in computed start date (date_released + pay_start_offset_days)
          - 'linked'       : show clients that are linked (same person_uid appears in another row)
          - 'unlinked'     : show clients not linked yet (suggested + 7x7-only)
          - 'suggested'    : show clients that have a same-name record in the other loan type but are not linked yet
          - 'blanks'       : show clients with missing key fields (area/released/due/principal)

        Notes:
          - Uses the existing persistent sqlite connection (self.conn).
          - Automatically adapts to older DBs missing some columns.
        """
        import sqlite3

        cur = self.conn.cursor()

        # Normalize loan_type (if provided)
        lt = (loan_type or '').strip()
        if lt:
            lt = self._norm_lt(lt)

        # Introspect available columns for robust queries across versions
        try:
            cols = {r[1] if not isinstance(r, sqlite3.Row) else r["name"] for r in cur.execute("PRAGMA table_info(clients)").fetchall()}
        except Exception:
            cols = set()

        has_loan_type = ("loan_type" in cols)
        has_area = ("area" in cols)
        has_principal = ("principal" in cols)
        has_released = ("date_released" in cols)
        has_due = ("due_date" in cols)
        has_pay_off = ("pay_start_offset_days" in cols)
        has_person = ("person_uid" in cols)
        has_optout = ("link_opt_out" in cols)
        has_archived = ("is_archived" in cols)

        sb = (search_by or 'all').strip().lower()
        term = (search or '').strip()
        # Convenience keywords when search_by is 'all':
        #   - typing 'blanks' shows clients with missing fields
        #   - typing 'linked' shows linked clients
        try:
            _tlow = (term or '').strip().lower()
            if sb in ('all','both') and _tlow in ('blanks','blank','missing','incomplete'):
                sb = 'blanks'
                term = ''
            elif sb in ('all','both') and _tlow in ('linked','link'):
                sb = 'linked'
                term = ''
            elif sb in ('all','both') and _tlow in ('unlinked','not linked','notlinked'):
                sb = 'unlinked'
                term = ''
            elif sb in ('all','both') and _tlow in ('suggested','suggest','suggestion','suggested link','suggestedlink'):
                sb = 'suggested'
                term = ''
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0139', 'suppressed exception excpass_0139', __spina_exc)
            pass
        like = f"%{term}%"

        # Helper: computed start date expression (SQLite date arithmetic)
        def _start_date_expr():
            # Requires date_released + pay_start_offset_days; if missing, fall back to date_released
            if has_released and has_pay_off:
                # date('YYYY-MM-DD', '+N day')
                return "IFNULL(date(date_released, '+' || IFNULL(pay_start_offset_days,0) || ' day'),'')"
            elif has_released:
                return "IFNULL(date_released,'')"
            else:
                return "''"

        where_pred = None
        where_params = []

        # Special filters that may ignore the search term
        if sb.startswith('blank'):
            preds = []
            if has_area:
                preds.append("IFNULL(area,'') = ''")
            if has_released:
                preds.append("IFNULL(date_released,'') = ''")
            if has_due:
                preds.append("IFNULL(due_date,'') = ''")
            if has_principal:
                preds.append("IFNULL(principal,0) = 0")
            where_pred = "(" + " OR ".join(preds) + ")" if preds else None
            where_params = []
        elif sb.startswith('unl'):
            # Unlinked: clients not linked yet (suggested + 7x7-only).
            # - Suggested: same-name record exists in the other loan type AND person_uid is blank
            # - 7x7-only: loan_type is 7x7 AND there is no Regular record AND person_uid is blank
            if not has_loan_type:
                # Fallback for older DBs: treat "unlinked" as missing person_uid
                if has_person:
                    base_pred = "TRIM(IFNULL(person_uid,'')) = ''"
                    if has_optout:
                        base_pred = f"({base_pred} AND IFNULL(link_opt_out,0)=0)"
                    if term:
                        where_pred = f"({base_pred} AND name LIKE ?)"
                        where_params = [like]
                    else:
                        where_pred = base_pred
                        where_params = []
                else:
                    where_pred = "name LIKE ?" if term else None
                    where_params = [like] if term else []
            else:
                # Suggested link predicate: other loan type exists for same name
                same_name_other = "EXISTS(SELECT 1 FROM clients c2 WHERE c2.name = clients.name AND c2.id <> clients.id AND IFNULL(c2.loan_type,'') <> IFNULL(clients.loan_type,''))"
                # 7x7-only predicate: is 7x7 and no Regular exists
                is_7x7 = "IFNULL(loan_type,'') = '7x7'"
                has_regular = "EXISTS(SELECT 1 FROM clients c2 WHERE c2.name = clients.name AND c2.id <> clients.id AND IFNULL(c2.loan_type,'') = 'Regular')"
                is_7x7_only = f"({is_7x7} AND NOT {has_regular})"
                if has_person:
                    not_linked = "TRIM(IFNULL(person_uid,'')) = ''"
                else:
                    not_linked = "1=1"
                base_pred = f"({not_linked} AND ({same_name_other} OR {is_7x7_only}))"
                if has_optout:
                    base_pred = f"({base_pred} AND IFNULL(link_opt_out,0)=0)"
                if term:
                    where_pred = f"({base_pred} AND name LIKE ?)"
                    where_params = [like]
                else:
                    where_pred = base_pred
                    where_params = []

        elif sb.startswith('link'):
            if not has_person:
                where_pred = None
                where_params = []
            else:
                base = "TRIM(IFNULL(person_uid,'')) <> ''"
                if has_optout:
                    base = f"({base} AND IFNULL(link_opt_out,0)=0)"
                # Require that the person_uid exists in another row (actual link)
                if has_loan_type:
                    link_exists = "EXISTS(SELECT 1 FROM clients c2 WHERE c2.person_uid = clients.person_uid AND c2.id <> clients.id AND IFNULL(c2.loan_type,'') <> IFNULL(clients.loan_type,''))"
                else:
                    link_exists = "EXISTS(SELECT 1 FROM clients c2 WHERE c2.person_uid = clients.person_uid AND c2.id <> clients.id)"
                # If user typed "no/unlinked", invert; else show linked
                t = (term or '').lower()
                if t in ("0","no","n","false","unlinked","not linked"):
                    where_pred = f"NOT ({base} AND {link_exists})"
                    where_params = []
                elif not term or t in ("1","yes","y","true","linked","✓","check"):
                    where_pred = f"({base} AND {link_exists})"
                    where_params = []
                else:
                    # Also allow searching by person_uid text
                    where_pred = f"(({base} AND {link_exists}) AND person_uid LIKE ?)"
                    where_params = [like]

        elif sb.startswith('sug'):
            # Suggested link: same-name record exists in the other loan type, but this row is not linked yet.
            # Mirrors the UI indicator: suggestion only applies when person_uid is blank.
            if has_loan_type:
                same_name_other = "EXISTS(SELECT 1 FROM clients c2 WHERE c2.name = clients.name AND c2.id <> clients.id AND IFNULL(c2.loan_type,'') <> IFNULL(clients.loan_type,''))"
            else:
                same_name_other = "EXISTS(SELECT 1 FROM clients c2 WHERE c2.name = clients.name AND c2.id <> clients.id)"
            if has_person:
                not_linked = "TRIM(IFNULL(person_uid,'')) = ''"
            else:
                not_linked = "1=1"
            base_pred = f"({not_linked} AND {same_name_other})"
            # If a term is provided, allow narrowing by name text
            if term:
                where_pred = f"({base_pred} AND name LIKE ?)"
                where_params = [like]
            else:
                where_pred = base_pred
                where_params = []

        else:
            # Text search across specific columns
            if not term:
                where_pred = None
                where_params = []
            else:
                if sb.startswith('cli') or sb in ("name",):
                    where_pred = "name LIKE ?"
                    where_params = [like]
                elif sb.startswith('are'):
                    if has_area:
                        where_pred = "IFNULL(area,'') LIKE ?"
                        where_params = [like]
                    else:
                        where_pred = "name LIKE ?"
                        where_params = [like]
                elif sb.startswith('pri'):
                    if has_principal:
                        where_pred = "CAST(IFNULL(principal,0) AS TEXT) LIKE ?"
                        where_params = [like]
                    else:
                        where_pred = "name LIKE ?"
                        where_params = [like]
                elif sb.startswith('rel'):
                    if has_released:
                        where_pred = "IFNULL(date_released,'') LIKE ?"
                        where_params = [like]
                    else:
                        where_pred = "name LIKE ?"
                        where_params = [like]
                elif sb.startswith('due'):
                    if has_due:
                        where_pred = "IFNULL(due_date,'') LIKE ?"
                        where_params = [like]
                    else:
                        where_pred = "name LIKE ?"
                        where_params = [like]
                elif sb.startswith('sta'):
                    # start_date
                    where_pred = f"{_start_date_expr()} LIKE ?"
                    where_params = [like]
                else:
                    # all/both
                    preds = ["name LIKE ?"]
                    params = [like]
                    if has_area:
                        preds.append("IFNULL(area,'') LIKE ?"); params.append(like)
                    if has_principal:
                        preds.append("CAST(IFNULL(principal,0) AS TEXT) LIKE ?"); params.append(like)
                    if has_released:
                        preds.append("IFNULL(date_released,'') LIKE ?"); params.append(like)
                    if has_due:
                        preds.append("IFNULL(due_date,'') LIKE ?"); params.append(like)
                    # computed start date (if possible)
                    if has_released:
                        preds.append(f"{_start_date_expr()} LIKE ?"); params.append(like)
                    if has_person:
                        preds.append("IFNULL(person_uid,'') LIKE ?"); params.append(like)
                    where_pred = "(" + " OR ".join(preds) + ")"
                    where_params = params

        # Build final query
        q = "SELECT name FROM clients"
        params = []
        if lt and has_loan_type:
            q += " WHERE loan_type = ?"
            params.append(lt)
            if where_pred:
                q += " AND " + where_pred
                params.extend(where_params)
        else:
            if where_pred:
                q += " WHERE " + where_pred
                params.extend(where_params)

        # Hide archived by default
        if (not include_archived) and has_archived:
            if " WHERE " in q:
                q += " AND COALESCE(is_archived,0)=0"
            else:
                q += " WHERE COALESCE(is_archived,0)=0"

        q += " ORDER BY name COLLATE NOCASE"

        try:
            cur.execute(q, params)
            rows = cur.fetchall()
            return [r["name"] if isinstance(r, sqlite3.Row) else r[0] for r in rows]
        except Exception:
            # Last-resort fallback: name-only
            try:
                if lt and has_loan_type:
                    if (not include_archived) and has_archived:
                        cur.execute("SELECT name FROM clients WHERE loan_type=? AND COALESCE(is_archived,0)=0 ORDER BY name COLLATE NOCASE", (lt,))
                    else:
                        cur.execute("SELECT name FROM clients WHERE loan_type=? ORDER BY name COLLATE NOCASE", (lt,))
                else:
                    if (not include_archived) and has_archived:
                        cur.execute("SELECT name FROM clients WHERE COALESCE(is_archived,0)=0 ORDER BY name COLLATE NOCASE")
                    else:
                        cur.execute("SELECT name FROM clients ORDER BY name COLLATE NOCASE")
                rows = cur.fetchall()
                return [r["name"] if isinstance(r, sqlite3.Row) else r[0] for r in rows]
            except Exception:
                return []

    def get_unpaired_7x7_names(self, search=None, search_by='all'):
        """Return 7x7 client names that have NO Regular record and are NOT linked.

        Used so 7x7-only clients can still be managed from the Regular view (appear at the bottom)
        and included in Collector Route prints.

        Rules:
          - loan_type must be '7x7'
          - there is no same-name Regular record
          - person_uid is blank/empty (not linked)
        """
        try:
            # Candidates by search filter (name/area/etc)
            candidates = self.get_all_clients(search=search, loan_type='7x7', search_by=search_by) or []
        except Exception:
            candidates = []
        out = []
        for nm in candidates:
            try:
                name = (nm or '').strip()
            except Exception:
                name = nm
            if not name:
                continue
            # Skip if a Regular record exists (suggested-link case, not 7x7-only)
            try:
                if self.get_client_info(name, loan_type='Regular'):
                    continue
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0140', 'suppressed exception excpass_0140', __spina_exc)
                pass
            # Skip if already linked (has person_uid)
            try:
                info7 = self.get_client_info(name, loan_type='7x7') or {}
                pu = (info7.get('person_uid') or '').strip()
                if pu:
                    continue
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0141', 'suppressed exception excpass_0141', __spina_exc)
                pass
            out.append(name)
        # Stable case-insensitive sort
        try:
            out = sorted(out, key=lambda s: str(s).lower())
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0142', 'suppressed exception excpass_0142', __spina_exc)
            pass
        return out


    def fetch_all_clients(self, loan_type=None, include_archived=False):
        """Return list of dict rows for clients (optionally filtered by loan_type)."""
        cur = self.conn.cursor()
        # soft-delete support
        has_archived = False
        try:
            cols = [r[1] for r in cur.execute("PRAGMA table_info(clients)").fetchall()]
            has_archived = ('is_archived' in cols)
        except Exception:
            has_archived = False
        lt = (loan_type or '').strip()
        if lt:
            if lt.lower().replace(' ', '') in ('7x7','7×7'):
                lt = '7x7'
            else:
                lt = 'Regular'
        try:
            if lt:
                cur.execute(
                    "SELECT name, area, principal, interest_amount, total_to_pay, date_released, due_date, loan_type FROM clients WHERE loan_type = ? " + ("AND COALESCE(is_archived,0)=0 " if ((not include_archived) and has_archived) else "") + "ORDER BY area, name;",
                    (lt,),
                )
            else:
                cur.execute(
                    "SELECT name, area, principal, interest_amount, total_to_pay, date_released, due_date, loan_type FROM clients " + ("WHERE COALESCE(is_archived,0)=0 " if ((not include_archived) and has_archived) else "") + "ORDER BY area, name;"
                )
        except Exception:
            # Older DB fallback (no loan_type)
            if lt:
                cur.execute("SELECT name, '' AS area FROM clients ORDER BY name;")
            else:
                cur.execute("SELECT name, '' AS area FROM clients ORDER BY name;")
        rows = cur.fetchall()
        return [dict(r) for r in rows]

    def get_client_info(self, name, loan_type=None, include_archived=False):
        cur = self.conn.cursor()
        lt = self._effective_lt(loan_type)
        q = "SELECT * FROM clients WHERE name = ? AND loan_type = ?"
        params = [name, lt]
        try:
            if not include_archived:
                cols = [r[1] for r in cur.execute("PRAGMA table_info(clients)").fetchall()]
                if "is_archived" in cols:
                    q += " AND COALESCE(is_archived,0)=0"
        except Exception:
            pass
        cur.execute(q, tuple(params))
        r = cur.fetchone()
        return dict(r) if r else None

