    def get_client_link_meta(self, name, loan_type=None):
        """Return (client_uid, person_uid, link_opt_out) for a client."""
        cur = self.conn.cursor()
        lt = self._effective_lt(loan_type)
        try:
            r = cur.execute(
                "SELECT client_uid, person_uid, link_opt_out FROM clients WHERE name=? AND loan_type=?",
                (name, lt),
            ).fetchone()
            if not r:
                return None
            return {
                "client_uid": r[0],
                "person_uid": r[1] or "",
                "link_opt_out": int(r[2] or 0),
                "loan_type": lt,
                "name": name,
            }
        except Exception:
            return None

    def set_link_opt_out_by_uid(self, client_uid, opt_out=1, source='clients:link_opt_out'):
        """Persist opt-out flag so auto-link prompts can be declined."""
        if not client_uid:
            return False
        cur = self.conn.cursor()
        try:
            old_row = self.get_client_by_uid(client_uid) or {}
            cur.execute("UPDATE clients SET link_opt_out=? WHERE client_uid=?", (1 if int(opt_out or 0) else 0, client_uid))
            self.conn.commit()
            try:
                new_row = self.get_client_by_uid(client_uid) or {}
                self._log_client_history(client_uid, 'UPDATE', old_row=old_row, new_row=new_row, source=source)
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0143', 'suppressed exception excpass_0143', __spina_exc)
                pass
            return True
        except Exception:
            return False
    def link_client_uids(self, uid_a, uid_b, source='clients:link'):
        """Link two client rows (typically Regular + 7x7) by assigning the same person_uid.

        Safety rules:
        - Prevent linking the same row to itself.
        - Prevent linking two rows of the same loan_type (to avoid accidental merges).
        - Prevent merging two different existing person_uid groups (unlink first).
        """
        self._set_last_error('')
        uid_a = (uid_a or '').strip()
        uid_b = (uid_b or '').strip()
        if not uid_a or not uid_b:
            self._set_last_error('Missing client UID(s).')
            return False
        if uid_a == uid_b:
            self._set_last_error('Cannot link a client to itself.')
            return False

        cur = self.conn.cursor()
        try:
            a_old = self.get_client_by_uid(uid_a) or {}
            b_old = self.get_client_by_uid(uid_b) or {}
            if not a_old or not b_old:
                self._set_last_error('Client record not found (UID missing in database).')
                return False

            lt_a = (a_old.get('loan_type') or 'Regular').strip()
            lt_b = (b_old.get('loan_type') or 'Regular').strip()
            if lt_a == lt_b:
                self._set_last_error(f"Cannot link two '{lt_a}' records. Linking is intended for Regular + 7x7 only.")
                return False

            pu_a = (a_old.get('person_uid') or '').strip()
            pu_b = (b_old.get('person_uid') or '').strip()

            # Strict rule: do not allow linking if either record is already part of any link group.
            # This keeps links as 1 Regular <-> 1 7x7 only. User must unlink first.
            if pu_a and pu_b and pu_a == pu_b:
                self._set_last_error('These records are already linked.')
                return False

            if pu_a and pu_b and pu_a != pu_b:
                self._set_last_error('These records are already linked to different people. Unlink first, then link again.')
                return False

            if pu_a or pu_b:
                if pu_a:
                    self._set_last_error(f"'{a_old.get('name') or 'Selected client'}' is already linked. Unlink it first.")
                else:
                    self._set_last_error(f"'{b_old.get('name') or 'Target client'}' is already linked. Unlink it first.")
                return False

            # Choose or create person_uid
            pu = ''
            try:
                import uuid
                pu = uuid.uuid4().hex
            except Exception:
                pu = str(datetime.now().timestamp()).replace('.', '')

            # Apply to both (and clear opt-out)
            cur.execute("UPDATE clients SET person_uid=?, link_opt_out=0 WHERE client_uid=?", (pu, uid_a))
            cur.execute("UPDATE clients SET person_uid=?, link_opt_out=0 WHERE client_uid=?", (pu, uid_b))
            self.conn.commit()

            # History log (before/after)
            try:
                a_new = self.get_client_by_uid(uid_a) or {}
                self._log_client_history(uid_a, 'UPDATE', old_row=a_old, new_row=a_new, source=source)
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0144', 'suppressed exception excpass_0144', __spina_exc)
                pass
            try:
                b_new = self.get_client_by_uid(uid_b) or {}
                self._log_client_history(uid_b, 'UPDATE', old_row=b_old, new_row=b_new, source=source)
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0145', 'suppressed exception excpass_0145', __spina_exc)
                pass
            return True
        except Exception as e:
            self._set_last_error(f'Link failed: {e}')
            try:
                self.conn.rollback()
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0146', 'suppressed exception excpass_0146', __spina_exc)
                pass
            return False





    def unlink_person_uid(self, person_uid, source='clients:unlink'):
        """Unlink all rows that share this person_uid (clears person_uid)."""
        pu = (person_uid or '').strip()
        if not pu:
            return False
        cur = self.conn.cursor()
        try:
            rows = cur.execute("SELECT client_uid FROM clients WHERE person_uid=?", (pu,)).fetchall() or []
            for (uid,) in rows:
                try:
                    old_row = self.get_client_by_uid(uid) or {}
                    cur.execute("UPDATE clients SET person_uid='', link_opt_out=0 WHERE client_uid=?", (uid,))
                    # log each
                    try:
                        new_row = self.get_client_by_uid(uid) or {}
                        self._log_client_history(uid, 'UPDATE', old_row=old_row, new_row=new_row, source=source)
                    except Exception as __spina_exc:
                        _log_suppressed_once('excpass_0147', 'suppressed exception excpass_0147', __spina_exc)
                        pass
                except Exception as __spina_exc:
                    _log_suppressed_once('excpass_0148', 'suppressed exception excpass_0148', __spina_exc)
                    pass
            self.conn.commit()
            return True
        except Exception:
            return False

    def find_clients_by_person_uid(self, person_uid):
        """Return list of client rows linked to this person_uid."""
        pu = (person_uid or '').strip()
        if not pu:
            return []
        cur = self.conn.cursor()
        try:
            rows = cur.execute("SELECT * FROM clients WHERE person_uid=? ORDER BY loan_type, name", (pu,)).fetchall() or []
            return [dict(r) for r in rows]
        except Exception:
            return []

