            style.configure("AppShell.TFrame", background=p["bg"])
            style.configure("Sidebar.TFrame", background=p["panel"], relief="flat", borderwidth=0)
            style.configure("Content.TFrame", background=p["bg"], relief="flat", borderwidth=0)
