    def _build_header(self):
        """Modern top header: app identity + fast Regular/7x7 switch + app actions."""
        hp = self._header_palette()
        family = 'Segoe UI' if os.name == 'nt' else 'TkDefaultFont'

        top = tk.Frame(self.root, bg=hp['bg'], bd=0, highlightthickness=0)
        top.pack(fill='x')
        self.modern_header = top

        # 3-column layout: identity | quick view switch | actions
        top.grid_columnconfigure(0, weight=1, minsize=260)
        top.grid_columnconfigure(1, weight=1, minsize=280)
        top.grid_columnconfigure(2, weight=1, minsize=360)

        left = tk.Frame(top, bg=hp['bg'])
        left.grid(row=0, column=0, sticky='w', padx=(16, 8), pady=10)
        self.header_left = left

        # Optional small logo mark, then SPINA title.
        try:
            if os.path.exists(LOGO_FILENAME):
                from PIL import Image, ImageTk
                with Image.open(LOGO_FILENAME) as _img:
                    img = _img.copy()
                img.thumbnail((38, 38), Image.LANCZOS)
                self.logo = ImageTk.PhotoImage(img)
                tk.Label(left, image=self.logo, bg=hp['bg'], bd=0).pack(side='left', padx=(0, 10))
        except Exception as __spina_exc:
            _log_suppressed_once('modern_header_logo', 'modern header logo failed', __spina_exc)

        title_box = tk.Frame(left, bg=hp['bg'])
        title_box.pack(side='left')
        self.header_title_label = tk.Label(
            title_box,
            text=APP_TITLE,
            bg=hp['bg'],
            fg=hp['fg'],
            anchor='w',
            font=(family, 17, 'bold'),
        )
        self.header_title_label.pack(anchor='w')
        self.header_subtitle_label = tk.Label(
            title_box,
            text=f"Account: {self.user_name}",
            bg=hp['bg'],
            fg=hp['muted'],
            anchor='w',
            font=(family, 9),
        )
        self.header_subtitle_label.pack(anchor='w', pady=(1, 0))
        self.user_role_label = self.header_subtitle_label

        try:
            self.pg_status_label = tk.Label(
                left,
                text='● PostgreSQL',
                bg=hp['chip'],
                fg=hp['accent2'],
                padx=10,
                pady=4,
                font=(family, 8, 'bold'),
            )
            self.pg_status_label.pack(side='left', padx=(14, 0))
        except Exception:
            self.pg_status_label = None

        center = tk.Frame(top, bg=hp['bg'])
        center.grid(row=0, column=1, sticky='n', padx=8, pady=8)
        self.header_center = center

        self.mode_switch_frame = tk.Frame(
            center,
            bg=hp['panel'],
            bd=0,
            highlightthickness=1,
            highlightbackground=hp['border'],
            padx=8,
            pady=6,
        )
        self.mode_switch_frame.pack()

        self.header_view_title = tk.Label(
            self.mode_switch_frame,
            text='Loan View',
            bg=hp['panel'],
            fg=hp['fg'],
            font=(family, 9, 'bold'),
        )
        self.header_view_title.pack(side='left', padx=(2, 8))

        self._mode_buttons = {}
        for label, key in (('Regular', 'Regular'), ('7x7', '7x7')):
            btn = tk.Button(
                self.mode_switch_frame,
                text=label,
                command=lambda k=key: self._set_mode(k),
                relief='flat',
                bd=0,
                padx=18,
                pady=7,
                cursor='hand2',
                font=(family, 10, 'bold'),
                highlightthickness=1,
            )
            btn.pack(side='left', padx=3)
            self._mode_buttons[key] = btn

        self.mode_status_label = tk.Label(
            center,
            text=f"Current view: {self._mode_filter()}",
            bg=hp['bg'],
            fg=hp['muted'],
            font=(family, 8),
        )
        self.mode_status_label.pack(pady=(4, 0))

        right = tk.Frame(top, bg=hp['bg'])
        right.grid(row=0, column=2, sticky='e', padx=(8, 14), pady=10)
        self.header_right = right

        # Theme toggle
        try:
            self.theme_btn = self._make_header_button(right, self._theme_toggle_text(), self.toggle_theme)
            self.theme_btn.pack(side='left', padx=4)
        except Exception:
            self.theme_btn = None

        # Switch account button
        try:
            self.switch_account_btn = self._make_header_button(right, 'Switch Account', self.switch_account)
            self.switch_account_btn.pack(side='left', padx=4)
        except Exception as __spina_exc:
            _log_suppressed_once('modern_switch_account_btn', 'modern switch account button failed', __spina_exc)

        # Settings button
        try:
            self.settings_btn = self._make_header_button(right, 'Settings', self.open_settings_dialog)
            self.settings_btn.pack(side='left', padx=4)
        except Exception as __spina_exc:
            _log_suppressed_once('modern_settings_btn', 'modern settings button failed', __spina_exc)

        # PostgreSQL Backup buttons (Admin/System only)
        try:
            self.backup_btn = self._make_header_button(right, 'Backup', self.backup_postgres_database, primary=True)
            self.backup_btn.pack(side='left', padx=4)
        except Exception as __spina_exc:
            self.backup_btn = None
