    def _build_data_tab(self):        # one unified table (Client, Area, Days...)
        frm = self.tab_data
        top = ttk.Frame(frm, style='Toolbar.TFrame')
        top.pack(fill='x', pady=(0, 8))

        row1 = ttk.Frame(top, style='Toolbar.TFrame')
        row1.pack(fill='x')
        row2 = ttk.Frame(top, style='Toolbar.TFrame')
        row2.pack(fill='x', pady=(6, 0))

        # Search / summary
        self.search_db_var = tk.StringVar()
        self._db_rows_var = tk.StringVar(value='')
        self._db_close_info_var = tk.StringVar(value='')

        ttk.Label(row1, text='Data Bank', style='Section.TLabel').pack(side='left', padx=(0, 10))
        ttk.Label(row1, text='Search:').pack(side='left', padx=(0, 6))
        self.db_search_entry = ttk.Entry(row1, textvariable=self.search_db_var, width=34)
        self.db_search_entry.pack(side='left', padx=(0, 6))
        self.search_db_var.trace_add('write', lambda *_: self.refresh_data_grid())
        try:
            self.db_search_entry.bind('<Return>', lambda *_: self.refresh_data_grid(), add='+')
            self.db_search_entry.bind('<Escape>', lambda *_: self.search_db_var.set(''), add='+')
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_databank_search_bind', 'suppressed exception excpass_databank_search_bind', __spina_exc)
            pass

        ttk.Button(row1, text='Clear', command=lambda: self.search_db_var.set('')).pack(side='left', padx=(0, 10))
        ttk.Label(row1, textvariable=self._db_rows_var).pack(side='left', padx=(6, 0))

        # Month nav on the right
        nav = ttk.Frame(row1, style='Toolbar.TFrame')
        nav.pack(side='right', padx=(8, 0))
        ttk.Button(nav, text='< Prev', command=self.prev_month).pack(side='left', padx=3)
        ttk.Button(nav, text='Today', command=self.goto_current_month).pack(side='left', padx=3)
        self.month_lbl = ttk.Label(nav, text=self._month_label())
        self.month_lbl.pack(side='left', padx=6)
