    header = ttk.Frame(frm)
    header.pack(fill="x", pady=(8, 4), padx=8)

    ttk.Label(header, text="Collector's Route", font=("Segoe UI", 12, "bold")).pack(side="left")

    right = ttk.Frame(header)
    right.pack(side="right")

    ttk.Label(right, text="Search:").pack(side="left", padx=(0, 4))
    self.collector_route_search_var = tk.StringVar(value="")
    ent_search = ttk.Entry(right, textvariable=self.collector_route_search_var, width=26)
    ent_search.pack(side="left")
    ttk.Button(right, text="Clear", command=self._clear_collectors_search_filters).pack(side="left", padx=(6, 0))

    # --- Filters row ---
    filters = ttk.Frame(frm)
