    ttk.Label(filters, text="Main:").pack(side="left", padx=(0, 4))
    self.collector_route_filter_main_var = tk.StringVar(value="(All)")
    self.collector_route_filter_main_cmb = ttk.Combobox(
        filters, textvariable=self.collector_route_filter_main_var,
        values=["(All)"], state="readonly", width=18
    )
    self.collector_route_filter_main_cmb.pack(side="left", padx=(0, 10))
    self.collector_route_filter_main_cmb.bind("<<ComboboxSelected>>", lambda e: self.refresh_collectors())

    self.collector_route_filter_conflicts_var = tk.BooleanVar(value=False)
    ttk.Checkbutton(filters, text="Conflicts only", variable=self.collector_route_filter_conflicts_var,
                    command=self.refresh_collectors).pack(side="left", padx=(0, 10))

    self.collector_route_filter_unknown_var = tk.BooleanVar(value=False)
    ttk.Checkbutton(filters, text="Unknown only", variable=self.collector_route_filter_unknown_var,
                    command=self.refresh_collectors).pack(side="left")

    ttk.Label(filters, text="   ").pack(side="left", padx=(6, 0))
    ttk.Label(filters, text="Tip: click a column header to sort.").pack(side="left")

    # --- Toolbar ---
    bar = ttk.Frame(frm)
    bar.pack(fill="x", pady=(0, 6), padx=8)

    ttk.Button(bar, text="➕ Add", command=self._add_collector).pack(side="left", padx=(0, 6))
    ttk.Button(bar, text="🖨 Print Route", style="Primary.TButton",
               command=self.print_collector_route_daily_ledger).pack(side="left", padx=(0, 10))

    ttk.Button(bar, text="Unassigned", command=self._show_unassigned_areas).pack(side="left", padx=(0, 6))
    ttk.Button(bar, text="No-Area Clients", command=self._show_no_area_clients).pack(side="left", padx=(0, 6))
    ttk.Button(bar, text="Show Conflicts", command=self._show_conflicts).pack(side="left", padx=(0, 10))

    # Selection mode
    self.collector_route_multi_var = tk.BooleanVar(value=False)
    ttk.Checkbutton(bar, text="Multi-select", variable=self.collector_route_multi_var,
                    command=self._on_collectors_multi_toggle).pack(side="left")

    ttk.Button(bar, text="Refresh", command=self.refresh_collectors).pack(side="right")

    # --- Bulk actions (only when multi-select + checked rows) ---
    self.collectors_bulk_bar = ttk.Frame(frm)
    self.collectors_bulk_bar.pack(fill="x", pady=(0, 6), padx=8)
    self.collectors_bulk_bar.pack_forget()

    self.collectors_bulk_count_var = tk.StringVar(value="")
    ttk.Label(self.collectors_bulk_bar, textvariable=self.collectors_bulk_count_var).pack(side="left")

