# ---------- Collector Route UI helpers (selection + bulk + inline edit) ----------

def _collectors_name_from_values(self, vals):
    """Return the collector name from a Treeview row values tuple.

    Backwards compatible with older layouts:
      - Old layout: first value is the collector name.
      - New layout: first value is a select marker (radio/checkbox/bullet), second is the collector name.
    """
    try:
        v = list(vals or [])
    except Exception:
        v = []
    if not v:
        return ""

    # First column may be a selection marker in the new UI.
    try:
        first = str(v[0] or "").strip()
    except Exception:
        first = ""

    # Marker set (different fonts render these slightly differently)
    markers = {
        "○","●","◯","◉","☐","☑",
        "•","∙","·","◦","▪","▫","■","□","",  # bullet variants / empties
    }

    if len(v) >= 2:
        try:
            second = str(v[1] or "").strip()
        except Exception:
            second = ""

        # Heuristic: treat the first value as a marker if it is short and non-alphanumeric,
        # or if it matches our marker set.
        try:
            looks_like_marker = (len(first) <= 2 and not any(ch.isalnum() for ch in first))
        except Exception:
            looks_like_marker = False

        if (first in markers) or (looks_like_marker and second):
            return second

    # Fallback: old layout (first column is the name)
    return first

def _collectors_get_selected_name(self):
    tree = getattr(self, "collectors_tree", None)
    if not tree:
        return ""
    sel = ()
    try:
        sel = tree.selection()
    except Exception:
        sel = ()
    sel_id = sel[0] if sel else tree.focus()
    if not sel_id:
        return ""
    vals = tree.item(sel_id, "values") or ()
    return self._collectors_name_from_values(vals)

def _collectors_toggle_sections(self):
    try:
        show_areas = bool(getattr(self, "collector_route_show_areas_var", None).get())
    except Exception:
        show_areas = True
    try:
        show_notes = bool(getattr(self, "collector_route_show_notes_var", None).get())
    except Exception:
        show_notes = True

    try:
        if show_areas:
            if not self.collector_route_areas_box.winfo_ismapped():
                self.collector_route_areas_box.pack(fill="both", expand=True, pady=(6, 6))
        else:
            if self.collector_route_areas_box.winfo_ismapped():
                self.collector_route_areas_box.pack_forget()
    except Exception:
        pass

    try:
        if show_notes:
            if not self.collector_route_notes_box.winfo_ismapped():
                self.collector_route_notes_box.pack(fill="both", expand=False)
        else:
            if self.collector_route_notes_box.winfo_ismapped():
                self.collector_route_notes_box.pack_forget()
    except Exception:
        pass

def _collectors_apply_markers(self):
    """Update the Sel column (radio/checkbox) based on current selection/multi checks."""
    tree = getattr(self, "collectors_tree", None)
    if not tree:
        return
    multi = False
    try:
        multi = bool(getattr(self, "collector_route_multi_var", None).get())
    except Exception:
        multi = False

    checked = set(getattr(self, "_collectors_checked", set()) or set())
    cur_name = (getattr(self, "_selected_collector_name", "") or "").strip()
    for iid in tree.get_children():
        vals = list(tree.item(iid, "values") or ())
        if not vals:
            continue
        name = self._collectors_name_from_values(vals)
        if not name:
            continue
        if multi:
            mark = "☑" if name in checked else "☐"
        else:
            mark = "●" if (cur_name and name == cur_name) else "○"
        # Update only the first cell (Sel)
        try:
            if str(vals[0]) != mark:
                vals[0] = mark
                tree.item(iid, values=tuple(vals))
        except Exception:
            pass

    try:
        self._collectors_refresh_bulk_bar()
    except Exception:
        pass

def _on_collectors_multi_toggle(self):
    # Leaving multi-select clears checks to avoid accidental bulk actions
    try:
        multi = bool(getattr(self, "collector_route_multi_var", None).get())
    except Exception:
        multi = False
    if not multi:
        try:
            self._collectors_checked = set()
        except Exception:
            self._collectors_checked = set()
    try:
        self._collectors_refresh_bulk_bar()
    except Exception:
        pass
    try:
        self._collectors_apply_markers()
    except Exception:
        pass
    try:
        self.refresh_collectors()
    except Exception:
        pass

def _collectors_refresh_bulk_bar(self):
    try:
        multi = bool(getattr(self, "collector_route_multi_var", None).get())
    except Exception:
        multi = False
    checked = set(getattr(self, "_collectors_checked", set()) or set())
    bar = getattr(self, "collectors_bulk_bar", None)
    if not bar:
        return
    if multi and checked:
        try:
            self.collectors_bulk_count_var.set(f"Selected: {len(checked)}")
        except Exception:
            pass
        try:
            if not bar.winfo_ismapped():
                bar.pack(fill="x", pady=(0, 6), padx=8)
        except Exception:
            pass
    else:
        try:
            if bar.winfo_ismapped():
                bar.pack_forget()
        except Exception:
            pass

def _collectors_clear_checked(self):
    try:
        self._collectors_checked = set()
    except Exception:
        self._collectors_checked = set()
    try:
        self._collectors_refresh_bulk_bar()
    except Exception:
        pass
    try:
        self._collectors_apply_markers()
    except Exception:
        pass

def _on_collectors_tree_click(self, event):
    """Handle clicks in Sel + Actions columns."""
    tree = getattr(self, "collectors_tree", None)
    if not tree:
        return
    # If editing inline, block row switching (prevents losing changes)
    if bool(getattr(self, "_collectors_inline_editing", False)):
        # Allow clicks inside right-side editor only; here we block list clicks
        return "break"

    iid = tree.identify_row(event.y)
    col = tree.identify_column(event.x)  # "#1".."#N"
    if not iid:
        return
    try:
        vals = tree.item(iid, "values") or ()
    except Exception:
        vals = ()
    name = self._collectors_name_from_values(vals)

    # Columns: 1=sel, 8=actions (given our columns order)
    if col == "#1":
        # toggle sel indicator
        multi = False
        try:
            multi = bool(getattr(self, "collector_route_multi_var", None).get())
        except Exception:
            multi = False

        try:
            tree.selection_set(iid)
            tree.focus(iid)
        except Exception:
            pass

        if multi:
            checked = set(getattr(self, "_collectors_checked", set()) or set())
            if name:
                if name in checked:
                    checked.remove(name)
                else:
                    checked.add(name)
                try:
                    self._collectors_checked = checked
                except Exception:
                    self._collectors_checked = checked
            self._collectors_apply_markers()
            return "break"
        else:
            # Single-select: normal selection highlight + radio marker
            try:
                self._on_collectors_select()
            except Exception:
                pass
            self._collectors_apply_markers()
            return "break"

    if col == "#8":
        # actions click: split into 3 zones (View/Edit/Delete)
        try:
            bbox = tree.bbox(iid, column="actions")
        except Exception:
            bbox = None
        if not bbox:
            return
        x0, y0, w, h = bbox
        xrel = event.x - x0
        if w <= 0:
            return "break"
        zone = int(max(0, min(2, (xrel * 3) // w)))
        try:
            tree.selection_set(iid)
            tree.focus(iid)
        except Exception:
            pass
        if zone == 0:
            try:
                self._on_collectors_select()
            except Exception:
                pass
        elif zone == 1:
            try:
                self._collectors_start_inline_edit()
            except Exception:
                pass
        else:
            try:
                self._delete_selected_collector()
            except Exception:
                pass
        return "break"
    return

def _collectors_delete_selected(self):
    from tkinter import messagebox
    checked = sorted(list(getattr(self, "_collectors_checked", set()) or set()), key=lambda s: str(s).lower())
    if not checked:
        messagebox.showinfo("Delete", "No collectors are checked.")
        return
    if not messagebox.askyesno("Confirm Delete", f"Delete {len(checked)} checked collector(s)?"):
        return

    path = data_path("collectors.json")
    try:
        with open(path, 'r', encoding='utf-8') as _f:
            raw = json.load(_f)
    except Exception:
        raw = {}

    # Normalize to dict
    data = {}
    if isinstance(raw, dict):
        data = dict(raw)
    elif isinstance(raw, list):
        for el in raw:
            if isinstance(el, dict):
                nm = (el.get("name") or el.get("collector") or "").strip()
                if not nm:
                    continue
                data[nm] = {"areas": el.get("areas") or el.get("route") or [], "notes": str(el.get("notes") or "")}

    deleted = 0
    for nm in checked:
        if nm in data:
            del data[nm]
            deleted += 1

    try:
        if not _write_json_atomic(path, data):
            raise IOError("Failed to save collectors.json (atomic write failed)")
    except Exception as e:
        _log_exc("collectors:bulk_delete", e)
        messagebox.showwarning("Save Error", "Failed to save collectors.json. See data/spina_app.log")
        return

    try:
        self._collectors_checked = set()
    except Exception:
        self._collectors_checked = set()

    self.refresh_collectors()
    try:
        self.status_var.set(f"Deleted {deleted} collector(s).")
    except Exception:
        pass

def _collectors_export_selected(self):
    from tkinter import messagebox, filedialog
    checked = sorted(list(getattr(self, "_collectors_checked", set()) or set()), key=lambda s: str(s).lower())
    if not checked:
        messagebox.showinfo("Export", "No collectors are checked.")
        return
    fp = filedialog.asksaveasfilename(
        title="Export checked collectors",
        defaultextension=".csv",
        filetypes=[("CSV", "*.csv"), ("JSON", "*.json"), ("All files", "*.*")]
    )
    if not fp:
        return

    path = data_path("collectors.json")
    try:
        with open(path, 'r', encoding='utf-8') as _f:
            raw = json.load(_f)
    except Exception:
        raw = {}

    data = {}
    if isinstance(raw, dict):
        data = raw
    elif isinstance(raw, list):
        for el in raw:
            if isinstance(el, dict):
                nm = (el.get("name") or el.get("collector") or "").strip()
                if not nm:
                    continue
                data[nm] = {"areas": el.get("areas") or el.get("route") or [], "notes": str(el.get("notes") or "")}

    try:
        if str(fp).lower().endswith(".json"):
            out = {nm: data.get(nm, {}) for nm in checked}
            with open(fp, "w", encoding="utf-8") as f:
                json.dump(out, f, ensure_ascii=False, indent=2)
        else:
            import csv
            with open(fp, "w", newline="", encoding="utf-8") as f:
                w = csv.writer(f)
                w.writerow(["collector", "areas", "notes"])
                for nm in checked:
                    rec = data.get(nm, {}) or {}
                    areas = rec.get("areas") or rec.get("route") or []
                    areas_txt = " | ".join([str(a).strip() for a in (areas or []) if str(a).strip()])
                    notes = str(rec.get("notes") or "")
                    w.writerow([nm, areas_txt, notes])
    except Exception as e:
        _log_exc("collectors:export_checked", e)
        messagebox.showwarning("Export", "Failed to export. See data/spina_app.log")
        return

    messagebox.showinfo("Export", f"Exported {len(checked)} collector(s).")

# ---- Inline edit ----

def _collectors_start_inline_edit(self):
    """Start inline editing for the currently selected collector (right panel)."""
    from tkinter import messagebox
    if bool(getattr(self, "_collectors_inline_editing", False)):
        return
    name = (getattr(self, "_selected_collector_name", "") or "").strip()
    if not name:
        # try from tree selection
        name = self._collectors_get_selected_name()
    if not name:
        messagebox.showwarning("Edit", "Please select a collector first.")
        return

    # Load fields
    self._collectors_inline_editing = True
    self._collectors_inline_original_name = name

    # swap name label -> entry
    try:
        self.collector_route_selected_name_lbl.pack_forget()
    except Exception:
        pass
    try:
        self.collector_route_edit_name_var.set(name)
    except Exception:
        pass
    try:
        self.collector_route_selected_name_ent.pack(side="left", padx=(0, 8))
    except Exception:
        pass

    # swap buttons
    try:
        self.collector_route_btn_edit.pack_forget()
    except Exception:
        pass
    try:
        self.collector_route_btn_save.pack(side="left", padx=(0, 6))
        self.collector_route_btn_cancel.pack(side="left", padx=(0, 8))
    except Exception:
        pass

    # show areas editor and hide view tree
    try:
        self.collector_route_area_tree.grid_remove()
    except Exception:
        pass
    try:
        self.collector_route_areas_edit_frm.grid()
    except Exception:
        pass

    # load current areas + notes into edit widgets
    try:
        self._collectors_load_inline_edit_fields(name)
    except Exception:
        pass

    # Disable list interactions to prevent accidental switching
    try:
        tv = getattr(self, "collectors_tree", None)
        if tv:
            tv.configure(selectmode="browse")
    except Exception:
        pass

def _collectors_load_inline_edit_fields(self, name):
    """Populate the right-side edit widgets from collectors.json cache."""
    # areas
    try:
        self.collector_route_areas_lb.delete(0, "end")
    except Exception:
        pass

    areas = []
    notes = ""
    try:
        cache = getattr(self, "_collectors_data_cache", {}) or {}
        rec = cache.get(name) or {}
        areas = rec.get("areas") or []
        notes = rec.get("notes") or ""
    except Exception:
        areas, notes = [], ""

    # keep the order as stored
    for a in (areas or []):
        s = str(a).strip()
        if s:
            try:
                self.collector_route_areas_lb.insert("end", s)
            except Exception:
                pass

    # notes text
    try:
        self.collector_route_notes_txt.delete("1.0", "end")
        self.collector_route_notes_txt.insert("1.0", str(notes or ""))
    except Exception:
        pass

def _collectors_cancel_inline_edit(self):
    """Cancel inline editing and restore view widgets."""
    if not bool(getattr(self, "_collectors_inline_editing", False)):
        return
    self._collectors_inline_editing = False

    # restore name label
    try:
        self.collector_route_selected_name_ent.pack_forget()
    except Exception:
        pass
    try:
        self.collector_route_selected_name_lbl.pack(side="left")
    except Exception:
        pass

    # restore buttons
    try:
        self.collector_route_btn_save.pack_forget()
        self.collector_route_btn_cancel.pack_forget()
    except Exception:
        pass
    try:
        self.collector_route_btn_edit.pack(side="left", padx=(0, 6))
    except Exception:
        pass

    # restore areas view tree
    try:
        self.collector_route_areas_edit_frm.grid_remove()
    except Exception:
        pass
    try:
        self.collector_route_area_tree.grid()
    except Exception:
        pass

    # repopulate view details for current selection
    try:
        self._populate_collector_details((getattr(self, "_selected_collector_name", "") or "").strip() or None)
    except Exception:
        pass

def _collectors_save_inline_edit(self):
    """Save inline edits to collectors.json (atomic), then refresh UI."""
    from tkinter import messagebox
    if not bool(getattr(self, "_collectors_inline_editing", False)):
        return

    old_name = (getattr(self, "_collectors_inline_original_name", "") or "").strip()
    new_name = ""
    try:
        new_name = str(self.collector_route_edit_name_var.get() or "").strip()
    except Exception:
        new_name = old_name

    if not new_name:
        messagebox.showwarning("Missing Name", "Please enter a collector name.")
        return

    # Gather areas list
    areas = []
    try:
        areas = [self.collector_route_areas_lb.get(i) for i in range(self.collector_route_areas_lb.size())]
        areas = [str(a).strip() for a in (areas or []) if str(a).strip()]
    except Exception:
        areas = []
    if not areas:
        messagebox.showwarning("No Areas", "Please add at least one area.")
        return

    # Notes
    try:
        notes = self.collector_route_notes_txt.get("1.0", "end").strip()
    except Exception:
        notes = ""

    # Load collectors.json and normalize to dict
    path = data_path("collectors.json")
    try:
        with open(path, 'r', encoding='utf-8') as _f:
            raw = json.load(_f)
    except Exception:
        raw = {}

    data = {}
    if isinstance(raw, dict):
        data = dict(raw)
    elif isinstance(raw, list):
        for el in raw:
            if isinstance(el, dict):
                nm = (el.get("name") or el.get("collector") or "").strip()
                if not nm:
                    continue
                data[nm] = {"areas": el.get("areas") or el.get("route") or [], "notes": str(el.get("notes") or "")}

    # Prevent accidental overwrite when renaming
    if old_name != new_name and new_name in data:
        if not messagebox.askyesno("Rename Conflict", f"'{new_name}' already exists. Overwrite it?"):
            return

    # Update / rename
    if old_name and old_name in data and old_name != new_name:
        try:
            del data[old_name]
        except Exception:
            pass
    data[new_name] = {"areas": areas, "notes": notes}

    try:
        if not _write_json_atomic(path, data):
            raise IOError("Failed to save collectors.json (atomic write failed)")
    except Exception as e:
        _log_exc("collectors:inline_save", e)
        messagebox.showwarning("Save Error", "Failed to save collectors.json. See data/spina_app.log")
        return

    # Exit edit mode and refresh
    self._collectors_inline_editing = False
    try:
        self._selected_collector_name = new_name
    except Exception:
        self._selected_collector_name = new_name

    try:
        self.refresh_collectors()
    except Exception:
        pass

    # Reselect saved row (best effort)
    try:
        tree = getattr(self, "collectors_tree", None)
        if tree:
            for iid in tree.get_children():
                vals = tree.item(iid, "values") or ()
                nm = self._collectors_name_from_values(vals)
                if nm == new_name:
                    tree.selection_set(iid)
                    tree.focus(iid)
                    break
    except Exception:
        pass

    # Restore view UI widgets
    try:
        self._collectors_cancel_inline_edit()
    except Exception:
        pass

    try:
        self.status_var.set(f"Saved '{new_name}'.")
    except Exception:
        pass

# ---- Areas edit helpers ----

def _collectors_choose_areas(self):
    """Pick areas via existing picker dialog, then load into listbox."""
    picked = self._area_picker_dialog(initial=[self.collector_route_areas_lb.get(i) for i in range(self.collector_route_areas_lb.size())],
                                      title="Select Route Areas")
    if picked is None:
        return
    try:
        self.collector_route_areas_lb.delete(0, "end")
    except Exception:
        pass
    for a in (picked or []):
        s = str(a).strip()
        if s:
            try:
                self.collector_route_areas_lb.insert("end", s)
            except Exception:
                pass

def _collectors_add_area_text(self):
    s = ""
    try:
        s = str(self.collector_route_area_add_var.get() or "").strip()
    except Exception:
        s = ""
    if not s:
        return
    # avoid duplicates (case-insensitive)
    existing = []
    try:
        existing = [str(self.collector_route_areas_lb.get(i) or "").strip().lower() for i in range(self.collector_route_areas_lb.size())]
    except Exception:
        existing = []
    if s.lower() in existing:
        return
    try:
        self.collector_route_areas_lb.insert("end", s)
        self.collector_route_area_add_var.set("")
    except Exception:
        pass

def _collectors_remove_area(self):
    try:
        idx = self.collector_route_areas_lb.curselection()
        if not idx:
            return
        i = int(idx[0])
        self.collector_route_areas_lb.delete(i)
    except Exception:
        pass

def _collectors_move_area(self, delta):
    try:
        idxs = self.collector_route_areas_lb.curselection()
        if not idxs:
            return
        i = int(idxs[0])
        j = max(0, min(self.collector_route_areas_lb.size() - 1, i + int(delta)))
        if i == j:
            return
        item = self.collector_route_areas_lb.get(i)
        self.collector_route_areas_lb.delete(i)
        self.collector_route_areas_lb.insert(j, item)
        self.collector_route_areas_lb.selection_clear(0, "end")
        self.collector_route_areas_lb.selection_set(j)
    except Exception:
        pass

def _collectors_areas_drag_start(self, event):
    try:
        self._areas_drag_index = self.collector_route_areas_lb.nearest(event.y)
    except Exception:
        self._areas_drag_index = None

def _collectors_areas_drag_motion(self, event):
    try:
        i = getattr(self, "_areas_drag_index", None)
        if i is None:
            return
        j = self.collector_route_areas_lb.nearest(event.y)
        if j == i:
            return
        item_i = self.collector_route_areas_lb.get(i)
        item_j = self.collector_route_areas_lb.get(j)
        self.collector_route_areas_lb.delete(i)
        self.collector_route_areas_lb.insert(i, item_j)
        self.collector_route_areas_lb.delete(j)
        self.collector_route_areas_lb.insert(j, item_i)
        self._areas_drag_index = j
        self.collector_route_areas_lb.selection_clear(0, "end")
        self.collector_route_areas_lb.selection_set(j)
    except Exception:
        pass

def _collectors_areas_drag_end(self, event):
    try:
        self._areas_drag_index = None
    except Exception:
        self._areas_drag_index = None
    def _on_collectors_tree_wheel(self, event):
        """Ensure mousewheel scroll works on Collector Route list."""
        try:
            tv = getattr(self, "collectors_tree", None)
            if not tv:
                return
            delta = 0
            if hasattr(event, "delta") and event.delta:
                delta = -1 if event.delta > 0 else 1
            elif getattr(event, "num", None) in (4, 5):
                delta = -1 if event.num == 4 else 1
            if delta:
                tv.yview_scroll(delta, "units")
        except Exception:
            pass
        return "break"

    def _schedule_collectors_refresh(self, delay_ms=220):
        """Debounce refresh_collectors while typing in Search."""
        try:
            after_id = getattr(self, "_collectors_refresh_after_id", None)
            if after_id:
                try:
                    self.root.after_cancel(after_id)
                except Exception:
                    pass
        except Exception:
            pass
        try:
            self._collectors_refresh_after_id = self.root.after(delay_ms, self.refresh_collectors)
        except Exception:
            try:
                self.refresh_collectors()
            except Exception:
                pass

    def _clear_collectors_search_filters(self):
        try:
            if hasattr(self, "collector_route_search_var"):
                self.collector_route_search_var.set("")
        except Exception:
            pass
        try:
            if hasattr(self, "collector_route_filter_main_var"):
                self.collector_route_filter_main_var.set("(All)")
        except Exception:
            pass
        try:
            if hasattr(self, "collector_route_filter_conflicts_var"):
                self.collector_route_filter_conflicts_var.set(False)
        except Exception:
            pass
        try:
            if hasattr(self, "collector_route_filter_unknown_var"):
                self.collector_route_filter_unknown_var.set(False)
        except Exception:
            pass
        try:
            self.refresh_collectors()
        except Exception:
            pass


def _on_collectors_select(self):
    """Populate the right-side details panel for the selected collector."""
    try:
        tree = getattr(self, "collectors_tree", None)
        if not tree:
            return

        # If inline editing is active, prevent switching rows (avoid losing changes)
        try:
            if bool(getattr(self, "_collectors_inline_editing", False)):
                cur = (getattr(self, "_collectors_inline_original_name", "") or getattr(self, "_selected_collector_name", "") or "").strip()
                if cur:
                    for iid in tree.get_children():
                        vals = tree.item(iid, "values") or ()
                        try:
                            nm = self._collectors_name_from_values(vals)
                        except Exception:
                            nm = (vals[0] if vals else "")
                        if str(nm).strip() == cur:
                            try:
                                tree.selection_set(iid)
                                tree.focus(iid)
                            except Exception:
                                pass
                            break
                return
        except Exception:
            pass

        sel = ()
        try:
            sel = tree.selection()
        except Exception:
            sel = ()
        sel_id = sel[0] if sel else tree.focus()
        if not sel_id:
            self._populate_collector_details(None)
            try:
                self._collectors_apply_markers()
            except Exception:
                pass
            return

        vals = tree.item(sel_id, "values") or ()
        try:
            name = self._collectors_name_from_values(vals)
        except Exception:
            name = (vals[0] if vals else "") or ""
        name = str(name).strip()

        self._populate_collector_details(name if name else None)
        try:
            self._collectors_apply_markers()
        except Exception:
            pass
    except Exception:
        pass

    def _populate_collector_details(self, collector_name):
        """Update the right panel: selected name, stats, areas tree, notes."""
        try:
            self._selected_collector_name = collector_name or ""
        except Exception:
            self._selected_collector_name = collector_name or ""

        try:
            if hasattr(self, "collector_route_selected_name_var"):
                self.collector_route_selected_name_var.set("Select a collector…" if not collector_name else str(collector_name))
        except Exception:
            pass
        try:
            if hasattr(self, "collector_route_selected_stats_var"):
                self.collector_route_selected_stats_var.set("")
        except Exception:
            pass

        # clear area tree
        try:
            tv = getattr(self, "collector_route_area_tree", None)
            if tv:
                for iid in tv.get_children():
                    tv.delete(iid)
        except Exception:
            pass

        # clear notes
        try:
            txtw = getattr(self, "collector_route_notes_txt", None)
            if txtw:
                txtw.delete("1.0", "end")
        except Exception:
            pass

        if not collector_name:
            return

        data = getattr(self, "_collectors_data_cache", {}) or {}
        rowinfo = (getattr(self, "_collectors_row_cache", {}) or {}).get(str(collector_name), {}) or {}
        rec = data.get(str(collector_name), {}) or {}
        areas_list = [str(a).strip() for a in (rec.get("areas") or []) if str(a).strip()]
        notes_txt = (rec.get("notes") or "").strip()

        # stats
        try:
            reg = int(rowinfo.get("reg", 0) or 0)
            sev = int(rowinfo.get("sev", 0) or 0)
            areas_count = int(rowinfo.get("areas_count", len(areas_list)) or 0)
            flags = []
            if rowinfo.get("any_conflict"):
                flags.append("conflict")
            if rowinfo.get("any_unknown"):
                flags.append("unknown")
            flag_txt = (" • " + ", ".join(flags)) if flags else ""
            if hasattr(self, "collector_route_selected_stats_var"):
                self.collector_route_selected_stats_var.set(f"Areas: {areas_count}    Clients: R:{reg}  7:{sev}{flag_txt}")
        except Exception:
            pass

        # notes
        try:
            txtw = getattr(self, "collector_route_notes_txt", None)
            if txtw is not None:
                txtw.insert("1.0", notes_txt or "")
        except Exception:
            pass

        # areas grouped main/sub from route entries
        try:
            tv = getattr(self, "collector_route_area_tree", None)
            if not tv:
                return

            main_nodes = {}
            order = []
            loose = []
            for a in areas_list:
                ma, su = split_area_main_sub(a)
                ma = (ma or "").strip()
                su = (su or "").strip()
                if not ma:
                    loose.append(a)
                    continue
                if ma not in main_nodes:
                    main_nodes[ma] = []
                    order.append(ma)
                if su and su not in main_nodes[ma]:
                    main_nodes[ma].append(su)

            for ma in order:
                iid = tv.insert("", "end", text=ma, values=("",))
                for su in main_nodes[ma]:
                    tv.insert(iid, "end", text=f"  - {su}", values=("",))
                tv.item(iid, open=True)

            for a in loose:
                tv.insert("", "end", text=a, values=("",))
        except Exception:
            pass

    def _save_selected_collector_notes(self):
        """Save Notes from the right panel to collectors.json (atomic)."""
        from tkinter import messagebox
        name = (getattr(self, "_selected_collector_name", "") or "").strip()
        if not name:
            messagebox.showwarning("Notes", "Select a collector first.")
            return

        txtw = getattr(self, "collector_route_notes_txt", None)
        notes = ""
        try:
            if txtw:
                notes = (txtw.get("1.0", "end") or "").strip()
        except Exception:
            notes = ""

        ok = False
        try:
            ok = self._save_collector_notes(name, notes)
        except Exception:
            ok = False

        if ok:
            try:
                self.status_var.set(f"Notes saved for '{name}'.")
            except Exception:
                pass
        else:
            messagebox.showwarning("Save Error", "Failed to save notes.\\n\\nSee log: data/spina_app.log")

    def _save_collector_notes(self, collector_name, notes_text):
        """Internal: update one collector's notes in collectors.json."""
        try:
            os.makedirs(DATA_DIR, exist_ok=True)
            path = data_path("collectors.json")
            try:
                with open(path, "r", encoding="utf-8") as _f:
                    raw = json.load(_f)
            except Exception:
                raw = {}

            data = {}
            if isinstance(raw, dict):
                data = raw
            elif isinstance(raw, list):
                for el in raw:
                    if isinstance(el, dict):
                        nm = (el.get("name") or el.get("collector") or "").strip()
                        if not nm:
                            continue
                        aa = el.get("areas") or el.get("route") or []
                        data[nm] = {"areas": aa, "notes": str(el.get("notes") or "")}

            if collector_name not in data:
                data[collector_name] = {"areas": [], "notes": ""}

            rec = data.get(collector_name)
            if not isinstance(rec, dict):
                rec = {"areas": [], "notes": ""}
                data[collector_name] = rec

            rec["notes"] = str(notes_text or "")

            if not _write_json_atomic(path, data):
                raise IOError("atomic write failed")

            self.refresh_collectors()
            try:
                self._populate_collector_details(collector_name)
            except Exception:
                pass
            return True
        except Exception as e:
            _log_exc("collectors:save_notes", e)
            return False

    def _refresh_collectors_table(self):
        """Backward-compatible alias for older code paths."""
        try:
            self.refresh_collectors()
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0466', 'suppressed exception excpass_0466', __spina_exc)
            pass

    def _add_collector_dialog(self):
        """Legacy dialog-based add; now writes the SAME dict schema as the main Collectors tab."""
        from tkinter import messagebox
        dlg = self.CollectorDialog(self.root, title='Add Collector')
        if not dlg.result:
            return
        name, areas = dlg.result
        name = (name or "").strip()
        if not name:
            return

        os.makedirs(DATA_DIR, exist_ok=True)
        path = data_path( "collectors.json")
        try:
            with open(path, 'r', encoding='utf-8') as _f:
                raw = json.load(_f)
        except Exception:
            raw = {}

        data = {}
        if isinstance(raw, dict):
            data = raw
        elif isinstance(raw, list):
            for el in raw:
                if isinstance(el, dict):
                    nm = (el.get("name") or el.get("collector") or "").strip()
                    if nm:
                        data[nm] = {"areas": el.get("areas") or el.get("route") or [], "notes": str(el.get("notes") or "")}

        if name in data:
            messagebox.showwarning("Exists", f"{name} already exists.")
            return

        data[name] = {"areas": areas, "notes": ""}
        try:
            if not _write_json_atomic(path, data):
                raise IOError('Failed to save collectors.json (atomic write failed)')
        except Exception as e:
            _log_exc('collectors:save_json', e)
            try:
                messagebox.showwarning('Save Error', 'Failed to save collectors.json.\n\nCheck permissions/disk space.\nSee log: data/spina_app.log')
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0467', 'suppressed exception excpass_0467', __spina_exc)
                pass
        self.refresh_collectors()

    def _edit_collector_dialog(self):
        """Legacy dialog-based edit; now edits the main collectors.json dict schema."""
        from tkinter import messagebox
        tree = getattr(self, "collectors_tree", None) or getattr(self, "collector_tree", None)
        if tree is None:
            messagebox.showwarning("Collectors", "Collectors table not ready.")
            return

        sel = ()
        try:
            sel = tree.selection()
        except Exception:
            sel = ()
        sel_id = sel[0] if sel else tree.focus()
        if not sel_id:
            messagebox.showwarning("Select", "Select a collector to edit")
            return

        vals = tree.item(sel_id, "values") or ()
        try:
            name = self._collectors_name_from_values(vals)
        except Exception:
            name = (vals[0] if len(vals) > 0 else "")
        name = (name or "").strip()
        if not name:
            messagebox.showwarning("Select", "Select a valid collector row")
            return

        path = data_path( "collectors.json")
        try:
            with open(path, 'r', encoding='utf-8') as _f:
                raw = json.load(_f)
        except Exception:
            raw = {}

        data = {}
        if isinstance(raw, dict):
            data = raw
        elif isinstance(raw, list):
            for el in raw:
                if isinstance(el, dict):
                    nm = (el.get("name") or el.get("collector") or "").strip()
                    if nm:
                        data[nm] = {"areas": el.get("areas") or el.get("route") or [], "notes": str(el.get("notes") or "")}

        rec = data.get(name, {"areas": [], "notes": ""})
        dlg = self.CollectorDialog(self.root, title='Edit Collector', name=name, areas=rec.get("areas", []))
        if not dlg.result:
            return

        new_name, new_areas = dlg.result
        new_name = (new_name or "").strip() or name

        if new_name != name and new_name in data:
            messagebox.showerror("Exists", "Another collector already has that name.")
            return

        if new_name != name and name in data:
            data[new_name] = data.pop(name)
        elif new_name not in data:
            data[new_name] = {}

        data[new_name]["areas"] = new_areas
        data[new_name]["notes"] = rec.get("notes","") if isinstance(rec, dict) else ""

        try:
            if not _write_json_atomic(path, data):
                raise IOError('Failed to save collectors.json (atomic write failed)')
        except Exception as e:
            _log_exc('collectors:save_json', e)
            try:
                messagebox.showwarning('Save Error', 'Failed to save collectors.json.\n\nCheck permissions/disk space.\nSee log: data/spina_app.log')
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0468', 'suppressed exception excpass_0468', __spina_exc)
                pass
        self.refresh_collectors()

    def _delete_collector(self):
        """Legacy delete; now deletes from the main collectors.json dict schema."""
        from tkinter import messagebox
        tree = getattr(self, "collectors_tree", None) or getattr(self, "collector_tree", None)
        if tree is None:
            messagebox.showwarning("Collectors", "Collectors table not ready.")
            return

        sel = ()
        try:
            sel = tree.selection()
        except Exception:
            sel = ()
        sel_id = sel[0] if sel else tree.focus()
        if not sel_id:
            messagebox.showwarning("Select", "Select a collector to delete")
            return

        vals = tree.item(sel_id, "values") or ()
        try:
            name = self._collectors_name_from_values(vals)
        except Exception:
            name = (vals[0] if len(vals) > 0 else "")
        name = (name or "").strip()
        if not name:
            messagebox.showwarning("Select", "Select a valid collector row")
            return

        if not messagebox.askyesno("Confirm", f"Delete collector {name}?"):
            return

        path = data_path( "collectors.json")
        try:
            with open(path, 'r', encoding='utf-8') as _f:
                raw = json.load(_f)
        except Exception:
            raw = {}

        data = {}
        if isinstance(raw, dict):
            data = raw
        elif isinstance(raw, list):
            for el in raw:
                if isinstance(el, dict):
                    nm = (el.get("name") or el.get("collector") or "").strip()
                    if nm:
                        data[nm] = {"areas": el.get("areas") or el.get("route") or [], "notes": str(el.get("notes") or "")}

        if name in data:
            del data[name]
        try:
            if not _write_json_atomic(path, data):
                raise IOError('Failed to save collectors.json (atomic write failed)')
        except Exception as e:
            _log_exc('collectors:save_json', e)
            try:
                messagebox.showwarning('Save Error', 'Failed to save collectors.json.\n\nCheck permissions/disk space.\nSee log: data/spina_app.log')
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0469', 'suppressed exception excpass_0469', __spina_exc)
                pass
        self.refresh_collectors()

    def print_collector_route_daily_ledger(self):
        """Print the SELECTED collector's route using the same 3-column
        Daily Collection Ledger layout as `print_full_daily_ledger`, but ONLY
        for that collector's areas (no 'arrange all areas' step).

        - Uses selection() first (more reliable than focus()).
        - Reads collectors.json in multiple historical schemas.
        - Sets temporary flags consumed by print_full_daily_ledger, then cleans them up.
        """
        from tkinter import messagebox
        import os, json

        tree = getattr(self, "collectors_tree", None) or getattr(self, "collector_tree", None)
        if tree is None:
            messagebox.showwarning("Collectors", "Collectors table not ready.")
            return

        sel = ()
        try:
            sel = tree.selection()
        except Exception:
            sel = ()
        sel_id = sel[0] if sel else tree.focus()
        if not sel_id:
            messagebox.showwarning("Select collector", "Please select a collector first.")
            return

        vals = tree.item(sel_id, "values") or ()
        collector_name = ""
        # Prefer stored selection name (new UI sets this).
        try:
            collector_name = (getattr(self, "_selected_collector_name", "") or "").strip()
        except Exception:
            collector_name = ""
        if not collector_name:
            try:
                collector_name = self._collectors_name_from_values(vals)
            except Exception:
                collector_name = ""
        if not collector_name:
            # Fallback: new table layout is (Sel, Collector, ...)
            try:
                collector_name = (vals[1] if len(vals) > 1 else (vals[0] if len(vals) > 0 else ""))
            except Exception:
                collector_name = ""
        collector_name = (str(collector_name or "")).strip()
        if not collector_name:
            messagebox.showwarning("Select collector", "Please select a valid collector row.")
            return

        os.makedirs(DATA_DIR, exist_ok=True)
        path = data_path( "collectors.json")
        try:
            with open(path, 'r', encoding='utf-8') as _f:
                raw = json.load(_f)
        except Exception:
            raw = {}

        areas = []

        if isinstance(raw, dict):
            val = raw.get(collector_name)
            if val is None:
                # Fallback: case/whitespace-insensitive key match
                def _nn(_s):
                    try:
                        return " ".join(str(_s or "").split()).strip().lower()
                    except Exception:
                        return str(_s or "").strip().lower()
                tgt = _nn(collector_name)
                for _k in (raw.keys() if isinstance(raw, dict) else []):
                    if _nn(_k) == tgt:
                        val = raw.get(_k)
                        break
            if isinstance(val, dict):
                aa = val.get("areas") or val.get("route") or []
                areas = [str(a).strip() for a in (aa or []) if str(a).strip()]
            elif isinstance(val, list):
                areas = [str(a).strip() for a in val if str(a).strip()]
        elif isinstance(raw, list):
            for el in raw:
                if isinstance(el, dict):
                    nm = (el.get("name") or el.get("collector") or "").strip()
                    if nm == collector_name:
                        aa = el.get("areas") or el.get("route") or []
                        areas = [str(a).strip() for a in (aa or []) if str(a).strip()]
                        break
            if not areas:
                for el in raw:
                    if isinstance(el, str):
                        s = el.strip()
                        if s.startswith(collector_name + ":") or s.startswith(collector_name + "|"):
                            parts = s.split(":", 1) if ":" in s else s.split("|", 1)
                            if len(parts) == 2:
                                areas = [a.strip() for a in parts[1].split(",") if a.strip()]
                                break

        # Filter saved route entries against CURRENT ACTIVE client areas so archived/empty
        # route entries do not print as blank 0-client headers in the collector route PDF.
        try:
            def _route_norm(_s):
                try:
                    return " ".join(str(_s or "").split()).strip().lower()
                except Exception:
                    return str(_s or "").strip().lower()

            _active_rows = []
            try:
                _cur = self.db.conn.cursor()
                _active_rows = _cur.execute(
                    "SELECT DISTINCT TRIM(area) AS a FROM clients WHERE IFNULL(TRIM(area),'')<>'' AND COALESCE(is_archived,0)=0 ORDER BY a COLLATE NOCASE"
                ).fetchall()
            except Exception:
                _active_rows = []

            _active_areas = []
            for _r in (_active_rows or []):
                try:
                    _a = (_r['a'] if hasattr(_r, 'keys') else _r[0])
                except Exception:
                    _a = ''
                _a = str(_a or '').strip()
                if _a:
                    _active_areas.append(_a)

            _active_full = set()
            _active_main = set()
            _active_pairs = set()
            for _ma_src in (_active_areas or []):
                _full = _route_norm(_ma_src)
                if _full:
                    _active_full.add(_full)
                try:
                    _m_main, _m_sub = split_area_main_sub(_ma_src)
                except Exception:
                    _m_main, _m_sub = (str(_ma_src or "").strip(), "")
                _mn = _route_norm(_m_main)
                _sn = _route_norm(_m_sub)
                if _mn:
                    _active_main.add(_mn)
                if _mn and _sn:
                    _active_pairs.add((_mn, _sn))

            _filtered = []
            _seen = set()
            for _ra in (areas or []):
                _ra = str(_ra or "").strip()
                if not _ra:
                    continue
                try:
                    _r_main, _r_sub = split_area_main_sub(_ra)
                except Exception:
                    _r_main, _r_sub = (_ra, "")
                _rn = _route_norm(_ra)
                _rmn = _route_norm(_r_main)
                _rsn = _route_norm(_r_sub)

                _ok = False
                if _rsn:
                    _ok = ((_rmn, _rsn) in _active_pairs) or (_rn in _active_full)
                else:
                    _ok = (_rmn in _active_main) or (_rn in _active_full)

                if _ok and _ra not in _seen:
                    _filtered.append(_ra)
                    _seen.add(_ra)
            areas = _filtered
        except Exception:
            pass

        if not areas:
            messagebox.showwarning("No areas", f"{collector_name} has no active areas configured.")
            return

        try:
            self._ledger_forced_areas = areas
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0470', 'suppressed exception excpass_0470', __spina_exc)
            pass

        try:
            self._ledger_forced_collector_name = collector_name
            # Collector Route: restore the classic TWO payment columns (Regular + 7x7)
            self._route_payment_two_cols = True
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0471', 'suppressed exception excpass_0471', __spina_exc)
            pass

        try:
            self.print_full_daily_ledger()
        finally:
            for attr, fallback in [
                ("_ledger_forced_collector_name", ""),
                ("_route_payment_two_cols", False),
            ]:
                try:
                    delattr(self, attr)
                except Exception:
                    try:
                        setattr(self, attr, fallback)
                    except Exception as __spina_exc:
                        _log_suppressed_once('excpass_0472', 'suppressed exception excpass_0472', __spina_exc)
                        pass

            # Also clear forced areas in case print_full_daily_ledger returned early
            try:
                if hasattr(self, "_ledger_forced_areas"):
                    delattr(self, "_ledger_forced_areas")
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0473', 'suppressed exception excpass_0473', __spina_exc)
                pass

    def print_full_daily_ledger(self):
        """
        Print a 3-column DAILY COLLECTION LEDGER with a small UI to change:
          - Ledger Date
          - Paper size and orientation
          - Areas order (arrange ALL areas)
        """

        # --- Ensure a base row height is always defined to avoid UnboundLocalError ---
        try:
            row_h  # type: ignore  # may be set later for route layouts
        except NameError:
            row_h = 14  # default row height in points
        # --- Dependencies (local import) ---
        try:
            from reportlab.pdfgen import canvas as _cv
            from reportlab.pdfbase.pdfmetrics import stringWidth
            from reportlab.lib.pagesizes import A4, LETTER, LEGAL
            from reportlab.lib.pagesizes import landscape as _landscape
            from reportlab.lib.units import inch
        except Exception as e:
            try:
                from tkinter import messagebox
                messagebox.showerror(
                    "Printing not available",
                    "PDF printing requires ReportLab.\n\nInstall it with:\n  pip install reportlab"
                )
            except Exception:
                pass
            try:
                _log_exc("print_full_daily_ledger:missing_reportlab", e)
            except Exception:
                pass
            return

        import os
        from datetime import date as _today, datetime
        # --- Gather base rows ---
        # NOTE: Collector Route print is REGULAR-only (7x7 is ignored).
        # If a two-payment layout is enabled elsewhere via _route_payment_two_cols, we include BOTH loan types.
        try:
            _route_two_cols = bool(getattr(self, "_route_payment_two_cols", False))
        except Exception:
            _route_two_cols = False

        def _fetch_clients_for(_loan_type):
            try:
                return self.db.fetch_all_clients(loan_type=_loan_type) or []
            except Exception:
                try:
                    return [{"name": n, "area": ""} for n in (self.db.get_all_clients(loan_type=_loan_type) or [])]
                except Exception:
                    return []


        if _route_two_cols:
            # Two-payment layout: show 2 payment columns, but DO NOT add 7x7-only clients.
            # We only list Regular clients; the 7x7 column is computed for linked 7x7 records of those Regular clients.
            rows_regular = _fetch_clients_for("Regular")
            rows_7x7     = _fetch_clients_for("7x7")
            rows = (rows_regular or [])
        else:
            # Collector Route print: REGULAR ONLY (no 7x7 detection)
            rows_regular = []
            rows_7x7 = []
            try:
                _forced_collector = getattr(self, "_ledger_forced_collector_name", "") or ""
            except Exception:
                _forced_collector = ""
            if _forced_collector:
                rows = _fetch_clients_for("Regular")
            else:
                rows = _fetch_clients_for(self._mode_filter())

        # Distinct areas (A→Z, blank last)
        def _s(v): return (v or "").strip()
        distinct_areas = sorted({_s(r.get("area") if isinstance(r, dict) else getattr(r, "area", "")) for r in rows},
                                key=lambda s: (s == "" or s is None, (s or "").lower()))

        # --- UI 1: Options (date + paper) ---
        def _options_dialog(parent, default_date=None):
            import tkinter as tk
            from tkinter import ttk
            top = tk.Toplevel(parent)
            top.title("Ledger Options")
            top.resizable(False, False)
            try:
                top.attributes("-topmost", True)
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0474', 'suppressed exception excpass_0474', __spina_exc)
                pass
            frm = ttk.Frame(top, padding=12); frm.pack(fill="both", expand=True)

            # Date
            ttk.Label(frm, text="Ledger date (YYYY-MM-DD):").grid(row=0, column=0, sticky="w")
            var_date = tk.StringVar(value=default_date or _today.today().strftime("%Y-%m-%d"))
            _ld_row = ttk.Frame(frm)
            _ld_row.grid(row=0, column=1, sticky='w', padx=(6,0))
            ent_date = ttk.Entry(_ld_row, textvariable=var_date, width=18)
            ent_date.pack(side='left')
            ttk.Button(_ld_row, text='📅', width=3, command=lambda: pick_date(top, var_date, title='Select Ledger Date')).pack(side='left', padx=(4,0))

            # Paper
            ttk.Label(frm, text="Paper size:").grid(row=1, column=0, sticky="w", pady=(8,0))
            papers = ["Folio (8 x 13 in)", "A4 (210 x 297 mm)", "Letter (8.5 x 11 in)", "Legal (8.5 x 14 in)"]
            var_paper = tk.StringVar(value=papers[0])
            cbp = ttk.Combobox(frm, textvariable=var_paper, values=papers, state="readonly", width=24)
            cbp.grid(row=1, column=1, sticky="we", padx=(6,0), pady=(8,0))

            # Orientation
            ttk.Label(frm, text="Orientation:").grid(row=2, column=0, sticky="w", pady=(8,0))
            orients = ["Portrait", "Landscape"]
            var_orient = tk.StringVar(value="Portrait")
            cbo = ttk.Combobox(frm, textvariable=var_orient, values=orients, state="readonly", width=24)
            cbo.grid(row=2, column=1, sticky="we", padx=(6,0), pady=(8,0))

            # Buttons
            btns = ttk.Frame(frm); btns.grid(row=3, column=0, columnspan=2, pady=(10,0), sticky="e")
            out = {"ok": False}
            def _ok():
                out["ok"] = True
                top.destroy()
            def _cancel():
                out["ok"] = False
                top.destroy()
            ttk.Button(btns, text="Cancel", command=_cancel).pack(side="right", padx=6)
            ttk.Button(btns, text="OK", command=_ok).pack(side="right")

            frm.columnconfigure(1, weight=1)
            # Center
            top.update_idletasks()
            try:
                x = parent.winfo_rootx() + (parent.winfo_width()//2 - top.winfo_width()//2)
                y = parent.winfo_rooty() + (parent.winfo_height()//2 - top.winfo_height()//2)
                top.geometry(f"+{max(0,x)}+{max(0,y)}")
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0475', 'suppressed exception excpass_0475', __spina_exc)
                pass
            top.grab_set(); top.wait_window()
            if not out["ok"]:
                return None, None, None
            return var_date.get(), var_paper.get(), var_orient.get()

        # --- UI 2: Arrange Areas (order only, all included) ---
        def _arrange_areas_dialog(parent, areas_list):
            import tkinter as tk
            from tkinter import ttk
            top = tk.Toplevel(parent)
            top.title("Arrange Areas (All will be printed)")
            top.resizable(False, False)
            try:
                top.attributes("-topmost", True)
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0476', 'suppressed exception excpass_0476', __spina_exc)
                pass
            frm = ttk.Frame(top, padding=12); frm.pack(fill="both", expand=True)

            ttk.Label(frm, text="Reorder areas:").grid(row=0, column=0, columnspan=2, sticky="w")
            lb = tk.Listbox(frm, height=14, width=34, exportselection=False)
            lb.grid(row=1, column=0, rowspan=6, sticky="nsw")
            sb = ttk.Scrollbar(frm, orient="vertical", command=lb.yview); sb.grid(row=1, column=1, rowspan=6, sticky="ns")
            lb.config(yscrollcommand=sb.set)

            # NEW: seed with last saved order (if any)

            prefs = _load_ledger_prefs()

            _saved = (prefs.get("areas_order") or [])

            _saved = [a for a in _saved if a in areas_list]

            _rest  = [a for a in areas_list if a not in _saved]

            order = _saved + _rest
            for a in order:
                lb.insert("end", a if a != "" else "(UNASSIGNED)")

            def _move(up=True, to_edge=False):
                sel = lb.curselection()
                if not sel:
                    return
                i = sel[0]
                j = 0 if (up and to_edge) else (len(order)-1 if (not up and to_edge) else (i-1 if up else i+1))
                if j < 0 or j >= len(order):
                    return
                item = order.pop(i)
                order.insert(j, item)
                lb.delete(0, "end")
                for a in order:
                    lb.insert("end", a if a != "" else "(UNASSIGNED)")
                lb.selection_clear(0, "end"); lb.selection_set(j); lb.see(j)

            btns = ttk.Frame(frm); btns.grid(row=1, column=2, rowspan=6, padx=(10,0), sticky="ns")
            ttk.Button(btns, text="Move Up", command=lambda:_move(True, False)).pack(fill="x", pady=2)
            ttk.Button(btns, text="Move Down", command=lambda:_move(False, False)).pack(fill="x", pady=2)
            ttk.Button(btns, text="Top", command=lambda:_move(True, True)).pack(fill="x", pady=6)
            ttk.Button(btns, text="Bottom", command=lambda:_move(False, True)).pack(fill="x", pady=2)

            act = {"ok": False}
            def _ok():
                act["ok"] = True; top.destroy()
            def _cancel():
                act["ok"] = False; top.destroy()
            row_last = 7
            ttk.Button(frm, text="Cancel", command=_cancel).grid(row=row_last, column=2, sticky="e", pady=(10,0))
            ttk.Button(frm, text="OK", command=_ok).grid(row=row_last, column=3, sticky="e", padx=6, pady=(10,0))

            # Center
            top.update_idletasks()
            try:
                x = parent.winfo_rootx() + (parent.winfo_width()//2 - top.winfo_width()//2)
                y = parent.winfo_rooty() + (parent.winfo_height()//2 - top.winfo_height()//2)
                top.geometry(f"+{max(0,x)}+{max(0,y)}")
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0477', 'suppressed exception excpass_0477', __spina_exc)
                pass
            top.grab_set(); top.wait_window()
            return order if act["ok"] else None

        # --- Run dialogs ---
        try:
            _silent_route_copy = bool(getattr(self, "_ledger_silent_route_copy", False))
        except Exception:
            _silent_route_copy = False
        if _silent_route_copy:
            opts = (
                str(getattr(self, "_ledger_forced_date", _today.today().strftime("%Y-%m-%d")) or _today.today().strftime("%Y-%m-%d")),
                str(getattr(self, "_ledger_forced_paper_label", "Folio (8 x 13 in)") or "Folio (8 x 13 in)"),
                str(getattr(self, "_ledger_forced_orientation", "Portrait") or "Portrait"),
            )
        else:
            opts = _options_dialog(self.root, default_date=_today.today().strftime("%Y-%m-%d"))
        if not opts or not all(opts):
            return
        ledger_date, paper_label, orient = opts

        # Resolve page size

        # Load NEW-client highlight setting (days; 0 = off) from prefs
        try:
            highlight_days = int(_load_ledger_prefs().get('new_highlight_days', 7))
        except Exception:
            highlight_days = 7
        page_size = (8*inch, 13*inch)  # default Folio
        if paper_label.startswith("A4"):
            page_size = A4
        elif paper_label.startswith("Letter"):
            page_size = LETTER
        elif paper_label.startswith("Legal"):
            page_size = LEGAL
        elif paper_label.startswith("Folio"):
            page_size = (8*inch, 13*inch)
        if str(orient).lower().startswith("land"):
            page_size = _landscape(page_size)
        width, height = page_size
# Arrange areas
        _forced = getattr(self, '_ledger_forced_areas', None)
        if _forced:
            # Use only the collector's route (preserve their order)
            ordered = [a for a in _forced if a is not None]
        else:
            ordered = _arrange_areas_dialog(self.root, distinct_areas)
        if not ordered:
            return


        # Persist chosen order only for the all-areas (non-forced) flow
        if not getattr(self, '_ledger_forced_areas', None):
            try:
                prefs = _load_ledger_prefs()
                prefs["areas_order"] = ordered
                _save_ledger_prefs(prefs)
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0478', 'suppressed exception excpass_0478', __spina_exc)
                pass
        # --- Build area -> clients map in chosen order ---
        by_area = {}

        if _route_two_cols:
            # Collector Route "Regular-first" logic:
            # - Place clients by their REGULAR record area when they exist in Regular.
            # - Only add 7x7 clients that do NOT have a Regular record (7x7-only), placed by their 7x7 area.
            # This prevents duplicates when a client exists in both types but has different areas.
            def _iter_rows(rr):
                for r in (rr or []):
                    if isinstance(r, dict):
                        yield _s(r.get("name")), _s(r.get("area"))
                    else:
                        yield _s(getattr(r, "name", "")), _s(getattr(r, "area", ""))

            reg_name_to_area = {}
            reg_name_to_disp = {}
            sev_name_to_area = {}
            sev_name_to_disp = {}

            for nm, ar in _iter_rows(rows_regular):
                if not nm:
                    continue
                key = nm.strip().lower()
                reg_name_to_area[key] = ar
                reg_name_to_disp[key] = nm

            for nm, ar in _iter_rows(rows_7x7):
                if not nm:
                    continue
                key = nm.strip().lower()
                sev_name_to_area[key] = ar
                sev_name_to_disp[key] = nm

            # Add ALL Regular clients (Regular area wins)
            for key, ar in reg_name_to_area.items():
                disp = reg_name_to_disp.get(key) or key
