                def _dash_norm_lt(_v):
                    try:
                        _s = str(_v or "Regular").strip().lower().replace(" ", "").replace("×", "x")
                    except Exception:
                        _s = "regular"
                    return "7x7" if _s == "7x7" or "7x7" in _s else "Regular"
        
                def _dash_fmt_money_short(_v):
                    try:
                        _n = float(_v or 0)
                    except Exception:
                        _n = 0.0
                    try:
                        if abs(_n - int(_n)) < 0.005:
                            return f"{int(_n):,}"
                    except Exception:
                        pass
