                                _asof_dt = None
                                try:
                                    _asof_dt = datetime.strptime(str(ledger_date)[:10], "%Y-%m-%d").date()
                                except Exception:
                                    try:
                                        _asof_dt = date.today()
                                    except Exception:
                                        _asof_dt = None
                                _rem_interest = _spina_cashctl_estimated_payoff_with_interest(self, dict(_dr or {}), _asof_dt)
                                _rem = round(max(0.0, float(_rem_interest or 0.0)), 2)
                                # If only interest/arrears remains, do not print COMPLETE; show it as 90% with balance.
