from spina_app.utilities.dates import _spina__parse_day_ymd


from spina_app.utilities.dates import _spina__norm_weekday


from spina_app.utilities.dates import _spina__norm_dom


def _spina__client_schedule_anchor(row: dict | None):
    row = row or {}
    anchor = _spina__parse_day_ymd((row or {}).get('payment_start_date') or (row or {}).get('date_released') or (row or {}).get('created_at') or (row or {}).get('due_date'))
    if anchor and not (row or {}).get('payment_start_date'):
        try:
            off = int((row or {}).get('pay_start_offset_days') or 0)
        except Exception:
            off = 0
        if off >= 1:
            try:
                anchor = anchor + timedelta(days=1)
            except Exception:
                pass
    return anchor


def _spina__client_due_meta(info: dict | None, as_of=None) -> tuple[str, bool]:
    """Return (day_due_label, due_today_bool) using stored schedule fields when present."""
    try:
        row = info or {}
        term = str(row.get('payment_term') or '').strip().title()
    except Exception:
        row = {}
        term = ''

    target = _spina__parse_day_ymd(as_of) if as_of else date.today()
    anchor = _spina__client_schedule_anchor(row)

    if term == 'Daily':
        due_today = bool(anchor and target and target >= anchor)
        return ('Daily', due_today)

    if term == 'Weekly':
        weekday = _spina__norm_weekday((row or {}).get('due_weekday'))
        if not weekday and anchor:
            try:
                weekday = anchor.strftime('%a')
            except Exception:
                weekday = ''
        if weekday:
            mp = {'Mon': 0, 'Tue': 1, 'Wed': 2, 'Thu': 3, 'Fri': 4, 'Sat': 5, 'Sun': 6}
            due_today = bool(anchor and target and target >= anchor and target.weekday() == mp.get(weekday, -99))
            return (weekday, due_today)
        return ('Weekly', False)

    if term == 'Monthly':
        dom = _spina__norm_dom((row or {}).get('monthly_due_day'))
        if dom is None and anchor:
            dom = anchor.day
        if dom is not None:
            import calendar as _cal
            label = f"Day {dom}"
            if target and anchor and target >= anchor:
                try:
                    due_dom = min(dom, _cal.monthrange(target.year, target.month)[1])
                    return (label, bool(target.day == due_dom))
                except Exception:
                    return (label, False)
            return (label, False)
        return ('Monthly', False)

    if term == 'Semi':
        d1 = _spina__norm_dom((row or {}).get('semi_due_day1'))
        d2 = _spina__norm_dom((row or {}).get('semi_due_day2'))
        if d1 is not None and d2 is not None:
            if d2 < d1:
                d1, d2 = d2, d1
            label = f"{d1}/{d2}"
            if target and anchor and target >= anchor:
                import calendar as _cal
                last_dom = _cal.monthrange(target.year, target.month)[1]
                v1 = min(d1, last_dom)
                v2 = min(d2, last_dom)
                return (label, bool(target.day in (v1, v2)))
            return (label, False)
        if anchor and target:
            delta = (target - anchor).days
            return ('15-day cycle', bool(delta >= 0 and (delta % 15 == 0)))
        return ('15-day cycle', False)

    return ('', False)

def refresh_clients(self):
    """Refresh the Clients tab table from the database, honoring the search box."""
    term = ""
    try:
        term = getattr(self, "search_clients_var", tk.StringVar()).get().strip()
    except Exception:
        term = ""

    try:
        for row_id in self.clients_tree.get_children():
            self.clients_tree.delete(row_id)
    except Exception:
        return

    try:
        names = self.db.get_all_clients(search=term if term else None, loan_type=self._mode_filter(), search_by='all')
    except Exception:
        names = []

    # Insert rows
    for name in names:
        info = self.db.get_client_info(name, loan_type=self._mode_filter()) or {}

        # Linked indicator:
        # - Shows "7x7✓" / "Regular✓" when this record is linked (person_uid group contains the other type),
        #   even if the other record's name is slightly different.
        # - Shows "7x7" / "Regular" when a same-name record exists in the other type (suggested, not linked yet).
        link_label = ""
        try:
            lt = self._mode_filter()
            lt = '7x7' if str(lt).lower().replace(' ', '') in ('7x7', '7×7') else 'Regular'
            other_lt = "7x7" if lt == "Regular" else "Regular"

            pu = (info.get("person_uid") or "").strip()
            if pu:
                linked_rows = []
                try:
                    linked_rows = self.db.find_clients_by_person_uid(pu) or []
                except Exception:
                    linked_rows = []

                other_types = set()
                for r in linked_rows:
                    try:
                        t = (r.get("loan_type") or "").strip()
                        if t and t != lt:
                            # normalize
                            t = '7x7' if t.lower().replace(' ', '') in ('7x7', '7×7') else 'Regular'
                            other_types.add(t)
                    except Exception as __spina_exc:
                        _log_suppressed_once('excpass_0520', 'suppressed exception excpass_0520', __spina_exc)
                        pass

                if other_types:
                    # If more than one other type exists, join them (rare)
                    order = ["Regular", "7x7"]
                    parts = [t for t in order if t in other_types]
                    link_label = "+".join(parts) + "✓"
                else:
                    # Linked group exists but only this record remains (e.g., other deleted)
                    link_label = "Linked✓"
            else:
                # Not linked: show existence of same-name record in the other type (suggestion)
                other = self.db.get_client_info(name, loan_type=other_lt)
                if other:
                    link_label = f"{other_lt}"
        except Exception:
            link_label = ""

        _day_due, _due_today = _spina__client_due_meta(info)
        _day_due_val = _day_due

        self.clients_tree.insert(
            "", "end",
            values=(
                name,
                info.get("contact_number", ""),
                info.get("payment_mode", "Cash"),
                info.get("payment_term", ""),
                _day_due_val,
                info.get("payment_amount", 0),
                link_label,
                info.get("area", ""),
                info.get("principal", 0),
                info.get("interest_amount", 0),
                info.get("total_to_pay", 0),
                info.get("date_released", ""),
                info.get("due_date", ""),
            ),
        )

    try:
        self._update_toolbar_states()
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0521', 'suppressed exception excpass_0521', __spina_exc)
        pass


    def delete_client_selected(self):
        sel = self.clients_tree.selection()
        if not sel:
            messagebox.showwarning('Select', 'Please select a client to delete.')
            return
        iid = sel[0]
        name = self.clients_tree.item(iid, 'values')[0]
        # Infer actual loan_type from the row (supports 7x7-only rows shown in Regular view)
        lt = self._mode_filter()
        try:
            tags = self.clients_tree.item(iid, 'tags') or ()
            for t in tags:
                if str(t).startswith('lt:'):
                    lt = str(t).split(':', 1)[1]
                    break
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0522', 'suppressed exception excpass_0522', __spina_exc)
            pass

        if not messagebox.askyesno('Confirm', f"Delete client '{name}' and all their transactions?"):
            return
        try:
            self.db.delete_client(name, loan_type=lt)
        except Exception as e:
            messagebox.showerror('Delete Error', str(e))
            return
        self.refresh_clients(); self.refresh_reports(); self.refresh_data_grid()
        try:
            if hasattr(self, '_update_toolbar_states'):
                self._update_toolbar_states()
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0523', 'suppressed exception excpass_0523', __spina_exc)
            pass
        messagebox.showinfo('Deleted', f"Client '{name}' deleted.")


    def renew_client_selected(self):
        """Renew (reloan) the selected client and update the client row."""
        sel = self.clients_tree.selection()
        if not sel:
            messagebox.showwarning('Select', 'Please select one client to renew.')
            return
        iid = sel[0]
        vals = self.clients_tree.item(iid, 'values') or ()
        if not vals:
            messagebox.showwarning('Select', 'Please select one client to renew.')
            return

        name = vals[0]
        lt = self._mode_filter()
        try:
            tags = self.clients_tree.item(iid, 'tags') or ()
            for t in tags:
                if str(t).startswith('lt:'):
                    lt = str(t).split(':', 1)[1]
                    break
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0524', 'suppressed exception excpass_0524', __spina_exc)
            pass

        info = self.db.get_client_info(name, loan_type=lt) or {}
        if not info:
            messagebox.showerror('Missing', 'Client not found in database.')
            return

        # Use the newer RenewDialog with auto-compute (Released Cash can be left blank).
        try:
            dlg = RenewDialog(self.root, initial=info, loan_type=lt, db=self.db)
        except Exception:
            dlg = self.RenewDialog(self.root, initial=info, loan_type=lt)
        if not getattr(dlg, 'result', None):
            return

        r = dlg.result
        ok = self.db.renew_client(
            name,
            released_cash=r.get('released_cash'),
            renew_date=r.get('renew_date'),
            new_principal=r.get('new_principal'),
            loan_type=lt,
            interest_rate=r.get('interest_rate'),
            pay_start_offset_days=r.get('pay_start_offset_days'),
            note=r.get('note',''),
        )
        if ok:
            try:
                messagebox.showinfo('Renewed', 'Client renewed successfully.')
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0525', 'suppressed exception excpass_0525', __spina_exc)
                pass
            try:
                self.refresh_clients()
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0526', 'suppressed exception excpass_0526', __spina_exc)
                pass
            try:
                self.refresh_reports()
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0527', 'suppressed exception excpass_0527', __spina_exc)
                pass
        else:
            reason = str(getattr(self.db, '_last_renew_error', '') or '').strip()
            messagebox.showerror('Error', ('Failed to renew client.\n\nReason: ' + reason) if reason else 'Failed to renew client.')


