    info_y = _draw_pair(info_y, 'Loan Type:', _display_loan_type_label(loan_type), 'Contact:', contact_raw or '-')
    info_y = _draw_pair(info_y, 'Payment Term:', _term_hdr, 'Payment Amount:', _pay_amt_hdr)
