def _ensure_prefs_file():
    try:
        os.makedirs(DATA_DIR, exist_ok=True)
        prefs = _load_ledger_prefs()
        if "areas_order" not in prefs:
            prefs["areas_order"] = []
            _save_ledger_prefs(prefs)
    except Exception:
        # Fail silently; feature is optional
        pass

# Ensure prefs file exists at import time
_ensure_prefs_file()


# --- Startup bindings / fixes (must be before main()) ---
# v4_23 patch: ensure Clients + Linking methods exist on App at import time,
# even if earlier patches accidentally nested method definitions.

def _app__norm_lt_value(self, v):
    try:
        return self.db._effective_lt(v)
    except Exception:
        s = (str(v or '').strip() or '')
        s2 = s.lower().replace(' ', '')
        if s2 in ('7x7','7×7'):
            return '7x7'
        return 'Regular'

def _app__other_lt(self, lt):
    lt = _app__norm_lt_value(self, lt)
    return '7x7' if lt == 'Regular' else 'Regular'

def _app__get_selected_client_name(self):
    try:
        sel = self.clients_tree.selection()
        if not sel:
            return None
        vals = self.clients_tree.item(sel[0], 'values') or ()
        if not vals:
            return None
        return str(vals[0]).strip()
    except Exception:
        return None

def _app__client_form(self, title, initial=None, is_edit=False):
    # Client add/edit dialog with:
    # - Area dropdown (validated)
    # - Calendar pickers for dates
    # - Optional payment start offset (+1 day) checkbox stored as pay_start_offset_days
    init = dict(initial or {})
    lt = _app__norm_lt_value(self, init.get('loan_type') or self._mode_filter())

    win = tk.Toplevel(self.root)
    win.title(title)
    # Bigger client editor window; allow resizing for long fields / dropdowns.
    win.resizable(True, True)
    try:
        win.transient(self.root)
        win.grab_set()
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0623', 'suppressed exception excpass_0623', __spina_exc)
        pass

    # Larger, easier-to-read editor text.
    try:
        import tkinter.font as _tkfont_client_editor
        _client_editor_font = _tkfont_client_editor.Font(family="Segoe UI", size=11)
        _client_editor_label_font = _tkfont_client_editor.Font(family="Segoe UI", size=11, weight="bold")
        _client_editor_button_font = _tkfont_client_editor.Font(family="Segoe UI", size=10)
    except Exception:
        _client_editor_font = None
        _client_editor_label_font = None
        _client_editor_button_font = None
    try:
        win.option_add("*TCombobox*Listbox.font", _client_editor_font)
    except Exception:
        pass

    # Vars
    name_var = tk.StringVar(value=str(init.get('name') or '').strip())
    contact_var = tk.StringVar(value=str(init.get('contact_number') or '').strip())
    loan_type_var = tk.StringVar(value=lt)
    area_var = tk.StringVar(value=str(init.get('area') or '').strip())
    principal_var = tk.StringVar(value=str(init.get('principal') or 0).strip())
    # interest rate stored as decimal (0.20) - only for Regular
    ir_init = init.get('interest_rate')
    if ir_init is None:
        ir_init = 0.20
    interest_var = tk.StringVar(value=str(ir_init))
    released_var = tk.StringVar(value=str(init.get('date_released') or '').strip())
    new_until_var = tk.StringVar(value=str(init.get('new_until') or '').strip())


    # Payment Term / Payment Amount / Payment Mode (optional)
    payterm_var = tk.StringVar(value=str(init.get('payment_term') or 'Daily').strip() or 'Daily')
    payamt_var = tk.StringVar(value=str(init.get('payment_amount') or '').strip())
    _pm_base0, _pm_other0 = _spina__split_payment_mode(init.get('payment_mode') or 'Cash')
    paymode_var = tk.StringVar(value=_pm_base0)
    paymode_other_var = tk.StringVar(value=_pm_other0)
    due_weekday_var = tk.StringVar(value=_spina__norm_weekday(init.get('due_weekday') or ''))
    semi_due_day1_var = tk.StringVar(value='' if init.get('semi_due_day1') in (None, '') else str(init.get('semi_due_day1')))
    semi_due_day2_var = tk.StringVar(value='' if init.get('semi_due_day2') in (None, '') else str(init.get('semi_due_day2')))
    monthly_due_day_var = tk.StringVar(value='' if init.get('monthly_due_day') in (None, '') else str(init.get('monthly_due_day')))
    flex_due_rule_var = tk.StringVar(value=str(init.get('flex_due_rule') or '').strip())

    # Friendly dropdown for flexible due schedules.
    # The database still stores compact rule codes, so existing collector-route logic remains stable.
    def _flex_due_options():
        opts = [
            ("Follow Payment Term", ""),

            ("Salary 5/20 - exact 5 and 20", "salary 5/20 window 0"),
            ("Salary 5/20 - before & after 1 day", "salary 5/20 window 1"),
            ("Salary 5/20 - before & after 2 days", "salary 5/20 window 2"),
            ("Salary 5/20 - before & after 3 days", "salary 5/20 window 3"),
            ("Salary 5/20 - common window dates", "days 4,5,6,19,20,21"),

            ("Salary 10/25 - exact 10 and 25", "salary 10/25 window 0"),
            ("Salary 10/25 - before & after 1 day", "salary 10/25 window 1"),
            ("Salary 10/25 - before & after 2 days", "salary 10/25 window 2"),
            ("Salary 10/25 - before & after 3 days", "salary 10/25 window 3"),
            ("Salary 10/25 - common window dates", "days 9,10,11,24,25,26"),

            ("Salary 15/30 - exact 15 and month-end", "salary 15/30 window 0"),
            ("Salary 15/30 - before & after 1 day", "salary 15/30 window 1"),
            ("Salary 15/30 - before & after 2 days", "salary 15/30 window 2"),
            ("Salary 15/30 - before & after 3 days", "salary 15/30 window 3"),
            ("Salary 15/30 - common window dates", "days 14,15,16,29,30,31"),

            ("Specific dates: 4,5,6,19,20,21", "days 4,5,6,19,20,21"),
            ("Specific dates: 9,10,11,24,25,26", "days 9,10,11,24,25,26"),
            ("Specific dates: 14,15,16,29,30,31", "days 14,15,16,29,30,31"),
        ]
        weekdays_full = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]

        # Twice-a-week payment/reminder schedules.
        # These cover clients who are paid twice weekly or collect reliably on two weekdays.
        # Stored as compact codes like: "weekly Monday Thursday".
        common_twice_weekly = [
            ("Monday", "Thursday"),
            ("Tuesday", "Friday"),
            ("Wednesday", "Saturday"),
            ("Monday", "Wednesday"),
            ("Monday", "Friday"),
            ("Tuesday", "Saturday"),
        ]
        seen_twice = set()
        for a, b in common_twice_weekly:
            key = tuple(sorted((a, b)))
            seen_twice.add(key)
            opts.append((f"Twice weekly: {a} and {b}", f"weekly {a} {b}"))

        # Add every possible pair too, so the dropdown can handle unusual work schedules.
        for i, a in enumerate(weekdays_full):
            for b in weekdays_full[i + 1:]:
                key = tuple(sorted((a, b)))
                if key in seen_twice:
                    continue
                opts.append((f"Twice weekly: {a} and {b}", f"weekly {a} {b}"))

        ordinals = [("1st", "1st"), ("2nd", "2nd"), ("3rd", "3rd"), ("4th", "4th"), ("5th", "5th"), ("Last", "last")]
        for lbl_ord, code_ord in ordinals:
            for wd in weekdays_full:
                opts.append((f"Every {lbl_ord} {wd}", f"{code_ord} {wd}"))
        return opts

    _flex_due_pairs = _flex_due_options()
    _flex_due_label_to_code = {lbl: code for lbl, code in _flex_due_pairs}
    _flex_due_code_to_label = {}
    for _lbl, _code in _flex_due_pairs:
        if _code not in _flex_due_code_to_label:
            _flex_due_code_to_label[_code] = _lbl

    def _flex_due_label_from_code(code):
        try:
            c = str(code or '').strip()
        except Exception:
            c = ''
        if not c:
            return "Follow Payment Term"
        if c in _flex_due_code_to_label:
            return _flex_due_code_to_label[c]
        return f"Custom / legacy: {c}"

    _initial_flex_label = _flex_due_label_from_code(flex_due_rule_var.get())
    _flex_due_values = [lbl for lbl, _code in _flex_due_pairs]
    if _initial_flex_label not in _flex_due_values:
        _flex_due_values.append(_initial_flex_label)
    flex_due_choice_var = tk.StringVar(value=_initial_flex_label)

    def _flex_due_code_from_choice():
        try:
            label = str(flex_due_choice_var.get() or '').strip()
        except Exception:
            label = ''
        if label.startswith('Custom / legacy:'):
            code = label.split(':', 1)[1].strip()
        else:
            code = _flex_due_label_to_code.get(label, '')
        try:
            flex_due_rule_var.set(code)
        except Exception:
            pass
        return code

    is_new_var = tk.IntVar(value=1 if str(init.get('new_until') or '').strip() else 0)

    # Pay start offset:
    # 0 = same-day start, 1 = next-day start (optional)
    psod = init.get('pay_start_offset_days')
    try:
        psod = int(psod or 0)
    except Exception:
        psod = 0

    psod_var = tk.IntVar(value=1 if psod >= 1 else 0)

    def _current_anchor_for_form():
        try:
            dr = (released_var.get() or '').strip()
            if not dr:
                return None
            d0 = datetime.strptime(dr, "%Y-%m-%d").date()
            return d0 + timedelta(days=(1 if psod_var.get() else 0))
        except Exception:
            return None

    def _prime_due_defaults(force=False):
        _term = (payterm_var.get() or '').strip().title()
        _anchor = _current_anchor_for_form()
        if not _anchor:
            return
        try:
            if _term == 'Weekly' and (force or not (due_weekday_var.get() or '').strip()):
                due_weekday_var.set(_anchor.strftime('%a'))
            elif _term == 'Monthly' and (force or not (monthly_due_day_var.get() or '').strip()):
                monthly_due_day_var.set(str(_anchor.day))
            elif _term == 'Semi':
                import calendar as _cal
                if force or not (semi_due_day1_var.get() or '').strip():
                    semi_due_day1_var.set(str(_anchor.day))
                if force or not (semi_due_day2_var.get() or '').strip():
                    _other = _anchor + timedelta(days=15)
                    semi_due_day2_var.set(str(min(_other.day, _cal.monthrange(_other.year, _other.month)[1])))
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0622due', 'suppressed exception excpass_0622due', __spina_exc)
            pass

    if not (due_weekday_var.get() or '').strip() and not (monthly_due_day_var.get() or '').strip() and not (semi_due_day1_var.get() or '').strip() and not (semi_due_day2_var.get() or '').strip():
        _prime_due_defaults(force=True)

    # Layout
    outer = ttk.Frame(win, padding=18)
    outer.pack(fill='both', expand=True)

    def row(label, widget, r):
        ttk.Label(outer, text=label, font=_client_editor_label_font).grid(row=r, column=0, sticky='w', padx=(0,14), pady=7)
        widget.grid(row=r, column=1, sticky='we', pady=7)
    outer.columnconfigure(1, weight=1)

    r = 0
    row("Name:", ttk.Entry(outer, textvariable=name_var, width=46), r); r += 1
    row("Contact No:", ttk.Entry(outer, textvariable=contact_var, width=46), r); r += 1

    # Loan type (readonly; locked on edit)
    lt_cb = ttk.Combobox(outer, textvariable=loan_type_var, values=('Regular','7x7'), state='readonly', width=44)
    row("Loan Type:", lt_cb, r); r += 1
    if is_edit:
        try: lt_cb.config(state='disabled')
        except Exception: pass

    # Managed hierarchical Area selector
    from spina_app.area_hierarchy_ui import build_simple_area_selector
    area_frame = build_simple_area_selector(self, outer, area_var, width=34)
    row("Area:", area_frame, r); r += 1

    row("Principal:", ttk.Entry(outer, textvariable=principal_var, width=46), r); r += 1

    ir_entry = ttk.Entry(outer, textvariable=interest_var, width=46)
    row("Interest Rate:", ir_entry, r); r += 1


    # Payment Term / Amount / Mode
    pt_cb = ttk.Combobox(outer, textvariable=payterm_var, values=('Daily','Weekly','Semi','Monthly'), state='readonly', width=44)
    row("Payment Term:", pt_cb, r); r += 1

    due_weekday_cb = ttk.Combobox(outer, textvariable=due_weekday_var, values=('Mon','Tue','Wed','Thu','Fri','Sat','Sun'), state='readonly', width=44)
    row("Due Weekday:", due_weekday_cb, r); r += 1

    def _dom_seed_date(_day_val=None):
        try:
            _base = _current_anchor_for_form() or date.today()
        except Exception:
            _base = date.today()
        try:
            _dom = _spina__norm_dom(_day_val)
        except Exception:
            _dom = None
        if _dom is None:
            return _base
        try:
            _last = calendar.monthrange(_base.year, _base.month)[1]
            return date(_base.year, _base.month, min(max(1, int(_dom)), _last))
        except Exception:
            return _base

    def _pick_dom(var_obj, title_text):
        try:
            _initial = _dom_seed_date(var_obj.get())
        except Exception:
            _initial = None
        _picked = pick_date(win, initial=(_initial.strftime("%Y-%m-%d") if _initial else None), title=title_text)
        try:
            if _picked is None:
                return
            var_obj.set(str(int(_picked.day)))
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0628dompick', 'suppressed exception excpass_0628dompick', __spina_exc)
            pass

    semi_frame = ttk.Frame(outer)
    semi1_frame = ttk.Frame(semi_frame)
    semi1_frame.pack(side='left')
    semi1_entry = ttk.Entry(semi1_frame, textvariable=semi_due_day1_var, width=12, state='readonly', justify='center')
    semi1_entry.pack(side='left')
    semi1_btn = ttk.Button(semi1_frame, text="📅", width=3, command=lambda: _pick_dom(semi_due_day1_var, "Semi Due Day 1"))
    semi1_btn.pack(side='left', padx=(4, 0))
    ttk.Label(semi_frame, text='/').pack(side='left', padx=6)
    semi2_frame = ttk.Frame(semi_frame)
    semi2_frame.pack(side='left')
    semi2_entry = ttk.Entry(semi2_frame, textvariable=semi_due_day2_var, width=12, state='readonly', justify='center')
    semi2_entry.pack(side='left')
    semi2_btn = ttk.Button(semi2_frame, text="📅", width=3, command=lambda: _pick_dom(semi_due_day2_var, "Semi Due Day 2"))
    semi2_btn.pack(side='left', padx=(4, 0))
    row("Semi Due Days:", semi_frame, r); r += 1

    monthly_due_frame = ttk.Frame(outer)
    monthly_due_entry = ttk.Entry(monthly_due_frame, textvariable=monthly_due_day_var, width=32, state='readonly', justify='center')
    monthly_due_entry.pack(side='left', fill='x', expand=True)
    monthly_due_btn = ttk.Button(monthly_due_frame, text="📅", width=3, command=lambda: _pick_dom(monthly_due_day_var, "Monthly Due Day"))
    monthly_due_btn.pack(side='left', padx=6)
    row("Monthly Due Day:", monthly_due_frame, r); r += 1

    flex_due_frame = ttk.Frame(outer)
    flex_due_cb = ttk.Combobox(
        flex_due_frame,
        textvariable=flex_due_choice_var,
        values=_flex_due_values,
        state='readonly',
        width=52,
    )
    flex_due_cb.pack(side='left', fill='x', expand=True)
    ttk.Label(
        flex_due_frame,
        text="Used for DUE TODAY reminders in Collector Route",
        foreground="#666666"
    ).pack(side='left', padx=(8,0))
    try:
        flex_due_cb.bind('<<ComboboxSelected>>', lambda _e=None: _flex_due_code_from_choice())
    except Exception:
        pass
    row("Flexible Due Rule:", flex_due_frame, r); r += 1

    row("Payment Amount:", ttk.Entry(outer, textvariable=payamt_var, width=46), r); r += 1
    pm_cb = ttk.Combobox(outer, textvariable=paymode_var, values=_SPINA_PAYMENT_MODE_OPTIONS, state='readonly', width=44)
    row("Mode of Payment:", pm_cb, r); r += 1
    pm_other_entry = ttk.Entry(outer, textvariable=paymode_other_var, width=46)
    row("Other Payment Mode:", pm_other_entry, r); r += 1
    # Date Released
    rel_frame = ttk.Frame(outer)
    rel_entry = ttk.Entry(rel_frame, textvariable=released_var, width=32)
    rel_entry.pack(side='left', fill='x', expand=True)
    ttk.Button(rel_frame, text="📅", width=3, command=lambda: pick_date(win, released_var, title="Date Released")).pack(side='left', padx=6)
    row("Date Released:", rel_frame, r); r += 1

    # Computed labels
    start_pay_lbl = ttk.Label(outer, text="")
    row("Start of Payment:", start_pay_lbl, r); r += 1

    due_lbl = ttk.Label(outer, text="")
    row("Due Date:", due_lbl, r); r += 1

    # New until
    new_frame = ttk.Frame(outer)
    new_chk = ttk.Checkbutton(new_frame, text="Mark as NEW", variable=is_new_var)
    new_chk.pack(side='left')
    nu_entry = ttk.Entry(new_frame, textvariable=new_until_var, width=24)
    nu_entry.pack(side='left', padx=6)
    ttk.Button(new_frame, text="📅", width=3, command=lambda: pick_date(win, new_until_var, title="New Until")).pack(side='left', padx=4)
    row("New Tag:", new_frame, r); r += 1

    # Payment start offset
    psod_chk = ttk.Checkbutton(outer, text="Next day start (+1 day after release)", variable=psod_var)
    psod_chk.grid(row=r, column=1, sticky='w', pady=6); r += 1

    def _toggle_new_until(*_):
        try:
            if is_new_var.get():
                nu_entry.config(state='normal')
            else:
                new_until_var.set("")
                nu_entry.config(state='disabled')
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0627', 'suppressed exception excpass_0627', __spina_exc)
            pass

    def _toggle_due_widgets(*_):
        _term = (payterm_var.get() or '').strip().title()
        try:
            due_weekday_cb.config(state='readonly' if _term == 'Weekly' else 'disabled')
        except Exception:
            pass
        try:
            semi_state = 'readonly' if _term == 'Semi' else 'disabled'
            semi_btn_state = 'normal' if _term == 'Semi' else 'disabled'
            semi1_entry.config(state=semi_state)
            semi2_entry.config(state=semi_state)
            semi1_btn.config(state=semi_btn_state)
            semi2_btn.config(state=semi_btn_state)
        except Exception:
            pass
        try:
            monthly_due_entry.config(state=('readonly' if _term == 'Monthly' else 'disabled'))
            monthly_due_btn.config(state=('normal' if _term == 'Monthly' else 'disabled'))
        except Exception:
            pass
        _prime_due_defaults(force=False)

    def _toggle_paymode_other(*_):
        try:
            is_other = ((paymode_var.get() or '').strip() == 'Others')
        except Exception:
            is_other = False
        try:
            pm_other_entry.config(state=('normal' if is_other else 'disabled'))
        except Exception:
            pass
        if not is_other:
            try:
                paymode_other_var.set('')
            except Exception:
                pass

    def _compute_dates(*_):
        lt_local = _app__norm_lt_value(self, loan_type_var.get())
        due_days = 49 if lt_local == '7x7' else 120
        try:
            dr = released_var.get().strip()
            d0 = datetime.strptime(dr, "%Y-%m-%d").date()
            offset = 1 if psod_var.get() else 0
            sp = d0 + timedelta(days=offset)
            start_pay_lbl.config(text=sp.strftime("%Y-%m-%d"))
            due_lbl.config(text=(d0 + timedelta(days=due_days)).strftime("%Y-%m-%d"))
        except Exception:
            start_pay_lbl.config(text="")
            due_lbl.config(text="")
        try:
            _prime_due_defaults(force=False)
        except Exception:
            pass
        try:
            if lt_local == '7x7':
                interest_var.set("0")
                ir_entry.config(state='disabled')
            else:
                ir_entry.config(state='normal')
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0628', 'suppressed exception excpass_0628', __spina_exc)
            pass

    try:
        is_new_var.trace_add('write', _toggle_new_until)
    except Exception as e:
        _log_ignored("ui.trace_add failed", e, key="ui.trace_add_failed")
    try:
        released_var.trace_add('write', _compute_dates)
        psod_var.trace_add('write', _compute_dates)
        loan_type_var.trace_add('write', _compute_dates)
        payterm_var.trace_add('write', _toggle_due_widgets)
        paymode_var.trace_add('write', _toggle_paymode_other)
    except Exception as e:
        _log_ignored("ui.trace_add failed", e, key="ui.trace_add_failed")
    _toggle_new_until()
    _toggle_due_widgets()
    _toggle_paymode_other()
    _compute_dates()

    # Buttons
    btns = ttk.Frame(outer)
    btns.grid(row=r, column=0, columnspan=2, sticky='e', pady=(10,0))
    result = {"ok": False}

    def _validate_date(s):
        s = (s or '').strip()
        if not s:
            return ""
        datetime.strptime(s[:10], "%Y-%m-%d")
        return s[:10]

    def save():
        nm = " ".join(name_var.get().strip().split())
        if not nm:
            messagebox.showerror("Required", "Client name is required.", parent=win)
            return
        lt_local = _app__norm_lt_value(self, loan_type_var.get())
        try:
            p = float(principal_var.get().strip() or 0)
        except Exception:
            messagebox.showerror("Invalid", "Principal must be a number.", parent=win)
            return
        try:
            dr = _validate_date(released_var.get())
        except Exception:
            messagebox.showerror("Invalid", "Date Released must be YYYY-MM-DD.", parent=win)
            return
        if is_new_var.get():
            try:
                nu = _validate_date(new_until_var.get())
            except Exception:
                messagebox.showerror("Invalid", "New Until must be YYYY-MM-DD.", parent=win)
                return
        else:
            nu = ""
        if lt_local == '7x7':
            ir = 0.0
        else:
            try:
                ir = float(interest_var.get().strip() or 0.20)
                if ir > 1.0:
                    ir = ir / 100.0
            except Exception:
                messagebox.showerror("Invalid", "Interest rate must be a number.", parent=win)
                return

        # Payment term / amount
        pt = (payterm_var.get() or '').strip() or 'Daily'
        if pt not in ('Daily','Weekly','Semi','Monthly'):
            pt2 = pt.lower().replace(' ', '').replace('-', '').replace('_', '')
            if 'week' in pt2:
                pt = 'Weekly'
            elif 'semi' in pt2 or 'bi' in pt2:
                pt = 'Semi'
            elif 'month' in pt2:
                pt = 'Monthly'
            else:
                pt = 'Daily'
        try:
            pa_txt = (payamt_var.get() or '').strip()
            pa = float(pa_txt.replace(',', '.').strip()) if pa_txt else 0.0
        except Exception:
            messagebox.showerror("Invalid", "Payment Amount must be a number.", parent=win)
            return

        due_weekday_val = _spina__norm_weekday(due_weekday_var.get())
        semi_due1_val = _spina__norm_dom(semi_due_day1_var.get())
        semi_due2_val = _spina__norm_dom(semi_due_day2_var.get())
        monthly_due_val = _spina__norm_dom(monthly_due_day_var.get())

        if pt == 'Weekly' and not due_weekday_val:
            messagebox.showerror("Required", "Due Weekday is required for Weekly payment term.", parent=win)
            return
        if pt == 'Semi' and (semi_due1_val is None or semi_due2_val is None):
            messagebox.showerror("Required", "Both Semi Due Days are required for Semi payment term.", parent=win)
            return
        if pt == 'Monthly' and monthly_due_val is None:
            messagebox.showerror("Required", "Monthly Due Day is required for Monthly payment term.", parent=win)
            return

        if pt != 'Weekly':
            due_weekday_val = ''
        if pt != 'Semi':
            semi_due1_val = None
            semi_due2_val = None
        if pt != 'Monthly':
            monthly_due_val = None

        flex_due_rule_val = (_flex_due_code_from_choice() or '').strip()

        res = {
            "name": nm,
            "contact_number": contact_var.get().strip(),
            "payment_term": pt,
            "payment_amount": pa,
            "payment_mode": _spina__merge_payment_mode((paymode_var.get() or '').strip() or 'Cash', (paymode_other_var.get() or '').strip()),
            "due_weekday": due_weekday_val,
            "semi_due_day1": semi_due1_val,
            "semi_due_day2": semi_due2_val,
            "monthly_due_day": monthly_due_val,
            "flex_due_rule": flex_due_rule_val,
            "loan_type": lt_local,
            "area": area_var.get().strip(),
            "principal": p,
            "interest_rate": ir,
            "date_released": dr,
            "new_until": nu,
            "pay_start_offset_days": 1 if psod_var.get() else 0,
        }
        result["ok"] = True
        result["data"] = res
        try:
            win.destroy()
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0629', 'suppressed exception excpass_0629', __spina_exc)
            pass

    def cancel():
        try:
            win.destroy()
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0630', 'suppressed exception excpass_0630', __spina_exc)
            pass

    ttk.Button(btns, text="Cancel", command=cancel).pack(side='right')
    ttk.Button(btns, text="Save", command=save).pack(side='right', padx=8)

    # Apply bigger font to all editor controls without changing app-wide styles.
    try:
        def _spina_apply_client_editor_font(_w):
            try:
                cls = _w.winfo_class()
            except Exception:
                cls = ""
            try:
                if cls in ("TEntry", "TCombobox", "TCheckbutton", "TLabel"):
                    if cls == "TLabel":
                        # Keep already-bold field labels; normal labels get the readable base font.
                        try:
                            if not str(_w.cget("font")).strip():
                                _w.configure(font=_client_editor_font)
                        except Exception:
                            _w.configure(font=_client_editor_font)
                    else:
                        _w.configure(font=_client_editor_font)
                elif cls in ("TButton",):
                    _w.configure(font=_client_editor_button_font)
            except Exception:
                pass
            try:
                for _ch in _w.winfo_children():
                    _spina_apply_client_editor_font(_ch)
            except Exception:
                pass

        _spina_apply_client_editor_font(win)
        win.minsize(760, 720)
    except Exception as __spina_exc:
        _log_suppressed_once('client_editor_font_patch', 'suppressed exception client_editor_font_patch', __spina_exc)
        pass

    try:
        win.bind("<Escape>", lambda e: cancel())
        win.bind("<Return>", lambda e: save())
    except Exception as e:
        _log_ignored("ui.bind failed", e, key="ui.bind_failed")


    # Center dialog on screen (or over main window)
    try:
        win.update_idletasks()
        try:
            self.root.update_idletasks()
        except Exception:
            pass

        w = win.winfo_width()
        h = win.winfo_height()

        pw = self.root.winfo_width()
        ph = self.root.winfo_height()
        if pw and ph and pw > 50 and ph > 50:
            px = self.root.winfo_rootx()
            py = self.root.winfo_rooty()
            x = px + (pw - w) // 2
            y = py + (ph - h) // 2
        else:
            sw = win.winfo_screenwidth()
            sh = win.winfo_screenheight()
            x = (sw - w) // 2
            y = (sh - h) // 2

        win.geometry(f"+{max(int(x), 0)}+{max(int(y), 0)}")
        try:
            win.lift()
        except Exception:
            pass
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0642', 'suppressed exception excpass_0642', __spina_exc)
        pass

    self.root.wait_window(win)
    if result.get("ok"):
        return result.get("data")
    return None

from spina_app.utilities.formatting import _spina__fmt_client_money


def _app_refresh_clients(self):
    try:
        term = (getattr(self, "search_clients_var", tk.StringVar()).get() or "").strip()
    except Exception:
        term = ""
    lt = _app__norm_lt_value(self, self._mode_filter())
    try:
        for rid in self.clients_tree.get_children():
            self.clients_tree.delete(rid)
    except Exception:
        return

    try:
        try:
            mode = (getattr(self, "clients_search_mode_var", tk.StringVar(value="All")).get() or "Both").strip().lower()
        except Exception:
            mode = "both"
        if mode.startswith("cli"):
            sb = "client"
        elif mode.startswith("are"):
            sb = "area"
        elif mode.startswith("link"):
            sb = "linked"
        elif mode.startswith("unl"):
            sb = "unlinked"
        elif mode.startswith("sug"):
            sb = "suggested"
        elif mode.startswith("blank"):
            sb = "blanks"
        elif mode.startswith("pri"):
            sb = "principal"
        elif mode.startswith("rel"):
            sb = "released"
        elif mode.startswith("sta"):
            sb = "start_date"
        elif mode.startswith("due"):
            sb = "due_date"
        else:
            sb = "all"
        names = self.db.get_all_clients(search=term if term else None, loan_type=lt, search_by=sb) or []
    except Exception:
        names = []

    other_lt = _app__other_lt(self, lt)

    # Build rows to show:
    # - Always show the current mode's clients
    # - If viewing Regular: append 7x7-only (no Regular record and not linked) at the bottom
    rows_to_show = []
    for n in (names or []):
        rows_to_show.append((n, lt, False))

    if str(lt) == "Regular" and sb not in ("linked", "suggested"):
        try:
            extra_7x7 = self.db.get_unpaired_7x7_names(search=term if term else None, search_by=sb) or []
        except Exception:
            extra_7x7 = []
        for n in (extra_7x7 or []):
            # Avoid duplicates (safety)
            if any(str(n).strip().lower() == str(a[0]).strip().lower() for a in rows_to_show):
                continue
            rows_to_show.append((n, "7x7", True))

    for name, row_lt, is_extra_7x7 in rows_to_show:
        info = self.db.get_client_info(name, loan_type=row_lt) or {}
        link_label = ""
        try:
            if is_extra_7x7:
                link_label = "7x7 ONLY"
            else:
                row_other_lt = _app__other_lt(self, row_lt)
                pu = (info.get("person_uid") or "").strip()
                if pu:
                    linked = self.db.find_clients_by_person_uid(pu) or []
                    has_other = any(str(r.get("loan_type")) != row_lt for r in linked)
                    link_label = f"{row_other_lt}✓" if has_other else "Linked✓"
                else:
                    if self.db.get_client_info(name, loan_type=row_other_lt):
                        link_label = row_other_lt
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0631', 'suppressed exception excpass_0631', __spina_exc)
            pass

        # Store the real loan_type on the row so edits/deletes/area changes work even when 7x7-only is shown in Regular view
        _day_due, _due_today = _spina__client_due_meta(info)
        _day_due_val = _day_due
        row_no = len(self.clients_tree.get_children())
        tags = [f"lt:{row_lt}", 'even' if (row_no % 2 == 0) else 'odd']
        if is_extra_7x7:
            tags.append('extra7x7')
        iid = None
        try:
            iid = (info.get("client_uid") or "").strip() or None
        except Exception:
            iid = None

        row_values = (
            info.get("name", name),
            info.get("area", ""),
            info.get("payment_term", ""),
            _day_due_val,
            _spina__fmt_client_money(info.get("payment_amount", 0)),
            info.get("payment_mode", "Cash"),
            link_label,
            info.get("contact_number", ""),
            _spina__fmt_client_money(info.get("principal", 0)),
            _spina__fmt_client_money(info.get("interest_amount", 0)),
            _spina__fmt_client_money(info.get("total_to_pay", 0)),
            info.get("date_released", ""),
            info.get("due_date", ""),
        )

        try:
            self.clients_tree.insert(
                "", "end",
                iid=iid,
                tags=tuple(tags),
                values=row_values,
            )
        except Exception:
            # Fallback insert if iid duplicates or fails
            try:
                self.clients_tree.insert(
                    "", "end",
                    tags=tuple(tags),
                    values=row_values,
                )
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0632', 'suppressed exception excpass_0632', __spina_exc)
                pass

    try:
        if hasattr(self, 'clients_count_var'):
            self.clients_count_var.set(f"Rows: {len(self.clients_tree.get_children())}")
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0632b', 'suppressed exception excpass_0632b', __spina_exc)
        pass

    try:
        self._update_toolbar_states()
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0633', 'suppressed exception excpass_0633', __spina_exc)
        pass
    # Refresh area dropdowns only when NOT actively filtering (prevents lag/jitter while typing)
    if not term:
        try:
            self._refresh_area_dropdowns()
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0634', 'suppressed exception excpass_0634', __spina_exc)
            pass

def _app_schedule_refresh_clients(self, *_):
    """Debounce Clients search so refresh doesn't run on every keystroke."""
    root = getattr(self, 'root', None) or getattr(self, 'master', None)
    # Cancel previous scheduled refresh, if any
    try:
        after_id = getattr(self, '_clients_refresh_after_id', None)
        if after_id and root is not None:
            root.after_cancel(after_id)
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0635', 'suppressed exception excpass_0635', __spina_exc)
        pass
    # Schedule a new refresh shortly
    try:
        if root is not None:
            self._clients_refresh_after_id = root.after(150, self.refresh_clients)
        else:
            self.refresh_clients()
    except Exception:
        try:
            self.refresh_clients()
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0636', 'suppressed exception excpass_0636', __spina_exc)
            pass

            pass

def _app_add_client_dialog(self):
    data = _app__client_form(self, "Add Client", initial={"loan_type": self._mode_filter()}, is_edit=False)
    if not data:
        return
    try:
        ok = self.db.add_client(
            data["name"],
            principal=data.get("principal", 0.0),
            date_released=data.get("date_released"),
            area=data.get("area", ""),
            interest_rate=data.get("interest_rate", None),
            new_until=data.get("new_until", ""),
            loan_type=data.get("loan_type"),
            pay_start_offset_days=data.get("pay_start_offset_days", 0),
            contact_number=data.get("contact_number", ""),
            payment_term=data.get("payment_term", "Daily"),
            payment_amount=data.get("payment_amount", 0.0),
            payment_mode=data.get("payment_mode", "Cash"),
            due_weekday=data.get("due_weekday", ""),
            semi_due_day1=data.get("semi_due_day1"),
            semi_due_day2=data.get("semi_due_day2"),
            monthly_due_day=data.get("monthly_due_day"),
            flex_due_rule=data.get("flex_due_rule", ""),
        )
        if not ok:
            messagebox.showerror("Failed", "Could not add client. (Maybe duplicate name in the same loan type?)")
            return
    except Exception as e:
        messagebox.showerror("Error", str(e))
        return

    try:
        _app__maybe_suggest_link_clients(self, data.get("name"), data.get("loan_type"))
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0637', 'suppressed exception excpass_0637', __spina_exc)
        pass

    try:
        self.refresh_clients()
        self.refresh_reports()
        self.refresh_data_grid()
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0638', 'suppressed exception excpass_0638', __spina_exc)
        pass

def _app_on_client_edit(self, event=None):
    name = _app__get_selected_client_name(self)
    if not name:
        return
    lt = _app__norm_lt_value(self, self._mode_filter())
    info = self.db.get_client_info(name, loan_type=lt) or {}
    data = _app__client_form(self, "Edit Client", initial=info, is_edit=True)
    if not data:
        return
    try:
        ok = self.db.update_client(
            old_name=name,
            new_name=data.get("name"),
            principal=data.get("principal"),
            date_released=data.get("date_released"),
            area=data.get("area"),
            interest_rate=data.get("interest_rate"),
            new_until=data.get("new_until"),
            loan_type=lt,
            pay_start_offset_days=data.get("pay_start_offset_days"),
            contact_number=data.get("contact_number"),
            payment_term=data.get("payment_term"),
            payment_amount=data.get("payment_amount"),
            payment_mode=data.get("payment_mode"),
            due_weekday=data.get("due_weekday"),
            semi_due_day1=data.get("semi_due_day1"),
            semi_due_day2=data.get("semi_due_day2"),
            monthly_due_day=data.get("monthly_due_day"),
            flex_due_rule=data.get("flex_due_rule", ""),
        )
        if not ok:
            messagebox.showerror("Failed", "Update failed.")
            return
    except Exception as e:
        messagebox.showerror("Error", str(e))
        return

    try:
        _app__maybe_suggest_link_clients(self, data.get("name"), lt)
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0639', 'suppressed exception excpass_0639', __spina_exc)
        pass

    try:
        self.refresh_clients()
        self.refresh_reports()
        self.refresh_data_grid()
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0640', 'suppressed exception excpass_0640', __spina_exc)
        pass

def _app_delete_client_selected(self):
    name = _app__get_selected_client_name(self)
    if not name:
        return
    lt = _app__norm_lt_value(self, self._mode_filter())
    if not messagebox.askyesno("Confirm", f"Archive (hide) client '{name}' ({lt})?\n\n• It will disappear\n• History stays\n• You can restore anytime"):
        return
    try:
        ok = self.db.archive_client(name, loan_type=lt)
        if not ok:
            messagebox.showerror("Failed", "Delete failed.")
            return
    except Exception as e:
        messagebox.showerror("Error", str(e))
        return
    try:
        self.refresh_clients()
        self.refresh_reports()
        self.refresh_data_grid()
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0641', 'suppressed exception excpass_0641', __spina_exc)
        pass
    messagebox.showinfo("Archived", f"Client '{name}' archived (hidden).")

def _app_open_client_history_dialog(self):
    name = _app__get_selected_client_name(self)
    if not name:
        messagebox.showinfo("History", "Select a client first.")
        return

    lt = _app__norm_lt_value(self, self._mode_filter())
    try:
        uid = self.db.get_client_uid(name, loan_type=lt)
    except Exception:
        uid = None
    if not uid:
        messagebox.showerror("History", "Could not locate client UID.")
        return

    # Determine linked group (Regular + 7x7) if any.
    linked_uids = [uid]
    linked_label = ""
    try:
        linked_uids = self.db.get_linked_client_uids(uid) or [uid]
        if len(linked_uids) > 1:
            linked_label = " (linked Regular+7x7)"
    except Exception:
        linked_uids = [uid]

    def _coerce_rows(rows):
        out = []
        for r in (rows or []):
            try:
                out.append(dict(r))
            except Exception:
                try:
                    out.append({k: r[k] for k in r.keys()})
                except Exception:
                    pass
        return out

    def _ts_key(row):
        return str(row.get("changed_at") or row.get("ts") or "")

    def _safe_json_load(blob):
        if blob in (None, ""):
            return None
        try:
            return json.loads(blob) if isinstance(blob, str) else blob
        except Exception:
            return None

    def _pretty(obj_or_json):
        if obj_or_json in (None, ""):
            return ""
        obj = _safe_json_load(obj_or_json)
        if obj is None:
            try:
                return str(obj_or_json)
            except Exception:
                return ""
        try:
            return json.dumps(obj, indent=2, ensure_ascii=False, sort_keys=True, default=str)
        except Exception:
            try:
                return str(obj)
            except Exception:
                return ""

    def _fmt_scalar(v):
        if v is None:
            return "None"
        try:
            s = str(v).replace("\n", " ").strip()
        except Exception:
            s = repr(v)
        return (s[:57] + "…") if len(s) > 58 else s

    def _diff_pairs(old_json, new_json):
        old_obj = _safe_json_load(old_json)
        new_obj = _safe_json_load(new_json)
        if old_obj is None and new_obj is None:
            return []
        if old_obj is None and isinstance(new_obj, dict):
            return [(k, None, new_obj.get(k)) for k in sorted(new_obj.keys())]
        if new_obj is None and isinstance(old_obj, dict):
            return [(k, old_obj.get(k), None) for k in sorted(old_obj.keys())]
        if not isinstance(old_obj, dict) or not isinstance(new_obj, dict):
            if old_obj != new_obj:
                return [("value", old_obj, new_obj)]
            return []
        pairs = []
        for k in sorted(set(old_obj.keys()) | set(new_obj.keys())):
            ov = old_obj.get(k)
            nv = new_obj.get(k)
            if ov != nv:
                pairs.append((k, ov, nv))
        return pairs

    def _diff_summary(old_json, new_json):
        pairs = _diff_pairs(old_json, new_json)
        if not pairs:
            return ""
        if len(pairs) == 1 and pairs[0][0] == "value":
            return f"value: {_fmt_scalar(pairs[0][1])} → {_fmt_scalar(pairs[0][2])}"
        names = [p[0] for p in pairs]
        head = ", ".join(names[:4])
        if len(names) > 4:
            head += f" +{len(names)-4} more"
        return f"{len(names)} field(s): {head}"

    # Pull histories for the whole linked group so audit stays complete.
    client_rows_all = []
    try:
        seen_hist = set()
        for _uid in linked_uids:
            for row in _coerce_rows(self.db.get_client_history(client_uid=_uid, limit=1000) or []):
                key = (row.get("id"), row.get("client_uid"), row.get("changed_at"), row.get("action"), row.get("source"))
                if key in seen_hist:
                    continue
                seen_hist.add(key)
                client_rows_all.append(row)
        client_rows_all.sort(key=lambda r: (str(r.get("changed_at") or ""), int(r.get("id") or 0)), reverse=True)
    except Exception:
        client_rows_all = []

    try:
        tx_rows_all = _coerce_rows(self.db.get_transactions_for_client_uids(linked_uids) or [])
    except Exception:
        tx_rows_all = []

    try:
        tx_hist_all = _coerce_rows(self.db.get_transaction_history_for_client_uids(linked_uids) or [])
    except Exception:
        tx_hist_all = []

    # Summary counts.
    action_counts = {}
    for r in client_rows_all:
        a = str(r.get("action") or "UPDATED").strip().upper() or "UPDATED"
        action_counts[a] = action_counts.get(a, 0) + 1

    win = tk.Toplevel(self.root)
    win.title(f"Audit History: {name} ({lt}){linked_label}")
    win.geometry("1180x760")
    try:
        win.transient(self.root)
        win.grab_set()
    except Exception:
        pass

    outer = ttk.Frame(win, padding=8)
    outer.pack(fill='both', expand=True)

    hdr = ttk.Frame(outer)
    hdr.pack(fill='x', pady=(0, 8))
    ttk.Label(hdr, text=f"Audit Trail - {name}", font=('TkDefaultFont', 12, 'bold')).pack(side='left')
    ttk.Label(hdr, text=f"Loan: {lt}    UID: {uid}    Linked records: {len(linked_uids)}", foreground='#666666').pack(side='left', padx=(12,0))

    stats = ttk.Frame(outer)
    stats.pack(fill='x', pady=(0, 6))
    summary_parts = [
        f"Client Changes: {len(client_rows_all)}",
        f"Payments: {len(tx_rows_all)}",
        f"Payment Audit: {len(tx_hist_all)}",
    ]
    if action_counts:
        for k in sorted(action_counts.keys()):
            summary_parts.append(f"{k}: {action_counts[k]}")
    ttk.Label(stats, text="   |   ".join(summary_parts)).pack(anchor='w')

    nb = ttk.Notebook(outer)
    nb.pack(fill='both', expand=True)

    # ---------------- Tab 1: Client Changes ----------------
    tab1 = ttk.Frame(nb, padding=6)
    nb.add(tab1, text="Client Audit")

    t1_filters = ttk.Frame(tab1)
    t1_filters.pack(fill='x')
    ttk.Label(t1_filters, text="Search:").pack(side='left')
    q1 = tk.StringVar()
    ttk.Entry(t1_filters, textvariable=q1, width=34).pack(side='left', padx=(6,12))
    ttk.Label(t1_filters, text="Action:").pack(side='left')
    action_options = ["All"] + sorted(action_counts.keys())
    act1 = tk.StringVar(value="All")
    try:
        ttk.Combobox(t1_filters, textvariable=act1, values=action_options, width=16, state='readonly').pack(side='left', padx=(6,12))
    except Exception:
        ttk.Entry(t1_filters, textvariable=act1, width=16).pack(side='left', padx=(6,12))
    ttk.Label(t1_filters, text="Tip: select a row to see changed fields, before, and after.", foreground='#666666').pack(side='right')

    list_wrap1 = ttk.Frame(tab1)
    list_wrap1.pack(fill='both', expand=True, pady=(6, 0))
    cols1 = ("ts", "action", "loan_type", "source", "fields", "note")
    tree1 = ttk.Treeview(list_wrap1, columns=cols1, show='headings', height=14)
    cfg1 = {
        "ts": (160, 'w', 'When'),
        "action": (95, 'w', 'Action'),
        "loan_type": (85, 'center', 'Loan'),
        "source": (180, 'w', 'Source'),
        "fields": (360, 'w', 'Changed Fields'),
        "note": (220, 'w', 'Note'),
    }
    for c, (w, a, lbl) in cfg1.items():
        tree1.heading(c, text=lbl)
        tree1.column(c, width=w, anchor=a, stretch=(c in ('source', 'fields', 'note')))
    y1 = ttk.Scrollbar(list_wrap1, orient='vertical', command=tree1.yview)
    x1 = ttk.Scrollbar(list_wrap1, orient='horizontal', command=tree1.xview)
    tree1.configure(yscrollcommand=y1.set, xscrollcommand=x1.set)
    tree1.grid(row=0, column=0, sticky='nsew')
    y1.grid(row=0, column=1, sticky='ns')
    x1.grid(row=1, column=0, sticky='ew')
    list_wrap1.grid_rowconfigure(0, weight=1)
    list_wrap1.grid_columnconfigure(0, weight=1)

    for tag, opts in {
        'SNAPSHOT': {'foreground': '#666666'},
        'ADD': {'foreground': '#1f7a1f'},
        'CREATE': {'foreground': '#1f7a1f'},
        'UPDATE': {'foreground': '#0b5fa5'},
        'EDIT': {'foreground': '#0b5fa5'},
        'RENEW': {'foreground': '#8a4b00'},
        'ARCHIVE': {'foreground': '#7a3f00'},
        'RESTORE': {'foreground': '#2f6f3e'},
        'DELETE': {'foreground': '#a11a1a'},
    }.items():
        try:
            tree1.tag_configure(tag, **opts)
        except Exception:
            pass

    lower1 = ttk.PanedWindow(tab1, orient='horizontal')
    lower1.pack(fill='both', expand=True, pady=(8,0))

    def _mk_ro_text(parent):
        frm = ttk.Frame(parent)
        txt = tk.Text(frm, wrap='none', height=12)
        ys = ttk.Scrollbar(frm, orient='vertical', command=txt.yview)
        xs = ttk.Scrollbar(frm, orient='horizontal', command=txt.xview)
        txt.configure(yscrollcommand=ys.set, xscrollcommand=xs.set)
        txt.grid(row=0, column=0, sticky='nsew')
        ys.grid(row=0, column=1, sticky='ns')
        xs.grid(row=1, column=0, sticky='ew')
        frm.grid_rowconfigure(0, weight=1)
        frm.grid_columnconfigure(0, weight=1)
        return frm, txt

    changed_frm, changed_txt = _mk_ro_text(lower1)
    before_frm, before_txt = _mk_ro_text(lower1)
    after_frm, after_txt = _mk_ro_text(lower1)
    lower1.add(changed_frm, weight=1)
    lower1.add(before_frm, weight=1)
    lower1.add(after_frm, weight=1)

    t1_rows = []

    def _set_ro(widget, content):
        widget.configure(state='normal')
        widget.delete('1.0', 'end')
        widget.insert('1.0', content or '')
        widget.configure(state='disabled')

    def _render_tab1():
        nonlocal t1_rows
        t1_rows = []
        tree1.delete(*tree1.get_children())
        q = (q1.get() or '').strip().lower()
        act_filter = (act1.get() or 'All').strip().upper()
        for r in (client_rows_all or []):
            act = str(r.get('action') or '').strip().upper()
            if act_filter != 'ALL' and act != act_filter:
                continue
            fields = _diff_summary(r.get('before_json') or r.get('old_json'), r.get('after_json') or r.get('new_json'))
            hay = ' '.join([
                str(r.get('ts') or r.get('changed_at') or ''),
                act,
                str(r.get('loan_type_after') or r.get('loan_type_before') or ''),
                str(r.get('source') or ''),
                str(r.get('note') or ''),
                fields,
            ]).lower()
            if q and q not in hay:
                continue
            t1_rows.append(r)
        for i, r in enumerate(t1_rows):
            iid = str(i)
            act = str(r.get('action') or '').strip().upper() or 'UPDATE'
            tree1.insert('', 'end', iid=iid, values=(
                r.get('ts') or r.get('changed_at') or '',
                act,
                r.get('loan_type_after') or r.get('loan_type_before') or '',
                r.get('source') or '',
                _diff_summary(r.get('before_json') or r.get('old_json'), r.get('after_json') or r.get('new_json')),
                r.get('note') or '',
            ), tags=(act,))
        if t1_rows:
            tree1.selection_set('0')
            _on_sel1()
        else:
            _set_ro(changed_txt, '')
            _set_ro(before_txt, '')
            _set_ro(after_txt, '')

    def _on_sel1(_=None):
        sel = tree1.selection()
        if not sel:
            return
        i = int(sel[0])
        if i < 0 or i >= len(t1_rows):
            return
        r = t1_rows[i]
        pairs = _diff_pairs(r.get('before_json') or r.get('old_json'), r.get('after_json') or r.get('new_json'))
        if not pairs:
            detail_lines = ["No field-level difference recorded."]
        else:
            detail_lines = []
            for k, ov, nv in pairs:
                detail_lines.append(f"{k}\n  Before: {_fmt_scalar(ov)}\n  After : {_fmt_scalar(nv)}")
        _set_ro(changed_txt, "\n\n".join(detail_lines))
        _set_ro(before_txt, _pretty(r.get('before_json') or r.get('old_json')))
        _set_ro(after_txt, _pretty(r.get('after_json') or r.get('new_json')))

    tree1.bind('<<TreeviewSelect>>', _on_sel1)
    q1.trace_add('write', lambda *_: _render_tab1())
    act1.trace_add('write', lambda *_: _render_tab1())
    _render_tab1()

