def _app_link_selected_client(self):
    name = _app__get_selected_client_name(self)
    if not name:
        messagebox.showinfo("Link", "Select a client first.")
        return
    lt = _app__norm_lt_value(self, self._mode_filter())
    other_lt = _app__other_lt(self, lt)

    uid_a = self.db.get_client_uid(name, loan_type=lt)
    if not uid_a:
        messagebox.showerror("Link", "Could not get selected client UID.")
        return

    win = tk.Toplevel(self.root)
    win.title(f"Link to {other_lt} client")
    win.geometry("520x480")
    try:
        win.transient(self.root)
        win.grab_set()
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0644', 'suppressed exception excpass_0644', __spina_exc)
        pass

    top = ttk.Frame(win, padding=8)
    top.pack(fill='both', expand=True)

    ttk.Label(top, text=f"Choose {other_lt} record to link with:").pack(anchor='w')
    qv = tk.StringVar()
    ttk.Entry(top, textvariable=qv).pack(fill='x', pady=6)

    lb = tk.Listbox(top)
    lb.pack(fill='both', expand=True)

    # Selected row itself must be unlinked before linking.
    try:
        _cur_info0 = self.db.get_client_info(name, loan_type=lt) or {}
        if (_cur_info0.get('person_uid') or '').strip():
            messagebox.showinfo("Already Linked", f"'{name}' ({lt}) is already linked. Unlink it first.")
            try:
                win.destroy()
            except Exception:
                pass
            return
    except Exception:
        pass

    all_names = []
    try:
        for _nm in (self.db.get_all_clients(loan_type=other_lt) or []):
            _info = self.db.get_client_info(_nm, loan_type=other_lt) or {}
            if not (_info.get('person_uid') or '').strip():
                all_names.append(_nm)
    except Exception:
        all_names = []

    def refresh_list():
        q = (qv.get() or "").strip().lower()
        lb.delete(0, 'end')
        for nm in all_names:
            if not q or q in nm.lower():
                lb.insert('end', nm)

    qv.trace_add('write', lambda *a: refresh_list())
    refresh_list()

    if not all_names:
        messagebox.showinfo("No records", f"No unlinked {other_lt} clients exist yet.", parent=win)

    def do_link():
        try:
            idx = lb.curselection()
            if not idx:
                messagebox.showinfo("Link", "Select a record to link.", parent=win)
                return
            target_name = lb.get(idx[0])
            uid_b = self.db.get_client_uid(target_name, loan_type=other_lt)
            if not uid_b:
                messagebox.showerror("Link", "Could not get target UID.", parent=win)
                return
            cur_info = self.db.get_client_info(name, loan_type=lt) or {}
            other_info = self.db.get_client_info(target_name, loan_type=other_lt) or {}
            pu_a = (cur_info.get('person_uid') or '').strip()
            pu_b = (other_info.get('person_uid') or '').strip()
            if pu_a and pu_b and pu_a == pu_b:
                messagebox.showinfo("Already Linked", f"'{name}' ({lt}) and '{target_name}' ({other_lt}) are already linked.", parent=win)
                return
            if pu_a or pu_b:
                who = name if pu_a else target_name
                messagebox.showinfo("Already Linked", f"'{who}' is already linked. Unlink it first.", parent=win)
                return
            ok = self.db.link_client_uids(uid_a, uid_b, source='clients:manual_link')
            if not ok:
                err = ''
                try:
                    err = self.db.get_last_error()
                except Exception:
                    err = ''
                if err and 'already linked' in err.lower():
                    messagebox.showinfo("Already Linked", err, parent=win)
                else:
                    messagebox.showerror("Link", err or "Link failed.", parent=win)
                return
            try:
                win.destroy()
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0645', 'suppressed exception excpass_0645', __spina_exc)
                pass
            self.refresh_clients()
            messagebox.showinfo("Linked", f"Linked '{name}' ({lt}) with '{target_name}' ({other_lt}).")
        except Exception as e:
            messagebox.showerror("Link", str(e), parent=win)

    btn = ttk.Frame(top)
    btn.pack(fill='x', pady=8)
    ttk.Button(btn, text="Cancel", command=lambda: win.destroy()).pack(side='right')
    ttk.Button(btn, text="Link", command=do_link).pack(side='right', padx=8)

    try:
        win.bind('<Return>', lambda e: do_link())
        win.bind('<Escape>', lambda e: win.destroy())
    except Exception as e:
        _log_ignored("ui.bind failed", e, key="ui.bind_failed")

def _app_unlink_selected_client(self):
    name = _app__get_selected_client_name(self)
    if not name:
        messagebox.showinfo("Unlink", "Select a client first.")
        return
    lt = _app__norm_lt_value(self, self._mode_filter())
    info = self.db.get_client_info(name, loan_type=lt) or {}
    pu = (info.get("person_uid") or "").strip()
    if not pu:
        messagebox.showinfo("Unlink", "Selected client is not linked.")
        return
    if not messagebox.askyesno("Confirm", "Unlink this client group (Regular + 7x7)?"):
        return
    try:
        ok = self.db.unlink_person_uid(pu, source='clients:manual_unlink')
        if ok:
            self.refresh_clients()
            messagebox.showinfo("Unlinked", "Unlinked successfully.")
        else:
            messagebox.showerror("Failed", "Unlink failed.")
    except Exception as e:
        messagebox.showerror("Error", str(e))

def _app__maybe_suggest_link_clients(self, name, loan_type):
    try:
        nm = (name or "").strip()
        if not nm:
            return
        lt = _app__norm_lt_value(self, loan_type or self._mode_filter())
        other_lt = _app__other_lt(self, lt)
        other_info = self.db.get_client_info(nm, loan_type=other_lt)
        if not other_info:
            return
        meta_a = self.db.get_client_link_meta(nm, loan_type=lt) or {}
        meta_b = self.db.get_client_link_meta(nm, loan_type=other_lt) or {}
        uid_a = meta_a.get("client_uid")
        uid_b = meta_b.get("client_uid")
        if not uid_a or not uid_b:
            return
        if int(meta_a.get("link_opt_out") or 0) == 1 or int(meta_b.get("link_opt_out") or 0) == 1:
            return
        pu_a = (meta_a.get("person_uid") or "").strip()
        pu_b = (meta_b.get("person_uid") or "").strip()
        if pu_a and pu_b and pu_a == pu_b:
            return
        msg = (
            f"'{nm}' exists in BOTH loan types:\n\n"
            f"• {lt}\n"
            f"• {other_lt}\n\n"
            "Link them as the SAME person?\n\n"
            "YES = connect (still separate loans)\n"
            "NO = keep separate and stop asking again for this pair"
        )
        if messagebox.askyesno("Link suggestion", msg):
            ok = False
            try:
                ok = self.db.link_client_uids(uid_a, uid_b, source='clients:auto_suggest:yes')
            except Exception:
                ok = False
            if not ok:
                err = ''
                try:
                    err = self.db.get_last_error()
                except Exception:
                    err = ''
                messagebox.showerror("Link", err or "Link failed.")
                return
            try:
                self.refresh_clients()
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0646', 'suppressed exception excpass_0646', __spina_exc)
                pass
        else:
            try:
                self.db.set_link_opt_out_by_uid(uid_a, 1, source='clients:auto_suggest:no')
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0647', 'suppressed exception excpass_0647', __spina_exc)
                pass
            try:
                self.db.set_link_opt_out_by_uid(uid_b, 1, source='clients:auto_suggest:no')
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0648', 'suppressed exception excpass_0648', __spina_exc)
                pass
    except Exception:
        return

def _app_export_clients_template(self):
    try:
        import openpyxl
        from openpyxl import Workbook
    except Exception:
        messagebox.showerror("Excel", "Missing dependency: openpyxl. Install with: pip install openpyxl")
        return
    path = filedialog.asksaveasfilename(
        title="Save Clients Template",
        defaultextension=".xlsx",
        filetypes=[("Excel", "*.xlsx")],
        initialfile="clients_template.xlsx",
    )
    if not path:
        return
    wb = Workbook()
    ws = wb.active
    ws.title = "Clients"
    headers = ["Name", "Contact Number", "Loan Type (Regular/7x7)", "Area", "Principal", "Interest Rate (Regular only)", "Date Released (YYYY-MM-DD)", "New Until (optional)", "Pay Start Offset Days (0/1)"]
    ws.append(headers)
    try:
        wb.save(path)
        messagebox.showinfo("Saved", f"Template saved:\n{path}")
    except Exception as e:
        messagebox.showerror("Save Error", str(e))

def _app_import_clients_from_excel(self):
    try:
        import openpyxl
    except Exception:
        messagebox.showerror("Excel", "Missing dependency: openpyxl. Install with: pip install openpyxl")
        return
    path = filedialog.askopenfilename(title="Select Clients Excel", filetypes=[("Excel", "*.xlsx")])
    if not path:
        return
    try:
        wb = openpyxl.load_workbook(path)
        ws = wb.active
    except Exception as e:
        messagebox.showerror("Excel", str(e))
        return

    lt_default = _app__norm_lt_value(self, self._mode_filter())
    imported = 0
    updated = 0
    failed = 0
    failure_samples = []

    rows_iter = iter(ws.iter_rows(values_only=True))
    first_row = next(rows_iter, None)
    if first_row is None:
        messagebox.showinfo("Import", "No data found.")
        return
    header = [str(x).strip().lower() if x is not None else "" for x in first_row]

    def col_idx(keys):
        for k in keys:
            if k in header:
                return header.index(k)
        return None

    i_name = col_idx(["name"])
    i_contact = col_idx(["contact number", "contact no", "contact", "phone", "mobile", "cell", "cp number", "tel", "telephone"])
    i_lt = col_idx(["loan type (regular/7x7)", "loan type", "loantype"])
    i_area = col_idx(["area"])
    i_pr = col_idx(["principal"])
    i_ir = col_idx(["interest rate (regular only)", "interest rate", "interestrate"])
    i_dr = col_idx(["date released (yyyy-mm-dd)", "date released", "released", "date_released"])
    i_nu = col_idx(["new until (optional)", "new until", "new_until"])
    i_ps = col_idx(["pay start offset days (0/1)", "pay start offset", "pay_start_offset_days", "offset"])

    if i_name is None:
        messagebox.showerror("Import", "Template must include a 'Name' column.")
        return

    for row_number, r in enumerate(rows_iter, start=2):
        try:
            nm = (r[i_name] or "")
            nm = " ".join(str(nm).strip().split())
            if not nm:
                continue
            lt = lt_default
            if i_lt is not None and r[i_lt]:
                lt = _app__norm_lt_value(self, r[i_lt])
            contact = (r[i_contact] or "") if i_contact is not None and i_contact < len(r) else ""
            contact = str(contact).strip()
            area = (r[i_area] or "") if i_area is not None else ""
            area = str(area).strip()
            pr = float(r[i_pr]) if i_pr is not None and r[i_pr] not in (None, "") else 0.0
            ir = None
            if lt == 'Regular':
                if i_ir is not None and r[i_ir] not in (None, ""):
                    ir = float(r[i_ir])
                else:
                    ir = 0.20
            dr = ""
            if i_dr is not None and r[i_dr]:
                dr = str(r[i_dr])[:10].strip()
                datetime.strptime(dr, "%Y-%m-%d")
            nu = ""
            if i_nu is not None and r[i_nu]:
                nu = str(r[i_nu])[:10].strip()
                datetime.strptime(nu, "%Y-%m-%d")
            psod = 0
            if i_ps is not None and r[i_ps] not in (None, ""):
                try:
                    psod = 1 if int(r[i_ps]) >= 1 else 0
                except Exception:
                    psod = 0

            exists = self.db.get_client_info(nm, loan_type=lt)
            if exists:
                ok = self.db.update_client(nm, new_name=nm, principal=pr, date_released=dr or None, area=area, interest_rate=ir, new_until=nu, loan_type=lt, pay_start_offset_days=psod, contact_number=contact)
                if ok:
                    updated += 1
            else:
                ok = self.db.add_client(nm, principal=pr, date_released=dr or None, area=area, interest_rate=ir, new_until=nu, loan_type=lt, pay_start_offset_days=psod, contact_number=contact)
                if ok:
                    imported += 1
        except Exception as e:
            failed += 1
            if len(failure_samples) < 5:
                failure_samples.append(f"Row {row_number}: {e}")
            try:
                _log_exc(f"import_clients_from_excel.row_{row_number}", e)
            except Exception:
                pass
            continue

    try:
        self.refresh_clients()
        self.refresh_reports()
        self.refresh_data_grid()
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0649', 'suppressed exception excpass_0649', __spina_exc)
        pass
    details = f"Imported: {imported}\nUpdated: {updated}\nFailed: {failed}"
    if failure_samples:
        details += "\n\nFirst errors:\n" + "\n".join(failure_samples)
    messagebox.showinfo("Import", details)

def _app_import_missing(self):
    try:
        n = self.db.import_missing_clients_from_transactions()
    except Exception as e:
        messagebox.showerror("Import", str(e))
        return
    try:
        self.refresh_clients()
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0650', 'suppressed exception excpass_0650', __spina_exc)
        pass
    messagebox.showinfo("Import", f"Added {n} missing client(s) from transactions.")

# ---------------- Renew (Reloan) UI ----------------
class RenewDialog(simpledialog.Dialog):
    """Renew (reloan) dialog.

    Auto-computes **Released Cash** using:
        released_cash = max(0, new_principal - remaining_due)

    remaining_due is based on the current cycle:
        Regular: remaining_due = max(0, total_to_pay - paid_total)
        7x7:     remaining_due = remaining_principal + unpaid_interest_arrears

    You can still override Released Cash manually; click **Auto** to recompute.
    """
    def __init__(self, parent, title=None, initial=None, loan_type='Regular', db=None):
        self.client = initial or {}
        self.loan_type = (loan_type or 'Regular')
        self.db = db
        self.result = None

        # When True, Released Cash keeps syncing from the auto-compute formula.
        self._auto_rc = True
        self._last_stats = None
        super().__init__(parent, title or 'Renew Client')

    def _parse_float(self, v):
        try:
            s = str(v or '').strip()
        except Exception:
            s = ''
        if not s:
            return None
        s = s.replace(',', '')
        try:
            return float(s)
        except Exception:
            return None

    def _valid_ymd(self, s):
        s = (s or '').strip()[:10]
        if not s:
            return None
        try:
            datetime.strptime(s, "%Y-%m-%d")
            return s
        except Exception:
            return None

    def _compute_stats(self):
        """Return dict with paid/remaining/suggested released cash (best-effort).

        Regular:
            remaining_due = max(0, total_to_pay - paid_total)

        7x7:
            remaining_due = remaining_principal + unpaid_interest_arrears (arrears must be cleared first).
            Uses the same rule as the SOA:
              - Daily interest = ceil(remaining_principal / 1000) * 7  (1..1000=7, 1001..2000=14, ...)
              - Interest accrues per day-gap; payment pays INTEREST first, then PRINCIPAL
              - Unpaid interest carries forward (arrears)
        """
        if not self.db:
            return None

        name = (self.client.get('name') or '').strip()
        if not name:
            return None

        # Normalize LT (Regular vs 7x7)
        try:
            lt = self.db._effective_lt(self.loan_type)
        except Exception:
            lt = (self.loan_type or 'Regular')

        lt_s = str(lt or '').lower().replace('×', 'x')
        is_7x7 = ('7x7' in lt_s) or ('emer' in lt_s)

        # Renew date (end of window)
        renew_date = self._valid_ymd(self.date_var.get()) or date.today().strftime("%Y-%m-%d")

        # Cycle start date:
        # Prefer manual payment_start_date, else date_released + pay_start_offset_days
        start_date = self._valid_ymd(str(self.client.get('payment_start_date') or ''))

        # Safety: after renew, a stale payment_start_date can remain (old cycle or equal to release date).
        # If it is <= date_released, ignore it so we fall back to Released + offset.
        try:
            _base_chk = self._valid_ymd(str(self.client.get('date_released') or ''))
        except Exception:
            _base_chk = None
        try:
            _off_chk = int(self.client.get('pay_start_offset_days') or 0)
        except Exception:
            _off_chk = 0
        _off_chk = 1 if _off_chk >= 1 else 0
        if start_date and _base_chk:
            if start_date < _base_chk or (_off_chk == 1 and start_date == _base_chk):
                start_date = None

        if not start_date:
            base = self._valid_ymd(str(self.client.get('date_released') or ''))
            start_date = base
            try:
                off = int(self.client.get('pay_start_offset_days') or 0)
            except Exception:
                off = 0
            off = 1 if off >= 1 else 0

            # Respect the saved start-of-payment offset only.

            if start_date and off:
                try:
                    start_date = (datetime.strptime(start_date, "%Y-%m-%d").date() + timedelta(days=off)).strftime("%Y-%m-%d")
                except Exception as __spina_exc:
                    _log_suppressed_once('excpass_0651', 'suppressed exception excpass_0651', __spina_exc)
                    pass

        # Pull rows in current cycle window
        try:
            rows = self.db.get_transactions_for_client(
                name,
                start_date=start_date,
                end_date=renew_date,
                loan_type=lt
            ) or []
        except Exception:
            rows = []

        # Paid total (same summing logic as reports)
        try:
            paid_total = float(_sum_paid_per_day(rows) or 0.0)
        except Exception:
            paid_total = 0.0

        # Current principal (original principal for this cycle)
        try:
            principal = float(self.client.get('principal') or 0.0)
        except Exception:
            principal = 0.0

        # New principal (use entry if present; else current principal)
        np = self._parse_float(self.new_principal_var.get())
        if np is None:
            np = principal

        # --- 7x7: compute principal balance using daily-interest split ---
        if is_7x7 and principal > 0:
            # Build per-day effective payments: last non-zero wins; 0 doesn't overwrite; ignore ADV-only marker rows
            per = {}
            for rr in rows:
                try:
                    ds = str(rr.get('date') if isinstance(rr, dict) else rr['date'])
                except Exception:
                    try:
                        ds = str(rr[0])
                    except Exception:
                        ds = ''
                ds = (ds or '')[:10].strip()
                if not ds:
                    continue
                try:
                    pay = float(rr.get('payment', 0) if isinstance(rr, dict) else rr['payment'])
                except Exception:
                    try:
                        pay = float(rr[2] or 0.0)
                    except Exception:
                        pay = 0.0
                try:
                    desc = str(rr.get('description', '') if isinstance(rr, dict) else rr['description'])
                except Exception:
                    try:
                        desc = str(rr[3] or '')
                    except Exception:
                        desc = ''
                if abs(pay) < 1e-9:
                    dl = desc.lower()
                    if 'adv' in dl and ('[' in dl or 'range' in dl or ':' in dl):
                        continue
                if ds not in per:
                    per[ds] = pay
                else:
                    if abs(pay) > 1e-9:
                        per[ds] = pay

            pay_days = []
            for ds, pay in per.items():
                try:
                    d = datetime.strptime(ds, "%Y-%m-%d").date()
                except Exception:
                    continue
                pay_days.append((d, float(pay or 0.0)))
            pay_days.sort(key=lambda x: x[0])

            # Daily interest is STEP-based from BALANCE principal:
            #   1..1000 = 7/day, 1001..2000 = 14/day, ...
            def _x7_daily_interest_for_balance(_bal):
                try:
                    b = float(_bal or 0.0)
                except Exception:
                    b = 0.0
                if b <= 0:
                    return 0.0
                try:
                    units = int((b + 999.999999) // 1000)
                except Exception:
                    units = 0
                if units < 1:
                    units = 1
                return float(units) * 7.0
            # Start DT for gap counting
            try:
                start_dt = datetime.strptime((start_date or renew_date)[:10], "%Y-%m-%d").date()
            except Exception:
                start_dt = None

            # User-requested 7x7 renew rule:
            #   renew amount / principal paid = total payment - (daily interest * number of days)
            # where daily interest is step-based from principal:
            #   1..1000 = 7/day, 1001..2000 = 14/day, ...
            try:
                renew_dt = datetime.strptime((renew_date or '')[:10], "%Y-%m-%d").date()
            except Exception:
                renew_dt = None

            try:
                daily_interest = float(_x7_daily_interest_for_balance(principal))
            except Exception:
                daily_interest = 0.0

            days_count = 0
            if start_dt and renew_dt:
                try:
                    days_count = max(0, int((renew_dt - start_dt).days) + 1)
                except Exception:
                    days_count = 0
            if days_count <= 0:
                try:
                    days_count = max(0, len(pay_days or []))
                except Exception:
                    days_count = 0

            interest_due_total = round(daily_interest * float(days_count), 2)
            paid_interest = round(min(float(paid_total or 0.0), interest_due_total), 2)
            paid_principal = round(max(0.0, float(paid_total or 0.0) - interest_due_total), 2)
            if paid_principal > float(principal or 0.0):
                paid_principal = round(float(principal or 0.0), 2)

            remaining_principal = round(max(0.0, float(principal or 0.0) - float(paid_principal or 0.0)), 2)
            remaining_due = remaining_principal
            suggested = round(np - remaining_due, 2)
            topup = 0.0
            if suggested < 0:
                topup = round(-suggested, 2)
                suggested = 0.0

            return {
                'paid': round(paid_total, 2),
                'paid_principal': round(paid_principal, 2),
                'paid_interest': round(paid_interest, 2),
                'interest_days': int(days_count),
                'daily_interest': round(daily_interest, 2),
                'interest_due_total': round(interest_due_total, 2),
                'total_to_pay': round(principal, 2),  # for 7x7, base is principal
                'remaining_due': remaining_due,       # remaining principal
                'new_principal': round(np, 2),
                'released_cash': suggested,
                'topup_needed': topup,
                'renew_date': renew_date,
                'start_date': start_date,
                'loan_type': lt,
                'is_7x7': True,
            }

        # --- Regular: remaining due is based on total_to_pay - paid_total ---
        try:
            interest_amount = float(self.client.get('interest_amount') or 0.0)
        except Exception:
            interest_amount = 0.0
        try:
            total_to_pay = float(self.client.get('total_to_pay') or 0.0)
        except Exception:
            total_to_pay = 0.0

        computed_total = round(principal + interest_amount, 2)
        if total_to_pay <= 0 or (interest_amount > 0 and abs(total_to_pay - principal) < 0.01):
            total_to_pay = computed_total

        remaining_due = max(0.0, round(total_to_pay - paid_total, 2))

        suggested = round(np - remaining_due, 2)
        topup = 0.0
        if suggested < 0:
            topup = round(-suggested, 2)
            suggested = 0.0

        return {
            'paid': round(paid_total, 2),
            'total_to_pay': round(total_to_pay, 2),
            'remaining_due': remaining_due,
            'new_principal': round(np, 2),
            'released_cash': suggested,
            'topup_needed': topup,
            'renew_date': renew_date,
            'start_date': start_date,
            'loan_type': lt,
            'is_7x7': False,
        }

    def _set_manual_rc(self, *_):
        self._auto_rc = False
        try:
            self.auto_hint_lbl.config(text="Released Cash: manual (click Auto to recompute)")
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0652', 'suppressed exception excpass_0652', __spina_exc)
            pass

    def _set_auto_rc(self):
        self._auto_rc = True
        try:
            self.auto_hint_lbl.config(text="Released Cash: auto")
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0653', 'suppressed exception excpass_0653', __spina_exc)
            pass
        self._recompute()

    def _recompute(self, *_):
        st = self._compute_stats()
        self._last_stats = st
        if not st:
            try:
                self.stats_lbl.config(text="")
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0654', 'suppressed exception excpass_0654', __spina_exc)
                pass
            return

        # Sync Released Cash only in auto mode
        if self._auto_rc:
            try:
                self.released_cash_var.set(f"{st['released_cash']:.2f}")
            except Exception as __spina_exc:
                _log_suppressed_once('excpass_0655', 'suppressed exception excpass_0655', __spina_exc)
                pass

        # Show computation summary
        try:
            msg = ""
            if st.get('is_7x7'):
                msg = f"Paid: {st['paid']:.2f} (Pr: {st.get('paid_principal', 0.0):.2f}, Int: {st.get('paid_interest', 0.0):.2f})   Daily Int: {st.get('daily_interest', 0.0):.2f} x {int(st.get('interest_days', 0) or 0)} day(s) = {st.get('interest_due_total', 0.0):.2f}   Remaining Principal: {st['remaining_due']:.2f}   Suggested Release: {st['released_cash']:.2f}"
            else:
                msg = f"Paid: {st['paid']:.2f}   Remaining: {st['remaining_due']:.2f}   Suggested Release: {st['released_cash']:.2f}"
            if st.get('topup_needed', 0.0) > 0:
                msg += f"   (Top-up needed: {st['topup_needed']:.2f})"
            self.stats_lbl.config(text=msg)
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0656', 'suppressed exception excpass_0656', __spina_exc)
            pass

    def body(self, master):
        frm = ttk.Frame(master)
        frm.pack(fill='both', expand=True, padx=12, pady=12)
        frm.columnconfigure(1, weight=1)

        def _row(r, label, widget):
            ttk.Label(frm, text=label).grid(row=r, column=0, sticky='w', pady=4, padx=(0, 10))
            widget.grid(row=r, column=1, sticky='ew', pady=4)
            return r + 1

        name = (self.client.get('name') or '')
        try:
            p0 = float(self.client.get('principal') or 0)
        except Exception:
            p0 = 0.0
        try:
            r0 = float(self.client.get('interest_rate') or 0.20)
        except Exception:
            r0 = 0.20

        self.date_var = tk.StringVar(value=date.today().strftime("%Y-%m-%d"))
        self.released_cash_var = tk.StringVar(value="")
        self.new_principal_var = tk.StringVar(value=f"{p0:g}")
        self.rate_var = tk.StringVar(value=str((r0 * 100.0) if r0 <= 1 else r0))
        self.note_var = tk.StringVar(value="")

        r = 0
        r = _row(r, "Client", ttk.Label(frm, text=name, font=('Segoe UI', 10, 'bold')))

        # Renew date
        r = _row(r, "Renew Date (YYYY-MM-DD)", ttk.Entry(frm, textvariable=self.date_var, width=18))

        # Start of Payment for the NEW cycle (after renew)
        # Checked = Next day, Unchecked = Same day as release
        try:
            _renew_off0 = int((self.client.get('pay_start_offset_days') if isinstance(self.client, dict) else 0) or 0)
        except Exception:
            _renew_off0 = 0
        self.pay_next_day_var = tk.BooleanVar(value=True if _renew_off0 >= 1 else False)
        r = _row(r, "Start of Payment", ttk.Checkbutton(frm, text="Next day (optional; uncheck = same day)", variable=self.pay_next_day_var))

        # Released Cash + Auto button
        rc_frame = ttk.Frame(frm)
        rc_frame.columnconfigure(0, weight=1)
        self.rc_entry = ttk.Entry(rc_frame, textvariable=self.released_cash_var, width=18)
        self.rc_entry.grid(row=0, column=0, sticky='ew')
        ttk.Button(rc_frame, text="Auto", width=6, command=self._set_auto_rc).grid(row=0, column=1, padx=(6, 0))
        r = _row(r, "Released Cash (PHP)", rc_frame)

        # New principal
        r = _row(r, "New Principal", ttk.Entry(frm, textvariable=self.new_principal_var, width=18))

        # Interest rate
        rate_entry = ttk.Entry(frm, textvariable=self.rate_var, width=18)
        r = _row(r, "Interest Rate (%)", rate_entry)
        if (self.loan_type or '').strip().lower() != 'regular':
            try:
                rate_entry.state(['disabled'])
            except Exception:
                rate_entry.configure(state='disabled')

        # Computation summary
        self.stats_lbl = ttk.Label(frm, text="", justify='left')
        self.stats_lbl.grid(row=r, column=0, columnspan=2, sticky='w', pady=(2, 2))
        r += 1

        self.auto_hint_lbl = ttk.Label(frm, text="Released Cash: auto")
        self.auto_hint_lbl.grid(row=r, column=0, columnspan=2, sticky='w', pady=(0, 8))
        r += 1

        ttk.Label(frm, text="Note (optional)").grid(row=r, column=0, sticky='nw', pady=4, padx=(0, 10))
        self.note_txt = tk.Text(frm, height=3, width=34)
        self.note_txt.grid(row=r, column=1, sticky='ew', pady=4)

        # Manual override detection
        try:
            self.rc_entry.bind("<KeyRelease>", self._set_manual_rc)
        except Exception as e:
            _log_ignored("ui.bind failed", e, key="ui.bind_failed")

        # Recompute on changes
        try:
            self.new_principal_var.trace_add("write", self._recompute)
        except Exception as e:
            _log_ignored("ui.trace_add failed", e, key="ui.trace_add_failed")
        try:
            self.date_var.trace_add("write", self._recompute)
        except Exception as e:
            _log_ignored("ui.trace_add failed", e, key="ui.trace_add_failed")

        # Initial compute
        self._recompute()
        return frm

    def validate(self):
        # Date
        d = (self.date_var.get() or "").strip()
        if d:
            try:
                datetime.strptime(d[:10], "%Y-%m-%d")
            except Exception:
                messagebox.showerror("Renew", "Invalid date. Use YYYY-MM-DD.")
                return False

        # Released cash (optional but if provided must be numeric)
        rc = (self.released_cash_var.get() or "").strip()
        if rc:
            try:
                float(rc.replace(",", ""))
            except Exception:
                messagebox.showerror("Renew", "Released Cash must be a number.")
                return False

        # New principal (optional but if provided must be numeric)
        np = (self.new_principal_var.get() or "").strip()
        if np:
            try:
                float(np.replace(",", ""))
            except Exception:
                messagebox.showerror("Renew", "New Principal must be a number.")
                return False

        # Interest rate for Regular
        if (self.loan_type or '').strip().lower() == 'regular':
            rv = (self.rate_var.get() or "").strip()
            if rv:
                try:
                    float(rv.replace(",", ""))
                except Exception:
                    messagebox.showerror("Renew", "Interest Rate must be a number.")
                    return False

        return True

    def apply(self):
        note = ""
        try:
            note = self.note_txt.get("1.0", "end").strip()
        except Exception:
            note = (self.note_var.get() or "").strip()

        released_cash = self._parse_float(self.released_cash_var.get())
        new_principal = self._parse_float(self.new_principal_var.get())

        # If user left Released Cash blank, compute it automatically
        if released_cash is None:
            st = self._compute_stats()
            if st:
                released_cash = st.get('released_cash', 0.0)

        ir = None
        if (self.loan_type or '').strip().lower() == 'regular':
            ir = self._parse_float(self.rate_var.get())

        self.result = {
            "renew_date": (self.date_var.get() or "").strip()[:10],
            "released_cash": released_cash,
            "new_principal": new_principal,
            "interest_rate": ir,
            "note": note,
            "pay_start_offset_days": (1 if bool(getattr(self, "pay_next_day_var", tk.BooleanVar(value=True)).get()) else 0),
        }


def _app_renew_client_selected(self):
    """Renew (reloan) the selected client and update the client row + report stats."""
    try:
        sel = self.clients_tree.selection()
    except Exception:
        sel = ()
    if not sel:
        messagebox.showwarning('Select', 'Please select one client to renew.')
        return

    iid = sel[0]
    vals = self.clients_tree.item(iid, 'values') or ()
    if not vals:
        messagebox.showwarning('Select', 'Please select one client to renew.')
        return

    name = vals[0]
    lt = self._mode_filter()
    # try to read the real loan type from row tags (if present)
    try:
        tags = self.clients_tree.item(iid, 'tags') or ()
        for t in tags:
            if str(t).startswith('lt:'):
                lt = str(t).split(':', 1)[1]
                break
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0657', 'suppressed exception excpass_0657', __spina_exc)
        pass

    info = {}
    try:
        info = self.db.get_client_info(name, loan_type=lt) or {}
    except Exception:
        info = {}
    if not info:
        messagebox.showerror('Missing', 'Client not found in database.')
        return

    dlg = RenewDialog(self.root, initial=info, loan_type=lt, db=self.db)
    if not getattr(dlg, 'result', None):
        return

    r = dlg.result
    try:
        ok = self.db.renew_client(
            name,
            released_cash=r.get('released_cash'),
            renew_date=r.get('renew_date'),
            new_principal=r.get('new_principal'),
            loan_type=lt,
            interest_rate=r.get('interest_rate'),
            pay_start_offset_days=r.get('pay_start_offset_days'),
            note=r.get('note',''),
        )
    except Exception as e:
        messagebox.showerror('Renew Error', str(e))
        return

    if ok:
        try:
            messagebox.showinfo('Renewed', 'Client renewed successfully.')
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0658', 'suppressed exception excpass_0658', __spina_exc)
            pass
        try:
            self.refresh_clients()
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0659', 'suppressed exception excpass_0659', __spina_exc)
            pass
        try:
            self.refresh_reports()
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0660', 'suppressed exception excpass_0660', __spina_exc)
            pass
        try:
            self.refresh_data_grid()
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0661', 'suppressed exception excpass_0661', __spina_exc)
            pass
    else:
        reason = str(getattr(self.db, '_last_renew_error', '') or '').strip()
        messagebox.showerror('Error', ('Failed to renew client.\n\nReason: ' + reason) if reason else 'Failed to renew client.')


def _app_open_archived_clients_dialog(self):
    try:
        win = tk.Toplevel(self.root)
    except Exception:
        win = tk.Toplevel()
    win.title("Archived Clients (Restore)")
    win.geometry("760x520")
    try:
        win.transient(self.root)
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0662', 'suppressed exception excpass_0662', __spina_exc)
        pass

    outer = ttk.Frame(win, padding=10)
    outer.pack(fill='both', expand=True)

    top = ttk.Frame(outer)
    top.pack(fill='x')

    ttk.Label(top, text="Archived Clients", style='Section.TLabel').pack(side='left', padx=(0, 10))

    search_var = tk.StringVar()
    ttk.Label(top, text="Search:").pack(side='left')
    ttk.Entry(top, textvariable=search_var, width=26).pack(side='left', padx=6)

    lt_var = tk.StringVar(value="All")
    ttk.Label(top, text="Loan:").pack(side='left', padx=(10,2))
    cb = ttk.Combobox(top, textvariable=lt_var, values=("All","Regular","7x7"), state='readonly', width=10)
    cb.pack(side='left')

    tree = ttk.Treeview(outer, columns=("name","loan_type","area","archived_at"), show='headings', height=18)
    tree.pack(fill='both', expand=True, pady=8)

    tree.heading("name", text="Name")
    tree.heading("loan_type", text="Loan Type")
    tree.heading("area", text="Area")
    tree.heading("archived_at", text="Archived At")

    tree.column("name", width=280, anchor='w')
    tree.column("loan_type", width=90, anchor='center')
    tree.column("area", width=150, anchor='w')
    tree.column("archived_at", width=160, anchor='w')

    status = tk.StringVar(value="")
    ttk.Label(outer, textvariable=status).pack(anchor='w')

    btns = ttk.Frame(outer)
    btns.pack(fill='x', pady=(6,0))

    def load_list(*_):
        for iid in tree.get_children():
            tree.delete(iid)
        lt = lt_var.get()
        loan_type = None if lt == "All" else lt
        term = (search_var.get() or "").strip() or None
        try:
            rows = self.db.get_archived_clients(search=term, loan_type=loan_type) or []
        except Exception:
            rows = []
        if not rows:
            status.set("No archived clients.")
            return
        status.set(f"{len(rows)} archived client(s). Select one and click Restore.")
        for r in rows:
            uid = (r.get("client_uid") or "").strip()
            if not uid:
                uid = f"{r.get('name','')}|{r.get('loan_type','')}"
            tree.insert("", "end", iid=uid, values=(r.get("name",""), r.get("loan_type",""), r.get("area",""), (r.get("archived_at","") or "")))

    def restore_selected():
        sel = tree.selection()
        if not sel:
            messagebox.showinfo("Restore", "Select an archived client first.")
            return
        uid = sel[0]
        vals = tree.item(uid, "values") or ()
        nm = vals[0] if vals else uid
        lt = vals[1] if len(vals) > 1 else ""
        if not messagebox.askyesno("Confirm", f"Restore '{nm}' ({lt})?"):
            return
        try:
            self.db.restore_client_by_uid(uid)
        except Exception as e:
            messagebox.showerror("Restore Error", str(e))
            return
        try:
            self.refresh_clients()
            self.refresh_reports()
            self.refresh_data_grid()
        except Exception as __spina_exc:
            _log_suppressed_once('excpass_0663', 'suppressed exception excpass_0663', __spina_exc)
            pass
        load_list()
        messagebox.showinfo("Restored", f"Client '{nm}' restored.")

    ttk.Button(btns, text="Restore Selected", command=restore_selected).pack(side='right')
    ttk.Button(btns, text="Close", command=win.destroy).pack(side='right', padx=6)

    try:

        search_var.trace_add('write', lambda *_: load_list())

    except Exception as e:

        try:

            search_var.trace('w', lambda *_: load_list())

        except Exception as e2:

            _log_ignored('ui.trace_add failed', e2, key='ui.trace_add_failed')
    try:
        cb.bind("<<ComboboxSelected>>", lambda e: load_list())
    except Exception as e:
        _log_ignored("ui.bind failed", e, key="ui.bind_failed")

    load_list()

