                            c.saveState()
                            c.setFont(_font2, _size2)
                            c.setFillColorRGB(0, 0, 0)
                            c.drawCentredString(x0 + idx_w + name_w + (pay_w / 2.0), _baseline2, _safe(pay_txt))
