# --- Collector Route UI FIXES (click/scroll + missing wrappers + safer refresh) ---
# These are appended fixes to prevent crashes and to fix scroll/selection issues.

def _on_collectors_multi_toggle(self):
    """Toggle multi-select mode for Collector Route list (checkbox Sel column)."""
    try:
        multi = bool(self.collector_route_multi_var.get())
    except Exception:
        multi = bool(getattr(self, "_collectors_multi_mode", False))
    try:
        self._collectors_multi_mode = multi
    except Exception:
        pass
    # When turning OFF multi mode, clear checked state
    if not multi:
        try:
            self._collectors_clear_checked()
        except Exception:
            pass
    try:
        self.refresh_collectors()
    except Exception:
        pass


def _on_collectors_tree_wheel(self, event):
    """Mouse wheel scroll for Collector Route list (Treeview)."""
    try:
        tv = None
        try:
            # Prefer the widget under the cursor
            tv = event.widget
        except Exception:
            tv = None
        if tv is None or not hasattr(tv, "yview_scroll"):
            tv = getattr(self, "collectors_tree", None)

        if tv is None:
            return

        delta = 0
        if hasattr(event, "delta") and event.delta:
            # Windows: 120 per notch; trackpads may be smaller
            try:
                delta = int(-1 * (event.delta / 120))
            except Exception:
                delta = -1 if event.delta > 0 else 1
            if delta == 0:
                delta = -1 if event.delta > 0 else 1
        elif getattr(event, "num", None) in (4, 5):
            # Linux
            delta = -1 if event.num == 4 else 1

        if delta:
            tv.yview_scroll(delta, "units")
            return "break"
    except Exception:
        return
    return


def _on_collectors_tree_click(self, event):
    """Handle click in Sel / Actions columns without breaking row selection."""
    try:
        tv = getattr(self, "collectors_tree", None)
        if tv is None:
            return

        iid = tv.identify_row(event.y)
        col = tv.identify_column(event.x)  # '#1'..'#N'
        if not iid:
            return  # header or empty area

        # Always keep row selected + focused
        try:
            tv.selection_set(iid)
            tv.focus(iid)
        except Exception:
            pass

        # Determine multi mode
        try:
            multi = bool(self.collector_route_multi_var.get())
        except Exception:
            multi = bool(getattr(self, "_collectors_multi_mode", False))

        # Sel column (#1) toggles checkbox when in multi mode
        if col == "#1":
            if not multi:
                # Single-select mode: just select row and update details
                try:
                    self._on_collectors_select()
                except Exception:
                    pass
                return

            # Multi mode: toggle checked set
            try:
                vals = tv.item(iid, "values") or ()
            except Exception:
                vals = ()
            try:
                name = self._collectors_name_from_values(vals)
            except Exception:
                name = (vals[1] if len(vals) > 1 else (vals[0] if len(vals) else ""))

            name = (name or "").strip()
            if not name:
                return "break"

            checked = getattr(self, "_collectors_checked", None)
            if checked is None:
                checked = set()
                try:
                    self._collectors_checked = checked
                except Exception:
                    pass

            try:
                if name in checked:
                    checked.remove(name)
                else:
                    checked.add(name)
            except Exception:
                pass

            # Update checkbox markers + bulk bar
            try:
                self._collectors_apply_markers()
            except Exception:
                pass
            try:
                self._collectors_refresh_bulk_bar()
            except Exception:
                pass

            # keep selection visible
            try:
                tv.see(iid)
            except Exception:
                pass
            return "break"

        # Actions column: open context menu (safe and obvious)
        # Columns = sel, collector, areas_count, clients, main_area, sub_area, details, actions
        if col == "#8":
            try:
                m = getattr(self, "_collectors_ctx_menu", None)
                if m is not None:
                    m.tk_popup(event.x_root, event.y_root)
                    return "break"
            except Exception:
                return "break"

        # Default behavior: update details panel
        try:
            self._on_collectors_select()
        except Exception:
            pass
    except Exception:
        return
    return


def _delete_selected_collector(self):
    """Safe delete action used by keybinds/buttons/menus."""
    # If multi mode and checked exists -> delete checked
    try:
        multi = bool(self.collector_route_multi_var.get())
    except Exception:
        multi = bool(getattr(self, "_collectors_multi_mode", False))

    try:
        checked = set(getattr(self, "_collectors_checked", set()) or set())
    except Exception:
        checked = set()

    if multi and checked:
        try:
            return self._collectors_delete_selected()
        except Exception:
            pass

    # Otherwise delete current selection (legacy single)
    try:
        if hasattr(self, "_delete_collector"):
            return self._delete_collector()
    except Exception:
        pass

    try:
        # fallback: bulk delete uses tree selection as checked list
        return self._collectors_delete_selected()
    except Exception:
        pass


def _edit_selected_collector(self):
    """Safe edit action for the context menu ('Full Editor…')."""
    # Prefer inline editor (new UI)
    try:
        if hasattr(self, "_collectors_start_inline_edit"):
            return self._collectors_start_inline_edit()
    except Exception:
        pass
    # Fallback: nothing else to do
    try:
        from tkinter import messagebox
        messagebox.showinfo("Edit", "Inline editor is not available in this build.")
    except Exception:
        pass
    return


def _collectors_areas_drag_motion(self, event):
    """Drag-to-reorder areas listbox (MOVE item) without index-shift bugs."""
    try:
        lb = getattr(self, "collector_route_areas_lb", None)
        if lb is None:
            return
        i = getattr(self, "_areas_drag_index", None)
        if i is None:
            return
        try:
            i = int(i)
        except Exception:
            return

        try:
            j = int(lb.nearest(event.y))
        except Exception:
            return

        if j == i:
            return

        items = list(lb.get(0, "end"))
        if i < 0 or i >= len(items) or j < 0 or j >= len(items):
            return

        item = items.pop(i)
        items.insert(j, item)

        lb.delete(0, "end")
        for it in items:
            lb.insert("end", it)

        self._areas_drag_index = j
        try:
            lb.selection_clear(0, "end")
            lb.selection_set(j)
            lb.activate(j)
            lb.see(j)
        except Exception:
            pass
    except Exception:
        pass


