# Make refresh_collectors non-reentrant (prevents freeze from overlapping refresh calls)
try:
    if hasattr(App, "refresh_collectors") and not getattr(App, "_refresh_collectors_guarded", False):
        _orig_refresh_collectors = App.refresh_collectors

        def _refresh_collectors_guard(self, *args, **kwargs):
            if getattr(self, "_collectors_refresh_running", False):
                return
            self._collectors_refresh_running = True
            try:
                return _orig_refresh_collectors(self, *args, **kwargs)
            finally:
                try:
                    self._collectors_refresh_running = False
                except Exception:
                    pass

        App.refresh_collectors = _refresh_collectors_guard
        App._refresh_collectors_guarded = True
except Exception:
    pass


# --- BEGIN: Clients tab picture support ---
def _spina__ensure_client_picture_column(db_obj):
    """Best-effort lazy migration for client_picture support."""
    try:
        cur = db_obj.conn.cursor()
        cols = [r[1] for r in cur.execute("PRAGMA table_info(clients)").fetchall()]
        if "client_picture" not in cols:
            cur.execute("ALTER TABLE clients ADD COLUMN client_picture TEXT DEFAULT ''")
            db_obj.conn.commit()
    except Exception as e:
        try:
            _log_exc('schema:ensure client_picture', e)
        except Exception:
            pass


def _spina__client_pictures_dir():
    try:
        p = data_path('client_pictures')
    except Exception:
        p = os.path.join(APP_DIR, 'data', 'client_pictures')
    try:
        os.makedirs(p, exist_ok=True)
    except Exception:
        pass
    return p


def _spina__resolve_app_path(p):
    try:
        s = str(p or '').strip()
    except Exception:
        s = ''
    if not s:
        return ''
    # V9: client pictures may now be stored in PostgreSQL as dbpic:<id>.
    try:
        if s.lower().startswith('dbpic:'):
            restored = _spina_pg_restore_client_picture_to_cache(s)
            if restored:
                return restored
    except Exception:
        pass
    if os.path.isabs(s):
        return s
    return os.path.abspath(os.path.join(APP_DIR, s))


def _spina__store_client_picture_file(src_path, client_uid):
    src = str(src_path or '').strip()
    uid = str(client_uid or '').strip()
    if not src or not uid:
        return ''
    # V9: save picture bytes into PostgreSQL first. If that fails, use the old
    # local-file storage as emergency fallback.
    try:
        tok = _spina_pg_store_client_picture_to_db(src, client_uid=uid)
        if tok:
            return tok
    except Exception:
        pass
    pics_dir = _spina__client_pictures_dir()
    try:
        ext = os.path.splitext(src)[1].lower().strip()
    except Exception:
        ext = ''
    if ext not in ('.png', '.jpg', '.jpeg', '.gif', '.bmp', '.webp'):
        ext = '.png'
    # Remove older saved picture(s) for the same client uid.
    try:
        for old in os.listdir(pics_dir):
            try:
                if old.startswith(uid + '.'):
                    os.remove(os.path.join(pics_dir, old))
            except Exception:
                pass
    except Exception:
        pass
    dst_name = f'{uid}{ext}'
    dst_abs = os.path.join(pics_dir, dst_name)
    shutil.copy2(src, dst_abs)
    try:
        _spina_pg_store_file_to_db(dst_abs, file_type='client_picture', client_uid=uid)
    except Exception:
        pass
    return os.path.join('data', 'client_pictures', dst_name)


def _spina__delete_client_picture_file(stored_path):
    try:
        s = str(stored_path or '').strip()
        if s.lower().startswith('dbpic:'):
            _spina_pg_delete_client_picture_token(s)
            return
        abs_path = _spina__resolve_app_path(stored_path)
        if not abs_path:
            return
        if os.path.exists(abs_path):
            os.remove(abs_path)
    except Exception:
        pass


def _db_get_client_picture(self, name, loan_type=None, include_archived=True):
    try:
        _spina__ensure_client_picture_column(self)
    except Exception:
        pass
    try:
        info = self.get_client_info(name, loan_type=loan_type, include_archived=include_archived) or {}
    except Exception:
        info = {}
    return str(info.get('client_picture') or '').strip()


def _db_set_client_picture(self, name, picture_source_path, loan_type=None, source='clients:picture'):
    _spina__ensure_client_picture_column(self)
    cur = self.conn.cursor()
    lt = self._effective_lt(loan_type)
    info = self.get_client_info(name, loan_type=lt, include_archived=True) or {}
    if not info:
        return ''
    uid = str(info.get('client_uid') or '').strip()
    if not uid:
        return ''
    old_path = str(info.get('client_picture') or '').strip()
    rel_path = _spina__store_client_picture_file(picture_source_path, uid)
    if not rel_path:
        return ''
    try:
        cur.execute('UPDATE clients SET client_picture=? WHERE client_uid=?', (rel_path, uid))
        self.conn.commit()
    except Exception:
        cur.execute('UPDATE clients SET client_picture=? WHERE name=? AND loan_type=?', (rel_path, name, lt))
        self.conn.commit()
    try:
        if old_path and old_path != rel_path:
            _spina__delete_client_picture_file(old_path)
    except Exception:
        pass
    try:
        new_row = self.get_client_by_uid(uid) or self.get_client_info(name, loan_type=lt, include_archived=True) or {}
        old_row = dict(info)
        self._log_client_history(uid, 'UPDATE', old_row=old_row, new_row=new_row, source=source, note='Updated client picture')
    except Exception:
        pass
    return rel_path


def _db_clear_client_picture(self, name, loan_type=None, source='clients:picture_clear'):
    _spina__ensure_client_picture_column(self)
    cur = self.conn.cursor()
    lt = self._effective_lt(loan_type)
    info = self.get_client_info(name, loan_type=lt, include_archived=True) or {}
    if not info:
        return False
    uid = str(info.get('client_uid') or '').strip()
    old_path = str(info.get('client_picture') or '').strip()
    try:
        if uid:
            cur.execute('UPDATE clients SET client_picture=? WHERE client_uid=?', ('', uid))
        else:
            cur.execute('UPDATE clients SET client_picture=? WHERE name=? AND loan_type=?', ('', name, lt))
        self.conn.commit()
    except Exception:
        return False
    try:
        if old_path:
            _spina__delete_client_picture_file(old_path)
    except Exception:
        pass
    try:
        if uid:
            new_row = self.get_client_by_uid(uid) or self.get_client_info(name, loan_type=lt, include_archived=True) or {}
            old_row = dict(info)
            self._log_client_history(uid, 'UPDATE', old_row=old_row, new_row=new_row, source=source, note='Cleared client picture')
    except Exception:
        pass
    return True


def _app__selected_client_name_and_lt(self):
    try:
        sel = self.clients_tree.selection()
    except Exception:
        sel = ()
    if not sel:
        return ('', _app__norm_lt_value(self, self._mode_filter()))
    iid = sel[0]
    try:
        vals = self.clients_tree.item(iid, 'values') or ()
    except Exception:
        vals = ()
    name = str(vals[0] if vals else '').strip()
    lt = _app__norm_lt_value(self, self._mode_filter())
    try:
        tags = self.clients_tree.item(iid, 'tags') or ()
        for t in tags:
            if str(t).startswith('lt:'):
                lt = _app__norm_lt_value(self, str(t).split(':', 1)[1])
                break
    except Exception:
        pass
    return (name, lt)


def _app_refresh_client_picture_panel(self):
    box = getattr(self, 'clients_picture_box', None)
    if box is None:
        return
    preview = getattr(self, 'clients_picture_preview', None)
    info_var = getattr(self, 'clients_picture_info_var', None)
    path_var = getattr(self, 'clients_picture_path_var', None)
    if preview is None or info_var is None or path_var is None:
        return

    name, lt = _app__selected_client_name_and_lt(self)
    if not name:
        try:
            preview.configure(image='', text='No picture selected')
            self._clients_picture_img = None
        except Exception:
            pass
        try:
            info_var.set('Select a client to view picture.')
            path_var.set('')
        except Exception:
            pass
        return

    try:
        pic_rel = self.db.get_client_picture(name, loan_type=lt, include_archived=True)
    except Exception:
        pic_rel = ''

    if not pic_rel:
        try:
            preview.configure(image='', text='No picture')
            self._clients_picture_img = None
        except Exception:
            pass
        try:
            info_var.set(f'{name} ({lt})')
            path_var.set('No saved picture.')
        except Exception:
            pass
        return

    abs_path = _spina__resolve_app_path(pic_rel)
    if not abs_path or not os.path.exists(abs_path):
        try:
            preview.configure(image='', text='Picture file\nnot found')
            self._clients_picture_img = None
        except Exception:
            pass
        try:
            info_var.set(f'{name} ({lt})')
            path_var.set(pic_rel)
        except Exception:
            pass
        return

    loaded = False
    try:
        from PIL import Image, ImageTk
        with Image.open(abs_path) as _img:
            img = _img.copy()
        img.thumbnail((150, 150), Image.LANCZOS)
        self._clients_picture_img = ImageTk.PhotoImage(img)
        preview.configure(image=self._clients_picture_img, text='')
        loaded = True
    except Exception:
        try:
            self._clients_picture_img = tk.PhotoImage(file=abs_path)
            preview.configure(image=self._clients_picture_img, text='')
            loaded = True
        except Exception:
            loaded = False

    if not loaded:
        try:
            preview.configure(image='', text='Picture saved\nbut preview failed')
            self._clients_picture_img = None
        except Exception:
            pass

    try:
        info_var.set(f'{name} ({lt})')
        path_var.set(pic_rel)
    except Exception:
        pass


def _app_set_selected_client_picture(self):
    name, lt = _app__selected_client_name_and_lt(self)
    if not name:
        messagebox.showinfo('Picture', 'Select a client first.')
        return
    file_path = filedialog.askopenfilename(
        parent=getattr(self, 'root', None),
        title='Select Client Picture',
        filetypes=[('Image files', '*.png *.jpg *.jpeg *.gif *.bmp *.webp'), ('All files', '*.*')],
    )
    if not file_path:
        return
    try:
        rel = self.db.set_client_picture(name, file_path, loan_type=lt)
        if not rel:
            messagebox.showerror('Picture', 'Failed to save client picture.')
            return
    except Exception as e:
        messagebox.showerror('Picture', f'Failed to save client picture.\n\n{e}')
        return
    try:
        self.refresh_client_picture_panel()
    except Exception:
        pass


def _app_clear_selected_client_picture(self):
    name, lt = _app__selected_client_name_and_lt(self)
    if not name:
        messagebox.showinfo('Picture', 'Select a client first.')
        return
    try:
        cur = self.db.get_client_picture(name, loan_type=lt, include_archived=True)
    except Exception:
        cur = ''
    if not cur:
        messagebox.showinfo('Picture', 'This client has no saved picture.')
        return
    if not messagebox.askyesno('Clear Picture', f"Remove the saved picture for '{name}' ({lt})?"):
        return
    try:
        ok = self.db.clear_client_picture(name, loan_type=lt)
        if not ok:
            messagebox.showerror('Picture', 'Failed to clear client picture.')
            return
    except Exception as e:
        messagebox.showerror('Picture', f'Failed to clear client picture.\n\n{e}')
        return
    try:
        self.refresh_client_picture_panel()
    except Exception:
        pass


def _app_install_clients_picture_ui(self):
    if getattr(self, '_clients_picture_ui_ready', False):
        try:
            self.refresh_client_picture_panel()
        except Exception:
            pass
        return

    try:
        box = ttk.LabelFrame(self.tab_clients, text='Client Picture')
        box.pack(fill='x', padx=8, pady=(0, 8))
    except Exception:
        return

    top = ttk.Frame(box)
    top.pack(fill='x', padx=8, pady=8)

    preview = ttk.Label(top, text='No picture selected', anchor='center', width=22)
    try:
        preview.configure(relief='solid', padding=8)
    except Exception:
        pass
    preview.pack(side='left', padx=(0, 12), pady=2)

    right = ttk.Frame(top)
    right.pack(side='left', fill='x', expand=True)

    info_var = tk.StringVar(value='Select a client to view picture.')
    path_var = tk.StringVar(value='')
    ttk.Label(right, textvariable=info_var, font=('TkDefaultFont', 10, 'bold')).pack(anchor='w')
    ttk.Label(right, textvariable=path_var, foreground='#666', wraplength=520, justify='left').pack(anchor='w', pady=(4, 8))

    btns = ttk.Frame(right)
    btns.pack(anchor='w')
    ttk.Button(btns, text='Set Picture', command=lambda: self.set_selected_client_picture()).pack(side='left', padx=(0, 6))
    ttk.Button(btns, text='Clear Picture', command=lambda: self.clear_selected_client_picture()).pack(side='left')

    self.clients_picture_box = box
    self.clients_picture_preview = preview
    self.clients_picture_info_var = info_var
    self.clients_picture_path_var = path_var
    self._clients_picture_img = None
    self._clients_picture_ui_ready = True

    try:
        self.clients_tree.bind('<<TreeviewSelect>>', lambda e: self.refresh_client_picture_panel(), add='+')
    except Exception:
        try:
            self.clients_tree.bind('<<TreeviewSelect>>', lambda e: self.refresh_client_picture_panel())
        except Exception:
            pass

    try:
        self.refresh_client_picture_panel()
    except Exception:
        pass


try:
    if 'LoanDB' in globals():
        setattr(LoanDB, 'get_client_picture', _db_get_client_picture)
        setattr(LoanDB, 'set_client_picture', _db_set_client_picture)
        setattr(LoanDB, 'clear_client_picture', _db_clear_client_picture)
except Exception:
    pass

try:
    if 'App' in globals():
        setattr(App, 'refresh_client_picture_panel', _app_refresh_client_picture_panel)
        setattr(App, 'set_selected_client_picture', _app_set_selected_client_picture)
        setattr(App, 'clear_selected_client_picture', _app_clear_selected_client_picture)
        setattr(App, '_install_clients_picture_ui', _app_install_clients_picture_ui)

        if hasattr(App, '_build_clients_tab') and not getattr(App, '_clients_picture_build_wrapped', False):
            _orig_build_clients_tab_with_picture = App._build_clients_tab
            def _build_clients_tab_with_picture(self, *args, **kwargs):
                res = _orig_build_clients_tab_with_picture(self, *args, **kwargs)
                try:
                    self._install_clients_picture_ui()
                except Exception as e:
                    try:
                        _log_exc('clients picture ui install', e)
                    except Exception:
                        pass
                return res
            App._build_clients_tab = _build_clients_tab_with_picture
            App._clients_picture_build_wrapped = True

        if hasattr(App, 'refresh_clients') and not getattr(App, '_clients_picture_refresh_wrapped', False):
            _orig_refresh_clients_with_picture = App.refresh_clients
            def _refresh_clients_with_picture(self, *args, **kwargs):
                res = _orig_refresh_clients_with_picture(self, *args, **kwargs)
                try:
                    self.refresh_client_picture_panel()
                except Exception:
                    pass
                return res
            App.refresh_clients = _refresh_clients_with_picture
            App._clients_picture_refresh_wrapped = True
except Exception:
    pass
# --- END: Clients tab picture support ---


# --- BEGIN: LARGE DATA PERFORMANCE PATCH (clients + databank) ---
# Purpose:
#   Fix lag when the database grows large by avoiding thousands of repeated
#   per-client/per-day queries during screen refreshes.
#   Safe for existing data: only creates indexes and changes how rows are read.
def _spina_perf_ensure_indexes(db):
    """Create helpful indexes for large datasets. Safe/idempotent."""
    try:
        conn = getattr(db, "conn", None)
        if conn is None:
            return
        cur = conn.cursor()
        idx_sql = [
            # Data Bank/month queries: date range + loan type, then client/name lookup
            "CREATE INDEX IF NOT EXISTS idx_tx_date_lt_uid ON transactions(date, loan_type, client_uid)",
            "CREATE INDEX IF NOT EXISTS idx_tx_date_lt_name ON transactions(date, loan_type, name)",
            "CREATE INDEX IF NOT EXISTS idx_tx_lt_date_uid ON transactions(loan_type, date, client_uid)",
            "CREATE INDEX IF NOT EXISTS idx_tx_lt_date_name ON transactions(loan_type, date, name)",
            # Upsert/fetch one day fast
            "CREATE INDEX IF NOT EXISTS idx_tx_uid_lt_date_id ON transactions(client_uid, loan_type, date, id)",
            "CREATE INDEX IF NOT EXISTS idx_tx_name_lt_date_id ON transactions(name, loan_type, date, id)",
            # Clients tab filters and ordering
            "CREATE INDEX IF NOT EXISTS idx_clients_lt_arch_name ON clients(loan_type, is_archived, name COLLATE NOCASE)",
            "CREATE INDEX IF NOT EXISTS idx_clients_lt_arch_area_name ON clients(loan_type, is_archived, area COLLATE NOCASE, name COLLATE NOCASE)",
            "CREATE INDEX IF NOT EXISTS idx_clients_lt_arch_person ON clients(loan_type, is_archived, person_uid)",
            "CREATE INDEX IF NOT EXISTS idx_clients_name_lt_arch ON clients(name COLLATE NOCASE, loan_type, is_archived)",
        ]
        for sql in idx_sql:
            try:
                cur.execute(sql)
            except Exception as e:
                try:
                    _log_suppressed_once("perf_index", "performance index creation skipped", e)
                except Exception:
                    pass
        try:
            conn.commit()
        except Exception:
            pass
        try:
            cur.execute("PRAGMA optimize")
        except Exception:
            pass
    except Exception as e:
        try:
            _log_suppressed_once("perf_indexes_outer", "performance index setup failed", e)
        except Exception:
            pass


def _spina_perf_norm_lt(v):
    try:
        s = str(v or "").strip()
    except Exception:
        s = ""
    if s.lower().replace(" ", "") in ("7x7", "7×7"):
        return "7x7"
    return "Regular"


from spina_app.utilities.records import _spina_perf_dict_rows


def _spina_perf_clients_rows(db, loan_type="Regular", search=None, search_by="all", include_extra_7x7=True):
    """Bulk load rows for Clients tab in one/few queries, avoiding per-row get_client_info()."""
    _spina_perf_ensure_indexes(db)
    lt = _spina_perf_norm_lt(loan_type)
    term = (search or "").strip()
    sb = (search_by or "all").strip().lower()
    cur = db.conn.cursor()

    # Map search mode aliases
    try:
        if sb.startswith("cli"):
            sb = "client"
        elif sb.startswith("are"):
            sb = "area"
        elif sb.startswith("link"):
            sb = "linked"
        elif sb.startswith("unl"):
            sb = "unlinked"
        elif sb.startswith("sug"):
            sb = "suggested"
        elif sb.startswith("blank"):
            sb = "blanks"
        elif sb.startswith("pri"):
            sb = "principal"
        elif sb.startswith("rel"):
            sb = "released"
        elif sb.startswith("sta"):
            sb = "start_date"
        elif sb.startswith("due"):
            sb = "due_date"
        else:
            sb = "all"
    except Exception:
        sb = "all"

    where = ["IFNULL(c.loan_type,'Regular') = ?", "COALESCE(c.is_archived,0)=0"]
    params = [lt]
    like = f"%{term}%"

    # Special typed commands in All search
    tlow = term.lower()
    if sb == "all" and tlow in ("blanks", "blank", "missing", "incomplete"):
        sb, term = "blanks", ""
    elif sb == "all" and tlow in ("linked", "link"):
        sb, term = "linked", ""
    elif sb == "all" and tlow in ("unlinked", "not linked", "notlinked"):
        sb, term = "unlinked", ""
    elif sb == "all" and tlow in ("suggested", "suggest", "suggestion", "suggested link", "suggestedlink"):
        sb, term = "suggested", ""

    if sb == "blanks":
        where.append("(IFNULL(c.area,'')='' OR IFNULL(c.date_released,'')='' OR IFNULL(c.due_date,'')='' OR IFNULL(c.principal,0)=0)")
    elif sb == "linked":
        where.append("TRIM(IFNULL(c.person_uid,'')) <> ''")
        where.append("EXISTS(SELECT 1 FROM clients c2 WHERE c2.person_uid=c.person_uid AND c2.id<>c.id AND IFNULL(c2.loan_type,'Regular')<>IFNULL(c.loan_type,'Regular') AND COALESCE(c2.is_archived,0)=0)")
    elif sb == "suggested":
        where.append("TRIM(IFNULL(c.person_uid,'')) = ''")
        where.append("EXISTS(SELECT 1 FROM clients c2 WHERE c2.name=c.name AND c2.id<>c.id AND IFNULL(c2.loan_type,'Regular')<>IFNULL(c.loan_type,'Regular') AND COALESCE(c2.is_archived,0)=0)")
        if term:
            where.append("c.name LIKE ?")
            params.append(like)
    elif sb == "unlinked":
        where.append("TRIM(IFNULL(c.person_uid,'')) = ''")
        where.append("(EXISTS(SELECT 1 FROM clients c2 WHERE c2.name=c.name AND c2.id<>c.id AND IFNULL(c2.loan_type,'Regular')<>IFNULL(c.loan_type,'Regular') AND COALESCE(c2.is_archived,0)=0) OR (IFNULL(c.loan_type,'Regular')='7x7' AND NOT EXISTS(SELECT 1 FROM clients c2 WHERE c2.name=c.name AND IFNULL(c2.loan_type,'Regular')='Regular' AND COALESCE(c2.is_archived,0)=0)))")
        if term:
            where.append("c.name LIKE ?")
            params.append(like)
    elif term:
        if sb == "client":
            where.append("c.name LIKE ?"); params.append(like)
        elif sb == "area":
            where.append("IFNULL(c.area,'') LIKE ?"); params.append(like)
        elif sb == "principal":
            where.append("CAST(IFNULL(c.principal,0) AS TEXT) LIKE ?"); params.append(like)
        elif sb == "released":
            where.append("IFNULL(c.date_released,'') LIKE ?"); params.append(like)
        elif sb == "due_date":
            where.append("IFNULL(c.due_date,'') LIKE ?"); params.append(like)
        elif sb == "start_date":
            where.append("IFNULL(date(c.date_released, '+' || IFNULL(c.pay_start_offset_days,0) || ' day'),'') LIKE ?"); params.append(like)
        else:
            where.append("""(
                c.name LIKE ?
                OR IFNULL(c.area,'') LIKE ?
                OR CAST(IFNULL(c.principal,0) AS TEXT) LIKE ?
                OR IFNULL(c.date_released,'') LIKE ?
                OR IFNULL(c.due_date,'') LIKE ?
                OR IFNULL(date(c.date_released, '+' || IFNULL(c.pay_start_offset_days,0) || ' day'),'') LIKE ?
                OR IFNULL(c.person_uid,'') LIKE ?
            )""")
            params.extend([like, like, like, like, like, like, like])

    sql = "SELECT c.* FROM clients c WHERE " + " AND ".join(where) + " ORDER BY c.name COLLATE NOCASE"
    rows = _spina_perf_dict_rows(cur.execute(sql, params).fetchall())

    # Build fast lookup sets for link labels, no per-row DB calls.
    try:
        active = _spina_perf_dict_rows(cur.execute(
            "SELECT name, loan_type, person_uid FROM clients WHERE COALESCE(is_archived,0)=0"
        ).fetchall())
    except Exception:
        active = []

    other_by_name = set()
    pu_types = {}
    for r in active:
        nm = str(r.get("name") or "").strip().lower()
        rlt = _spina_perf_norm_lt(r.get("loan_type"))
        pu = str(r.get("person_uid") or "").strip()
        if rlt != lt and nm:
            other_by_name.add(nm)
        if pu:
            pu_types.setdefault(pu, set()).add(rlt)

    other_lt = "7x7" if lt == "Regular" else "Regular"
    final = []
    seen = set()
    for r in rows:
        nm_key = str(r.get("name") or "").strip().lower()
        pu = str(r.get("person_uid") or "").strip()
        link_label = ""
        if pu and len(pu_types.get(pu, set())) > 1:
            link_label = f"{other_lt}✓"
        elif pu:
            link_label = "Linked✓"
        elif nm_key in other_by_name:
            link_label = other_lt
        r["_spina_link_label"] = link_label
        r["_spina_row_lt"] = lt
        r["_spina_extra7x7"] = False
        final.append(r)
        seen.add(nm_key)

    # In Regular view, append unpaired 7x7 clients using one SQL query.
    if lt == "Regular" and include_extra_7x7 and sb not in ("linked", "suggested"):
        extra_where = [
            "IFNULL(c.loan_type,'Regular')='7x7'",
            "COALESCE(c.is_archived,0)=0",
            "TRIM(IFNULL(c.person_uid,''))=''",
            "NOT EXISTS(SELECT 1 FROM clients r WHERE r.name=c.name AND IFNULL(r.loan_type,'Regular')='Regular' AND COALESCE(r.is_archived,0)=0)"
        ]
        extra_params = []
        if term:
            if sb == "area":
                extra_where.append("IFNULL(c.area,'') LIKE ?"); extra_params.append(like)
            elif sb == "principal":
                extra_where.append("CAST(IFNULL(c.principal,0) AS TEXT) LIKE ?"); extra_params.append(like)
            elif sb == "released":
                extra_where.append("IFNULL(c.date_released,'') LIKE ?"); extra_params.append(like)
            elif sb == "due_date":
                extra_where.append("IFNULL(c.due_date,'') LIKE ?"); extra_params.append(like)
            elif sb == "start_date":
                extra_where.append("IFNULL(date(c.date_released, '+' || IFNULL(c.pay_start_offset_days,0) || ' day'),'') LIKE ?"); extra_params.append(like)
            else:
                extra_where.append("(c.name LIKE ? OR IFNULL(c.area,'') LIKE ?)")
                extra_params.extend([like, like])
        extra_sql = "SELECT c.* FROM clients c WHERE " + " AND ".join(extra_where) + " ORDER BY c.name COLLATE NOCASE"
        for r in _spina_perf_dict_rows(cur.execute(extra_sql, extra_params).fetchall()):
            nm_key = str(r.get("name") or "").strip().lower()
            if nm_key in seen:
                continue
            r["_spina_link_label"] = "7x7 ONLY"
            r["_spina_row_lt"] = "7x7"
            r["_spina_extra7x7"] = True
            final.append(r)
            seen.add(nm_key)

    return final


def _spina_perf_month_transactions(db, client_rows, start_date, end_date, loan_type):
    """Return {(row_key, yyyy-mm-dd): payment} for visible clients in the month using one range query."""
    _spina_perf_ensure_indexes(db)
    cur = db.conn.cursor()
    lt = _spina_perf_norm_lt(loan_type)

    uids = []
    names = []
    for r in client_rows or []:
        try:
            row_lt = _spina_perf_norm_lt(r.get("_spina_row_lt") or r.get("loan_type") or lt)
            if row_lt != lt:
                # Data Bank is current loan type only; skip 7x7 extras if ever present
                continue
            uid = str(r.get("client_uid") or "").strip()
            nm = str(r.get("name") or "").strip()
            if uid:
                uids.append(uid)
            elif nm:
                names.append(nm)
        except Exception:
            pass

    pay = {}
    def _chunks(seq, n=850):
        for i in range(0, len(seq), n):
            yield seq[i:i+n]

    # Prefer client_uid when available. Keep latest id for duplicate same-day records.
    for chunk in _chunks(uids):
        ph = ",".join(["?"] * len(chunk))
        sql = f"""
            SELECT client_uid, name, date, payment, id
            FROM transactions
            WHERE client_uid IN ({ph})
              AND IFNULL(NULLIF(TRIM(loan_type),''),'Regular')=?
              AND date >= ? AND date <= ?
            ORDER BY id ASC
        """
        for tr in cur.execute(sql, list(chunk) + [lt, start_date, end_date]).fetchall():
            try:
                uid = tr["client_uid"] if hasattr(tr, "keys") else tr[0]
                ds = tr["date"] if hasattr(tr, "keys") else tr[2]
                val = tr["payment"] if hasattr(tr, "keys") else tr[3]
                pay[(str(uid), str(ds)[:10])] = val
            except Exception:
                pass

    # Fallback for legacy rows without uid
    for chunk in _chunks(names):
        ph = ",".join(["?"] * len(chunk))
        sql = f"""
            SELECT name, date, payment, id
            FROM transactions
            WHERE name IN ({ph})
              AND IFNULL(NULLIF(TRIM(loan_type),''),'Regular')=?
              AND date >= ? AND date <= ?
            ORDER BY id ASC
        """
        for tr in cur.execute(sql, list(chunk) + [lt, start_date, end_date]).fetchall():
            try:
                nm = tr["name"] if hasattr(tr, "keys") else tr[0]
                ds = tr["date"] if hasattr(tr, "keys") else tr[1]
                val = tr["payment"] if hasattr(tr, "keys") else tr[2]
                pay[(str(nm).strip().lower(), str(ds)[:10])] = val
            except Exception:
                pass
    return pay


def _spina_perf_refresh_clients(self):
    """Fast Clients tab refresh for large datasets."""
    try:
        term = (getattr(self, "search_clients_var", tk.StringVar()).get() or "").strip()
    except Exception:
        term = ""
    try:
        lt = _app__norm_lt_value(self, self._mode_filter())
    except Exception:
        lt = "Regular"
    try:
        mode = (getattr(self, "clients_search_mode_var", tk.StringVar(value="All")).get() or "Both").strip().lower()
    except Exception:
        mode = "both"

    try:
        tree = self.clients_tree
        try:
            tree.delete(*tree.get_children())
        except Exception:
            for rid in tree.get_children():
                tree.delete(rid)
    except Exception:
        return

    try:
        rows = _spina_perf_clients_rows(self.db, loan_type=lt, search=term if term else None, search_by=mode, include_extra_7x7=True)
    except Exception as e:
        try:
            _log_exc("perf_refresh_clients: bulk load failed; using old loader", e)
        except Exception:
            pass
        try:
            return _app_refresh_clients(self)
        except Exception:
            return

    for idx, info in enumerate(rows or []):
        try:
            row_lt = _spina_perf_norm_lt(info.get("_spina_row_lt") or info.get("loan_type") or lt)
            is_extra_7x7 = bool(info.get("_spina_extra7x7"))
            _day_due, _due_today = _spina__client_due_meta(info)
            tags = [f"lt:{row_lt}", "even" if (idx % 2 == 0) else "odd"]
            if is_extra_7x7:
                tags.append("extra7x7")
            iid = (str(info.get("client_uid") or "").strip() or None)
            row_values = (
                info.get("name", ""),
                info.get("area", ""),
                info.get("payment_term", ""),
                _day_due,
                _spina__fmt_client_money(info.get("payment_amount", 0)),
                info.get("payment_mode", "Cash"),
                info.get("_spina_link_label", ""),
                info.get("contact_number", ""),
                _spina__fmt_client_money(info.get("principal", 0)),
                _spina__fmt_client_money(info.get("interest_amount", 0)),
                _spina__fmt_client_money(info.get("total_to_pay", 0)),
                info.get("date_released", ""),
                info.get("due_date", ""),
            )
            try:
                tree.insert("", "end", iid=iid, tags=tuple(tags), values=row_values)
            except Exception:
                tree.insert("", "end", tags=tuple(tags), values=row_values)
        except Exception as e:
            try:
                _log_suppressed_once("perf_client_row_insert", "client row insert skipped", e)
            except Exception:
                pass

    try:
        if hasattr(self, "clients_count_var"):
            self.clients_count_var.set(f"Rows: {len(tree.get_children())}")
    except Exception:
        pass
    try:
        self._update_toolbar_states()
    except Exception:
        pass
    if not term:
        try:
            self._refresh_area_dropdowns()
        except Exception:
            pass
    try:
        if hasattr(self, "refresh_client_picture_panel"):
            self.refresh_client_picture_panel()
    except Exception:
        pass


def _spina_perf_refresh_data_grid(self):
    """Fast Data Bank month grid refresh using bulk month transaction query."""
    try:
        self.status_var.set("Data Bank is view-only. Encode in Excel, then Import.")
    except Exception:
        pass

    try:
        for w in self.inner.winfo_children():
            try:
                w.destroy()
            except Exception:
                pass
    except Exception:
        return

    days = calendar.monthrange(self.grid_year, self.grid_month)[1]
    day_cols = tuple(f"d{d}" for d in range(1, days + 1))
    cols = ("client", "area") + day_cols

    grid = ttk.Frame(self.inner)
    grid.grid(row=0, column=0, sticky="nsew")
    try:
        self.inner.grid_rowconfigure(0, weight=1)
        self.inner.grid_columnconfigure(0, weight=1)
    except Exception:
        pass
    grid.grid_rowconfigure(0, weight=1)
    grid.grid_columnconfigure(1, weight=1)

    self.name_tree = ttk.Treeview(grid, columns=("client", "area"), show="headings", height=31)
    self._configure_tree_stripes(self.name_tree)
    self.name_tree.heading("client", text="Client Name")
    self.name_tree.heading("area", text="Area")
    self.name_tree.column("client", width=330, anchor="w", stretch=False)
    self.name_tree.column("area", width=185, anchor="w", stretch=False)

    self.days_tree = ttk.Treeview(grid, columns=cols, show="headings", height=31)
    self._configure_tree_stripes(self.days_tree)
    self.days_tree.heading("client", text="")
    self.days_tree.heading("area", text="")
    self.days_tree.column("client", width=0, minwidth=0, stretch=False)
    self.days_tree.column("area", width=0, minwidth=0, stretch=False)
    for c in day_cols:
        d = int(c[1:])
        self.days_tree.heading(c, text=str(d))
        self.days_tree.column(c, width=86, anchor="center", stretch=False)

    def _yview(*args):
        try: self.name_tree.yview(*args)
        except Exception: pass
        try: self.days_tree.yview(*args)
        except Exception: pass

    v = ttk.Scrollbar(grid, orient="vertical", command=_yview)
    h = ttk.Scrollbar(grid, orient="horizontal", command=self.days_tree.xview)
    self.name_tree.configure(yscrollcommand=v.set)
    self.days_tree.configure(yscrollcommand=v.set, xscrollcommand=h.set)
    self.name_tree.grid(row=0, column=0, sticky="ns")
    self.days_tree.grid(row=0, column=1, sticky="nsew")
    v.grid(row=0, column=2, sticky="ns")
    h.grid(row=1, column=1, sticky="ew")

    def _sync_selection(from_tv, to_tv):
        try:
            sel = from_tv.selection()
            if not sel:
                return
            if to_tv.selection() != sel:
                to_tv.selection_set(sel)
            try:
                to_tv.focus(sel[0])
            except Exception:
                pass
        except Exception:
            pass

    try:
        self.name_tree.bind("<<TreeviewSelect>>", lambda e=None: _sync_selection(self.name_tree, self.days_tree), add="+")
        self.days_tree.bind("<<TreeviewSelect>>", lambda e=None: _sync_selection(self.days_tree, self.name_tree), add="+")
        self.days_tree.bind("<Double-1>", self._begin_cell_edit, add="+")
        self.days_tree.bind("<Button-1>", self._remember_cell_click, add="+")
        self.days_tree.bind("<Delete>", self.delete_selected_cell, add="+")
        self.name_tree.bind("<Delete>", self.delete_selected_cell, add="+")
        for tv in (self.name_tree, self.days_tree):
            tv.bind("<MouseWheel>", self._on_mousewheel_sync, add="+")
            tv.bind("<Button-4>", self._on_mousewheel_sync, add="+")
            tv.bind("<Button-5>", self._on_mousewheel_sync, add="+")
    except Exception as e:
        try:
            _log_ignored("ui.bind failed", e, key="ui.bind_failed")
        except Exception:
            pass

    try:
        self._db_menu = tk.Menu(self.days_tree, tearoff=0)
        self._db_menu.add_command(label="Mark as missed (enter reason)", command=self._mark_missed_for_selected)
        self._db_menu.add_separator()
        self._db_menu.add_command(label="Delete this payment cell", command=self.delete_selected_cell)
        def _popup_db_menu(ev):
            try: self._remember_cell_click(ev)
            except Exception: pass
            try:
                self._db_menu.tk_popup(ev.x_root, ev.y_root)
            finally:
                try: self._db_menu.grab_release()
                except Exception: pass
        self.days_tree.bind("<Button-3>", _popup_db_menu, add="+")
    except Exception:
        pass

    try:
        self.inner.bind("<Configure>", self._resize_databank_columns, add="+")
    except Exception:
        pass

    try:
        search_term = self.search_db_var.get().strip()
    except Exception:
        search_term = ""
    try:
        mode_txt = self._mode_filter()
    except Exception:
        mode_txt = "Regular"

    # Data Bank should show current loan type only. No 7x7 extras here.
    try:
        clients = _spina_perf_clients_rows(self.db, loan_type=mode_txt, search=search_term if search_term else None, search_by="all", include_extra_7x7=False)
    except Exception as e:
        try:
            _log_exc("perf_refresh_data_grid: clients bulk load failed", e)
        except Exception:
            pass
        clients = []

    try:
        rows_txt = f"{len(clients or [])} row{'s' if len(clients or []) != 1 else ''} • {mode_txt} • {self._month_label()}"
        if search_term:
            rows_txt += f" • filter: {search_term}"
        if hasattr(self, "_db_rows_var") and self._db_rows_var is not None:
            self._db_rows_var.set(rows_txt)
    except Exception:
        pass

    if not clients:
        iid = "r0"
        self.name_tree.insert("", "end", iid=iid, values=("(no clients)", ""), tags=("odd",))
        self.days_tree.insert("", "end", iid=iid, values=("(no clients)", "", *([''] * days)), tags=("odd",))
    else:
        start_date = date(self.grid_year, self.grid_month, 1).strftime("%Y-%m-%d")
        end_date = date(self.grid_year, self.grid_month, days).strftime("%Y-%m-%d")
        try:
            payment_map = _spina_perf_month_transactions(self.db, clients, start_date, end_date, mode_txt)
        except Exception as e:
            try:
                _log_exc("perf_refresh_data_grid: tx bulk load failed", e)
            except Exception:
                pass
            payment_map = {}

        for idx, info in enumerate(clients):
            try:
                name = str(info.get("name") or "")
                area = str(info.get("area") or "")
                uid = str(info.get("client_uid") or "").strip()
                key = uid if uid else name.strip().lower()
                vals = [name, area]
                for d in range(1, days + 1):
                    ds = date(self.grid_year, self.grid_month, d).strftime("%Y-%m-%d")
                    if (key, ds) in payment_map:
                        p = payment_map.get((key, ds))
                        try:
                            if p is not None and float(p) != 0:
                                vals.append(fmt_currency(p))
                            else:
                                vals.append("0")
                        except Exception:
                            vals.append(str(p or ""))
                    else:
                        vals.append("")
                tag = "odd" if (idx % 2) == 0 else "even"
                iid = f"r{idx}"
                try:
                    self.name_tree.insert("", "end", iid=iid, values=(name, area), tags=(tag,))
                except Exception:
                    self.name_tree.insert("", "end", values=(name, area), tags=(tag,))
                try:
                    self.days_tree.insert("", "end", iid=iid, values=tuple(vals), tags=(tag,))
                except Exception:
                    self.days_tree.insert("", "end", values=tuple(vals), tags=(tag,))
            except Exception as e:
                try:
                    _log_suppressed_once("perf_databank_row_insert", "databank row insert skipped", e)
                except Exception:
                    pass

    try:
        self._resize_databank_columns()
    except Exception:
        pass
    try:
        if hasattr(self, "_update_data_toolbar"):
            self._update_data_toolbar()
    except Exception:
        pass


# Bind optimized loaders after the normal app methods are installed.
try:
    if "App" in globals():
        try:
            _spina_perf_ensure_indexes(LoanDB(DB_FILE))
        except Exception:
            pass
        setattr(App, "refresh_clients", _spina_perf_refresh_clients)
        setattr(App, "refresh_data_grid", _spina_perf_refresh_data_grid)
except Exception as e:
    try:
        _log_suppressed_once("perf_bind", "performance patch bind failed", e)
    except Exception:
        pass
