        self.cashctl_avg_collection_var = tk.StringVar(value='Average Daily Collection: PHP 0.00')
        self.cashctl_future_cash_var = tk.StringVar(value='Average Forecast Collection: PHP 0.00')
        self.cashctl_current_available_var = tk.StringVar(value='Current Available Cash: PHP 0.00')
        self.cashctl_forecast_available_var = tk.StringVar(value='Forecasted Available Cash: PHP 0.00')
        self.cashctl_reserve_var = tk.StringVar(value='Renewal Release Reserve (-): PHP 0.00')
        self.cashctl_renewal_payoff_var = tk.StringVar(value='Expected Renewal Payoff incl. Interest (+): PHP 0.00')
        self.cashctl_net_renewal_var = tk.StringVar(value='Net Renewal Cash Need (-): PHP 0.00')
        self.cashctl_buffer_amount_var = tk.StringVar(value='Emergency Buffer: PHP 0.00')
        self.cashctl_safe_now_var = tk.StringVar(value='Safe Amount Now: PHP 0.00')
        self.cashctl_forecast_safe_var = tk.StringVar(value='Forecasted Safe Amount: PHP 0.00')
        # Backward-compatible alias for older helper code.
