def _spina_v21_cash_refresh(self):
    try:
        if not hasattr(self, "tab_cash_control"):
            return

        ds = _spina_cashctl__valid_date(getattr(self, "cashctl_date_var", tk.StringVar(value="")).get())
        try:
            if str(self.cashctl_date_var.get() or "").strip()[:10] != ds:
                self.cashctl_date_var.set(ds)
                return
        except Exception:
            pass

        days = _spina_cashctl__int_range(getattr(self, "cashctl_forecast_days_var", tk.StringVar(value="14")).get(), 14, 1, 120)
        avg_window_days = _spina_cashctl__int_range(getattr(self, "cashctl_avg_window_days_var", tk.StringVar(value="30")).get(), 30, 1, 365)
        buffer_pct = _spina_cashctl__parse_percent(getattr(self, "cashctl_buffer_percent_var", tk.StringVar(value="10")).get(), default=10.0)

        totals = _spina_cashctl_get_collection_totals(self, ds)
        combined = float(totals.get("combined") or 0.0)
        reg = float(totals.get("regular") or 0.0)
        x7 = float(totals.get("7x7") or 0.0)
        other = float(totals.get("other") or 0.0)

        avg_info = _spina_cashctl_get_average_collection(self, ds, window_days=avg_window_days)
        avg_daily = float(avg_info.get("average") or 0.0)
        avg_active_days = int(avg_info.get("active_days") or 0)
        avg_total = float(avg_info.get("total") or 0.0)
        future_cash = round(avg_daily * days, 2)

        reserve_rows = _spina_cashctl_reserve_rows(self, forecast_days=days)
        reserve_total = round(sum(float(r.get("reserve_amount") or 0.0) for r in reserve_rows), 2)
        expected_renewal_payoff = round(sum(max(0.0, float(r.get("expected_payoff_collection", r.get("remaining", 0.0)) or 0.0)) for r in reserve_rows), 2)
        net_renewal_need = round(max(0.0, reserve_total - expected_renewal_payoff), 2)

        cash_on_hand = _spina_cashctl__parse_amount(getattr(self, "cashctl_cash_on_hand_var", tk.StringVar(value="0")).get())
        current_available = round(cash_on_hand + combined, 2)
        current_buffer_amount = round(max(0.0, current_available) * (buffer_pct / 100.0), 2)
        safe_now_raw = round(current_available - net_renewal_need - current_buffer_amount, 2)
        safe_now = max(0.0, safe_now_raw)

        forecast_available = round(current_available + future_cash, 2)
        forecast_buffer_amount = round(max(0.0, forecast_available) * (buffer_pct / 100.0), 2)
        forecast_safe_raw = round(forecast_available - net_renewal_need - forecast_buffer_amount, 2)
        forecast_safe = max(0.0, forecast_safe_raw)

        # Backward-compatible text vars
        self.cashctl_collection_var.set("Today Combined Collected for %s: %s" % (ds, _spina_cashctl__fmt_money(combined)))
        br = "Regular: %s    7x7: %s" % (_spina_cashctl__fmt_money(reg), _spina_cashctl__fmt_money(x7))
        if abs(other) >= 0.005:
            br += "    Other/Unclassified: %s" % _spina_cashctl__fmt_money(other)
        self.cashctl_breakdown_var.set(br)
        self.cashctl_avg_collection_var.set("Average Daily Collection: %s" % _spina_cashctl__fmt_money(avg_daily))
        self.cashctl_future_cash_var.set("Average Forecast Collection (%s day/s): %s" % (days, _spina_cashctl__fmt_money(future_cash)))
        self.cashctl_current_available_var.set("Current Available Cash: %s" % _spina_cashctl__fmt_money(current_available))
        self.cashctl_forecast_available_var.set("Forecasted Available Cash: %s" % _spina_cashctl__fmt_money(forecast_available))
        self.cashctl_reserve_var.set("All Active Renewal Release Reserve (-): %s" % _spina_cashctl__fmt_money(reserve_total))
        self.cashctl_renewal_payoff_var.set("Expected Renewal Payoff incl. Interest (+): %s" % _spina_cashctl__fmt_money(expected_renewal_payoff))
        self.cashctl_net_renewal_var.set("Net Renewal Cash Need (-): %s" % _spina_cashctl__fmt_money(net_renewal_need))
        self.cashctl_buffer_amount_var.set("Emergency Buffer: Now %s / Forecast %s" % (_spina_cashctl__fmt_money(current_buffer_amount), _spina_cashctl__fmt_money(forecast_buffer_amount)))
        self.cashctl_safe_now_var.set("Safe Amount Now: %s" % _spina_cashctl__fmt_money(safe_now))
        self.cashctl_forecast_safe_var.set("Forecasted Safe Amount: %s" % _spina_cashctl__fmt_money(forecast_safe))

        # Modern cards
        _spina_v21_cash_set_card(self, "safe_now", _spina_cashctl__fmt_money(safe_now), "Real cash only")
        _spina_v21_cash_set_card(self, "forecast_safe", _spina_cashctl__fmt_money(forecast_safe), f"After {days} forecast day(s)")
        _spina_v21_cash_set_card(self, "collection", _spina_cashctl__fmt_money(combined), f"Regular {_spina_v21_cash_money_short(reg)} • 7x7 {_spina_v21_cash_money_short(x7)}")
        _spina_v21_cash_set_card(self, "net_need", _spina_cashctl__fmt_money(net_renewal_need), "Reserve minus expected payoff")
        _spina_v21_cash_set_card(self, "reserve", _spina_cashctl__fmt_money(reserve_total), f"{len(reserve_rows)} active loan record(s)")
        _spina_v21_cash_set_card(self, "buffer", _spina_cashctl__fmt_money(current_buffer_amount), f"{_spina_cashctl__fmt_pct(buffer_pct)} of current available")
        _spina_v21_cash_set_card(self, "average", _spina_cashctl__fmt_money(avg_daily), f"{avg_active_days} active day(s), total {_spina_v21_cash_money_short(avg_total)}")
        _spina_v21_cash_set_card(self, "available", _spina_cashctl__fmt_money(current_available), "Cash on hand + today collection")

        if safe_now_raw > 0 and forecast_safe_raw > safe_now_raw:
            result = "Safe now: %s. Forecast safe: %s if average collection arrives. Use Safe Now for real release decisions." % (
                _spina_cashctl__fmt_money(safe_now),
                _spina_cashctl__fmt_money(forecast_safe),
            )
        elif safe_now_raw > 0:
            result = "Safe now: %s. This uses only true cash on hand plus today's collected cash." % _spina_cashctl__fmt_money(safe_now)
        elif abs(safe_now_raw) < 0.005:
            result = "No safe release amount now after renewal need and emergency buffer."
        else:
            result = "Do not release new loans now. Current cash is short by %s after renewal need and emergency buffer." % _spina_cashctl__fmt_money(abs(safe_now_raw))
        if avg_active_days <= 0:
            result += " Forecast is PHP 0.00 because no collection history was found in the selected window."
        self.cashctl_decision_var.set(result)

        self._cashctl_last_data = {
            "date": ds,
            "regular": reg,
            "7x7": x7,
            "other": other,
            "combined": combined,
            "avg_daily": avg_daily,
            "future_cash": future_cash,
            "reserve_total": reserve_total,
            "expected_payoff": expected_renewal_payoff,
            "net_need": net_renewal_need,
            "cash_on_hand": cash_on_hand,
            "current_available": current_available,
            "buffer_now": current_buffer_amount,
            "safe_now": safe_now_raw,
            "forecast_available": forecast_available,
            "buffer_forecast": forecast_buffer_amount,
            "forecast_safe": forecast_safe_raw,
            "reserve_rows": reserve_rows,
        }

        _spina_v21_cash_draw_charts(self, self._cashctl_last_data)

        try:
            if hasattr(self, "cashctl_table_summary_var"):
                urgent = sum(1 for r in reserve_rows if r.get("status") in ("Finishing Now", "Near Completion", "Due Soon", "Overdue"))
                self.cashctl_table_summary_var.set(f"{len(reserve_rows)} active loan records • {urgent} priority")
        except Exception:
            pass

        tree = getattr(self, "cashctl_tree", None)
        if tree is not None:
            for iid in tree.get_children():
                tree.delete(iid)

            for r in reserve_rows:
                dl = r.get("days_left")
                status = r.get("status") or ""
                tag = ""
                if status == "Finishing Now":
                    tag = "finish"
                elif status == "Near Completion":
                    tag = "near"
                elif status == "Due Soon":
                    tag = "due"
                elif status == "Overdue":
                    tag = "overdue"

                tree.insert(
                    "",
                    "end",
                    values=(
                        status,
                        r.get("name") or "",
                        r.get("loan_type") or "",
                        r.get("area") or "",
                        _spina_cashctl__fmt_money(r.get("principal") or 0.0),
                        _spina_cashctl__fmt_pct(r.get("completion_pct") or 0.0),
                        _spina_cashctl__fmt_money(r.get("remaining") or 0.0),
                        _spina_dash__date_text(r.get("due_date")) if "_spina_dash__date_text" in globals() else str(r.get("due_date") or ""),
                        "" if dl is None else str(dl),
                        _spina_cashctl__fmt_money(r.get("reserve_amount") or 0.0),
                        r.get("reserve_reason") or "",
                    ),
                    tags=(tag,) if tag else (),
                )

        try:
            if hasattr(self, "status_var"):
                self.status_var.set("Cash Control refreshed with modern graphs and all active renewal reserve.")
        except Exception:
            pass

    except Exception as e:
        try:
            _log_exc("v21.cash_control.refresh", e)
        except Exception:
            pass
        try:
            messagebox.showerror("Cash Control", "Unable to refresh Cash Control.\n\nSee data/spina_app.log for details.")
        except Exception:
            pass


try:
    if "App" in globals():
        App._build_cash_control_tab = _spina_v21_cash_build_tab
        App.refresh_cash_control = _spina_v21_cash_refresh
except Exception as __spina_exc:
    try:
        _log_suppressed_once("v21_cash_control_bind_failed", "v21 cash control patch failed", __spina_exc)
    except Exception:
        pass
