        _spina_v25_collector_button(header, "Add Collector", command=self._add_collector, kind="success").pack(side="right", padx=(8, 0))
        _spina_v25_collector_button(header, "Refresh", command=self.refresh_collectors, kind="soft").pack(side="right", padx=(8, 0))

        # Simple guide
        guide = tk.Frame(outer, bg=c["panel"], highlightbackground=c["border"], highlightthickness=1, bd=0)
        guide.pack(fill="x", padx=18, pady=(0, 12))
        tk.Label(guide, text="Daily route check", bg=c["panel"], fg=c["fg"], font=("Segoe UI", 11, "bold"), anchor="w").pack(fill="x", padx=14, pady=(10, 0))
        tk.Label(
            guide,
            text="1) Confirm every active area is assigned.  2) Check clients with blank area.  3) Print the route.  Use the right panel to edit only the selected collector.",
            bg=c["panel"],
            fg=c["muted"],
            font=("Segoe UI", 9),
            anchor="w",
            justify="left",
        ).pack(fill="x", padx=14, pady=(3, 10))

        # Controls
        controls = tk.Frame(outer, bg=c["panel"], highlightbackground=c["border"], highlightthickness=1, bd=0)
        controls.pack(fill="x", padx=18, pady=(0, 12))
        row = tk.Frame(controls, bg=c["panel"])
        row.pack(fill="x", padx=12, pady=10)

        search_box = tk.Frame(row, bg=c["panel"])
        search_box.pack(side="left", fill="x", expand=True, padx=(0, 10))
        tk.Label(search_box, text="Search Collector / Route / Notes", bg=c["panel"], fg=c["muted"], font=("Segoe UI", 8, "bold"), anchor="w").pack(fill="x")
        search_line = tk.Frame(search_box, bg=c["panel"])
        search_line.pack(fill="x", pady=(3, 0))
        ent_search = ttk.Entry(search_line, textvariable=self.collector_route_search_var)
        ent_search.pack(side="left", fill="x", expand=True)
        _spina_v25_collector_button(search_line, "Clear", command=self._clear_collectors_search_filters, kind="soft").pack(side="left", padx=(8, 0))

        filter_box = tk.Frame(row, bg=c["panel"])
        filter_box.pack(side="left", padx=(0, 10))
        tk.Label(filter_box, text="Main Area", bg=c["panel"], fg=c["muted"], font=("Segoe UI", 8, "bold"), anchor="w").pack(fill="x")
        self.collector_route_filter_main_cmb = ttk.Combobox(
            filter_box,
            textvariable=self.collector_route_filter_main_var,
            values=["(All)"],
            state="readonly",
            width=18,
        )
        self.collector_route_filter_main_cmb.pack(fill="x", pady=(3, 0))
        self.collector_route_filter_main_cmb.bind("<<ComboboxSelected>>", lambda e: self.refresh_collectors())

        checks = tk.Frame(row, bg=c["panel"])
        checks.pack(side="left", padx=(0, 10))
        tk.Label(checks, text="Route Check", bg=c["panel"], fg=c["muted"], font=("Segoe UI", 8, "bold"), anchor="w").pack(fill="x")
        check_line = tk.Frame(checks, bg=c["panel"])
        check_line.pack(fill="x", pady=(3, 0))
        ttk.Checkbutton(check_line, text="Conflicts", variable=self.collector_route_filter_conflicts_var, command=self.refresh_collectors).pack(side="left")
        ttk.Checkbutton(check_line, text="Unknown", variable=self.collector_route_filter_unknown_var, command=self.refresh_collectors).pack(side="left", padx=(8, 0))

        quick = tk.Frame(row, bg=c["panel"])
        quick.pack(side="right", padx=(0, 0), pady=(12, 0))
        _spina_v25_collector_button(quick, "Unassigned", command=self._show_unassigned_areas, kind="soft").pack(side="left", padx=(0, 6))
        _spina_v25_collector_button(quick, "No-Area Clients", command=self._show_no_area_clients, kind="soft").pack(side="left", padx=(0, 6))
        _spina_v25_collector_button(quick, "Conflicts", command=self._show_conflicts, kind="soft").pack(side="left")

        # Hidden bulk bar kept for compatibility with existing bulk functions.
        self.collectors_bulk_bar = tk.Frame(outer, bg=c["panel"], highlightbackground=c["border"], highlightthickness=1, bd=0)
        tk.Label(self.collectors_bulk_bar, textvariable=self.collectors_bulk_count_var, bg=c["panel"], fg=c["fg"], font=("Segoe UI", 9, "bold")).pack(side="left", padx=12, pady=8)
        _spina_v25_collector_button(self.collectors_bulk_bar, "Clear", command=self._collectors_clear_checked, kind="soft").pack(side="right", padx=(6, 12), pady=6)
        _spina_v25_collector_button(self.collectors_bulk_bar, "Export", command=self._collectors_export_selected, kind="soft").pack(side="right", padx=6, pady=6)
        _spina_v25_collector_button(self.collectors_bulk_bar, "Delete", command=self._collectors_delete_selected, kind="danger").pack(side="right", padx=6, pady=6)
        self.collectors_bulk_bar.pack_forget()

        # Summary cards
        cards = tk.Frame(outer, bg=c["bg"])
        cards.pack(fill="x", padx=18, pady=(0, 12))
        for i in range(4):
            cards.columnconfigure(i, weight=1, uniform="routecards")

        for i, (key, title, value, sub, accent) in enumerate([
            ("routes", "Routes Shown", "0", "Current filtered list", c["blue"]),
            ("unassigned", "Unassigned Areas", "0", "Active areas not routed", c["orange"]),
            ("noarea", "No-Area Clients", "0", "Needs area assignment", c["purple"]),
            ("issues", "Route Issues", "0", "Unknown + conflicts", c["red"]),
        ]):
            card, val, sublbl = _spina_v25_collector_card(cards, title, value, sub, accent)
            card.grid(row=0, column=i, sticky="nsew", padx=(0 if i == 0 else 8, 0), ipady=2)
            self._collector_route_cards[key] = (val, sublbl)

