try:
    if "App" in globals():
        _spina_v26_prev_on_collectors_select = getattr(App, "_on_collectors_select", None)
        if callable(_spina_v26_prev_on_collectors_select):
            def _spina_v26_on_collectors_select(self, *args, **kwargs):
                # v26 intentionally removed the visible selected collector/assigned areas panel.
                # Keep this function safe for context-menu/legacy calls, but do not show anything.
                try:
                    tree = getattr(self, "collectors_tree", None)
                    if tree is not None and hasattr(self, "collector_route_table_status_var"):
                        sel = tree.selection()
                        if sel:
                            vals = tree.item(sel[0], "values") or []
                            collector = str(vals[1] if len(vals) > 1 else vals[0] if vals else "").strip()
                            self.collector_route_table_status_var.set(f"Selected: {collector}")
                except Exception:
                    pass
                try:
                    _spina_v25_update_collector_cards(self)
                except Exception:
                    pass
                return None
            App._on_collectors_select = _spina_v26_on_collectors_select
except Exception as __spina_exc:
    try:
        _log_suppressed_once("v26_collector_route_remove_panel_bind_failed", "v26 collector route remove panel patch failed", __spina_exc)
    except Exception:
        pass
