def _spina_v27_build_collectors_tab(self):
    try:
        frm = self.tab_collectors
        try:
            for w in frm.winfo_children():
                w.destroy()
        except Exception:
            pass

        c = _spina_v27_route_colors(self)
        _spina_v27_style_route_trees(self)

        # Vars used by existing route logic
        self.collector_route_search_var = tk.StringVar(value="")
        self.collector_route_filter_main_var = tk.StringVar(value="(All)")
        self.collector_route_filter_conflicts_var = tk.BooleanVar(value=False)
        self.collector_route_filter_unknown_var = tk.BooleanVar(value=False)
        self.collector_route_multi_var = tk.BooleanVar(value=False)
        self.collector_route_unassigned_var = tk.StringVar(value="Unassigned areas: 0")
        self.collector_route_noarea_var = tk.StringVar(value="No-area clients: 0")
        self.collector_route_unknown_var = tk.StringVar(value="")
        self.collector_route_conflict_var = tk.StringVar(value="")
        self.collectors_bulk_count_var = tk.StringVar(value="")
        self._collectors_checked = set()
        self._collector_route_cards = {}
        self._route_health_labels = {}

        outer = tk.Frame(frm, bg=c["bg"])
        outer.pack(fill="both", expand=True)

        # Header
        header = tk.Frame(outer, bg=c["bg"])
        header.pack(fill="x", padx=18, pady=(16, 10))

        titlebox = tk.Frame(header, bg=c["bg"])
        titlebox.pack(side="left", fill="x", expand=True)
        tk.Label(titlebox, text="Collector Route", bg=c["bg"], fg=c["fg"], font=("Segoe UI", 20, "bold"), anchor="w").pack(fill="x")
        tk.Label(
            titlebox,
            text="Daily route overview. Select a collector, print the route, or open the bigger route editor.",
            bg=c["bg"],
            fg=c["muted"],
            font=("Segoe UI", 10),
            anchor="w",
        ).pack(fill="x", pady=(2, 0))

        _spina_v27_route_button(header, "Print Selected Route", command=self.print_collector_route_daily_ledger, kind="primary").pack(side="right", padx=(8, 0))
        _spina_v27_route_button(header, "Edit Route", command=self._edit_selected_collector, kind="success").pack(side="right", padx=(8, 0))
        _spina_v27_route_button(header, "Add Collector", command=self._add_collector, kind="soft").pack(side="right", padx=(8, 0))

        # Route health + simple instructions
        top_split = tk.Frame(outer, bg=c["bg"])
        top_split.pack(fill="x", padx=18, pady=(0, 12))
        top_split.columnconfigure(0, weight=2)
        top_split.columnconfigure(1, weight=1)

        guide = tk.Frame(top_split, bg=c["panel"], highlightbackground=c["border"], highlightthickness=1, bd=0)
        guide.grid(row=0, column=0, sticky="nsew", padx=(0, 8))
        tk.Label(guide, text="Daily route workflow", bg=c["panel"], fg=c["fg"], font=("Segoe UI", 11, "bold"), anchor="w").pack(fill="x", padx=14, pady=(10, 0))
        tk.Label(
            guide,
            text="1) Check route health.  2) Select collector.  3) Print selected route.  4) Use Edit Route only when you need to change assigned areas/order.",
            bg=c["panel"],
            fg=c["muted"],
            font=("Segoe UI", 9),
            anchor="w",
            justify="left",
            wraplength=900,
        ).pack(fill="x", padx=14, pady=(3, 10))

        health = tk.Frame(top_split, bg=c["panel"], highlightbackground=c["border"], highlightthickness=1, bd=0)
        health.grid(row=0, column=1, sticky="nsew")
        tk.Label(health, text="Route Health Check", bg=c["panel"], fg=c["fg"], font=("Segoe UI", 11, "bold"), anchor="w").pack(fill="x", padx=14, pady=(10, 4))
        for key in ("unassigned", "noarea", "unknown", "conflict"):
            lbl = tk.Label(health, text="✓ Checking…", bg=c["panel"], fg=c["muted"], font=("Segoe UI", 9, "bold"), anchor="w")
            lbl.pack(fill="x", padx=14, pady=(0, 4))
            self._route_health_labels[key] = lbl

        # Controls
        controls = tk.Frame(outer, bg=c["panel"], highlightbackground=c["border"], highlightthickness=1, bd=0)
        controls.pack(fill="x", padx=18, pady=(0, 12))
        row = tk.Frame(controls, bg=c["panel"])
        row.pack(fill="x", padx=12, pady=10)

        search_box = tk.Frame(row, bg=c["panel"])
        search_box.pack(side="left", fill="x", expand=True, padx=(0, 10))
        tk.Label(search_box, text="Search Collector / Route / Notes", bg=c["panel"], fg=c["muted"], font=("Segoe UI", 8, "bold"), anchor="w").pack(fill="x")
        search_line = tk.Frame(search_box, bg=c["panel"])
        search_line.pack(fill="x", pady=(3, 0))
        ent_search = ttk.Entry(search_line, textvariable=self.collector_route_search_var)
        ent_search.pack(side="left", fill="x", expand=True)
        _spina_v27_route_button(search_line, "Clear", command=self._clear_collectors_search_filters, kind="soft").pack(side="left", padx=(8, 0))

        filter_box = tk.Frame(row, bg=c["panel"])
        filter_box.pack(side="left", padx=(0, 10))
        tk.Label(filter_box, text="Main Area", bg=c["panel"], fg=c["muted"], font=("Segoe UI", 8, "bold"), anchor="w").pack(fill="x")
        self.collector_route_filter_main_cmb = ttk.Combobox(
            filter_box,
            textvariable=self.collector_route_filter_main_var,
            values=["(All)"],
            state="readonly",
            width=18,
        )
        self.collector_route_filter_main_cmb.pack(fill="x", pady=(3, 0))
        self.collector_route_filter_main_cmb.bind("<<ComboboxSelected>>", lambda e: self.refresh_collectors())

        # More options menu keeps advanced functions but removes visible clutter.
        more = tk.Menubutton(
            row,
            text="More Options",
            bg=c["card2"],
            fg=c["fg"],
            activebackground=c["soft"],
            activeforeground=c["fg"],
            relief="flat",
            bd=0,
            padx=14,
            pady=8,
            font=("Segoe UI", 9, "bold"),
            cursor="hand2",
        )
        menu = tk.Menu(more, tearoff=0)
        more.configure(menu=menu)
        menu.add_command(label="Show Unassigned Areas", command=self._show_unassigned_areas)
        menu.add_command(label="Show No-Area Clients", command=self._show_no_area_clients)
        menu.add_command(label="Show Route Conflicts", command=self._show_conflicts)
        menu.add_separator()
        menu.add_command(label="Refresh", command=self.refresh_collectors)
        menu.add_command(label="Delete Selected Collector", command=self._delete_selected_collector)
        more.pack(side="right", pady=(12, 0))

        # Summary cards
        cards = tk.Frame(outer, bg=c["bg"])
        cards.pack(fill="x", padx=18, pady=(0, 12))
        for i in range(4):
            cards.columnconfigure(i, weight=1, uniform="routecards")

        for i, (key, title, value, sub, accent) in enumerate([
            ("routes", "Routes Shown", "0", "Collectors shown", c["blue"]),
            ("unassigned", "Unassigned Areas", "0", "Active areas not assigned", c["orange"]),
            ("noarea", "No-Area Clients", "0", "Needs area assignment", c["purple"]),
            ("issues", "Route Issues", "0", "Unknown + conflicts", c["red"]),
        ]):
            card, val, sublbl = _spina_v27_route_card(cards, title, value, sub, accent)
            card.grid(row=0, column=i, sticky="nsew", padx=(0 if i == 0 else 8, 0), ipady=2)
            self._collector_route_cards[key] = (val, sublbl)

        # Main table
        table_card = tk.Frame(outer, bg=c["panel"], highlightbackground=c["border"], highlightthickness=1, bd=0)
        table_card.pack(fill="both", expand=True, padx=18, pady=(0, 18))
        table_head = tk.Frame(table_card, bg=c["panel"])
        table_head.pack(fill="x", padx=12, pady=(10, 4))
        tk.Label(table_head, text="Collector Route List", bg=c["panel"], fg=c["fg"], font=("Segoe UI", 12, "bold"), anchor="w").pack(side="left")
        self.collector_route_table_status_var = tk.StringVar(value="Double-click a row to edit route.")
        tk.Label(table_head, textvariable=self.collector_route_table_status_var, bg=c["panel"], fg=c["muted"], font=("Segoe UI", 9), anchor="e").pack(side="right")

        tree_frm = tk.Frame(table_card, bg=c["panel"])
        tree_frm.pack(fill="both", expand=True, padx=12, pady=(0, 12))

        cols = ("sel", "collector", "areas_count", "clients", "main_area", "sub_area", "details", "actions")
        self.collectors_tree = ttk.Treeview(
            tree_frm,
            columns=cols,
            displaycolumns=("collector", "areas_count", "clients", "main_area", "details", "actions"),
            show="headings",
            selectmode="browse",
            style="ModernRoute.Treeview",
        )
        tree = self.collectors_tree

        self._collectors_sort_col = "collector"
        self._collectors_sort_reverse = False

        def _set_sort(col):
            try:
                if getattr(self, "_collectors_sort_col", None) == col:
                    self._collectors_sort_reverse = not bool(getattr(self, "_collectors_sort_reverse", False))
                else:
                    self._collectors_sort_col = col
                    self._collectors_sort_reverse = False
            except Exception:
                self._collectors_sort_col = col
                self._collectors_sort_reverse = False
            self.refresh_collectors()

        headings = {
            "collector": ("Collector", 190, "w", "collector"),
            "areas_count": ("Areas", 75, "center", "areas_count"),
            "clients": ("Clients", 120, "center", "clients"),
            "main_area": ("Main Areas", 250, "w", "main_area"),
            "details": ("Route Summary / Notes", 480, "w", "details"),
            "actions": ("Action", 140, "center", None),
        }
        for col in cols:
            if col in headings:
                label, width, anchor, sort = headings[col]
                tree.heading(col, text=label, command=(lambda c=sort: _set_sort(c)) if sort else "")
                tree.column(col, width=width, minwidth=70, anchor=anchor, stretch=(col in ("main_area", "details")))
            else:
                tree.heading(col, text="")
                tree.column(col, width=1, minwidth=1, stretch=False)

        vsb = ttk.Scrollbar(tree_frm, orient="vertical", command=tree.yview)
        hsb = ttk.Scrollbar(tree_frm, orient="horizontal", command=tree.xview)
        tree.configure(yscrollcommand=vsb.set, xscrollcommand=hsb.set)
        tree.grid(row=0, column=0, sticky="nsew")
        vsb.grid(row=0, column=1, sticky="ns")
        hsb.grid(row=1, column=0, sticky="ew")
        tree_frm.grid_rowconfigure(0, weight=1)
        tree_frm.grid_columnconfigure(0, weight=1)

        try:
            tree.tag_configure("odd", background=c["panel"])
            tree.tag_configure("even", background=c["card2"])
            tree.tag_configure("warn", foreground=c["red"])
            tree.tag_configure("unknown", foreground=c["orange"])
        except Exception:
            pass

        # Double-click = modern editor. Selection only updates status/cards.
        def _select_status(_=None):
            try:
                vals = tree.item(tree.selection()[0], "values") if tree.selection() else ()
                nm = self._collectors_name_from_values(vals)
                self._selected_collector_name = nm
                if hasattr(self, "collector_route_table_status_var"):
                    self.collector_route_table_status_var.set(f"Selected: {nm}. Double-click to edit or click Print Selected Route.")
            except Exception:
                pass
            _spina_v27_update_route_cards(self)

        tree.bind("<<TreeviewSelect>>", _select_status)
        tree.bind("<Double-1>", lambda e: self._edit_selected_collector())
        tree.bind("<Return>", lambda e: self._edit_selected_collector())
        tree.bind("<Delete>", lambda e: self._delete_selected_collector())

        # Context menu
        ctx = tk.Menu(tree, tearoff=0)
        ctx.add_command(label="Edit Route", command=self._edit_selected_collector)
        ctx.add_command(label="Print Selected Route", command=self.print_collector_route_daily_ledger)
        ctx.add_separator()
        ctx.add_command(label="Delete Collector", command=self._delete_selected_collector)
        self._collectors_ctx_menu = ctx

        def _popup(event):
            try:
                iid = tree.identify_row(event.y)
                if iid:
                    tree.selection_set(iid)
                    tree.focus(iid)
                ctx.tk_popup(event.x_root, event.y_root)
            finally:
                try:
                    ctx.grab_release()
                except Exception:
                    pass

        tree.bind("<Button-3>", _popup)
        tree.bind("<Button-2>", _popup)

        _spina_v27_hidden_collector_widgets(self, outer)

        def _on_search(*_):
            try:
                self._schedule_collectors_refresh()
            except Exception:
                try:
                    self.refresh_collectors()
                except Exception:
                    pass

        try:
            self.collector_route_search_var.trace_add("write", _on_search)
        except Exception:
            pass

        try:
            ent_search.focus_set()
        except Exception:
            pass

        self.refresh_collectors()
        _spina_v27_update_route_cards(self)

    except Exception as e:
        try:
            _log_exc("v27.collector_route.build_tab", e)
        except Exception:
            pass
        try:
            messagebox.showerror("Collector Route", f"Unable to build Collector Route page.\n\n{e}")
        except Exception:
            pass


def _spina_v27_get_route_master_areas(self):
    areas = []
    try:
        # Prefer active/master areas from the last route refresh because it already normalizes route area names.
        m = getattr(self, "_last_master_area_name_map", {}) or {}
        if m:
            areas = list(m.values())
    except Exception:
        areas = []

    if not areas:
        try:
            areas = list(self.db.get_all_areas() or [])
        except Exception:
            areas = []

    cleaned = []
    seen = set()
    for a in areas:
        s = str(a or "").strip()
        if not s:
            continue
        k = " ".join(s.split()).lower()
        if k in seen:
            continue
        seen.add(k)
        cleaned.append(s)
    try:
        cleaned = sorted(cleaned, key=lambda x: str(x).lower())
    except Exception:
        pass
    return cleaned


def _spina_v27_collector_editor_dialog(self, title="Collector", initial_name="", initial_areas=None, initial_notes=""):
    """Modern route editor: Available Areas vs Assigned Route Order."""
    c = _spina_v27_route_colors(self)
    result = {"ok": False, "name": None, "areas": None, "notes": None}

    top = tk.Toplevel(self.root)
    top.title(title)
    top.configure(bg=c["bg"])
    try:
        top.transient(self.root)
        top.grab_set()
    except Exception:
        pass

    try:
        sw, sh = top.winfo_screenwidth(), top.winfo_screenheight()
        w = min(1120, max(940, sw - 120))
        h = min(780, max(680, sh - 160))
        rx, ry = self.root.winfo_rootx(), self.root.winfo_rooty()
        rw, rh = self.root.winfo_width(), self.root.winfo_height()
        px = max(10, min(rx + (rw - w) // 2, sw - w - 10))
        py = max(10, min(ry + (rh - h) // 2, sh - h - 60))
        top.geometry(f"{w}x{h}+{px}+{py}")
        top.minsize(900, 640)
    except Exception:
        top.geometry("1040x720")

    name_var = tk.StringVar(value=str(initial_name or "").strip())
    search_available_var = tk.StringVar(value="")
    search_assigned_var = tk.StringVar(value="")
    status_var = tk.StringVar(value="Use Add → / ← Remove or double-click areas. Assigned order is the print order.")

    initial = []
    seen_init = set()
    for a in (initial_areas or []):
        s = str(a or "").strip()
        if not s:
            continue
        k = " ".join(s.split()).lower()
        if k not in seen_init:
            seen_init.add(k)
            initial.append(s)

    assigned = {"areas": list(initial)}
    master_areas = _spina_v27_get_route_master_areas(self)
    # Include initial legacy/unknown areas so user can see and decide to keep/remove them.
    for a in initial:
        if a not in master_areas:
            master_areas.append(a)

    header = tk.Frame(top, bg=c["bg"])
    header.pack(fill="x", padx=18, pady=(16, 10))
    titlebox = tk.Frame(header, bg=c["bg"])
    titlebox.pack(side="left", fill="x", expand=True)
    tk.Label(titlebox, text=title, bg=c["bg"], fg=c["fg"], font=("Segoe UI", 20, "bold"), anchor="w").pack(fill="x")
    tk.Label(titlebox, text="Route Editor", bg=c["bg"], fg=c["muted"], font=("Segoe UI", 10), anchor="w").pack(fill="x", pady=(2, 0))

    name_panel = tk.Frame(top, bg=c["panel"], highlightbackground=c["border"], highlightthickness=1, bd=0)
    name_panel.pack(fill="x", padx=18, pady=(0, 12))
    tk.Label(name_panel, text="Collector Name", bg=c["panel"], fg=c["muted"], font=("Segoe UI", 8, "bold"), anchor="w").pack(fill="x", padx=14, pady=(10, 0))
    ttk.Entry(name_panel, textvariable=name_var, font=("Segoe UI", 12)).pack(fill="x", padx=14, pady=(3, 10))

    body = tk.Frame(top, bg=c["bg"])
    body.pack(fill="both", expand=True, padx=18, pady=(0, 12))
    body.columnconfigure(0, weight=1)
    body.columnconfigure(1, weight=0)
    body.columnconfigure(2, weight=1)
    body.rowconfigure(0, weight=1)

    def _panel(parent, title_text, subtitle):
        p = tk.Frame(parent, bg=c["panel"], highlightbackground=c["border"], highlightthickness=1, bd=0)
        tk.Label(p, text=title_text, bg=c["panel"], fg=c["fg"], font=("Segoe UI", 13, "bold"), anchor="w").pack(fill="x", padx=14, pady=(12, 0))
        tk.Label(p, text=subtitle, bg=c["panel"], fg=c["muted"], font=("Segoe UI", 9), anchor="w").pack(fill="x", padx=14, pady=(2, 8))
        return p

    available_panel = _panel(body, "Available Areas", "Areas not yet assigned to this collector.")
    available_panel.grid(row=0, column=0, sticky="nsew", padx=(0, 10))

    search_a = tk.Frame(available_panel, bg=c["panel"])
    search_a.pack(fill="x", padx=14, pady=(0, 8))
    ttk.Entry(search_a, textvariable=search_available_var).pack(side="left", fill="x", expand=True)
    _spina_v27_route_button(search_a, "Clear", command=lambda: search_available_var.set(""), kind="soft").pack(side="left", padx=(8, 0))

    avail_frame = tk.Frame(available_panel, bg=c["panel"])
    avail_frame.pack(fill="both", expand=True, padx=14, pady=(0, 14))
    available_lb = tk.Listbox(avail_frame, selectmode="extended", bg=c["entry"], fg=c["fg"], selectbackground=c["blue"], relief="flat", font=("Segoe UI", 10), activestyle="none")
    avail_vsb = ttk.Scrollbar(avail_frame, orient="vertical", command=available_lb.yview)
    available_lb.configure(yscrollcommand=avail_vsb.set)
    available_lb.pack(side="left", fill="both", expand=True)
    avail_vsb.pack(side="right", fill="y")

    middle = tk.Frame(body, bg=c["bg"], width=135)
    middle.grid(row=0, column=1, sticky="ns", padx=(0, 10))
    middle.grid_propagate(False)

    assigned_panel = _panel(body, "Assigned Route Order", "This order is used when printing the collector route.")
    assigned_panel.grid(row=0, column=2, sticky="nsew")

    search_s = tk.Frame(assigned_panel, bg=c["panel"])
    search_s.pack(fill="x", padx=14, pady=(0, 8))
    ttk.Entry(search_s, textvariable=search_assigned_var).pack(side="left", fill="x", expand=True)
    _spina_v27_route_button(search_s, "Clear", command=lambda: search_assigned_var.set(""), kind="soft").pack(side="left", padx=(8, 0))

    assigned_frame = tk.Frame(assigned_panel, bg=c["panel"])
    assigned_frame.pack(fill="both", expand=True, padx=14, pady=(0, 14))
    assigned_lb = tk.Listbox(assigned_frame, selectmode="extended", bg=c["entry"], fg=c["fg"], selectbackground=c["green"], relief="flat", font=("Segoe UI", 10), activestyle="none")
    assigned_vsb = ttk.Scrollbar(assigned_frame, orient="vertical", command=assigned_lb.yview)
    assigned_lb.configure(yscrollcommand=assigned_vsb.set)
    assigned_lb.pack(side="left", fill="both", expand=True)
    assigned_vsb.pack(side="right", fill="y")

    def _assigned_keys():
        return {" ".join(str(a).split()).lower() for a in assigned["areas"]}

    def _refresh_lists(select_assigned_index=None):
        try:
            available_lb.delete(0, "end")
            assigned_lb.delete(0, "end")
        except Exception:
            pass

        q_avail = search_available_var.get().strip().lower()
        q_assigned = search_assigned_var.get().strip().lower()
        used = _assigned_keys()

        for a in master_areas:
            s = str(a or "").strip()
            if not s:
                continue
            if " ".join(s.split()).lower() in used:
                continue
            if q_avail and q_avail not in s.lower():
                continue
            available_lb.insert("end", s)

        for idx, a in enumerate(assigned["areas"], start=1):
            s = str(a or "").strip()
            if not s:
                continue
            display = f"{idx}. {s}"
            if q_assigned and q_assigned not in s.lower():
                continue
            assigned_lb.insert("end", display)

        if select_assigned_index is not None:
            try:
                idx = max(0, min(select_assigned_index, assigned_lb.size() - 1))
                assigned_lb.selection_clear(0, "end")
                assigned_lb.selection_set(idx)
                assigned_lb.see(idx)
            except Exception:
                pass

        status_var.set(f"Available: {available_lb.size()} • Assigned: {len(assigned['areas'])}")

    def _clean_assigned_display(value):
        try:
            s = str(value or "")
            return re.sub(r"^\s*\d+\.\s*", "", s).strip()
        except Exception:
            return str(value or "").strip()

    def _add_selected():
        picks = []
        try:
            for i in available_lb.curselection():
                picks.append(available_lb.get(i))
        except Exception:
            picks = []
        if not picks:
            return
        used = _assigned_keys()
        for a in picks:
            s = str(a or "").strip()
            k = " ".join(s.split()).lower()
            if s and k not in used:
                assigned["areas"].append(s)
                used.add(k)
        _refresh_lists(select_assigned_index=len(assigned["areas"]) - 1)

    def _remove_selected():
        picks = []
        try:
            for i in assigned_lb.curselection():
                picks.append(_clean_assigned_display(assigned_lb.get(i)))
        except Exception:
            picks = []
        if not picks:
            return
        rm = {" ".join(str(a).split()).lower() for a in picks}
        assigned["areas"] = [a for a in assigned["areas"] if " ".join(str(a).split()).lower() not in rm]
        _refresh_lists()

    def _move_selected(delta):
        try:
            sel = list(assigned_lb.curselection())
        except Exception:
            sel = []
        if not sel:
            return
        # For filtered view, move by value in real assigned list.
        value = _clean_assigned_display(assigned_lb.get(sel[0]))
        try:
            idx = next(i for i, a in enumerate(assigned["areas"]) if str(a).strip() == value)
        except Exception:
            return
        new_idx = max(0, min(len(assigned["areas"]) - 1, idx + delta))
        if new_idx == idx:
            return
        item = assigned["areas"].pop(idx)
        assigned["areas"].insert(new_idx, item)
        _refresh_lists(select_assigned_index=new_idx)

    def _move_top():
        try:
            sel = list(assigned_lb.curselection())
            if not sel:
                return
            value = _clean_assigned_display(assigned_lb.get(sel[0]))
            idx = next(i for i, a in enumerate(assigned["areas"]) if str(a).strip() == value)
            item = assigned["areas"].pop(idx)
            assigned["areas"].insert(0, item)
            _refresh_lists(select_assigned_index=0)
        except Exception:
            pass

    def _move_bottom():
        try:
            sel = list(assigned_lb.curselection())
            if not sel:
                return
            value = _clean_assigned_display(assigned_lb.get(sel[0]))
            idx = next(i for i, a in enumerate(assigned["areas"]) if str(a).strip() == value)
            item = assigned["areas"].pop(idx)
            assigned["areas"].append(item)
            _refresh_lists(select_assigned_index=len(assigned["areas"]) - 1)
        except Exception:
            pass

    def _add_all_visible():
        used = _assigned_keys()
        for i in range(available_lb.size()):
            s = str(available_lb.get(i) or "").strip()
            k = " ".join(s.split()).lower()
            if s and k not in used:
                assigned["areas"].append(s)
                used.add(k)
        _refresh_lists(select_assigned_index=len(assigned["areas"]) - 1)

    def _clear_assigned():
        if not assigned["areas"]:
            return
        try:
            if not messagebox.askyesno("Clear Assigned Areas", "Remove all assigned areas from this collector?", parent=top):
                return
        except Exception:
            pass
        assigned["areas"] = []
        _refresh_lists()

    # Middle buttons
    tk.Frame(middle, bg=c["bg"], height=45).pack(fill="x")
    _spina_v27_route_button(middle, "Add →", command=_add_selected, kind="primary").pack(fill="x", pady=(0, 8))
    _spina_v27_route_button(middle, "← Remove", command=_remove_selected, kind="soft").pack(fill="x", pady=(0, 18))
    _spina_v27_route_button(middle, "Move Up", command=lambda: _move_selected(-1), kind="soft").pack(fill="x", pady=(0, 8))
    _spina_v27_route_button(middle, "Move Down", command=lambda: _move_selected(1), kind="soft").pack(fill="x", pady=(0, 8))
    _spina_v27_route_button(middle, "Top", command=_move_top, kind="soft").pack(fill="x", pady=(0, 8))
    _spina_v27_route_button(middle, "Bottom", command=_move_bottom, kind="soft").pack(fill="x", pady=(0, 18))
    _spina_v27_route_button(middle, "Add All", command=_add_all_visible, kind="soft").pack(fill="x", pady=(0, 8))
    _spina_v27_route_button(middle, "Clear All", command=_clear_assigned, kind="danger").pack(fill="x")

    try:
        available_lb.bind("<Double-1>", lambda e: _add_selected())
        assigned_lb.bind("<Double-1>", lambda e: _remove_selected())
        search_available_var.trace_add("write", lambda *_: _refresh_lists())
        search_assigned_var.trace_add("write", lambda *_: _refresh_lists())
    except Exception:
        pass

    # Notes section
    notes_panel = tk.Frame(top, bg=c["panel"], highlightbackground=c["border"], highlightthickness=1, bd=0)
    notes_panel.pack(fill="x", padx=18, pady=(0, 12))
    tk.Label(notes_panel, text="Route Notes / Instructions", bg=c["panel"], fg=c["fg"], font=("Segoe UI", 11, "bold"), anchor="w").pack(fill="x", padx=14, pady=(10, 0))
    notes_txt = tk.Text(notes_panel, height=4, wrap="word", bg=c["entry"], fg=c["fg"], insertbackground=c["fg"], relief="flat", font=("Segoe UI", 10))
    notes_txt.pack(fill="x", padx=14, pady=(6, 12))
    try:
        notes_txt.insert("1.0", str(initial_notes or ""))
    except Exception:
        pass

    # Footer
    footer = tk.Frame(top, bg=c["bg"])
    footer.pack(fill="x", padx=18, pady=(0, 16))
    tk.Label(footer, textvariable=status_var, bg=c["bg"], fg=c["muted"], font=("Segoe UI", 9), anchor="w").pack(side="left", fill="x", expand=True)

    def _save():
        nm = (name_var.get() or "").strip()
        if not nm:
            messagebox.showwarning("Missing Name", "Please enter a collector name.", parent=top)
            return
        clean = []
        seen = set()
        for a in assigned["areas"]:
            s = str(a or "").strip()
            if not s:
                continue
            k = " ".join(s.split()).lower()
            if k in seen:
                continue
            seen.add(k)
            clean.append(s)
        if not clean:
            messagebox.showwarning("No Areas", "Please assign at least one area to this collector.", parent=top)
            return
        try:
            nt = notes_txt.get("1.0", "end").strip()
        except Exception:
            nt = ""
        result.update({"ok": True, "name": nm, "areas": clean, "notes": nt})
        try:
            top.grab_release()
        except Exception:
            pass
        top.destroy()

    def _cancel():
        result.update({"ok": False})
        try:
            top.grab_release()
        except Exception:
            pass
        top.destroy()

    _spina_v27_route_button(footer, "Cancel", command=_cancel, kind="soft").pack(side="right", padx=(8, 0))
    _spina_v27_route_button(footer, "Save Route", command=_save, kind="primary").pack(side="right", padx=(8, 0))

    try:
        top.protocol("WM_DELETE_WINDOW", _cancel)
        top.bind("<Escape>", lambda e: _cancel())
    except Exception:
        pass

    _refresh_lists()
    try:
        top.wait_window()
    except Exception:
        pass
    if result.get("ok"):
        return {"name": result["name"], "areas": result["areas"], "notes": result["notes"]}
    return None


try:
    if "App" in globals():
        App._build_collectors_tab = _spina_v27_build_collectors_tab
        App._collector_editor_dialog = _spina_v27_collector_editor_dialog

        _spina_v27_prev_refresh_collectors = getattr(App, "refresh_collectors", None)
        if callable(_spina_v27_prev_refresh_collectors):
            def _spina_v27_refresh_collectors(self, *args, **kwargs):
                res = _spina_v27_prev_refresh_collectors(self, *args, **kwargs)
                try:
                    _spina_v27_update_route_cards(self)
                except Exception:
                    pass
                return res
            App.refresh_collectors = _spina_v27_refresh_collectors

        _spina_v27_prev_on_select = getattr(App, "_on_collectors_select", None)
        if callable(_spina_v27_prev_on_select):
            def _spina_v27_on_collectors_select(self, *args, **kwargs):
                # Keep selection lightweight. The visible right-side editor was removed.
                try:
                    tree = getattr(self, "collectors_tree", None)
                    if tree is not None and tree.selection():
                        vals = tree.item(tree.selection()[0], "values") or ()
                        nm = self._collectors_name_from_values(vals)
                        self._selected_collector_name = nm
                        if hasattr(self, "collector_route_table_status_var"):
                            self.collector_route_table_status_var.set(f"Selected: {nm}")
                except Exception:
                    pass
                try:
                    _spina_v27_update_route_cards(self)
                except Exception:
                    pass
                return None
            App._on_collectors_select = _spina_v27_on_collectors_select
except Exception as __spina_exc:
    try:
        _log_suppressed_once("v27_collector_route_bind_failed", "v27 collector route modern editor patch failed", __spina_exc)
    except Exception:
        pass
