def _spina_v32_login_colors(self=None):
    try:
        theme = str(getattr(self, "ui_theme", "dark") or "dark").lower()
    except Exception:
        theme = "dark"

    if theme.startswith("l"):
        return {
            "bg": "#f3f6fb",
            "left": "#111827",
            "panel": "#ffffff",
            "card": "#ffffff",
            "card2": "#f8fafc",
            "border": "#d6dde8",
            "fg": "#111827",
            "muted": "#64748b",
            "left_fg": "#ffffff",
            "left_muted": "#cbd5e1",
            "blue": "#2563eb",
            "green": "#16a34a",
            "red": "#dc2626",
            "soft": "#e8eef7",
        }

    return {
        "bg": "#0f1117",
        "left": "#111827",
        "panel": "#171a23",
        "card": "#20232d",
        "card2": "#262a36",
        "border": "#343b4d",
        "fg": "#f8fafc",
        "muted": "#aab3c2",
        "left_fg": "#ffffff",
        "left_muted": "#cbd5e1",
        "blue": "#60a5fa",
        "green": "#22c55e",
        "red": "#fb7185",
        "soft": "#252b38",
    }


def _spina_v32_login_button(parent, text, command=None, kind="normal", width=None):
    c = _spina_v32_login_colors()
    bg, fg = c["card2"], c["fg"]
    if kind == "primary":
        bg, fg = c["blue"], "#ffffff"
    elif kind == "success":
        bg, fg = c["green"], "#ffffff"
    elif kind == "danger":
        bg, fg = c["red"], "#ffffff"
    elif kind == "soft":
        bg, fg = c["soft"], c["fg"]

    return tk.Button(
        parent,
        text=text,
        command=command,
        bg=bg,
        fg=fg,
        activebackground=bg,
        activeforeground=fg,
        relief="flat",
        bd=0,
        padx=14,
        pady=9,
        font=("Segoe UI", 10, "bold"),
        cursor="hand2",
        width=width,
    )


def _spina_v32_account_default_name(username):
    u = str(username or "").strip().lower()
    return {
        "admin": "Owner Account",
        "encoder": "Encoding Account",
        "viewer": "Reports Account",
        "system": "Control Account",
        "collector": "Collector Account",
    }.get(u, str(username or "").strip() or "Account")


def _spina_v32_account_permission_text(role):
    r = str(role or "").strip()
    if r == "Admin":
        return "Full app access"
    if r == "Encoder":
        return "Encoding, reports, and route access"
    if r == "Viewer":
        return "Reports access"
    if r == "System":
        return "Audit, controls, and system tools"
    return "Custom account access"


def _spina_v32_account_display_name(self, username):
    username = str(username or "").strip()
    try:
        db = self._load_users_db()
        rec = (db.get("users") or {}).get(username) or {}
        display = str(rec.get("display_name") or rec.get("account_name") or rec.get("label") or "").strip()
        if display:
            return display
    except Exception:
        pass
    return _spina_v32_account_default_name(username)


def _spina_v32_account_role(self, username):
    username = str(username or "").strip()
    try:
        db = self._load_users_db()
        rec = (db.get("users") or {}).get(username) or {}
        r = str(rec.get("access_profile") or rec.get("role") or "").strip()
        if r in ("Admin", "Encoder", "Viewer", "System"):
            return r
    except Exception:
        pass
    return "Viewer"


def _spina_v32_account_choices(self, users=None):
    if not isinstance(users, dict):
        try:
            db = self._load_users_db()
            users = db.get("users") or {}
        except Exception:
            users = {}

    names = sorted([u for u in users.keys() if isinstance(u, str) and u.strip()], key=lambda s: s.lower())
    if not names:
        names = ["admin"]

    choices = []
    label_to_user = {}
    used = set()
    for u in names:
        rec = users.get(u) or {}
        label = str(rec.get("display_name") or rec.get("account_name") or rec.get("label") or "").strip()
        if not label:
            label = _spina_v32_account_default_name(u)
        base = label
        n = 2
        while label.lower() in used:
            label = f"{base} {n}"
            n += 1
        used.add(label.lower())
        choices.append(label)
        label_to_user[label] = u
    return choices, label_to_user


def _spina_v32_selected_label_for_user(self, username, choices, label_to_user):
    username = str(username or "").strip()
    for label in choices:
        if str(label_to_user.get(label) or "").strip() == username:
            return label
    return choices[0] if choices else ""


def _spina_v32_make_users_account_based(self):
    """Add account display metadata while preserving existing usernames/passwords/access."""
    try:
        # Use the original loader when available to avoid recursion.
        orig = getattr(App, "_spina_v32_orig_load_users_db", None)
        db = orig(self) if callable(orig) else self._load_users_db()
        if not isinstance(db, dict):
            db = {}
        users = db.get("users")
        if not isinstance(users, dict):
            users = {}
            db["users"] = users

        changed = False
        for username, rec in list(users.items()):
            if not isinstance(rec, dict):
                continue
            role = str(rec.get("role") or "").strip()
            if role not in ("Admin", "Encoder", "Viewer", "System"):
                role = "Viewer"
                rec["role"] = role
                changed = True

            if not str(rec.get("display_name") or "").strip():
                rec["display_name"] = _spina_v32_account_default_name(username)
                changed = True

            # Keep an account-based alias for the internal access profile.
            if not str(rec.get("access_profile") or "").strip():
                rec["access_profile"] = role
                changed = True

            # Store a human-readable permission summary without exposing role names.
            perm = _spina_v32_account_permission_text(role)
            if str(rec.get("permission_summary") or "").strip() != perm:
                rec["permission_summary"] = perm
                changed = True

            users[username] = rec

        db["users"] = users
        if changed:
            try:
                self._save_users_db(db)
            except Exception:
                pass
        return db
    except Exception:
        try:
            orig = getattr(App, "_spina_v32_orig_load_users_db", None)
            if callable(orig):
                return orig(self)
        except Exception:
            pass
        return {"users": {}}


def _spina_v32_prompt_login(self, default_user: str = "admin"):
    """Modern account-based login dialog. Returns (username, internal_access_profile)."""
    import tkinter as tk
    from tkinter import ttk, messagebox

    c = _spina_v32_login_colors(self)
    family = "Segoe UI" if os.name == "nt" else "TkDefaultFont"

    try:
        db = self._load_users_db()
        users = db.get("users") or {}
    except Exception:
        users = {}

    choices, label_to_user = _spina_v32_account_choices(self, users=users)
    if not choices:
        choices, label_to_user = ["Owner Account"], {"Owner Account": "admin"}

    selected_label = _spina_v32_selected_label_for_user(self, default_user, choices, label_to_user)

    result = {"user": None, "role": None}

    dlg = tk.Toplevel(self.root)
    dlg.title("Account Sign In")
    dlg.configure(bg=c["bg"])
    dlg.resizable(False, False)

    try:
        dlg.transient(self.root)
    except Exception as __spina_exc:
        _log_suppressed_once('pure_login_dialog_ui.transient', 'suppressed pure login dialog UI exception: login_dialog_transient', __spina_exc)
        pass

    # Main shell
    shell = tk.Frame(dlg, bg=c["bg"], padx=18, pady=18)
    shell.pack(fill="both", expand=True)

    card = tk.Frame(shell, bg=c["panel"], highlightbackground=c["border"], highlightthickness=1, bd=0)
    card.pack(fill="both", expand=True)

    left = tk.Frame(card, bg=c["left"], width=260)
    left.pack(side="left", fill="both")
    left.pack_propagate(False)

    tk.Label(left, text="SPINA", bg=c["left"], fg=c["left_fg"], font=(family, 24, "bold"), anchor="w").pack(fill="x", padx=24, pady=(34, 0))
    tk.Label(left, text="Account-based sign in", bg=c["left"], fg=c["left_muted"], font=(family, 11, "bold"), anchor="w").pack(fill="x", padx=24, pady=(6, 0))
    tk.Label(
        left,
        text="Each account keeps its own access permissions. No need to choose Admin, Viewer, Collector, or System during login.",
        bg=c["left"],
        fg=c["left_muted"],
        font=(family, 9),
        justify="left",
        wraplength=210,
        anchor="nw",
    ).pack(fill="x", padx=24, pady=(28, 0))

    tk.Frame(left, bg="#1f2937", height=1).pack(fill="x", padx=24, pady=(28, 14))
    tk.Label(
        left,
        text="Tip: use Switch Account from the header when another person needs to use the app.",
        bg=c["left"],
        fg=c["left_muted"],
        font=(family, 8),
        justify="left",
        wraplength=210,
        anchor="nw",
    ).pack(fill="x", padx=24, pady=(0, 0))

    right = tk.Frame(card, bg=c["panel"], width=430)
    right.pack(side="left", fill="both", expand=True)
    right.pack_propagate(False)

    tk.Label(right, text="Welcome back", bg=c["panel"], fg=c["fg"], font=(family, 20, "bold"), anchor="w").pack(fill="x", padx=28, pady=(32, 0))
    tk.Label(right, text="Sign in with your account.", bg=c["panel"], fg=c["muted"], font=(family, 10), anchor="w").pack(fill="x", padx=28, pady=(4, 18))

    form = tk.Frame(right, bg=c["panel"])
    form.pack(fill="x", padx=28)

    tk.Label(form, text="Account", bg=c["panel"], fg=c["muted"], font=(family, 9, "bold"), anchor="w").pack(fill="x")
    account_var = tk.StringVar(value=selected_label)
    account_cb = ttk.Combobox(form, textvariable=account_var, values=choices, state="readonly", width=32)
    account_cb.pack(fill="x", pady=(4, 12), ipady=3)

    account_info_var = tk.StringVar(value="")
    tk.Label(form, textvariable=account_info_var, bg=c["panel"], fg=c["muted"], font=(family, 8), anchor="w").pack(fill="x", pady=(0, 8))

    tk.Label(form, text="Password", bg=c["panel"], fg=c["muted"], font=(family, 9, "bold"), anchor="w").pack(fill="x")
    pw_var = tk.StringVar(value="")
    pw_entry = ttk.Entry(form, textvariable=pw_var, show="*", width=34)
    pw_entry.pack(fill="x", pady=(4, 8), ipady=3)

    show_var = tk.BooleanVar(value=False)
    def _toggle_show():
        try:
            pw_entry.configure(show="" if show_var.get() else "*")
        except Exception:
            pass

    try:
        ttk.Checkbutton(form, text="Show password", variable=show_var, command=_toggle_show).pack(anchor="w", pady=(0, 8))
    except Exception:
        pass

    msg_var = tk.StringVar(value="")
    msg_lbl = tk.Label(form, textvariable=msg_var, bg=c["panel"], fg=c["red"], font=(family, 9, "bold"), anchor="w", justify="left", wraplength=360)
    msg_lbl.pack(fill="x", pady=(0, 8))

    btns = tk.Frame(right, bg=c["panel"])
    btns.pack(fill="x", padx=28, pady=(4, 0))

    def _refresh_account_info(*_):
        try:
            label = account_var.get()
            username = label_to_user.get(label, label)
            rec = (users or {}).get(username) or {}
            summary = str(rec.get("permission_summary") or _spina_v32_account_permission_text(rec.get("role")) or "").strip()
            if summary:
                account_info_var.set(summary)
            else:
                account_info_var.set("Account permissions will be loaded after sign in.")
        except Exception:
            account_info_var.set("Account permissions will be loaded after sign in.")

    def _ok():
        label = (account_var.get() or "").strip()
        username = str(label_to_user.get(label, label) or "").strip()
        password = pw_var.get() or ""

        if not username:
            msg_var.set("Please choose an account.")
            return

        role = self._verify_login(username, password)
        if not role:
            msg_var.set("Invalid account or password.")
            try:
                pw_entry.focus_set()
                pw_entry.selection_range(0, "end")
            except Exception:
                pass
            return

        try:
            if self._must_change_password(username, password):
                if not self._force_change_password_dialog(username, old_password=password):
                    msg_var.set("Password change required to continue.")
                    return
        except Exception:
            try:
                _log_exc("force_change_password")
            except Exception:
                pass
            msg_var.set("Password change required, but the change dialog failed. See log.")
            return

        result["user"] = username
        result["role"] = role
        try:
            dlg.grab_release()
        except Exception:
            pass
        dlg.destroy()

    def _cancel():
        try:
            dlg.grab_release()
        except Exception:
            pass
        dlg.destroy()

    _spina_v32_login_button(btns, "Sign In", command=_ok, kind="primary").pack(side="right")
    _spina_v32_login_button(btns, "Cancel", command=_cancel, kind="soft").pack(side="right", padx=(0, 8))

    tk.Label(
        right,
        text="Existing passwords are unchanged. Default accounts still require password change on first login.",
        bg=c["panel"],
        fg=c["muted"],
        font=(family, 8),
        anchor="w",
        justify="left",
        wraplength=360,
    ).pack(fill="x", padx=28, pady=(16, 0))

    try:
        account_var.trace_add("write", _refresh_account_info)
    except Exception as __spina_exc:
        _log_suppressed_once('pure_login_dialog_ui.account_trace', 'suppressed pure login dialog UI exception: login_dialog_account_trace', __spina_exc)
        pass
    _refresh_account_info()

    def _enter(_=None):
        _ok()

    try:
        pw_entry.bind("<Return>", _enter)
        account_cb.bind("<Return>", _enter)
    except Exception as __spina_exc:
        _log_suppressed_once('pure_login_dialog_ui.return_bind', 'suppressed pure login dialog UI exception: login_dialog_return_bind', __spina_exc)
        pass

    try:
        dlg.grab_set()
    except Exception as __spina_exc:
        _log_suppressed_once('pure_login_dialog_ui.grab_set', 'suppressed pure login dialog UI exception: login_dialog_grab_set', __spina_exc)
        pass

    try:
        dlg.update_idletasks()
        w, h = 735, 455
        sw, sh = dlg.winfo_screenwidth(), dlg.winfo_screenheight()
        try:
            rx, ry = self.root.winfo_rootx(), self.root.winfo_rooty()
            rw, rh = self.root.winfo_width(), self.root.winfo_height()
            x = rx + (rw - w) // 2
            y = ry + (rh - h) // 2
        except Exception:
            x = (sw - w) // 2
            y = (sh - h) // 2
        x = max(10, min(x, sw - w - 10))
        y = max(10, min(y, sh - h - 60))
        dlg.geometry(f"{w}x{h}+{x}+{y}")
    except Exception as __spina_exc:
        _log_suppressed_once('pure_login_dialog_ui.position', 'suppressed pure login dialog UI exception: login_dialog_position', __spina_exc)
        pass

    try:
        pw_entry.focus_set()
    except Exception:
        pass

    self.root.wait_window(dlg)
    return (result.get("user"), result.get("role"))


def _spina_v32_refresh_user_header(self):
    try:
        if getattr(self, "user_role_label", None) is not None:
            display = _spina_v32_account_display_name(self, getattr(self, "user_name", ""))
            self.user_role_label.config(text=f"Account: {display}")
    except Exception as __spina_exc:
        try:
            _log_suppressed_once("v32_refresh_user_header", "v32 refresh user header failed", __spina_exc)
        except Exception:
            pass
    try:
        self._refresh_header_theme()
    except Exception:
        pass


def _spina_v32_switch_account(self):
    old_user = getattr(self, "user_name", "") or ""
    old_display = _spina_v32_account_display_name(self, old_user) if old_user else ""

    try:
        u, r = self._prompt_login(default_user=(self.user_name or "admin"))
    except Exception as e:
        try:
            _log_exc("switch_account_login", e)
        except Exception:
            pass
        try:
            messagebox.showerror("Switch Account", "Failed to open the account sign-in window. See log for details.")
        except Exception:
            pass
        return

    if not u or not r:
        return

    self.user_name = u
    self.user_role = r

    try:
        self._save_last_user(self.user_name)
    except Exception:
        pass
    try:
        self._save_user_role(self.user_role)
    except Exception:
        pass

    try:
        self._refresh_user_header()
    except Exception:
        pass
    try:
        self._rebuild_side_nav()
    except Exception:
        pass

    try:
        self.apply_role_access()
    except Exception as e:
        try:
            _log_exc("switch_account_apply_role_access", e)
        except Exception:
            pass
        try:
            messagebox.showwarning("Switch Account", "The account was switched, but the UI permissions could not be fully refreshed. Please restart the app if something looks wrong.")
        except Exception:
            pass

    try:
        new_display = _spina_v32_account_display_name(self, self.user_name)
        self.status_var.set(f"Switched account: {old_display or old_user} → {new_display}")
    except Exception:
        pass


def _spina_v32_prompt_user_role(self, default: str = "Admin") -> str:
    # Fallback only. Do not show the old role selector anymore.
    d = str(default or "Admin").strip()
    return d if d in ("Admin", "Encoder", "Viewer", "System") else "Admin"


try:
    if "App" in globals():
        if not hasattr(App, "_spina_v32_orig_load_users_db"):
            App._spina_v32_orig_load_users_db = getattr(App, "_load_users_db", None)

        App._load_users_db = _spina_v32_make_users_account_based
        App._prompt_login = _spina_v32_prompt_login
        App._prompt_user_role = _spina_v32_prompt_user_role
        App._refresh_user_header = _spina_v32_refresh_user_header
        App.switch_account = _spina_v32_switch_account

        _spina_v32_orig_build_header = getattr(App, "_build_header", None)
        if callable(_spina_v32_orig_build_header):
            def _spina_v32_build_header(self, *args, **kwargs):
                res = _spina_v32_orig_build_header(self, *args, **kwargs)
                try:
                    self._refresh_user_header()
                except Exception:
                    pass
                try:
                    if getattr(self, "switch_account_btn", None) is not None:
                        self.switch_account_btn.configure(text="Account")
                except Exception:
                    pass
                return res
            App._build_header = _spina_v32_build_header
except Exception as __spina_exc:
    try:
        _log_suppressed_once("v32_account_login_bind_failed", "v32 account login patch failed", __spina_exc)
    except Exception:
        pass
# --- END: v32 Modern Account-Based Login ---


# --- FINAL ENTRY POINT (after all runtime patches) ---

# --- BEGIN: SPINA REMOVE LEGACY CLIENT ACTION BUTTONS ---
# Legacy Clients-tab actions are intentionally removed from the UI/action layer:
# From Transactions, Full Ledger, Export Template, and Import Excel.
# Collector Route, notes, balances, 7x7, payment logic, and report math are untouched.
def _spina_legacy_client_action_removed_message(action="Legacy client action"):
    message = str(action) + " is removed from the Clients tab."
    try:
        if "messagebox" in globals():
            messagebox.showinfo("Action Removed", message)
        else:
            print("[SPINA] " + message, flush=True)
    except Exception:
        try:
            print("[SPINA] " + message, flush=True)
        except Exception:
            pass


def _spina_make_removed_legacy_client_action(label):
    def _spina_removed_action(*args, **kwargs):
        _spina_legacy_client_action_removed_message(label)
        return None
    _spina_removed_action.__name__ = "_spina_removed_" + str(label).lower().replace(" ", "_")
    return _spina_removed_action
if __name__ == '__main__':
    main()
